// Phiên bản app đang chạy — khớp tham số ?v= của app.js trong index.html.
// Khi deploy bản mới, HTML trỏ sang ?v= khác; bản đang mở sẽ hiện banner
// "bấm để cập nhật" thay vì chạy mãi JS cũ trong tab SPA.
const APP_BUILD = (() => {
  try { return new URL(document.currentScript.src, location.href).searchParams.get("v") || "0"; }
  catch { return "0"; }
})();

async function checkAppVersion() {
  if (!state.data || matchPublicPaymentPath()) return;
  try {
    const html = await (await fetch("/", { cache: "no-store" })).text();
    const match = html.match(/app\.js\?v=(\d+)/);
    if (match && match[1] !== APP_BUILD) showUpdateBanner();
  } catch {}
}

function showUpdateBanner() {
  if (document.querySelector(".app-update-banner")) return;
  const banner = document.createElement("button");
  banner.type = "button";
  banner.className = "app-update-banner";
  banner.textContent = "Đã có bản mới — bấm để cập nhật";
  banner.addEventListener("click", () => location.reload());
  document.body.appendChild(banner);
}

