function icon(name, className = "") {
  return `<svg class="icon ${className}" viewBox="0 0 24 24" aria-hidden="true">${svgPaths[name] || svgPaths.clipboard}</svg>`;
}

function escapeHtml(value) {
  return String(value ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#039;");
}

function toast(message) {
  $toast.textContent = message;
  $toast.classList.add("show");
  clearTimeout(toast.timer);
  toast.timer = setTimeout(() => $toast.classList.remove("show"), 2200);
}

const MALE_VOICE = /male|david|daniel|alex|fred|mark|guy|tom|james|aaron|arthur|rishi|george|thomas|gordon|ryan|nathan|matthew/i;
const FEMALE_VOICE = /female|samantha|victoria|karen|moira|tessa|fiona|zira|susan|siri|hazel|serena|allison|ava|jenny|aria|natasha/i;

function pickMaleEnglishVoice() {
  if (!("speechSynthesis" in window)) return undefined;
  const voices = window.speechSynthesis.getVoices();
  const english = voices.filter((voice) => /^en\b/i.test(voice.lang) || /english/i.test(voice.name));
  const pool = english.length ? english : voices;
  return pool.find((voice) => MALE_VOICE.test(voice.name) && !FEMALE_VOICE.test(voice.name));
}

let heldUtterance = null;
let resumeTimer = 0;

function speakEnglish(text) {
  if (!("speechSynthesis" in window)) return false;
  const synth = window.speechSynthesis;
  const word = String(text || "").split("/")[0].trim();
  if (!word) return false;
  synth.getVoices();
  if (synth.speaking || synth.pending) synth.cancel();
  const speech = new SpeechSynthesisUtterance(word);
  heldUtterance = speech;
  speech.rate = 0.85;
  speech.lang = "en-GB";
  speech.pitch = 0.7;
  const voice = pickMaleEnglishVoice();
  if (voice) {
    speech.voice = voice;
    speech.lang = voice.lang || "en-GB";
    speech.pitch = 1;
  }
  speech.onend = () => window.clearInterval(resumeTimer);
  speech.onerror = () => window.clearInterval(resumeTimer);
  synth.speak(speech);
  synth.resume();
  window.clearInterval(resumeTimer);
  resumeTimer = window.setInterval(() => {
    if (!synth.speaking) {
      window.clearInterval(resumeTimer);
      return;
    }
    if (synth.paused) synth.resume();
  }, 250);
  return true;
}

if ("speechSynthesis" in window) {
  window.speechSynthesis.getVoices();
  window.speechSynthesis.addEventListener("voiceschanged", () => window.speechSynthesis.getVoices());
}

// Thân request lớn (lưu cả danh sách, sao kê…) nén gzip trước khi gửi — dữ liệu y nguyên, chỉ nhẹ đường truyền.
// Máy chủ báo BODY_DECODE (proxy làm hỏng gói nén) thì gửi lại bản thường và tắt nén cho phiên này.
const API_GZIP_MIN_BYTES = 32 * 1024;
let apiGzipBody = typeof CompressionStream === "function";

async function apiGzip(text) {
  const stream = new Blob([text]).stream().pipeThrough(new CompressionStream("gzip"));
  return new Uint8Array(await new Response(stream).arrayBuffer());
}

async function api(path, options = {}) {
  const method = String(options.method || "GET").toUpperCase();
  if (method !== "GET" && method !== "HEAD" && bootstrapRest.pending) {
    const error = new Error("Đang tải nốt dữ liệu, vui lòng thử lại sau giây lát.");
    error.status = 0;
    throw error;
  }
  const headers = { "Content-Type": "application/json", ...(options.headers || {}) };
  if (apiGzipBody && typeof options.body === "string" && options.body.length >= API_GZIP_MIN_BYTES) {
    let packed = null;
    try { packed = await apiGzip(options.body); } catch { apiGzipBody = false; }
    if (packed) {
      // Lỗi mạng giữa chừng thì báo lỗi như cũ (không tự gửi lại — tránh ghi hai lần).
      const response = await fetch(path, { ...options, body: packed, headers: { ...headers, "Content-Encoding": "gzip" } });
      // Chỉ gửi lại bản không nén khi máy chủ chắc chắn CHƯA xử lý: không giải nén được / không nhận kiểu nén.
      const payload = response.status === 400 || response.status === 415 ? await response.clone().json().catch(() => ({})) : null;
      if (!(response.status === 415 || payload?.error === "BODY_DECODE")) return apiPayload(response);
      apiGzipBody = false;
    }
  }
  return apiPayload(await fetch(path, { ...options, headers }));
}

/**
 * Mở web chỉ tải phần trang cần (anh Mori 17/11/2026). /api/bootstrap?split=1 trả bản nhẹ: các mảng
 * lớn ít trang dùng (nhật ký, tin Zalo, sổ thu chi, đối soát, lệnh thanh toán, giao dịch ngân hàng)
 * để null kèm `bootstrapRest` — tải nốt ngay sau khi vẽ trang. Trong lúc chờ:
 * - mảng đó là "chỗ giữ": trang nào đọc tới thì hiện "Đang tải" rồi tự vẽ lại khi xong;
 * - không cho thao tác / ghi gì (tránh lưu dữ liệu thiếu phần chưa tải).
 * Tải xong, state.data giống hệt bản tải một lần như trước.
 */
const bootstrapRest = { pending: false, touched: false, quiet: 0, showedLoading: false, holders: [], seq: 0 };

function bootstrapRestPlaceholder(holder, key) {
  const empty = [];
  const get = () => {
    if (!bootstrapRest.quiet) bootstrapRest.touched = true;
    return empty;
  };
  Object.defineProperty(holder, key, {
    configurable: true,
    enumerable: true,
    get,
    set(value) { Object.defineProperty(holder, key, { value, writable: true, enumerable: true, configurable: true }); },
  });
  bootstrapRest.holders.push({ holder, key, get });
}

function bootstrapRestIsPlaceholder(holder, key) {
  const desc = holder && Object.getOwnPropertyDescriptor(holder, key);
  return Boolean(desc?.get && bootstrapRest.holders.some((item) => item.holder === holder && item.key === key && item.get === desc.get));
}

/** Bản sao nông, thay chỗ giữ bằng giá trị thật (giữ đúng thứ tự khoá). */
function bootstrapRestFill(holder, values, prefix) {
  const out = {};
  for (const key of Object.keys(holder)) {
    const path = prefix ? `${prefix}.${key}` : key;
    out[key] = bootstrapRestIsPlaceholder(holder, key) && Object.prototype.hasOwnProperty.call(values, path)
      ? values[path]
      : Object.getOwnPropertyDescriptor(holder, key).value;
  }
  return out;
}

async function loadBootstrap(retry = false) {
  const data = retry ? await apiWithRetry("/api/bootstrap?split=1") : await api("/api/bootstrap?split=1");
  const meta = data.bootstrapRest;
  delete data.bootstrapRest;
  const seq = ++bootstrapRest.seq;
  bootstrapRest.holders = [];
  bootstrapRest.pending = false;
  if (!meta?.token || !Array.isArray(meta.paths) || !meta.paths.length) return data;
  for (const path of meta.paths) {
    const parts = String(path).split(".");
    const key = parts.pop();
    const holder = parts.reduce((node, part) => (node && typeof node === "object" ? node[part] : null), data);
    if (holder && typeof holder === "object" && holder[key] === null) bootstrapRestPlaceholder(holder, key);
  }
  bootstrapRest.pending = true;
  bootstrapRest.showedLoading = false;
  // Tải nốt sau khi trang đầu đã vẽ (không tranh băng thông với bản nhẹ).
  setTimeout(() => { void loadBootstrapRest(data, meta, seq); }, 0);
  return data;
}

async function loadBootstrapRest(data, meta, seq) {
  let values = null;
  try {
    values = (await apiWithRetry(`/api/bootstrap/rest?token=${encodeURIComponent(meta.token)}`)).values;
  } catch {
    values = null;
  }
  if (seq !== bootstrapRest.seq) return;
  if (!values) {
    // Phần tải sau đã hết hạn (dữ liệu vừa đổi) → tải lại bản đầy đủ một lần như trước.
    try {
      const full = await apiWithRetry("/api/bootstrap");
      if (seq !== bootstrapRest.seq) return;
      if (state.data === data) state.data = full;
    } catch {
      setTimeout(() => { if (seq === bootstrapRest.seq) void loadBootstrapRest(data, meta, seq); }, 3000);
      return;
    }
  } else if (state.data === data) {
    // Mảng cấp trên: thay thẳng; finance / sepay: object mới (bộ nhớ đệm tính toán tự làm mới theo tham chiếu).
    for (const key of ["auditLogs", "zaloMessages"]) {
      if (bootstrapRestIsPlaceholder(data, key) && Object.prototype.hasOwnProperty.call(values, key)) data[key] = values[key];
    }
    const finance = data.finance;
    if (finance && typeof finance === "object") {
      const sepay = finance.sepay;
      const sepayPending = sepay && typeof sepay === "object" && Object.keys(sepay).some((key) => bootstrapRestIsPlaceholder(sepay, key));
      const financePending = Object.keys(finance).some((key) => bootstrapRestIsPlaceholder(finance, key));
      if (sepayPending || financePending) {
        const next = bootstrapRestFill(finance, values, "finance");
        if (sepayPending) next.sepay = bootstrapRestFill(sepay, values, "finance.sepay");
        data.finance = next;
      }
    }
  }
  bootstrapRest.pending = false;
  bootstrapRest.holders = [];
  if (bootstrapRest.showedLoading || state.data !== data) render();
}

function bootstrapRestBlocked() {
  if (!bootstrapRest.pending) return false;
  toast("Đang tải nốt dữ liệu, vui lòng thử lại sau giây lát.");
  return true;
}

async function apiPayload(response) {
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) {
    const error = new Error(payload.error || "Có lỗi xảy ra.");
    error.status = response.status;
    throw error;
  }
  return payload;
}

async function apiWithRetry(path, options = {}, attempts = 4, baseDelay = 350) {
  let lastError;
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    try {
      return await api(path, options);
    } catch (error) {
      lastError = error;
      const status = Number(error?.status || 0);
      const retryable = !status || status === 408 || status === 429 || status >= 500;
      if (!retryable || attempt === attempts - 1) throw error;
      await new Promise((resolve) => setTimeout(resolve, baseDelay * (2 ** attempt)));
    }
  }
  throw lastError;
}

function newId(prefix) {
  const uuid = globalThis.crypto?.randomUUID?.();
  if (uuid) return `${prefix}-${uuid}`;
  return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

function go(path) {
  state.academicReportModal = "";
  state.periodicReportModal = null;
  const toAcademicReport = path.startsWith("/bao-cao/hoc-vu") || path.startsWith("/gv/bao-cao-hoc-vu");
  const fromAcademicReport = state.route.startsWith("/bao-cao/hoc-vu") || state.route.startsWith("/gv/bao-cao-hoc-vu");
  if (toAcademicReport && !fromAcademicReport) {
    state.reportQuery = "";
    state.reportClass = "";
    state.reportTeacher = "";
    state.reportFrom = "";
    state.reportTo = "";
  }
  // Quản lý task: mở từ menu luôn về ngày hôm nay.
  if (path.startsWith("/quan-ly-task") && !state.route.startsWith("/quan-ly-task")) state.taskBoardDate = "";
  if (path.startsWith("/bao-cao/chuyen-can") && !state.route.startsWith("/bao-cao/chuyen-can")) {
    state.reportClass = "";
  }
  if (path.startsWith("/bao-cao/dinh-ky") && !state.route.startsWith("/bao-cao/dinh-ky")) {
    state.periodicReportClass = "";
    state.periodicReportMonth = monthKey();
    state.periodicReportCourse = 0;
  }
  if (path.startsWith("/bao-cao/cham-phieu") && !state.route.startsWith("/bao-cao/cham-phieu")) {
    state.gradingTestId = "";
    state.gradingModal = null;
    state.gradingView = "";
    state.grading = emptyGradingState();
  }
  if (!String(path).includes("/diem-danh")) {
    state.attendanceOff = null;
    state.attendanceHomework = null;
    state.attendanceVideo = false;
    state.attendanceColumnDrafts = {};
    state.attendanceRemovedColumns = {};
    state.attendanceColumnOrders = {};
    state.attendanceColumnNames = {};
  }
  state.route = path;
  if (!path.startsWith("/syllabus/") && !path.startsWith("/portal/syllabus")) state.selectedSyllabus = null;
  history.pushState({}, "", path);
  state.settingsModal = null;
  state.peopleModal = null;
  state.classModal = null;
  state.classStudentModal = null;
  state.calendarModal = null;
  state.calendarMakeup = null;
  state.calendarEvent = null;
  state.financeModal = null;
  state.portalGame = null;
  document.body.classList.remove("menu-open");
  render();
}

