/** Xoá học viên / xoá lớp: chỉ admin (Audit, kế toán, giáo viên… không xoá được). */
function canDeleteRoster() {
  return isSuperAdmin();
}

/** Tab Quản lý task: admin + nhân sự phòng Hành chính (anh Mori 12/11/2026). */
function canViewTaskBoard() {
  if (isSuperAdmin()) return true;
  return typeof staffTaskRosterDepartment === "function" && staffTaskRosterDepartment(state.data?.user?.name || "") === "Hành chính";
}

/** Menu kế toán; nhân sự Hành chính đăng nhập bằng tài khoản kế toán thấy thêm Quản lý task. */
function accountantNavGroupsForUser() {
  if (!canViewTaskBoard() && !isOfficeHc()) return accountantNavGroups;
  return accountantNavGroups.map((group) => {
    if (group.title === "Quản lý Vận hành") return { ...group, items: group.items.flatMap((item) => item[2] === "/lich-day" && canViewTaskBoard() ? [item, ["Quản lý task", "clipboard", "/quan-ly-task"]] : item[2] === "/hoc-vien" && isOfficeHc() ? [item, ["Giáo viên", "graduation", "/giao-vien"]] : [item]) };
    if (group.title === "Cấu hình hệ thống" && isOfficeHc()) return { ...group, items: [["Cấu hình", "settings", "/cai-dat/trung-tam"], ...group.items] };
    return group;
  });
}

/** Sửa hồ sơ học viên (thông tin liên hệ, trạng thái, tài khoản Portal): admin, Audit, kế toán, hành chính.
 *  Số buổi tồn, Miễn học phí, xoá học viên vẫn chỉ admin. */
function canEditStudentProfile() {
  return canManageRoster() || state.role === "ACCOUNTANT";
}

function canManageRoster() {
  return state.role === "ADMIN";
}

/** Thêm học viên: admin, Audit và nhân sự Hành chính (tài khoản kế toán nhóm HC). HV mới vào Lớp chờ, không có học phí. */
function canAddStudent() {
  return canManageRoster() || (state.role === "ACCOUNTANT" && isOfficeHc());
}

/** Thêm / sửa giáo viên + tick "Quyền trợ giảng": superadmin và nhân sự Hành chính. Xoá giáo viên chỉ superadmin. */
function canEditTeachers() {
  return isSuperAdmin() || ((state.role === "ACCOUNTANT" || isAuditor()) && isOfficeHc());
}

/** Giáo viên có phòng ban "Trợ giảng" trên hồ sơ lương (cách cũ) — vẫn được quyền trợ giảng. */
function teacherAssistantByDepartment(teacherId) {
  const department = String(payrollContract(teacherId)?.department || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/đ/gi, "d").toLowerCase().replace(/\s+/g, " ").trim();
  return department === "tro giang";
}

function teacherHasAssistantAccess(teacher) {
  return Boolean(teacher?.assistantAccess) || teacherAssistantByDepartment(teacher?.id);
}

