/** Tài khoản Audit: quyền như admin nhưng không quản lý tài khoản / cấu hình, không gỡ đối soát. */
function isAuditor() {
  return state.role === "ADMIN" && Boolean(state.data?.user?.auditor);
}

function isSuperAdmin() {
  return state.role === "ADMIN" && !state.data?.user?.auditor;
}

/** Ngày hôm nay theo giờ Việt Nam (UTC+7). */
function vnTodayKey(now = new Date()) {
  return new Date(now.getTime() + 7 * 60 * 60 * 1000).toISOString().slice(0, 10);
}

/** Hôm nay đã bấm Đối soát xong → khoá toàn bộ thu chi, thu học phí đến 0h (giờ VN). */
function financeTodayLocked() {
  return Boolean(reconLockFor(vnTodayKey()));
}

function financeTodayLockBanner() {
  if (!financeTodayLocked()) return "";
  const lock = reconLockFor(vnTodayKey());
  return `<div class="finance-lock-banner">${icon("lock")}<div><strong>Hôm nay ${formatDateVi(vnTodayKey())} đã đối soát xong${lock?.lockedByName ? ` (${escapeHtml(lock.lockedByName)})` : ""}.</strong><span>Khoá toàn bộ thao tác thu học phí, thu chi, cập nhật sao kê đến 0h đêm nay (giờ Việt Nam).${isSuperAdmin() ? " Cần sửa gấp: vào Đối soát thu chi → Gỡ đối soát." : ""}</span></div></div>`;
}

function reconLockFor(date) {
  return (state.data?.reconLocks || []).find((row) => row.date === date) || null;
}

/** Nhóm menu admin; Audit không thấy mục quản lý tài khoản nhân sự và cấu hình hệ thống. */
function adminGroupsForUser() {
  if (!isAuditor()) return activeAdminGroups.map((group) => ({ ...group, items: group.items.filter((item) => item[2] !== "/task") }));
  const hidden = new Set(["/audit", "/hanh-chinh", ...(isOfficeHc() ? [] : ["/cai-dat"]), ...(canViewTaskBoard() ? [] : ["/quan-ly-task"])]);
  return activeAdminGroups.map((group) => ({ ...group, items: group.items.filter((item) => !hidden.has(item[2])) })).filter((group) => group.items.length);
}

