function adminNav(groups = activeAdminGroups) {
  return groups.map((group) => {
    const items = group.items.map(([label, iconName, href]) => {
    const active = href && (href === "/gv" ? state.route === href : href === "/portal" ? state.route === href || state.route.startsWith("/portal/game/") : state.route.startsWith(href));
    return `<button class="nav-item ${active ? "active" : ""}" data-nav="${href || "disabled"}">${icon(iconName)}${label}</button>`;
    }).join("");
    if (!group.folder) return `<section class="nav-group">${group.title ? `<p class="nav-title">${group.title}</p>` : ""}${items}</section>`;
    const active = group.items.some(([, , href]) => href && state.route.startsWith(href));
    return `<section class="nav-folder ${active ? "active" : ""}"><div class="nav-folder-heading">${icon(group.icon || "panels")}<span>${escapeHtml(group.title)}</span></div><div class="nav-folder-items">${items}</div></section>`;
  }).join("");
}

