    if (state.route.startsWith("/gv/lich-day")) return "Lịch dạy";
    if (state.route.startsWith("/gv/task")) return "Task của tôi";
    if (state.route.startsWith("/gv/lop-hoc")) return isAcademicAssistant() ? "Nhập điểm buổi học" : "Lớp của tôi";
    if (state.route.startsWith("/gv/bao-cao-hoc-vu")) return "Báo cáo học vụ";
