function adminShell(content, teacher = false, student = false) {
  const user = state.data.user;
  const accountant = !teacher && !student && state.role === "ACCOUNTANT";
  const groups = teacher
    ? isAcademicAssistant()
      ? [{ items: [["Báo cáo học vụ", "clipboard", "/gv/bao-cao-hoc-vu"], ["Chấm điểm Phiếu", "pencil", "/bao-cao/cham-phieu"], ["Tài liệu sử dụng", "book", "/tai-lieu"]] }]
      : [{ items: [["Dashboard", "dashboard", "/gv"], ["Lịch dạy", "calendar", "/gv/lich-day"], ["Lớp của tôi", "school", "/gv/lop-hoc"], ["Báo cáo học vụ", "clipboard", "/gv/bao-cao-hoc-vu"], ["Chấm điểm Phiếu", "pencil", "/bao-cao/cham-phieu"], ["Task của tôi", "clipboard", "/gv/task"], ["Chấm công của tôi", "calendar", "/gv/cham-cong"], ["Portal", "book", "/soan-portal"], ["Tài liệu sử dụng", "book", "/tai-lieu"]] }]
    : accountant
      ? accountantNavGroupsForUser()
      : adminGroupsForUser();
  const roleLabel = isAcademicAssistant() ? "Trợ giảng" : teacher ? "Giáo viên" : student ? "Học viên" : accountant ? "Kế toán" : isAuditor() ? "Audit" : "Quản trị viên";
  const nextActivity = student ? portalNextActivity() : null;
  const topbarAction = student && nextActivity && !state.route.startsWith("/portal/game/")
      ? portalIsStudioProgram()
        ? (portalSelectedActivityId() || portalSelectedDayId() || state.route === "/portal" ? "" : `<button class="primary-btn topbar-action" type="button" data-nav="/portal/buoi/${encodeURIComponent(nextActivity.day.id)}">Tiếp tục học</button>`)
        : `<button class="primary-btn topbar-action" type="button" data-portal-activity="${escapeHtml(activeSyllabus().id)}|${escapeHtml(nextActivity.id)}">Tiếp tục học</button>`
      : "";
  const topbarBack = parseClassRoute(teacher)
    ? `<button class="back-link topbar-back" data-nav="${isAcademicAssistant() ? "/gv/bao-cao-hoc-vu" : teacher ? "/gv/lop-hoc" : "/lop-hoc"}">${isAcademicAssistant() ? "← Báo cáo học vụ" : "← Danh sách lớp học"}</button>`
    : "";
  return `<div class="admin-shell${student ? " student-shell" : ""}">
    <aside class="admin-sidebar">
      <div class="admin-brand"><span class="logo-tile">${icon("graduation")}</span><strong>STEPS LMS</strong></div>
      <nav class="admin-nav${student ? " portal-tree" : ""}">${student ? portalTreeNav() : adminNav(groups)}</nav>
    </aside>
    <div class="admin-workspace">
      <header class="admin-topbar${state.route.startsWith("/tai-lieu") ? " docs-topbar" : ""}"><button class="mobile-menu" data-action="menu">${icon("menu", "icon-lg")}</button><h1 class="admin-page-title">${escapeHtml(adminPageTitle(teacher, student))}</h1>${topbarBack}${topbarAction}<div class="admin-topbar-user"><span class="avatar">${escapeHtml(user.name.charAt(0).toUpperCase())}</span><div class="user-copy"><strong>${escapeHtml(user.name)}</strong><small>${roleLabel}</small></div>${isSuperAdmin() && String(state.data?.user?.email || "").includes("@") ? `<button class="icon-button" data-action="password" title="Đổi mật khẩu">${icon("key")}</button>` : ""}<button class="icon-button danger" data-action="logout" title="Đăng xuất">${icon("logout")}</button></div></header>
      <main class="admin-content">${content}</main>
    </div><button class="backdrop" data-action="close-menu"></button>
  </div>`;
}

const BRANCH_TUITION_MONTH_MIN = "2026-10";
const BRANCH_TUITION_MONTH_MAX = "2027-12";

function branchTuitionMonthOptions() {
  const options = [];
  let [year, month] = BRANCH_TUITION_MONTH_MIN.split("-").map(Number);
  const [endYear, endMonth] = BRANCH_TUITION_MONTH_MAX.split("-").map(Number);
  while (year < endYear || (year === endYear && month <= endMonth)) {
    options.push(`${year}-${String(month).padStart(2, "0")}`);
    month += 1;
    if (month > 12) { month = 1; year += 1; }
  }
  return options;
}

function dashboardBranchMonth(branchId) {
  const options = branchTuitionMonthOptions();
  const selected = String(state.dashTuitionMonth?.[branchId] || "");
  if (options.includes(selected)) return selected;
  const current = monthKey();
  if (current < options[0]) return options[0];
  if (current > options[options.length - 1]) return options[options.length - 1];
  return current;
}

/** Tháng theo giờ VN của một mốc thời gian — chuỗi ISO có múi giờ (Z) là UTC, còn "YYYY-MM-DD[ HH:mm]" naive đã là giờ VN. */
function vnMonthKey(dateValue) {
  const raw = String(dateValue || "");
  if (!raw) return "";
  const vnDay = /(Z|[+-]\d{2}:?\d{2})\s*$/i.test(raw) && !Number.isNaN(new Date(raw).getTime())
    ? new Date(new Date(raw).getTime() + 7 * 3600000).toISOString().slice(0, 10)
    : raw.slice(0, 10);
  return vnDay.slice(0, 7);
}

/** Tổng hợp công nợ một chi nhánh cho tháng chọn: đọc ledger finance đã sync (giống trang Phải thu).
 * Lớp thu tháng → phiếu có billKey chứa tháng (gộp nhiều tháng thì tính vào từng tháng được gộp);
 * lớp thu khóa → phiếu của khóa N đến hạn khi khóa N-1 kết thúc, tức tháng "khóa trước kết thúc"
 * (khóa 1 = tháng khai giảng). Phiếu phát hành sớm vẫn xếp về đúng tháng đến hạn. */
function branchTuitionSummary(branchId, month) {
  const sepay = sepayBook();
  const classes = (state.data.classes || []).filter((row) => row.branchId === branchId);
  const classIds = new Set(classes.map((row) => row.id));
  const classById = new Map((state.data.classes || []).map((row) => [row.id, row]));
  const studentIds = new Set((state.data.students || []).map((row) => row.id));
  const enrollment = classes.reduce((sum, row) => sum + (row.studentIds || []).filter((id) => studentIds.has(id)).length, 0);
  const courseWindowCache = new Map();
  const courseReceivableMonth = (row) => {
    const cls = classById.get(row.classId);
    if (!cls) return vnMonthKey(row.issueDate);
    const index = courseIndexOfBillKey(String(row.billKey || "")) || 1;
    const windowIndex = index > 1 ? index - 1 : 1;
    const cacheKey = `${row.classId}|${windowIndex}`;
    if (!courseWindowCache.has(cacheKey)) courseWindowCache.set(cacheKey, classCourseWindowByIndex(cls, windowIndex));
    const window = courseWindowCache.get(cacheKey);
    return vnMonthKey(index > 1 ? window?.end : window?.start) || vnMonthKey(row.issueDate);
  };
  const due = (sepay.receivables || []).filter((row) => {
    if (row.status === "CANCELLED" || !classIds.has(row.classId)) return false;
    const billKey = String(row.billKey || "");
    if (billKey.startsWith("month|") || billKey.startsWith("months|")) return billKey.split("|").slice(2).join("|").split(",").includes(month);
    return courseReceivableMonth(row) === month;
  }).reduce((sum, row) => sum + (Number(row.amountDue) || 0), 0);
  const receivableById = new Map((sepay.receivables || []).map((row) => [row.id, row]));
  const paymentById = new Map((sepay.payments || []).map((row) => [row.id, row]));
  let receiptCount = 0;
  let receiptTotal = 0;
  for (const receipt of sepay.receipts || []) {
    const payment = paymentById.get(receipt.paymentId);
    const receivable = payment ? receivableById.get(payment.receivableId) : null;
    const classId = receipt.classId || receivable?.classId;
    if (!classIds.has(classId) || vnMonthKey(receipt.issuedAt) !== month) continue;
    receiptCount += 1;
    receiptTotal += Number(receipt.amount) || 0;
  }
  // Đã xuất hóa đơn = số dòng doanh số (Quản lý doanh số) đã xuất của chi nhánh —
  // gồm cả 97 bạn T1–T5 xuất ngoài hệ thống, không phụ thuộc phiếu thu tháng.
  const invoiceRows = invoiceQueueRows().filter((row) => row.branchId === branchId);
  const invoiceCount = invoiceRows.filter((row) => invoiceRowStage(row) === "ISSUED").length;
  return {
    classCount: classes.length,
    enrollment,
    due,
    receiptCount,
    receiptTotal,
    invoiceCount,
    invoiceTotal: invoiceRows.length,
    remaining: due - receiptTotal,
  };
}

function branchPrettyName(branch) {
  const name = String(branch?.name || "").trim();
  const rest = name.replace(/^chi\s*nhánh\s*/i, "") || name;
  return rest.toLowerCase().replace(/(^|\s)(\S)/g, (_match, space, ch) => space + ch.toUpperCase()) || "—";
}

function branchTuitionTitle(branch) {
  return `Học phí chi nhánh ${branchPrettyName(branch)}`;
}

function dashboardOverview() {
  const branches = state.data.settings.branches || [];
  const cards = branches.map((branch) => {
    const month = dashboardBranchMonth(branch.id);
    const summary = branchTuitionSummary(branch.id, month);
    const options = branchTuitionMonthOptions().map((key) => `<option value="${key}" ${key === month ? "selected" : ""}>${escapeHtml(monthLabel(key))}</option>`).join("");
    const stat = (label, value, strong = false) => `<div class="dashboard-branch-stat${strong ? " is-strong" : ""}"><span>${label}</span><b>${value}</b></div>`;
    return `<section class="card dashboard-branch-card"><div class="card-header"><div><h2>${escapeHtml(branchTuitionTitle(branch))}</h2><p>Công nợ và tiền thu của ${escapeHtml(branchTuitionTitle(branch).replace("Học phí ", ""))}.</p></div><label class="field dashboard-branch-period"><span>Kỳ thu</span><select class="input" data-branch-tuition-month="${escapeHtml(branch.id)}">${options}</select></label></div><div class="dashboard-branch-stats">${stat("Số lớp", String(summary.classCount))}${stat("Tổng sĩ số", `${summary.enrollment} học viên`)}${stat("Công nợ phải thu tháng này", vnd(summary.due))}${stat("Đã thu", `${summary.receiptCount} phiếu — ${vnd(summary.receiptTotal)}`)}${stat("Đã xuất hoá đơn", `${summary.invoiceCount}/${summary.invoiceTotal} học viên`)}${stat("Còn lại", vnd(summary.remaining), true)}</div></section>`;
  }).join("");
  return `<div class="dashboard-branch-grid">${cards || `<section class="card"><div class="card-body"><p class="empty-cell">Chưa có chi nhánh nào.</p></div></section>`}</div>`;
}

function sessionRecurrenceKey(session) {
  return session?.recurrenceKey || `${session?.classId || ""}|${session?.date || ""}|${session?.startTime || ""}`;
}

function sessionAttendanceMarked(session) {
  const identity = sessionRecurrenceKey(session);
  const persisted = (state.data.lessonSessions || []).some((item) => item.id === session.id || sessionRecurrenceKey(item) === identity);
  return persisted && (session.status === "COMPLETED" || (session.attendance || []).some((item) => item.status));
}

function dashboardActivity(teacherView = false) {
  const today = localDateKey(new Date());
  const activeClasses = (teacherView ? teacherClasses() : (state.data.classes || [])).filter((cls) => cls.status === "ACTIVE");
  const scheduledRows = activeClasses.flatMap((cls) => classSessions(cls).map((session) => ({ cls, session })));
  const availableDates = [...new Set([today, ...scheduledRows.filter(({ session }) => session.date <= today).map(({ session }) => session.date)])]
    .sort((a, b) => b.localeCompare(a));
  const selectedDate = availableDates.includes(state.dashboardDate) ? state.dashboardDate : today;
  state.dashboardDate = selectedDate;
  const validStudentIds = new Set((state.data.students || []).map((item) => item.id));
  const rows = scheduledRows
    .filter(({ session }) => session.date === selectedDate)
    .sort((a, b) => `${a.session.startTime}|${a.cls.name}`.localeCompare(`${b.session.startTime}|${b.cls.name}`, "vi"));
  const body = rows.map(({ cls, session }, index) => {
    const studentCount = new Set((cls.studentIds || []).filter((id) => validStudentIds.has(id))).size;
    const marked = sessionAttendanceMarked(session);
    const branch = findBy(state.data.settings.branches, cls.branchId);
    const teacher = findBy(state.data.teachers, session.teacherId || cls.teacherId);
    const href = classHref(cls.id, "diem-danh", session.id, teacherView);
    const roster = (cls.studentIds || []).map((id) => findBy(state.data.students, id)).filter((student) => student && validStudentIds.has(student.id));
    const notice = marked ? attendanceNoticeText(session, roster) : "";
    const noticeHtml = notice ? `<small class="dashboard-attendance-note${attendanceNoticeComplete(session, roster) ? " is-complete" : ""}">${escapeHtml(notice)}</small>` : "";
    const classCell = `<button class="table-link dashboard-class-link" data-nav="${escapeHtml(href)}">${escapeHtml(cls.name)}</button>${noticeHtml}`;
    const attendance = session.isOff
      ? '<span class="badge badge-amber">Nghỉ học</span>'
      : `<button class="table-link dashboard-attendance-link" data-nav="${escapeHtml(href)}"><span class="badge badge-${marked ? "green" : "slate"}">${marked ? "Đã điểm danh" : "Chưa điểm danh"}</span></button>`;
    if (teacherView) {
      const completed = Boolean(session.isOff || marked);
      return `<tr><td class="cell-index">${index + 1}</td><td>${classCell}</td><td class="tabular dashboard-time">${escapeHtml(session.startTime)}–${escapeHtml(session.endTime)}</td><td>${escapeHtml(branch?.name || "—")}</td><td class="tabular">${studentCount}</td><td>${attendance}</td><td class="teacher-task-action"><button class="secondary-btn" data-nav="${escapeHtml(href)}">${completed ? "Xem lại" : "Điểm danh"}</button></td></tr>`;
    }
    return `<tr><td class="cell-index">${index + 1}</td><td>${classCell}</td><td class="tabular dashboard-time">${escapeHtml(session.startTime)}–${escapeHtml(session.endTime)}</td><td>${escapeHtml(branch?.name || "—")}</td><td>${escapeHtml(teacher?.fullName || "—")}</td><td class="tabular">${studentCount}</td><td>${attendance}</td></tr>`;
  }).join("");
  const dateOptions = availableDates.map((date) => `<option value="${date}" ${date === selectedDate ? "selected" : ""}>${date === today ? "Hôm nay · " : ""}${formatDateVi(date)}</option>`).join("");
  const heading = selectedDate === today ? "Điểm danh hôm nay" : "Điểm danh ngày";
  const empty = selectedDate === today ? (teacherView ? "Hôm nay không có lớp cần điểm danh." : "Hôm nay chưa có lớp học.") : `Ngày ${formatDateVi(selectedDate)} chưa có lớp học.`;
  const tableClass = teacherView ? "dashboard-activity-table teacher-task-table" : "dashboard-activity-table";
  const head = teacherView
    ? "<tr><th>STT</th><th>Lớp</th><th>Giờ</th><th>Chi nhánh</th><th>HV</th><th>Điểm danh</th><th>Thực hiện</th></tr>"
    : "<tr><th>STT</th><th>Lớp</th><th>Giờ</th><th>Chi nhánh</th><th>Giáo viên</th><th>HV</th><th>Điểm danh</th></tr>";
  return `<section class="card dashboard-activity-card${teacherView ? " teacher-task-card" : ""}"><div class="card-header"><div class="dashboard-activity-heading"><h2>${heading}</h2><p>${formatDateVi(selectedDate)}</p></div><label class="dashboard-activity-date"><span>Ngày điểm danh</span><select class="input" id="dashboard-activity-date">${dateOptions}</select></label></div><div class="table-wrap"><table class="${tableClass}"><thead>${head}</thead><tbody>${body || `<tr><td class="empty-cell" colspan="7">${empty}</td></tr>`}</tbody></table></div></section>`;
}

function sessionDurationMinutes(session) {
  const parse = (v) => { const [h, m] = String(v || "0:0").split(":").map(Number); return (h || 0) * 60 + (m || 0); };
  return Math.max(0, parse(session.endTime) - parse(session.startTime));
}

function dashboardMgmtData() {
  const today = localDateKey(new Date());
  const month = today.slice(0, 7);
  const classes = (state.data.classes || []).filter((cls) => cls.status === "ACTIVE");
  const past = classes.flatMap((cls) => classSessions(cls).filter((s) => s.date <= today).map((session) => ({ cls, session })));

  const teacherAgg = new Map();
  const attAgg = new Map();
  for (const { cls, session } of past) {
    const marked = sessionAttendanceMarked(session);
    const tid = session.teacherId || cls.teacherId || "";
    if (tid) {
      const e = teacherAgg.get(tid) || { total: 0, done: 0, mins: 0, monthMins: 0 };
      e.total += 1;
      if (marked || session.isOff) e.done += 1;
      if (marked && !session.isOff) {
        const m = sessionDurationMinutes(session);
        e.mins += m;
        if (session.date.startsWith(month)) e.monthMins += m;
      }
      teacherAgg.set(tid, e);
    }
    if (marked && !session.isOff) {
      const e = attAgg.get(cls.id) || { present: 0, total: 0, sessions: 0 };
      e.sessions += 1;
      for (const a of session.attendance || []) { e.total += 1; if (a.status === "PRESENT") e.present += 1; }
      attAgg.set(cls.id, e);
    }
  }
  const byClass = new Map();
  for (const r of sepayBook().receivables || []) {
    const e = byClass.get(r.classId || "") || { due: 0, paid: 0, bal: 0 };
    e.due += Number(r.amountDue) || 0;
    e.paid += Number(r.amountPaid) || 0;
    e.bal += Number(r.balanceDue) || 0;
    byClass.set(r.classId || "", e);
  }
  const teachers = (state.data.teachers || []).slice().sort((a, b) => a.fullName.localeCompare(b.fullName, "vi"));
  return { today, month, classes, teacherAgg, attAgg, byClass, teachers };
}

function mgmtPctBadge(done, total) {
  if (!total) return "—";
  const pct = Math.round((done / total) * 100);
  return `<span class="badge badge-${pct >= 90 ? "green" : pct >= 70 ? "amber" : "red"} tabular">${pct}%</span>`;
}

function mgmtCard(title, sub, head, body, colspan) {
  return `<section class="card dashboard-activity-card mgmt-card"><div class="card-header"><div><h2>${title}</h2><p>${sub}</p></div></div><div class="table-wrap"><table class="dashboard-activity-table mgmt-table"><thead>${head}</thead><tbody>${body || `<tr><td class="empty-cell" colspan="${colspan}">Chưa có dữ liệu.</td></tr>`}</tbody></table></div></section>`;
}

function dashboardKpiTab() {
  const { teacherAgg, teachers } = dashboardMgmtData();
  const rows = teachers.map((t, i) => {
    const e = teacherAgg.get(t.id) || { total: 0, done: 0 };
    return `<tr><td class="cell-index">${i + 1}</td><td>${escapeHtml(t.fullName)}</td><td class="tabular">${e.done}/${e.total} buổi</td><td>${mgmtPctBadge(e.done, e.total)}</td></tr>`;
  }).join("");
  return mgmtCard("KPI giáo viên", "Tỷ lệ buổi học đã điểm danh / tổng buổi đã qua đến hôm nay.", "<tr><th>STT</th><th>Giáo viên</th><th>Đã điểm danh</th><th>% hoàn thành</th></tr>", rows, 4);
}

function dashboardTuitionTab() {
  const { byClass } = dashboardMgmtData();
  const className = (id) => findBy(state.data.classes, id)?.name || "Không gắn lớp";
  const rows = [...byClass.entries()]
    .sort((a, b) => b[1].bal - a[1].bal || className(a[0]).localeCompare(className(b[0]), "vi"))
    .map(([classId, e], i) => `<tr><td class="cell-index">${i + 1}</td><td>${escapeHtml(className(classId))}</td><td class="tabular">${vnd(e.due)}</td><td class="tabular">${vnd(e.paid)}</td><td class="tabular${e.bal > 0 ? " text-red" : ""}">${vnd(e.bal)}</td></tr>`)
    .join("");
  const totals = [...byClass.values()].reduce((s, e) => ({ due: s.due + e.due, paid: s.paid + e.paid, bal: s.bal + e.bal }), { due: 0, paid: 0, bal: 0 });
  const foot = byClass.size ? `<tr class="mgmt-total-row"><td></td><td><strong>Tổng cộng</strong></td><td class="tabular"><strong>${vnd(totals.due)}</strong></td><td class="tabular"><strong>${vnd(totals.paid)}</strong></td><td class="tabular"><strong>${vnd(totals.bal)}</strong></td></tr>` : "";
  return mgmtCard("Học phí theo lớp", "Tổng học phí phải thu, đã thu và còn lại theo từng lớp.", "<tr><th>STT</th><th>Lớp</th><th>Tổng học phí</th><th>Đã thu</th><th>Còn lại</th></tr>", rows + foot, 5);
}

function dashboardTimesheetTab() {
  const { teacherAgg, teachers, month } = dashboardMgmtData();
  const fmtH = (m) => `${(m / 60).toLocaleString("vi-VN", { maximumFractionDigits: 1 })}h`;
  const rows = teachers.map((t, i) => {
    const e = teacherAgg.get(t.id) || { mins: 0, monthMins: 0 };
    return `<tr><td class="cell-index">${i + 1}</td><td>${escapeHtml(t.fullName)}</td><td class="tabular">${fmtH(e.monthMins)}</td><td class="tabular">${fmtH(e.mins)}</td></tr>`;
  }).join("");
  return mgmtCard("Chấm công giáo viên", `Thời gian dạy thực tế (buổi đã điểm danh). Tháng ${month.split("-").reverse().join("/")} và tổng tích lũy.`, "<tr><th>STT</th><th>Giáo viên</th><th>Tháng này</th><th>Tổng cộng</th></tr>", rows, 4);
}

function dashboardAttendanceTab() {
  const { attAgg, classes } = dashboardMgmtData();
  const rows = classes.slice().sort((a, b) => a.code.localeCompare(b.code, "vi")).map((cls, i) => {
    const e = attAgg.get(cls.id);
    return `<tr><td class="cell-index">${i + 1}</td><td>${escapeHtml(cls.name)}</td><td class="tabular">${e ? `${e.present}/${e.total}` : "—"}</td><td>${e ? mgmtPctBadge(e.present, e.total) : "—"}</td></tr>`;
  }).join("");
  return mgmtCard("Chuyên cần theo lớp", "Tỷ lệ học viên có mặt trên các buổi đã điểm danh.", "<tr><th>STT</th><th>Lớp</th><th>Có mặt</th><th>% chuyên cần</th></tr>", rows, 4);
}

/** Tháng của tab Bổ trợ: 09/2026 (app bắt đầu dùng) → 12/2027, mặc định tháng hiện tại (kẹp trong khoảng). */
const DASHBOARD_SUPPORT_MONTH_START = "2026-09";
const DASHBOARD_SUPPORT_MONTH_END = "2027-12";
function dashboardSupportMonthKey() {
  const raw = /^\d{4}-(0[1-9]|1[0-2])$/.test(String(state.dashboardSupportMonth || "")) ? state.dashboardSupportMonth : monthKey();
  return raw < DASHBOARD_SUPPORT_MONTH_START ? DASHBOARD_SUPPORT_MONTH_START : raw > DASHBOARD_SUPPORT_MONTH_END ? DASHBOARD_SUPPORT_MONTH_END : raw;
}

/**
 * Học viên được điểm danh "Vắng có phép" trong tháng — để xếp bổ trợ. Mỗi dòng một học viên
 * ở một lớp, ghi các ngày vắng. Không tính buổi cả lớp nghỉ / đã hủy (khi đó hệ thống tự ghi
 * vắng phép cho cả lớp, không phải học viên xin nghỉ).
 */
function dashboardSupportRows(month = dashboardSupportMonthKey(), classId = state.dashboardSupportClass) {
  const byKey = new Map();
  for (const session of state.data.lessonSessions || []) {
    if (!String(session.date || "").startsWith(month) || session.isOff || session.status === "CANCELLED") continue;
    if (classId && session.classId !== classId) continue;
    for (const entry of session.attendance || []) {
      if (entry?.status !== "EXCUSED") continue;
      const key = `${entry.studentId}|${session.classId}`;
      if (!byKey.has(key)) byKey.set(key, { student: findBy(state.data.students, entry.studentId), cls: findBy(state.data.classes, session.classId), studentId: entry.studentId, dates: [] });
      byKey.get(key).dates.push(session.date);
    }
  }
  return [...byKey.values()]
    .map((row) => ({ ...row, dates: [...new Set(row.dates)].sort() }))
    .sort((a, b) => String(a.cls?.code || "").localeCompare(String(b.cls?.code || ""), "vi", { numeric: true })
      || String(a.student?.fullName || "").localeCompare(String(b.student?.fullName || ""), "vi"));
}

function dashboardSupportTab() {
  const month = dashboardSupportMonthKey();
  const options = [];
  for (let key = DASHBOARD_SUPPORT_MONTH_START; key <= DASHBOARD_SUPPORT_MONTH_END && options.length < 60; key = shiftMonthKey(key, 1)) {
    options.push(`<option value="${key}" ${key === month ? "selected" : ""}>${escapeHtml(monthLabel(key))}</option>`);
  }
  const items = dashboardSupportRows(month);
  // Lọc lớp: chỉ liệt kê các lớp có học viên vắng có phép trong tháng (lớp đang chọn luôn giữ lại).
  const classIds = new Set(dashboardSupportRows(month, "").map((row) => row.cls?.id).filter(Boolean));
  if (state.dashboardSupportClass) classIds.add(state.dashboardSupportClass);
  const classOptions = (state.data.classes || []).filter((cls) => classIds.has(cls.id))
    .sort((a, b) => String(a.code || a.name).localeCompare(String(b.code || b.name), "vi", { numeric: true }))
    .map((cls) => `<option value="${escapeHtml(cls.id)}" ${state.dashboardSupportClass === cls.id ? "selected" : ""}>${escapeHtml(cls.name)}</option>`).join("");
  const rows = items.map((row, index) => `<tr><td class="cell-index">${index + 1}</td><td>${escapeHtml(row.student?.fullName || "Học viên đã xoá")}${row.student?.code ? `<small class="people-subline">${escapeHtml(row.student.code)}</small>` : ""}</td><td>${row.cls ? `<button class="table-link" data-nav="${classHref(row.cls.id)}">${escapeHtml(row.cls.name)}</button>` : "—"}</td><td>${row.dates.map((date) => escapeHtml(formatDateVi(date))).join(", ")}</td></tr>`).join("");
  const total = items.reduce((sum, row) => sum + row.dates.length, 0);
  return `<section class="card dashboard-activity-card"><div class="card-header"><div class="dashboard-activity-heading"><h2>Bổ trợ · Học viên vắng có phép</h2><p>${items.length} học viên · ${total} buổi vắng có phép trong ${escapeHtml(monthLabel(month))}. Không tính buổi cả lớp nghỉ.</p></div><div class="dashboard-support-tools"><label class="dashboard-activity-date"><span>Lớp</span><select class="input" id="dashboard-support-class"><option value="">Tất cả lớp</option>${classOptions}</select></label><label class="dashboard-activity-date"><span>Tháng</span><select class="input" id="dashboard-support-month">${options.join("")}</select></label><button class="secondary-btn" type="button" data-dashboard-support-pdf>${icon("download")}Xuất PDF</button></div></div><div class="table-wrap"><table class="dashboard-activity-table"><thead><tr><th>STT</th><th>Tên</th><th>Lớp</th><th>Ngày vắng</th></tr></thead><tbody>${rows || '<tr><td class="empty-cell" colspan="4">Không có học viên vắng có phép trong tháng này.</td></tr>'}</tbody></table></div></section>`;
}

/** Dữ liệu PDF "Học viên cần bổ trợ" theo đúng tháng + lớp đang lọc ở tab Bổ trợ. */
function dashboardSupportReportData(now = new Date()) {
  const month = dashboardSupportMonthKey();
  const cls = state.dashboardSupportClass ? findBy(state.data.classes, state.dashboardSupportClass) : null;
  const pad = (n) => String(n).padStart(2, "0");
  return {
    month: monthLabel(month),
    filter: cls ? `Lớp: ${cls.name}` : "Tất cả lớp",
    exportedAt: `${pad(now.getHours())}:${pad(now.getMinutes())} ${formatDateVi(now)}`,
    rows: dashboardSupportRows(month).map((row) => ({
      name: row.student?.fullName || "Học viên đã xoá", code: row.student?.code || "",
      className: row.cls?.name || "—", dates: row.dates.map((date) => formatDateVi(date)),
    })),
  };
}

async function exportDashboardSupportPdf(button) {
  if (button) button.disabled = true;
  try {
    const data = dashboardSupportReportData();
    const response = await fetch("/api/dashboard/support-pdf", {
      method: "POST",
      credentials: "same-origin",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data),
    });
    if (!response.ok) {
      const body = await response.json().catch(() => ({}));
      throw new Error(body.error || "Không tạo được PDF học viên cần bổ trợ.");
    }
    const blob = await response.blob();
    const match = /filename="([^"]+)"/.exec(response.headers.get("Content-Disposition") || "");
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = match?.[1] || "hoc-vien-can-bo-tro.pdf";
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(link.href), 1000);
    toast(`Đã xuất PDF (${data.rows.length} học viên).`);
  } catch (error) {
    toast(error.message || "Không xuất được PDF. Thử lại.");
  } finally {
    if (button) button.disabled = false;
  }
}

/**
 * Nhật ký điều chuyển học viên: chuyển lớp, xoá khỏi lớp (về Lớp chờ), xếp từ
 * Lớp chờ vào lớp mới. Dựng từ nhật ký hệ thống — worker đã ghi sẵn từng lần
 * xếp/gỡ học viên trong roster, nên tab này chỉ đọc, không ghi dữ liệu.
 */
const TRANSFER_LOG_FORMS = [
  { re: /^Chuyển lớp:\s*(.+?)\s*\(([^)]*)\)\s*—\s*(.+?)\s*→\s*(.+)$/, from: 3, to: 4 },
  { re: /^(?:Xoá|Gỡ)\s+(.+?)\s*\(([^)]*)\)\s*khỏi lớp\s*(.+?)\s*—\s*đưa về Lớp chờ\s*$/, from: 3, to: null },
  { re: /^Xếp\s+(.+?)\s*\(([^)]*)\)\s*vào lớp\s*(.+?)\s*—\s*từ Lớp chờ\s*$/, from: null, to: 3 },
];
const WAITING_CLASS_LABEL = "Lớp chờ";

function dashboardTransferRows() {
  const rows = [];
  for (const log of state.data.auditLogs || []) {
    if (log.entity !== "Student") continue;
    const summary = String(log.summary || "");
    for (const form of TRANSFER_LOG_FORMS) {
      const match = form.re.exec(summary);
      if (!match) continue;
      rows.push({
        at: String(log.createdAt || ""),
        studentId: String(log.entityId || ""),
        name: (match[1] || "").trim(),
        code: (match[2] || "").trim(),
        from: form.from ? (match[form.from] || "").trim() : WAITING_CLASS_LABEL,
        to: form.to ? (match[form.to] || "").trim() : WAITING_CLASS_LABEL,
      });
      break;
    }
  }
  return rows.sort((a, b) => b.at.localeCompare(a.at));
}

function dashboardTransferStamp(value) {
  const time = new Date(value);
  if (Number.isNaN(time.getTime())) return "—";
  return new Intl.DateTimeFormat("vi-VN", { timeZone: "Asia/Ho_Chi_Minh", day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit", hour12: false }).format(time);
}

function dashboardTransferTab() {
  const items = dashboardTransferRows();
  const rows = items.map((row, index) => {
    const student = row.studentId ? findBy(state.data.students, row.studentId) : null;
    const name = student
      ? `<button class="table-link" data-nav="${studentHref(row.studentId)}">${escapeHtml(row.name)}</button>`
      : escapeHtml(row.name || "Học viên đã xoá");
    return `<tr><td class="cell-index">${index + 1}</td><td>${name}${row.code ? `<small class="people-subline">${escapeHtml(row.code)}</small>` : ""}</td><td>${escapeHtml(row.from || "—")}</td><td>${escapeHtml(row.to || "—")}</td><td class="tabular">${escapeHtml(dashboardTransferStamp(row.at))}</td></tr>`;
  }).join("");
  return `<section class="card dashboard-activity-card"><div class="card-header"><div class="dashboard-activity-heading"><h2>Điều chuyển · Nhật ký chuyển lớp</h2><p>${items.length} lần điều chuyển — chuyển lớp, xoá khỏi lớp về Lớp chờ và xếp từ Lớp chờ vào lớp mới. Mới nhất trước, lấy từ nhật ký hệ thống.</p></div></div><div class="table-wrap"><table class="dashboard-activity-table dashboard-transfer-table"><thead><tr><th>STT</th><th>Học viên</th><th>Lớp cũ</th><th>Lớp mới</th><th>Thời gian</th></tr></thead><tbody>${rows || '<tr><td class="empty-cell" colspan="5">Chưa có lần điều chuyển nào được ghi nhận.</td></tr>'}</tbody></table></div></section>`;
}

/**
 * Lớp thu khóa có phiếu học phí khóa mới phát sinh trong tháng: khóa có buổi 1
 * rơi vào tháng hiện tại (cùng quy tắc doanh số theo tháng phát sinh). Trả về
 * { index, start } của khóa đó, hoặc null. Gồm cả khóa sắp bắt đầu cuối tháng.
 */
function classNewCourseThisMonth(cls, now = new Date()) {
  if (classBillingMode(cls) !== "COURSE" || cls.billingEnabled === false) return null;
  const month = monthKey(now);
  const last = classCurrentCourseIndex(cls, now) + 1;
  for (let index = 1; index <= last; index += 1) {
    const start = String(classCourseWindowByIndex(cls, index)?.start || "");
    if (start.slice(0, 7) === month) return { index, start };
    if (start.slice(0, 7) > month) break;
  }
  return null;
}

function dashboardScheduleTab() {
  const mode = state.dashboardScheduleMode === "COURSE" ? "COURSE" : "MONTHLY";
  const now = new Date();
  const rows = (state.data.classes || [])
    .filter((cls) => !isWaitingClass(cls) && classBillingMode(cls) === mode)
    .map((cls) => ({ cls, progress: classProgressCounts(cls), newCourse: mode === "COURSE" ? classNewCourseThisMonth(cls, now) : null }))
    // Sắp xếp lớp còn nhiều buổi nhất lên trước; lớp chưa có tiến độ xuống cuối.
    .sort((a, b) => (b.progress ? b.progress.total - b.progress.done : -1) - (a.progress ? a.progress.total - a.progress.done : -1)
      || a.cls.name.localeCompare(b.cls.name, "vi"))
    .map(({ cls, progress, newCourse }, index) => {
      const teacher = findBy(state.data.teachers, cls.teacherId);
      const bg = newCourse ? "#fee2e2" : "";
      const note = newCourse
        ? `<span style="color:#dc2626;font-size:11px;">Có phiếu HP khóa ${newCourse.index} trong tháng · bắt đầu ${formatDateVi(newCourse.start)}</span>`
        : "";
      return `<tr style="background:${bg}"><td class="cell-index">${index + 1}</td><td><button class="table-link" data-nav="/lop-hoc/${encodeURIComponent(cls.id)}">${escapeHtml(cls.name)}</button></td><td>${escapeHtml(teacher?.fullName || "—")}</td><td>${escapeHtml(classScheduleText(cls))}</td><td class="tabular">${progress ? `${progress.done}/${progress.total}` : "—"}${note ? ` ${note}` : ""}</td></tr>`;
    }).join("");
  return `<section class="card dashboard-activity-card"><div class="card-header"><div class="dashboard-activity-heading"><h2>Class Schedule</h2><p>Tiến độ buổi học theo lớp — lớp còn nhiều buổi xếp trước.</p></div><label class="dashboard-activity-date"><span>Hình thức thu</span><select class="input" id="dashboard-schedule-mode"><option value="MONTHLY" ${mode === "MONTHLY" ? "selected" : ""}>Theo tháng</option><option value="COURSE" ${mode === "COURSE" ? "selected" : ""}>Theo khóa</option></select></label></div><div class="table-wrap"><table class="dashboard-activity-table"><thead><tr><th>STT</th><th>Tên lớp</th><th>Giáo viên</th><th>Lịch học</th><th>Tiến độ</th></tr></thead><tbody>${rows || '<tr><td class="empty-cell" colspan="5">Không có lớp nào theo hình thức này.</td></tr>'}</tbody></table></div></section>`;
}

