const studentStatuses = {
  UNASSIGNED: "Chưa xếp lớp",
  STUDYING: "Đang học",
  STOPPED: "Nghỉ học",
};

/** "Lớp chờ" — lớp chứa học viên bị xoá khỏi lớp / chưa xếp lớp. */
function isWaitingClass(cls) {
  return cls?.id === "class-waiting" || String(cls?.name || "").trim() === "Lớp chờ";
}

function normalizePeopleSearch(value) {
  return String(value ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/đ/g, "d")
    .replace(/Đ/g, "D")
    .toLowerCase()
    .trim();
}

function staffLoginUsername(value) {
  return normalizePeopleSearch(value).replace(/[^a-z0-9]/g, "");
}

function filterStudents(students, query, status) {
  const normalizedQuery = normalizePeopleSearch(query);
  const normalizedStatus = String(status || "").trim().toUpperCase();
  return (Array.isArray(students) ? students : []).filter((item) => {
    const searchable = normalizePeopleSearch([
      item.code,
      item.fullName,
      item.phone,
      item.parentPhone1,
      item.parentPhone2,
      item.school,
      item.parentZalo,
      item.parentName,
      item.nationalId,
      item.address,
    ].filter(Boolean).join(" "));
    const matchesQuery = !normalizedQuery || searchable.includes(normalizedQuery);
    const matchesStatus = !normalizedStatus || String(item.status || "").toUpperCase() === normalizedStatus;
    return matchesQuery && matchesStatus;
  });
}

function peopleActions(kind, id) {
  if (isAuditor() && kind !== "students") return '<span class="muted">—</span>';
  return `<div class="row-actions settings-row-actions"><button class="mini-btn" title="Sửa" data-people-edit="${kind}|${escapeHtml(id)}">${icon("pencil")}</button><button class="trash-btn" title="Xóa" data-people-delete="${kind}|${escapeHtml(id)}">${icon("trash")}</button></div>`;
}

function peopleModalHtml(kind) {
  const modal = state.peopleModal;
  if (!modal || modal.kind !== kind) return "";
  const editing = Boolean(modal.id);
  if (kind === "students") {
    const row = state.data.students.find((item) => item.id === modal.id);
    const parentPhone1 = row?.parentPhone1 || row?.phone || row?.parentZalo || "";
    const parentPhone2 = row?.parentPhone2 || (row?.phone && row?.parentZalo && row.phone !== row.parentZalo ? row.parentZalo : "");
    return `<div class="modal-backdrop" data-action="close-people-modal"><div class="modal-card people-modal" data-people-modal-card><div class="modal-head"><div><h2>${editing ? "Sửa học viên" : "Thêm học viên"}</h2><p>Thông tin liên hệ và tình trạng học tập, không bao gồm học phí.</p></div><button class="close-btn" type="button" data-action="close-people-modal">×</button></div><form id="people-entity-form" data-kind="students" data-id="${escapeHtml(modal.id || "")}"><div class="form-grid"><label class="field"><span>Họ và tên</span><input class="input" name="fullName" value="${escapeHtml(row?.fullName || "")}" placeholder="Nguyễn Văn A" required autofocus /></label><label class="field"><span>Mã học viên</span><input class="input" name="code" value="${escapeHtml(row?.code || "")}" placeholder="Bỏ trống để tự sinh" /></label><label class="field"><span>SĐT thứ nhất</span><input class="input" name="parentPhone1" value="${escapeHtml(parentPhone1)}" placeholder="0900 000 000" /></label><label class="field"><span>SĐT thứ 2</span><input class="input" name="parentPhone2" value="${escapeHtml(parentPhone2)}" placeholder="0900 000 000" /></label><label class="field span-2"><span>Trường đang học</span><input class="input" name="school" value="${escapeHtml(row?.school || "")}" placeholder="Tên trường hiện tại" /></label><label class="field span-2"><span>Địa chỉ</span><input class="input" name="address" value="${escapeHtml(row?.address || "")}" placeholder="Số nhà, đường, phường, quận" /></label><label class="field span-2"><span>Tình trạng</span><select class="input" name="status">${Object.entries(studentStatuses).map(([value, label]) => `<option value="${value}" ${(row?.status || "UNASSIGNED") === value ? "selected" : ""}>${label}</option>`).join("")}</select></label></div><div class="settings-modal-footer"><button class="secondary-btn" type="button" data-action="close-people-modal">Hủy</button><button class="primary-btn" type="submit">${editing ? "Lưu" : "Thêm học viên"}</button></div></form></div></div>`;
  }
  if (kind === "assistants") {
    const row = (state.data.assistants || []).find((item) => item.id === modal.id);
    return `<div class="modal-backdrop" data-action="close-people-modal"><div class="modal-card people-modal" data-people-modal-card><div class="modal-head"><div><h2>${editing ? "Sửa trợ giảng" : "Thêm trợ giảng"}</h2><p>Chỉ họ và tên là bắt buộc. Các thông tin liên hệ có thể bổ sung sau.</p></div><button class="close-btn" type="button" data-action="close-people-modal">×</button></div><form id="people-entity-form" data-kind="assistants" data-id="${escapeHtml(modal.id || "")}" novalidate><div class="form-grid"><label class="field"><span>Họ và tên *</span><input class="input" name="fullName" value="${escapeHtml(row?.fullName || "")}" placeholder="Nguyễn Thị Hà" required autofocus /></label><label class="field"><span>Mã trợ giảng</span><input class="input" name="code" value="${escapeHtml(row?.code || "")}" placeholder="Bỏ trống để tự sinh" /></label><label class="field"><span>Số điện thoại</span><input class="input" name="phone" value="${escapeHtml(row?.phone || "")}" placeholder="0900 000 000" /></label><label class="field"><span>Email</span><input class="input" type="email" name="email" value="${escapeHtml(row?.email || "")}" placeholder="Không bắt buộc" /></label><label class="field span-2"><span>Địa chỉ</span><input class="input" name="address" value="${escapeHtml(row?.address || "")}" placeholder="Số nhà, đường, phường, quận" /></label></div><div class="settings-modal-footer"><button class="secondary-btn" type="button" data-action="close-people-modal">Hủy</button><button class="primary-btn" type="submit">${editing ? "Lưu" : "Thêm trợ giảng"}</button></div></form></div></div>`;
  }
  if (kind === "audits") {
    const row = (state.data.audits || []).find((item) => item.id === modal.id);
    return `<div class="modal-backdrop" data-action="close-people-modal"><div class="modal-card people-modal" data-people-modal-card><div class="modal-head"><div><h2>${editing ? "Sửa Audit" : "Thêm Audit"}</h2><p>Chỉ họ và tên là bắt buộc. Tên đăng nhập là họ tên viết liền không dấu.</p></div><button class="close-btn" type="button" data-action="close-people-modal">×</button></div><form id="people-entity-form" data-kind="audits" data-id="${escapeHtml(modal.id || "")}" novalidate><div class="form-grid"><label class="field"><span>Họ và tên *</span><input class="input" name="fullName" value="${escapeHtml(row?.fullName || "")}" placeholder="Nguyễn Thị Hà" required autofocus /></label><label class="field"><span>Mã Audit</span><input class="input" name="code" value="${escapeHtml(row?.code || "")}" placeholder="Bỏ trống để tự sinh" /></label><label class="field"><span>Số điện thoại</span><input class="input" name="phone" value="${escapeHtml(row?.phone || "")}" placeholder="0900 000 000" /></label><label class="field"><span>Email</span><input class="input" type="email" name="email" value="${escapeHtml(row?.email || "")}" placeholder="Không bắt buộc" /></label><label class="field span-2"><span>Địa chỉ</span><input class="input" name="address" value="${escapeHtml(row?.address || "")}" placeholder="Số nhà, đường, phường, quận" /></label></div><div class="settings-modal-footer"><button class="secondary-btn" type="button" data-action="close-people-modal">Hủy</button><button class="primary-btn" type="submit">${editing ? "Lưu" : "Thêm Audit"}</button></div></form></div></div>`;
  }
  if (kind === "accountants") {
    const row = (state.data.accountants || []).find((item) => item.id === modal.id);
    return `<div class="modal-backdrop" data-action="close-people-modal"><div class="modal-card people-modal" data-people-modal-card><div class="modal-head"><div><h2>${editing ? "Sửa kế toán" : "Thêm kế toán"}</h2><p>Chỉ họ và tên là bắt buộc. Các thông tin liên hệ có thể bổ sung sau.</p></div><button class="close-btn" type="button" data-action="close-people-modal">×</button></div><form id="people-entity-form" data-kind="accountants" data-id="${escapeHtml(modal.id || "")}" novalidate><div class="form-grid"><label class="field"><span>Họ và tên *</span><input class="input" name="fullName" value="${escapeHtml(row?.fullName || "")}" placeholder="Nguyễn Thị Hà" required autofocus /></label><label class="field"><span>Mã kế toán</span><input class="input" name="code" value="${escapeHtml(row?.code || "")}" placeholder="Bỏ trống để tự sinh" /></label><label class="field"><span>Số điện thoại</span><input class="input" name="phone" value="${escapeHtml(row?.phone || "")}" placeholder="0900 000 000" /></label><label class="field"><span>Email</span><input class="input" type="email" name="email" value="${escapeHtml(row?.email || "")}" placeholder="Không bắt buộc" /></label><label class="field span-2"><span>Địa chỉ</span><input class="input" name="address" value="${escapeHtml(row?.address || "")}" placeholder="Số nhà, đường, phường, quận" /></label></div><div class="settings-modal-footer"><button class="secondary-btn" type="button" data-action="close-people-modal">Hủy</button><button class="primary-btn" type="submit">${editing ? "Lưu" : "Thêm kế toán"}</button></div></form></div></div>`;
  }
  const row = state.data.teachers.find((item) => item.id === modal.id);
  return `<div class="modal-backdrop" data-action="close-people-modal"><div class="modal-card people-modal" data-people-modal-card><div class="modal-head"><div><h2>${editing ? "Sửa giáo viên" : "Thêm giáo viên"}</h2><p>Quản lý thông tin liên hệ và các lớp đang phụ trách.</p></div><button class="close-btn" type="button" data-action="close-people-modal">×</button></div><form id="people-entity-form" data-kind="teachers" data-id="${escapeHtml(modal.id || "")}"><div class="form-grid"><label class="field"><span>Họ và tên</span><input class="input" name="fullName" value="${escapeHtml(row?.fullName || "")}" placeholder="Trần Thị B" required autofocus /></label><label class="field"><span>Mã giáo viên</span><input class="input" name="code" value="${escapeHtml(row?.code || "")}" placeholder="Bỏ trống để tự sinh" /></label><label class="field"><span>Số điện thoại</span><input class="input" name="phone" value="${escapeHtml(row?.phone || "")}" placeholder="0900 000 000" /></label><label class="field"><span>Email</span><input class="input" type="email" name="email" value="${escapeHtml(row?.email || "")}" placeholder="giaovien@steps.edu.vn" required /></label><label class="field span-2"><span>Địa chỉ</span><input class="input" name="address" value="${escapeHtml(row?.address || "")}" placeholder="Số nhà, đường, phường, quận" /></label><label class="field span-2"><span>Lớp đang phụ trách</span><textarea class="input textarea" name="assignedClasses" placeholder="Mỗi lớp một dòng">${escapeHtml((row?.assignedClasses || []).join("\n"))}</textarea></label><label class="teacher-assistant-toggle span-2"><input type="checkbox" name="assistantAccess" ${row?.assistantAccess ? "checked" : ""} /><span><strong>Quyền trợ giảng</strong><small>Tick để giáo viên vào mọi lớp nhập điểm như trợ giảng.</small></span></label></div><div class="settings-modal-footer"><button class="secondary-btn" type="button" data-action="close-people-modal">Hủy</button><button class="primary-btn" type="submit">${editing ? "Lưu" : "Thêm giáo viên"}</button></div></form></div></div>`;
}

function studentsPage() {
  if (state.studentBranch && state.studentClass) {
    const sel = findBy(state.data.classes, state.studentClass);
    if (!sel || sel.branchId !== state.studentBranch) state.studentClass = "";
  }
  const items = filterStudents(state.data.students, state.peopleQuery, state.studentStatus).filter((item) => {
    if (!state.studentClass && !state.studentBranch) return true;
    const cls = studentClasses(item.id);
    if (state.studentClass === "__none__") return cls.length === 0;
    if (state.studentClass) return cls.some((c) => c.id === state.studentClass);
    return cls.some((c) => c.branchId === state.studentBranch);
  });
  const rows = items.map((item, index) => {
    const tone = item.status === "STUDYING" ? "green" : item.status === "STOPPED" ? "amber" : "blue";
    return `<tr><td class="cell-index">${index + 1}</td><td class="code">${escapeHtml(item.code)}</td><td><button class="table-link" data-nav="/hoc-vien/${encodeURIComponent(item.id)}">${escapeHtml(item.fullName)}</button></td><td>${escapeHtml(item.parentName || "—")}</td><td>${escapeHtml(item.parentZalo || "—")}</td><td>${escapeHtml(item.phone || "—")}</td><td><span class="badge badge-${tone}">${escapeHtml(studentStatuses[item.status] || item.status)}</span></td><td class="settings-actions-cell">${canDeleteRoster() ? `<div class="row-actions settings-row-actions"><button class="trash-btn" title="Xóa" data-people-delete="students|${escapeHtml(item.id)}">${icon("trash")}</button></div>` : "—"}</td></tr>`;
  }).join("");
  const classFilterOptions = state.data.classes
    .filter((c) => !state.studentBranch || c.branchId === state.studentBranch)
    .slice()
    .sort((a, b) => a.code.localeCompare(b.code, "vi"))
    .map((c) => `<option value="${escapeHtml(c.id)}" ${state.studentClass === c.id ? "selected" : ""}>${escapeHtml(c.code)} — ${escapeHtml(c.name)}</option>`)
    .join("");
  return `<div class="people-page"><div class="page-header"><div><h1>Học viên</h1><p>Thông tin liên hệ, trường đang học và tình trạng học tập của từng học viên.</p></div></div><section class="card settings-card"><div class="card-header people-card-header"><div class="card-heading"><div><h2>Danh sách học viên (${items.length})</h2><p>Bấm vào tên học viên để xem và cập nhật hồ sơ chi tiết.</p></div><div class="class-roster-actions"><button class="secondary-btn" type="button" data-students-export>${icon("download")}Xuất Excel</button>${canManageRoster() ? `<label class="secondary-btn student-import-btn">${icon("upload")}Nhập Excel<input id="student-import-file" type="file" accept=".xls,.xlsx,.csv" hidden></label>` : ""}${canAddStudent() ? `<button class="primary-btn" data-people-add="students">${icon("plus")}Thêm học viên</button>` : ""}</div></div><form id="student-filter-form" class="people-filters"><label class="field"><span>Tìm kiếm</span><input class="input" type="search" name="q" value="${escapeHtml(state.peopleQuery)}" autocomplete="off" placeholder="Tên, mã HV, SĐT, bố mẹ..." /></label><label class="field"><span>Tình trạng</span><select class="input" name="status"><option value="">Tất cả</option>${Object.entries(studentStatuses).map(([value, label]) => `<option value="${value}" ${state.studentStatus === value ? "selected" : ""}>${label}</option>`).join("")}</select></label><label class="field"><span>Chi nhánh</span><select class="input" name="branch"><option value="">Tất cả</option>${state.data.settings.branches.map((b) => `<option value="${escapeHtml(b.id)}" ${state.studentBranch === b.id ? "selected" : ""}>${escapeHtml(b.name)}</option>`).join("")}</select></label><label class="field"><span>Lớp</span><select class="input" name="classId"><option value="">Tất cả</option><option value="__none__" ${state.studentClass === "__none__" ? "selected" : ""}>Chưa xếp lớp</option>${classFilterOptions}</select></label></form></div><div class="table-wrap people-table"><table><thead><tr><th>STT</th><th>Mã HV</th><th>Tên HV</th><th>Bố mẹ</th><th>SĐT 1</th><th>SĐT 2</th><th>Tình trạng</th><th class="settings-actions-cell">Thao tác</th></tr></thead><tbody>${rows || '<tr><td class="empty-cell" colspan="8">Không có học viên phù hợp.</td></tr>'}</tbody></table></div></section>${peopleModalHtml("students")}${studentImportModalHtml()}</div>`;
}

/**
 * Popup Nhập Excel học viên: xem trước rồi mới ghi. Dữ liệu cũ luôn giữ — chỉ
 * điền ô đang trống và thêm học viên mới (Chưa xếp lớp); chỗ Excel ghi khác LMS
 * chỉ liệt kê để kiểm tra, không ghi đè.
 */
function studentImportModalHtml() {
  const modal = state.studentImport;
  if (!modal) return "";
  const close = `<button class="close-btn" type="button" data-student-import-close>×</button>`;
  const head = `<div class="modal-head"><div><h2>Nhập Excel học viên</h2><p>${escapeHtml(modal.fileName || "")} · Giữ nguyên dữ liệu cũ, chỉ điền ô đang trống và thêm học viên mới.</p></div>${close}</div>`;
  if (modal.busy === "preview" || !modal.preview) return `<div class="modal-backdrop"><div class="modal-card student-import-modal">${head}<div class="student-import-body"><p class="muted">Đang đọc file…</p></div></div></div>`;
  const p = modal.preview;
  const section = (title, count, body, tone = "") => `<details class="student-import-section ${tone}"${count && count <= 30 ? " open" : ""}><summary><strong>${title}</strong><span>${count}</span></summary>${body}</details>`;
  const created = p.created.map((row) => `<tr><td>${row.line}</td><td class="code">${escapeHtml(row.code)}</td><td>${escapeHtml(row.fullName)}</td><td>${escapeHtml(row.parentName || "—")}</td><td>${escapeHtml(row.phone || "—")}</td></tr>`).join("");
  const updated = p.updated.map((row) => `<tr><td>${row.line}</td><td class="code">${escapeHtml(row.code)}</td><td>${escapeHtml(row.fullName)}</td><td>${row.fields.map((item) => `<div><b>${escapeHtml(item.label)}:</b> ${escapeHtml(item.value)}</div>`).join("")}</td></tr>`).join("");
  const conflicts = p.conflicts.map((row) => `<tr><td>${row.line}</td><td class="code">${escapeHtml(row.code)}</td><td>${escapeHtml(row.fullName)}</td><td>${escapeHtml(row.label)}</td><td><b>${escapeHtml(row.lms)}</b></td><td class="muted">${escapeHtml(row.excel)}</td></tr>`).join("");
  const notes = [...p.errors.map((text) => `<li class="is-error">${escapeHtml(text)}</li>`), ...p.warnings.map((text) => `<li>${escapeHtml(text)}</li>`)].join("");
  const done = modal.done;
  const changes = p.created.length + p.updated.length;
  return `<div class="modal-backdrop"><div class="modal-card student-import-modal">${head}<div class="student-import-body">
    <div class="student-import-stats"><div><strong>${p.rows}</strong><small>Dòng trong file</small></div><div class="tone-green"><strong>${p.created.length}</strong><small>Học viên mới</small></div><div class="tone-blue"><strong>${p.updated.length}</strong><small>Bổ sung thông tin</small></div><div><strong>${p.unchanged}</strong><small>Không đổi</small></div><div class="tone-amber"><strong>${p.conflicts.length}</strong><small>Khác LMS (giữ LMS)</small></div></div>
    ${done ? `<p class="student-import-done">✓ Đã cập nhật: thêm ${p.created.length} học viên, bổ sung thông tin ${p.updated.length} học viên.</p>` : ""}
    ${notes ? `<ul class="student-import-notes">${notes}</ul>` : ""}
    ${p.created.length ? section("Học viên mới — tạo hồ sơ, vào Lớp chờ (Chưa xếp lớp)", p.created.length, `<div class="table-wrap"><table><thead><tr><th>Dòng</th><th>Mã HV</th><th>Tên học viên</th><th>Phụ huynh</th><th>SĐT</th></tr></thead><tbody>${created}</tbody></table></div>`, "tone-green") : ""}
    ${p.updated.length ? section("Bổ sung thông tin còn trống", p.updated.length, `<div class="table-wrap"><table><thead><tr><th>Dòng</th><th>Mã HV</th><th>Tên học viên</th><th>Thông tin điền thêm</th></tr></thead><tbody>${updated}</tbody></table></div>`, "tone-blue") : ""}
    ${p.conflicts.length ? section("Excel ghi khác LMS — giữ nguyên LMS, không ghi đè", p.conflicts.length, `<p class="muted">Nếu thông tin trong Excel mới đúng, anh sửa tay trong hồ sơ học viên.</p><div class="table-wrap"><table><thead><tr><th>Dòng</th><th>Mã HV</th><th>Tên học viên</th><th>Thông tin</th><th>LMS (giữ)</th><th>Excel</th></tr></thead><tbody>${conflicts}</tbody></table></div>`, "tone-amber") : ""}
    ${!changes && !done ? `<p class="student-import-done muted">File không có học viên mới hay thông tin nào cần bổ sung.</p>` : ""}
  </div><div class="settings-modal-footer"><button class="secondary-btn" type="button" data-student-import-close>${done ? "Đóng" : "Hủy"}</button>${done ? "" : `<button class="primary-btn" type="button" data-student-import-apply ${changes && !modal.busy ? "" : "disabled"}>${modal.busy === "apply" ? "Đang cập nhật…" : `Cập nhật ${changes} học viên`}</button>`}</div></div></div>`;
}

/** Xuất Excel toàn bộ học viên: STT · Mã HV · Tên · Phụ huynh · SĐT · CCCD · Địa chỉ. */
function exportStudentsExcel() {
  const students = state.data.students || [];
  if (!students.length) return toast("Chưa có học viên nào để xuất.");
  const text = (value) => `<td style="mso-number-format:'\\@'">${escapeHtml(String(value ?? ""))}</td>`;
  const phoneOf = (row) => {
    const first = String(row.parentPhone1 || row.phone || row.parentZalo || "").trim();
    const second = String(row.parentPhone2 || (row.phone && row.parentZalo && row.phone !== row.parentZalo ? row.parentZalo : "") || "").trim();
    return [first, second].filter((item, index, list) => item && list.indexOf(item) === index).join(" / ");
  };
  const rows = students.map((row, index) => {
    const classCodes = studentClasses(row.id).map((item) => item.code || item.name).filter(Boolean).join(", ");
    const parent = String(row.parentName || "").trim() || "Khách hàng chưa cung cấp thông tin";
    return `<tr><td>${index + 1}</td>${text(row.code)}${text(row.fullName)}${text(classCodes)}${text(parent)}${text(phoneOf(row))}${text(row.nationalId)}${text(row.address)}</tr>`;
  }).join("");
  const html = `<html xmlns:x="urn:schemas-microsoft-com:office:excel"><head><meta charset="UTF-8"><!--[if gte mso 9]><xml><x:ExcelWorkbook><x:ExcelWorksheets><x:ExcelWorksheet><x:Name>Danh sach hoc vien</x:Name><x:WorksheetOptions><x:DisplayGridlines/></x:WorksheetOptions></x:ExcelWorksheet></x:ExcelWorksheets></x:ExcelWorkbook></xml><![endif]--></head><body><table border="1"><thead><tr><th>STT</th><th>Mã HV</th><th>Tên học viên</th><th>Mã lớp</th><th>Tên phụ huynh</th><th>Số điện thoại</th><th>CCCD</th><th>Địa chỉ</th></tr></thead><tbody>${rows}</tbody></table></body></html>`;
  const blob = new Blob([html], { type: "application/vnd.ms-excel" });
  const link = document.createElement("a");
  link.href = URL.createObjectURL(blob);
  link.download = `DSHV-tat-ca-${localDateKey(new Date()).replace(/-/g, "")}.xls`;
  link.click();
  setTimeout(() => URL.revokeObjectURL(link.href), 1000);
  toast(`Đã xuất ${students.length} học viên.`);
}

// Chỉ mục + memo phục vụ tính toán: dựng lười một lần, tra cứu O(1) thay vì
// quét lại mảng lớn cho từng học viên. Tự vô hiệu khi mảng nguồn bị thay —
// mọi thao tác ghi đều gán mảng mới nên cache không đọc dữ liệu cũ.
const perf = { maps: null, refs: null, memo: new Map(), weak: new WeakMap(), active: false };
// Bộ đệm chỉ sống trong MỘT lượt render() (tạo đầu lượt, bỏ cuối lượt): bảng doanh số, chỉ mục buổi bù.
let invoiceQueueRenderCache = null;

function perfValid() {
  // Chỉ so tham chiếu — không tính là "trang đọc phần chưa tải".
  bootstrapRest.quiet += 1;
  let refs;
  try {
    refs = [
      state.data?.students, state.data?.classes, state.data?.lessonSessions,
      state.data?.zaloMessages, state.data?.finance, state.data?.settings,
      state.data?.teachers,
    ];
  } finally {
    bootstrapRest.quiet -= 1;
  }
  if (perf.refs && perf.refs.every((ref, index) => ref === refs[index])) return true;
  perf.refs = refs;
  perf.maps = null;
  perf.memo = new Map();
  perf.weak = new WeakMap();
  return false;
}

// Chỉ cache trong lúc render: các hàm được gọi trực tiếp từ handler (mở phiếu,
// xuất file…) phải đọc dữ liệu mới nhất kể cả khi có mutation tại chỗ.
function perfMemo(name, key, compute) {
  if (!perf.active) return compute();
  perfValid();
  const memoKey = `${name}|${key}`;
  if (perf.memo.has(memoKey)) return perf.memo.get(memoKey);
  const value = compute();
  perf.memo.set(memoKey, value);
  return value;
}

function perfMaps() {
  if (!perf.active) return perfBuildMaps();
  perfValid();
  if (!perf.maps) perf.maps = perfBuildMaps();
  return perf.maps;
}

function perfBuildMaps() {
  const sessions = state.data?.lessonSessions || [];
  const book = typeof sepayBook === "function" ? sepayBook() : {};
  const receivables = book.receivables || [];
  const receipts = book.receipts || [];
  const payments = book.payments || [];
  const maps = { sessions, claimedByClass: new Map() };
  maps.studentsById = new Map();
  for (const row of state.data?.students || []) maps.studentsById.set(row.id, row);
  maps.classesByStudent = new Map();
  for (const cls of state.data?.classes || []) {
    for (const studentId of cls.studentIds || []) {
      let list = maps.classesByStudent.get(studentId);
      if (!list) maps.classesByStudent.set(studentId, list = []);
      list.push(cls);
    }
  }
  maps.paymentsById = new Map();
  for (const row of payments) maps.paymentsById.set(row.id, row);
  maps.receivablesById = new Map();
  maps.receivablesByStudent = new Map();
  for (const row of receivables) {
    maps.receivablesById.set(row.id, row);
    let list = maps.receivablesByStudent.get(row.studentId);
    if (!list) maps.receivablesByStudent.set(row.studentId, list = []);
    list.push(row);
  }
  maps.receiptsByStudent = new Map();
  for (const row of receipts) {
    let list = maps.receiptsByStudent.get(row.studentId);
    if (!list) maps.receiptsByStudent.set(row.studentId, list = []);
    list.push(row);
  }
  maps.sessionsByClass = new Map();
  for (const row of sessions) {
    let list = maps.sessionsByClass.get(row.classId);
    if (!list) maps.sessionsByClass.set(row.classId, list = []);
    list.push(row);
  }
  // Dựng khi trang thật sự cần (tin Zalo có thể còn đang tải sau — xem bootstrapRest).
  let zaloByReceivable = null;
  Object.defineProperty(maps, "zaloByReceivable", {
    enumerable: true,
    get() {
      if (!zaloByReceivable) {
        zaloByReceivable = new Map();
        for (const row of state.data?.zaloMessages || []) {
          if (row.kind === "PAYMENT_REQUEST" && row.receivableId && !zaloByReceivable.has(row.receivableId)) zaloByReceivable.set(row.receivableId, row);
        }
      }
      return zaloByReceivable;
    },
  });
  return maps;
}

function perfStudentReceivables(studentId) {
  return perfMaps().receivablesByStudent.get(studentId) || [];
}

function perfStudentReceipts(studentId) {
  return perfMaps().receiptsByStudent.get(studentId) || [];
}

function perfClassSessions(classId) {
  return perfMaps().sessionsByClass.get(classId) || [];
}

// Bản ghi buổi của lớp gom theo ngày nhận suất — dựng một lần dùng chung cho
// mọi học viên của lớp (storedSessionsByClaimDate tự lọc theo classId).
function perfStoredByClaimDate(classId) {
  const maps = perfMaps();
  let map = maps.claimedByClass.get(classId);
  if (!map) {
    map = storedSessionsByClaimDate(maps.sessions, classId);
    maps.claimedByClass.set(classId, map);
  }
  return map;
}

// Chỉ memoize khi tham số sessions là đúng mảng state gốc — subset/synthetic
// sessions phải tính trực tiếp để giữ nguyên kết quả.
function perfDefaultSessions(sessions) {
  return sessions === perfMaps().sessions;
}

function studentClasses(studentId) {
  return perfMaps().classesByStudent.get(studentId) || [];
}

function completedClassSessions(cls) {
  return classSessions(cls).filter((item) => item.status === "COMPLETED" && !item.isOff).length;
}

function classElapsedCourseSessions(cls, now = new Date()) {
  return perfMemo("celapsed", `${cls?.id}|${localDateKey(now)}`, () => classElapsedCourseSessionsInner(cls, now));
}

function classElapsedCourseSessionsInner(cls, now = new Date()) {
  const startKey = classCourseStartDate(cls);
  const todayKey = localDateKey(now);
  if (startKey > todayKey) return 0;
  const explicit = perfClassSessions(cls.id);
  const storedByDate = perfStoredByClaimDate(cls.id);
  const seen = new Set();
  let count = 0;
  for (let cursor = localDate(startKey); localDateKey(cursor) < todayKey; cursor = addDays(cursor, 1)) {
    const date = localDateKey(cursor);
    const daySlots = (cls.schedules || []).filter((slot) => scheduleSlotAppliesOnDate(slot, date));
    if (!daySlots.length) continue;
    const { claimed } = claimDaySlots(daySlots, storedByDate.get(date) || []);
    for (const stored of claimed) {
      if (stored) seen.add(sessionIdentity(stored));
      // Buổi GV cho nghỉ không phải buổi đã học — khóa kéo dài để dạy bù. Buổi
      // "học không tính phí" cũng không đếm vào tiến độ tính phí của khóa.
      if (stored?.isOff || isNoFeeSession(stored)) continue;
      if (sessionChargesTuition(stored || { status: "COMPLETED", isOff: false })) count += 1;
    }
  }
  for (const session of explicit) {
    if (session.date < startKey || session.date > todayKey || seen.has(sessionIdentity(session))) continue;
    if (!session.isOff && sessionChargesTuition(session)) count += 1;
  }
  return count;
}

function tuitionExemptRemainingSessions(cls, now = new Date()) {
  const elapsed = classElapsedCourseSessions(cls, now);
  if (elapsed === 0) return classCourseSizeAt(cls, 1);
  const index = courseIndexAtSlotOrdinal(cls, elapsed);
  const used = elapsed - courseSlotOffsetBefore(cls, index);
  return used === 0 ? 0 : classCourseWindowSlotsAt(cls, index) - used;
}

function studentSessionRemaining(student, cls, now = new Date()) {
  const studentId = typeof student === "object" ? student?.id : student;
  return perfMemo("remaining", `${studentId}|${cls?.id}|${localDateKey(now)}`, () => studentSessionRemainingInner(student, cls, now));
}

function studentSessionRemainingInner(student, cls, now = new Date()) {
  if (student?.tuitionExempt) return tuitionExemptRemainingSessions(cls);
  if (classBillingMode(cls) === "COURSE" && student?.id) {
    // Tồn = buổi đã đóng của mọi khóa − buổi đã học từ khóa đầu tiên của học
    // viên (mirror courseRemainingSessions): sang khóa mới chưa đóng thì 0 rồi
    // âm dần, còn nợ khóa cũ thì âm thêm số buổi khóa cũ, đóng khóa nào +đủ khóa đó.
    const current = classCurrentCourseIndex(cls);
    const joinDate = studentClassJoinDate(student, cls.id);
    const first = studentFirstCourseIndex(student, cls);
    const legacyDebt = Math.min(0, Math.round(Number(student?.tuitionCredits?.[cls.id]) || 0));
    let last = Math.max(current, first);
    for (const receipt of perfStudentReceipts(student.id)) {
      if (receipt.studentId !== student.id || !receipt.classId || receiptClassId(receipt) !== cls.id) continue;
      if ((receipt.billingMode || "COURSE") !== "COURSE") continue;
      last = Math.max(last, receiptCourseIndex(receipt));
    }
    let paid = 0;
    for (let index = first; index <= last; index += 1) {
      const assumedSize = joinDate && index === first ? billedCourseSessions(cls, state.data.lessonSessions || [], index, joinDate) : undefined;
      const paidOfCourse = hasCourseWindowOverride(cls, index)
        ? Math.min(paidCourseSessions(student, cls, index, assumedSize), classCourseWindowSlotsAt(cls, index))
        : paidCourseSessions(student, cls, index, assumedSize);
      const coveredPaid = index <= current && isTransferCoveredCourse(student, cls, index) ? coveredCoursePaidSessions(student, cls, index) : 0;
      paid += Math.max(paidOfCourse, coveredPaid);
    }
    // Mỗi khóa tính tối đa đúng số buổi của khóa (mirror server).
    let charged = 0;
    for (let index = first; index <= current; index += 1) {
      const size = billedCourseSessions(cls, state.data.lessonSessions || [], index, index === first ? joinDate : undefined);
      charged += Math.min(chargedCourseSessions(student.id, cls, index, joinDate), size || Number.MAX_SAFE_INTEGER);
    }
    return paid - charged + legacyDebt;
  }
  if (!student?.id) return storedSessionBalance(student, cls);
  // Nợ cũ quy ra buổi: luôn trừ trong tồn kể cả sau khi đã đóng — các buổi đó
  // đã được học thật, khoản đóng chỉ bù lại số đã tiêu. Buổi đã qua của tháng
  // superseded không đếm nữa vì nghĩa vụ của nó nằm trong con số này.
  const price = classSessionPrice(cls);
  // Tháng neo nợ áp dụng khi tháng đó đã tới (đang sống) hoặc đã được đóng.
  const anchorMonths = new Set(paidSessionMonths(student, cls));
  for (let cursor = SESSION_BALANCE_EPOCH_MONTH; cursor <= monthKey(now); cursor = nextMonthKey(cursor)) {
    anchorMonths.add(cursor);
  }
  const debtSessions = price > 0
    ? Math.round(studentOldDebtAmount(student, cls, [...anchorMonths]) / price)
    : 0;
  return paidSessionsSinceSeptember(student, cls, now)
    - chargedMonthlySessions(student, cls, now, studentClassJoinDate(student, cls.id))
    - debtSessions;
}

/** Số buổi tồn thô trong dữ liệu, chỉ dùng khi chưa biết học viên là ai. */
function storedSessionBalance(student, cls) {
  const stored = student?.sessionBalances?.[cls.id];
  if (stored === undefined || stored === null || String(stored) === "") return 0;
  return Math.round(Number(stored) || 0);
}

/**
 * Bản sao của monthlyElapsedSessions trong cloudflare/tuition-billing.ts:
 * buổi theo thời khóa biểu đã qua vẫn coi như đã dạy dù chưa ai điểm danh.
 */
function monthlyElapsedSessions(cls, now = new Date()) {
  return perfMemo("melapsed", `${cls?.id}|${localDateKey(now)}`, () => monthlyElapsedSessionsInner(cls, now));
}

function monthlyElapsedSessionsInner(cls, now = new Date()) {
  const todayKey = localDateKey(now);
  const storedByDate = perfStoredByClaimDate(cls.id);
  const rows = [];
  for (let cursor = localDate(LESSON_SCHEDULE_START); localDateKey(cursor) < todayKey; cursor = addDays(cursor, 1)) {
    const date = localDateKey(cursor);
    const daySlots = (cls.schedules || []).filter((slot) => scheduleSlotAppliesOnDate(slot, date));
    if (!daySlots.length) continue;
    const { claimed } = claimDaySlots(daySlots, storedByDate.get(date) || []);
    for (let index = 0; index < daySlots.length; index += 1) {
      const slot = daySlots[index];
      const stored = claimed[index];
      const recurrenceKey = `${cls.id}|${date}|${slot.startTime}`;
      rows.push(stored || {
        id: `recurring|${recurrenceKey}`,
        classId: cls.id,
        date,
        startTime: slot.startTime,
        endTime: slot.endTime,
        teacherId: cls.teacherId,
        roomId: cls.roomId,
        status: "COMPLETED",
        isExtra: false,
        recurrenceKey,
        isOff: false,
        attendance: [],
      });
    }
  }
  return rows;
}

/** Bản sao của chargedMonthlySessions: buổi đã tính phí của lớp thu tháng.
 * Học viên vào lớp giữa tháng (joinDate) không bị tính buổi trước ngày vào. */
function chargedMonthlySessions(student, cls, now = new Date(), joinDate) {
  const studentId = typeof student === "string" ? student : student?.id;
  return perfMemo("cmonth", `${typeof student === "string" ? "s" : "o"}:${studentId}|${cls?.id}|${localDateKey(now)}|${joinDate ?? ""}`, () => chargedMonthlySessionsInner(student, cls, now, joinDate));
}

function chargedMonthlySessionsInner(student, cls, now = new Date(), joinDate) {
  const studentId = typeof student === "string" ? student : student?.id;
  if (!studentId || !cls) return 0;
  const sessions = perfClassSessions(cls.id);
  const generated = monthlyElapsedSessions(cls, now);
  const seen = new Set(generated.map((item) => sessionIdentity(item)));
  // Buổi của tháng đã được dòng nợ cũ thay thế không đếm nữa — nghĩa vụ của
  // nó nằm trong phần nợ quy ra buổi, đếm tiếp sẽ thu kép.
  const chargeable = (session) => typeof student === "string"
    || !supersededDebtMonth(student, cls, String(session.date || "").slice(0, 7));
  let count = 0;
  for (const session of generated) {
    if (!sessionWithinJoinRule(session, joinDate) || !chargeable(session)) continue;
    if (!sessionChargesTuition(session) || !sessionStudentIds(session, cls).has(studentId)) continue;
    count += 1;
  }
  for (const session of sessions) {
    if (session.classId !== cls.id || session.date < LESSON_SCHEDULE_START) continue;
    if (!sessionWithinJoinRule(session, joinDate) || !chargeable(session)) continue;
    if (seen.has(sessionIdentity(session))) continue;
    // Buổi dạy bù học lại đúng buổi nghỉ — buổi nghỉ đã trừ tồn, không trừ lần hai.
    if (session.makeupOf) continue;
    if (!sessionChargesTuition(session) || !sessionStudentIds(session, cls).has(studentId)) continue;
    count += 1;
  }
  return count;
}

/** Tháng đã được thu học phí: mốc paidThrough + tháng ghi trên biên lai. Bản sao tuition-billing. */
function paidSessionMonths(student, cls) {
  return perfMemo("paidmonths", `${student?.id}|${cls?.id}`, () => paidSessionMonthsInner(student, cls));
}

function paidSessionMonthsInner(student, cls) {
  const months = new Set();
  const paidThrough = effectivePaidThrough(student, cls, student.tuitionPaidThrough?.[cls.id]);
  if (/^\d{4}-(0[1-9]|1[0-2])$/.test(String(paidThrough || "")) && paidThrough >= SESSION_BALANCE_EPOCH_MONTH) {
    let cursor = SESSION_BALANCE_EPOCH_MONTH;
    while (cursor <= paidThrough) {
      months.add(cursor);
      cursor = nextMonthKey(cursor);
    }
  }
  for (const receipt of perfStudentReceipts(student.id)) {
    if (receipt.studentId !== student.id || receiptClassId(receipt) !== cls.id) continue;
    if ((receipt.billingMode || classBillingMode(cls)) === "COURSE") continue;
    for (const match of String(receipt.billingPeriod || "").matchAll(/Tháng\s+(0[1-9]|1[0-2])\/(\d{4})/g)) {
      const key = `${match[2]}-${match[1]}`;
      if (key >= SESSION_BALANCE_EPOCH_MONTH) months.add(key);
    }
  }
  return months;
}

/** Bản sao của paidSessionsSinceSeptember: số buổi học phí đã thu từ 01/09. */
function paidSessionsSinceSeptember(student, cls, now = new Date()) {
  return perfMemo("paidsince", `${student?.id}|${cls?.id}|${localDateKey(now)}`, () => paidSessionsSinceSeptemberInner(student, cls, now));
}

function paidSessionsSinceSeptemberInner(student, cls, now = new Date()) {
  const months = paidSessionMonths(student, cls);
  const oldDebtSplit = hasOldDebtBill(student.id, cls.id);
  let extraPaid = 0;
  const price = classSessionPrice(cls);
  for (const receipt of perfStudentReceipts(student.id)) {
    if (receipt.studentId !== student.id || receiptClassId(receipt) !== cls.id) continue;
    if ((receipt.billingMode || classBillingMode(cls)) === "COURSE") {
      extraPaid += price > 0 ? Math.round(receiptTuitionAmount(receipt, joinExcessIndex().byPayment.get(receipt.paymentId) || 0) / price) : classCourseSizeAt(cls, receiptCourseIndex(receipt) || 1);
      continue;
    }
    // Biên lai gắn tháng đã nằm trong `months` — không cộng lại theo số tiền.
    if ([...String(receipt.billingPeriod || "").matchAll(/Tháng\s+(0[1-9]|1[0-2])\/(\d{4})/g)]
      .map((match) => `${match[2]}-${match[1]}`)
      .some((key) => key >= SESSION_BALANCE_EPOCH_MONTH)) continue;
    if ((receipt.issuedAt || "") >= LESSON_SCHEDULE_START && price > 0) extraPaid += Math.round(receiptTuitionAmount(receipt) / price);
  }
  // Mốc vào lớp: tháng trước ngày vào không tính; tháng vào chỉ tính các buổi
  // kể từ ngày nhập học (phiếu tháng đó ra ngay, không hoãn).
  const joinDate = studentClassJoinDate(student, cls.id);
  const joinMonth = joinDate?.slice(0, 7);
  return extraPaid + [...months].reduce((sum, key) => {
    if (joinMonth && key < joinMonth) return sum;
    // Tháng đã nhập vào dòng nợ cũ: buổi của nó nằm trong debtSessions của tháng
    // neo nợ, không cộng buổi theo lịch nữa.
    if (supersededDebtMonth(student, cls, key)) return sum;
    // Phiếu gộp nợ cũ (vd 750k = 8 buổi tháng + 7 buổi nợ): khi tháng neo đã
    // đóng thì phần nợ cũng đã được trả — cộng thêm vào buổi đã thu.
    // Đã tách phiếu nợ cũ riêng: phần nợ trả qua biên lai của phiếu đó (cộng theo tiền ở extraPaid).
    const debtPaid = price > 0 && !oldDebtSplit ? Math.round(studentOldDebtAmount(student, cls, [key]) / price) : 0;
    return sum + billedMonthSessions(cls, state.data?.lessonSessions || [], key, key === joinMonth ? joinDate : undefined) + debtPaid;
  }, 0);
}

function studentHref(id, tab = "info") {
  return tab === "hoat-dong" ? `/hoc-vien/${encodeURIComponent(id)}/hoat-dong` : `/hoc-vien/${encodeURIComponent(id)}`;
}

function mergeStudent(row, patch) {
  return {
    id: patch.id || row.id,
    code: patch.code ?? row.code,
    fullName: patch.fullName ?? row.fullName,
    phone: patch.phone ?? row.phone ?? "",
    address: patch.address ?? row.address ?? "",
    school: patch.school ?? row.school ?? "",
    parentZalo: patch.parentZalo ?? row.parentZalo ?? "",
    parentPhone1: patch.parentPhone1 ?? row.parentPhone1 ?? row.phone ?? row.parentZalo ?? "",
    parentPhone2: patch.parentPhone2 ?? row.parentPhone2 ?? "",
    status: patch.status ?? row.status ?? "UNASSIGNED",
    dateOfBirth: patch.dateOfBirth ?? row.dateOfBirth ?? "",
    parentName: patch.parentName ?? row.parentName ?? "",
    nationalId: patch.nationalId ?? row.nationalId ?? "",
    note: patch.note ?? row.note ?? "",
    loginEmail: patch.loginEmail ?? row.loginEmail ?? "",
    loginPassword: patch.loginPassword ?? row.loginPassword ?? "",
    tuitionExempt: patch.tuitionExempt ?? row.tuitionExempt ?? false,
    sessionBalances: { ...(row.sessionBalances || {}), ...(patch.sessionBalances || {}) },
    tuitionCredits: { ...(row.tuitionCredits || {}), ...(patch.tuitionCredits || {}) },
    tuitionPaidThrough: { ...(row.tuitionPaidThrough || {}), ...(patch.tuitionPaidThrough || {}) },
    classJoinedAt: { ...(row.classJoinedAt || {}), ...(patch.classJoinedAt || {}) },
  };
}

function studentActivities(row) {
  const items = studentClasses(row.id).map((cls) => ({
    at: "",
    label: "Nhập học",
    tone: "green",
    classId: cls.id,
    className: cls.name,
    detail: cls.code,
    receiptId: "",
  }));
  for (const log of state.data.auditLogs || []) {
    const match = log.entity === "Student" && (log.entityId === row.id || String(log.summary || "").includes(row.fullName));
    if (!match) continue;
    if (/đóng học phí/i.test(log.summary || "")) continue;
    items.push({
      at: log.createdAt,
      label: auditActionLabels[log.action] || log.action,
      tone: log.action === "DELETE" ? "red" : log.action === "CREATE" ? "green" : "blue",
      classId: "",
      className: "",
      detail: [log.summary || "—", ...(Array.isArray(log.details) ? log.details.slice(0, 6).map((item) => `${item.label}: ${item.from || "(trống)"} → ${item.to || "(trống)"}`) : [])].join(" · "),
      receiptId: "",
    });
  }
  const sepay = sepayBook();
  for (const receipt of sepay.receipts || []) {
    if (receipt.studentId !== row.id) continue;
    if (!financeHistoryVisible(receipt.issuedAt)) continue;
    const payment = (sepay.payments || []).find((item) => item.id === receipt.paymentId);
    const receivable = payment ? sepay.receivables.find((item) => item.id === payment.receivableId) : null;
    const cls = findBy(state.data.classes, receipt.classId || receivable?.classId);
    const method = receipt.method || payment?.method || "Chuyển khoản";
    const className = receipt.className || cls?.name || "";
    const period = String(receipt.billingPeriod || receivable?.billingPeriod || "").replace(className ? new RegExp(`\\s*·\\s*${className.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}$`) : /$^/, "");
    items.push({
      at: receipt.issuedAt || payment?.paidAt || "",
      label: "Đóng học phí",
      tone: "green",
      classId: cls?.id || receipt.classId || "",
      className,
      detail: [period, vnd(receipt.amount), method].filter(Boolean).join(" · "),
      receiptId: receipt.id,
    });
  }
  return items.sort((a, b) => String(b.at).localeCompare(String(a.at)));
}

function classBillingLabel(cls) {
  return classBillingMode(cls) === "MONTHLY" ? "Theo tháng" : "Theo khóa 24 buổi";
}

function studentBillingLabel(classes, student) {
  if (student?.tuitionExempt) return "Miễn học phí";
  if (!classes.length) return "—";
  const labels = [...new Set(classes.map(classBillingLabel))];
  return labels.join(" · ");
}

function studentActivityTab(row) {
  const items = studentActivities(row);
  const rows = items.map((item, index) => `<tr>
    <td class="cell-index">${index + 1}</td>
    <td>${item.at ? escapeHtml(new Intl.DateTimeFormat("vi-VN", { dateStyle: "short" }).format(new Date(item.at))) : "—"}</td>
    <td><span class="badge badge-${item.tone === "green" ? "green" : item.tone === "red" ? "red" : "blue"}">${escapeHtml(item.label)}</span></td>
    <td>${item.classId ? `<button class="table-link" data-nav="/lop-hoc/${encodeURIComponent(item.classId)}">${escapeHtml(item.className)}</button>${item.detail ? ` · ${escapeHtml(item.detail)}` : ""}` : escapeHtml(item.detail || "—")}</td>
    <td class="settings-actions-cell">${item.receiptId ? `<button class="secondary-btn" type="button" data-receipt-print="${escapeHtml(item.receiptId)}">${icon("download")}Tải biên lai PDF</button>` : "—"}</td>
  </tr>`).join("");
  return `<section class="card nz-student-card">
    <div class="card-header"><div><h2>Lịch sử hoạt động (${items.length})</h2><p>Ghi danh, đóng học phí và các lần sửa hồ sơ — mới nhất ở trên.</p></div></div>
    <div class="table-wrap"><table><thead><tr><th>STT</th><th>Ngày</th><th>Hoạt động</th><th>Chi tiết</th><th class="settings-actions-cell">Biên lai</th></tr></thead><tbody>${rows || '<tr><td class="empty-cell" colspan="5">Chưa có hoạt động nào được ghi nhận.</td></tr>'}</tbody></table></div>
  </section>`;
}

function studentInfoTab(row) {
  const classes = studentClasses(row.id);
  const classLabel = classes.map((item) => item.name).join(", ") || "—";
  const parentPhone1 = row.parentPhone1 || row.phone || row.parentZalo || "";
  const parentPhone2 = row.parentPhone2 || (row.phone && row.parentZalo && row.phone !== row.parentZalo ? row.parentZalo : "");
  const hasLogin = Boolean(row.loginEmail);
  const lock = canEditStudentProfile() ? "" : " disabled";
  const statusOptions = Object.entries(studentStatuses).map(([value, label]) => `<option value="${value}" ${row.status === value ? "selected" : ""}>${label}</option>`).join("");
  const billedClasses = classes.filter((cls) => !isWaitingClass(cls));
  const remainingFields = billedClasses.length
    ? billedClasses.map((cls) => {
      const hint = classBillingMode(cls) === "COURSE"
        ? "Buổi đã thu trừ buổi theo lịch đã dạy"
        : "Buổi học phí đã thu trừ buổi theo lịch đã dạy";
      return `<label class="field"><span>${billedClasses.length > 1 ? `Số buổi tồn · ${escapeHtml(cls.name)}` : "Số buổi tồn"}</span><input class="input" type="number" value="${studentSessionRemaining(row, cls)}" disabled readonly /><small class="field-hint">${hint}</small></label>`;
    }).join("")
    : `<label class="field"><span>Số buổi tồn</span><input class="input" value="—" disabled readonly /></label>`;
  return `<section class="card nz-student-card"><div class="nz-student-body">
    <div class="nz-student-profile">
      <p class="nz-section-label">Hồ sơ</p>
      <form id="student-profile-form" data-id="${escapeHtml(row.id)}" class="nz-student-form">
        <input type="hidden" name="school" value="${escapeHtml(row.school || "")}" />
        <label class="field"><span>Họ và tên</span><input class="input" name="fullName" value="${escapeHtml(row.fullName)}" required${lock} /></label>
        <label class="field"><span>Mã học viên</span><input class="input" name="code" value="${escapeHtml(row.code)}" required${lock} /></label>
        <label class="field"><span>Ngày sinh</span><input class="input" name="dateOfBirth" type="date" value="${escapeHtml(row.dateOfBirth || "")}"${lock} /></label>
        <label class="field"><span>Trạng thái</span><select class="input" name="status"${lock}>${statusOptions}</select></label>
        <label class="field"><span>Lớp đang học</span><input class="input" value="${escapeHtml(classLabel)}" disabled readonly /></label>
        <label class="field"><span>Học phí</span><input class="input" value="${escapeHtml(studentBillingLabel(classes, row))}" disabled readonly /></label>
        <label class="field"><span>SĐT thứ nhất</span><input class="input" name="parentPhone1" value="${escapeHtml(parentPhone1)}" placeholder="0900 000 000"${lock} /></label>
        <label class="field"><span>SĐT thứ 2</span><input class="input" name="parentPhone2" value="${escapeHtml(parentPhone2)}" placeholder="0900 000 000"${lock} /></label>
        <label class="field"><span>Tên phụ huynh</span><input class="input" name="parentName" value="${escapeHtml(row.parentName || "")}"${lock} /></label>
        <label class="field"><span>CCCD / MST phụ huynh</span><input class="input" name="nationalId" value="${escapeHtml(row.nationalId || "")}" inputmode="numeric"${lock} /><small>Của người đóng tiền: CCCD 12 số hoặc mã số thuế 10/13 số. Dùng để xuất hóa đơn.</small></label>
        <label class="field"><span>Địa chỉ</span><input class="input" name="address" value="${escapeHtml(row.address || "")}" placeholder="Số nhà, đường, phường, quận"${lock} /></label>
        <label class="field"><span>Ghi chú</span><input class="input" name="note" value="${escapeHtml(row.note || "")}"${lock} /></label>
        ${remainingFields}
        <label class="tuition-exempt-field"><input type="checkbox" name="tuitionExempt" ${row.tuitionExempt ? "checked" : ""} ${canManageRoster() ? "" : "disabled"} /><span>Miễn học phí</span></label>
        ${canEditStudentProfile() ? `<div class="nz-student-save"><button class="primary-btn" type="submit">Lưu hồ sơ</button></div>` : ""}
      </form>
      <div class="nz-student-account">
        <p class="nz-section-label">Tài khoản đăng nhập</p>
        <form id="student-account-form" data-id="${escapeHtml(row.id)}" class="nz-student-form">
          <label class="field"><span>Email đăng nhập</span><input class="input" name="loginEmail" type="email" value="${escapeHtml(row.loginEmail || "")}" placeholder="hocvien@steps.edu.vn" required${lock} /></label>
          ${hasLogin
            ? `<label class="field"><span>Mật khẩu mới</span><input class="input" name="loginPassword" type="password" minlength="8" autocomplete="new-password" placeholder="Để trống nếu không đổi"${lock} /></label>`
            : `<label class="field"><span>Mật khẩu</span><input class="input" name="loginPassword" type="password" minlength="8" autocomplete="new-password" placeholder="Tối thiểu 8 ký tự" required${lock} /></label>`}
          ${canEditStudentProfile() ? `<div class="nz-student-save"><button class="primary-btn" type="submit">${hasLogin ? "Lưu tài khoản" : "Tạo tài khoản"}</button></div>` : ""}
        </form>
      </div>
    </div>
  </div></section>`;
}

function studentDetailPage(row, tab = "info") {
  const classes = studentClasses(row.id);
  const enrollments = classes.length;
  return `<div class="nz-student-page">
    <button class="back-link" data-nav="/hoc-vien">← Danh sách học viên</button>
    <div class="page-header">
      <div><h1>${escapeHtml(row.fullName)}</h1><p>Mã ${escapeHtml(row.code)} · ${classes.length} lớp đang học · ${enrollments} lần ghi danh</p></div>
      ${canDeleteRoster() ? `<div class="page-actions"><button class="danger-btn" data-people-delete="students|${escapeHtml(row.id)}">${icon("trash")}Xóa</button></div>` : ""}
    </div>
    <nav class="nz-class-tabs">
      <button class="nz-tab ${tab === "info" ? "active" : ""}" data-nav="${studentHref(row.id)}">Thông tin học viên</button>
      <button class="nz-tab ${tab === "hoat-dong" ? "active" : ""}" data-nav="${studentHref(row.id, "hoat-dong")}">Lịch sử hoạt động</button>
    </nav>
    ${tab === "hoat-dong" ? studentActivityTab(row) : studentInfoTab(row)}
  </div>`;
}

function teachersPage() {
  const query = state.peopleQuery.trim().toLowerCase(); const items = state.data.teachers.filter((item) => !query || `${item.code} ${item.fullName} ${item.phone} ${item.assignedClasses.join(" ")}`.toLowerCase().includes(query));
  const rows = items.map((item, index) => {
    const contract = payrollContract(item.id);
    const kind = payrollContractKind(contract);
    const status = payrollContractStatus(contract);
    const hasContract = Boolean(contract.contractKind || contract.contractType || contract.salaryCoefficient);
    const contractCell = hasContract
      ? `${escapeHtml(PAYROLL_CONTRACT_KIND_LABELS[kind])}<small class="people-subline">${payrollPayMode(contract) === "MONTHLY" ? "Lương tháng" : "Theo giờ"} · ${escapeHtml(PAYROLL_CONTRACT_STATUS_LABELS[status])}</small>`
      : '<span class="muted">Chưa cấu hình</span>';
    const actionButtons = `${isAuditor() ? "" : `<button class="mini-btn" title="In hợp đồng" data-print-contract="${escapeHtml(item.id)}">${icon("printer")}</button>`}${canEditTeachers() ? `<button class="mini-btn" title="Sửa" data-people-edit="teachers|${escapeHtml(item.id)}">${icon("pencil")}</button>` : ""}${isSuperAdmin() ? `<button class="trash-btn" title="Xóa" data-people-delete="teachers|${escapeHtml(item.id)}">${icon("trash")}</button>` : ""}`;
    const actions = actionButtons ? `<div class="row-actions settings-row-actions">${actionButtons}</div>` : '<span class="muted">—</span>';
    const assistantBadge = teacherHasAssistantAccess(item) ? ' <span class="badge badge-blue" title="Được nhập điểm mọi lớp như trợ giảng">Trợ giảng</span>' : "";
    return `<tr><td class="cell-index">${index + 1}</td><td class="code">${escapeHtml(item.code)}</td><td><button class="table-link" data-nav="/giao-vien/${encodeURIComponent(item.id)}">${escapeHtml(item.fullName)}</button>${assistantBadge}</td><td>${escapeHtml(item.phone || "—")}</td><td>${escapeHtml(item.address || "—")}</td><td>${contractCell}</td><td>${item.assignedClasses.length ? item.assignedClasses.map((name) => `<span class="class-chip">${escapeHtml(name)}</span>`).join(" ") : '<span class="muted">Chưa phân công</span>'}</td><td class="settings-actions-cell">${actions}</td></tr>`;
  }).join("");
  return `<div class="people-page"><div class="page-header"><div><h1>Giáo viên</h1><p>Thông tin liên hệ, hợp đồng và danh sách lớp đang phụ trách. Bấm biểu tượng máy in để in hợp đồng demo.</p></div></div><section class="card settings-card"><div class="card-header people-card-header"><div class="card-heading"><div><h2>Danh sách giáo viên (${items.length})</h2><p>Thêm, sửa thông tin và cập nhật lớp phụ trách tại đây.</p></div>${canEditTeachers() ? `<button class="primary-btn" data-people-add="teachers">${icon("plus")}Thêm giáo viên</button>` : ""}</div><form id="people-filter-form" class="people-filters teacher-filter"><label class="field"><span>Tìm kiếm</span><input class="input" name="q" value="${escapeHtml(state.peopleQuery)}" placeholder="Tên, mã, số điện thoại, lớp phụ trách..." /></label><button class="secondary-btn" type="submit">Tìm</button></form></div><div class="table-wrap people-table"><table><thead><tr><th>STT</th><th>Mã</th><th>Họ và tên</th><th>Liên hệ</th><th>Địa chỉ</th><th>Hợp đồng</th><th>Lớp đang phụ trách</th><th class="settings-actions-cell">Thao tác</th></tr></thead><tbody>${rows || '<tr><td class="empty-cell" colspan="8">Không có giáo viên phù hợp.</td></tr>'}</tbody></table></div></section>${peopleModalHtml("teachers")}</div>`;
}

const PAYROLL_CONTRACT_STATUS_LABELS = { DRAFT: "Bản nháp", ACTIVE: "Đang hiệu lực", EXPIRED: "Đã hết hạn" };

function teacherHref(id, tab = "tong-quan") {
  const base = `/giao-vien/${encodeURIComponent(id)}`;
  return tab === "hop-dong" ? `${base}/hop-dong` : tab === "luong" ? `${base}/luong` : base;
}

/** Trang chi tiết dùng chung cho giáo viên và kế toán, chỉ khác đường dẫn. */
function staffHref(kind, id, tab = "tong-quan") {
  const base = `/${kind === "accountants" ? "ke-toan-vien" : "giao-vien"}/${encodeURIComponent(id)}`;
  return tab === "tong-quan" ? base : `${base}/${tab}`;
}

function payrollContractStatus(contract) {
  return PAYROLL_CONTRACT_STATUS_LABELS[contract?.status] ? contract.status : "DRAFT";
}

function teacherClassRows(classes) {
  return classes.map((item, index) => `<tr><td class="cell-index">${index + 1}</td><td class="code">${escapeHtml(item.code)}</td><td><button class="table-link" data-nav="/lop-hoc/${encodeURIComponent(item.id)}">${escapeHtml(item.name)}</button></td><td>${escapeHtml(findBy(state.data.settings.branches, item.branchId)?.name || "—")}</td><td>${escapeHtml(classScheduleText(item))}</td><td>${classStudentCount(item)}</td><td><span class="badge badge-${item.status === "ACTIVE" ? "green" : item.status === "PAUSED" ? "amber" : "blue"}">${classStatusLabels[item.status]}</span></td></tr>`).join("");
}

function teacherOverviewTab(row, classes, kind = "teachers") {
  const isAccountant = kind === "accountants";
  return `<section class="card detail-section profile-card"><div class="card-header"><div><h2>Thông tin ${isAccountant ? "kế toán" : "giáo viên"}</h2><p>Thông tin liên hệ và phân công hiện tại.</p></div></div><dl class="profile-info-grid"><div><dt>Họ và tên</dt><dd>${escapeHtml(row.fullName)}</dd></div><div><dt>Mã ${isAccountant ? "kế toán" : "giáo viên"}</dt><dd>${escapeHtml(row.code)}</dd></div><div><dt>Số điện thoại</dt><dd>${escapeHtml(row.phone || "—")}</dd></div><div><dt>Email</dt><dd>${escapeHtml(row.email || "—")}</dd></div><div class="span-2"><dt>Địa chỉ</dt><dd>${escapeHtml(row.address || "—")}</dd></div></dl></section>${isAccountant ? "" : teacherAssistantAccessCard(row)}<section class="card detail-section"><div class="card-header"><div><h2>Lớp đang phụ trách (${classes.length})</h2><p>Bấm tên lớp để xem danh sách học viên và thời khoá biểu.</p></div></div><div class="table-wrap"><table><thead><tr><th>STT</th><th>Mã</th><th>Lớp học</th><th>Chi nhánh</th><th>Lịch tuần</th><th>Học viên</th><th>Trạng thái</th></tr></thead><tbody>${teacherClassRows(classes) || `<tr><td class="empty-cell" colspan="7">${isAccountant ? "Kế toán không phụ trách lớp." : "Giáo viên chưa được phân công lớp."}</td></tr>`}</tbody></table></div></section>`;
}

/** Ô tick "Quyền trợ giảng": tick → giáo viên vào Báo cáo học vụ mọi lớp để thêm cột điểm, nhập điểm, nhận xét
 *  như tài khoản trợ giảng; lớp của chính mình vẫn đủ quyền giáo viên. */
function teacherAssistantAccessCard(row) {
  const byDepartment = teacherAssistantByDepartment(row.id);
  const checked = Boolean(row.assistantAccess) || byDepartment;
  const editable = canEditTeachers() && !byDepartment;
  const note = byDepartment
    ? "Đang có quyền theo phòng ban \"Trợ giảng\" trên hồ sơ lương — đổi phòng ban ở tab Hợp đồng nếu muốn bỏ."
    : checked
      ? "Giáo viên vào được mọi lớp để thêm cột điểm, nhập điểm và nhận xét như trợ giảng. Lớp của mình vẫn đủ quyền giáo viên."
      : "Tick để giáo viên vào mọi lớp nhập điểm như trợ giảng (không sửa điểm danh lớp khác).";
  return `<section class="card detail-section teacher-assistant-card"><label class="teacher-assistant-toggle${editable ? "" : " is-disabled"}"><input type="checkbox" data-teacher-assistant="${escapeHtml(row.id)}" ${checked ? "checked" : ""} ${editable ? "" : "disabled"} /><span><strong>Quyền trợ giảng</strong><small>${escapeHtml(note)}</small></span></label></section>`;
}

function teacherContractTab(row) {
  const contract = payrollContract(row.id);
  const kind = payrollContractKind(contract);
  const mode = payrollStaffPayMode(row.id, contract);
  const status = payrollContractStatus(contract);
  const isAccountant = payrollStaffRole(row.id) === "ACCOUNTANT";
  const policy = payrollPolicy();
  const rates = payrollInsuranceRates(contract, policy);
  const value = (input) => escapeHtml(input ?? "");
  const moneyValue = (input) => Number(input) > 0 ? String(input) : "";
  const coefficientValue = (input) => Number.isFinite(Number(input)) && input !== undefined && input !== null && input !== "" ? String(Number(Number(input).toFixed(2))) : "";
  const overrideValue = (input) => input === "" || input === null || input === undefined ? "" : String(input);
  const kindOptions = Object.entries(PAYROLL_CONTRACT_KIND_LABELS).map(([key, label]) => `<option value="${key}" ${kind === key ? "selected" : ""}>${label}</option>`).join("");
  const statusOptions = Object.entries(PAYROLL_CONTRACT_STATUS_LABELS).map(([key, label]) => `<option value="${key}" ${status === key ? "selected" : ""}>${label}</option>`).join("");
  const insuranceNote = kind === "NN"
    ? `Người nước ngoài: NLD ${payrollPercent(rates.employee)} · NSDLĐ ${payrollPercent(rates.employer)}`
    : kind === "CSH" || kind === "DV"
      ? "Hợp đồng cộng sự/dịch vụ: không đóng BH, khấu trừ thuế theo chính sách dịch vụ."
      : `NLD ${payrollPercent(rates.employee)} · NSDLĐ ${payrollPercent(rates.employer)}`;
  return `<section class="card settings-card teacher-contract-card"><div class="card-header people-card-header"><div class="card-heading"><div><h2>Hợp đồng &amp; thoả thuận lương</h2><p>Thông tin này dùng để tính lương, BH và thuế. ${escapeHtml(insuranceNote)}</p></div></div></div><form id="teacher-contract-form" data-teacher-id="${escapeHtml(row.id)}"><div class="form-grid padded"><p class="teacher-form-section">Thông tin hợp đồng</p><label class="field"><span>Số hợp đồng</span><input class="input" name="contractNo" value="${value(contract.contractNo)}" placeholder="VD: HĐLĐ-2026/001" /></label><label class="field"><span>Trạng thái</span><select class="input" name="status">${statusOptions}</select></label><label class="field"><span>Loại hợp đồng</span><select class="input" name="contractKind">${kindOptions}</select></label><label class="field"><span>Hình thức trả lương</span><select class="input" name="payMode"><option value="HOURLY" ${mode === "HOURLY" ? "selected" : ""}>Lương giờ — lấy giờ từ chấm công</option><option value="MONTHLY" ${mode === "MONTHLY" ? "selected" : ""}>Lương cứng — trừ ngày nghỉ không lương cấu hình theo tháng</option></select></label><label class="field"><span>Chức danh</span><input class="input" name="jobTitle" value="${value(contract.jobTitle)}" placeholder="${isAccountant ? "Kế toán" : "Giáo viên tiếng Anh"}" /></label><label class="field"><span>Phòng ban</span><input class="input" name="department" value="${value(contract.department)}" placeholder="${isAccountant ? "Kế toán" : "Giáo viên"}" /></label><label class="field"><span>Địa điểm làm việc</span><input class="input" name="workLocation" value="${value(contract.workLocation)}" placeholder="Chi nhánh / trung tâm" /></label><label class="field"><span>Ngày ký</span><input class="input" type="date" name="signedDate" value="${value(contract.signedDate)}" /></label><label class="field"><span>Ngày bắt đầu</span><input class="input" type="date" name="startDate" value="${value(contract.startDate)}" /></label><label class="field"><span>Ngày kết thúc</span><input class="input" type="date" name="endDate" value="${value(contract.endDate)}" /></label><p class="teacher-form-section">Lương, phụ cấp &amp; thuế</p><label class="field"><span>Hệ số lương</span><input class="input" type="number" min="0" max="10" step="0.01" name="salaryCoefficient" value="${coefficientValue(contract.salaryCoefficient)}" placeholder="1" /><small>Đơn giá giờ = giờ công chuẩn của trung tâm (${vnd(policy.standardHourlyRate)}/giờ) × hệ số = ${vnd(payrollHourlyRate(contract, policy))}/giờ. Giờ công chuẩn cấu hình ở Cấu hình › Cấu hình lương.</small></label>${mode === "MONTHLY" ? `<label class="field"><span>Lương đóng BH</span><input class="input" type="number" min="0" step="100000" name="insuranceSalary" value="${moneyValue(contract.insuranceSalary)}" placeholder="Bỏ trống = đơn giá giờ × 8 giờ × ngày công chuẩn của tháng" /></label><p class="teacher-form-section">Lương tháng: hệ thống quy ${PAYROLL_DAILY_HOURS} giờ × số ngày công tính lương thành giờ lương, rồi nhân đơn giá giờ. Nghỉ không lương trừ nguyên ngày nên giờ lương giảm theo.</p>` : `<p class="teacher-form-section">Lương giờ: thu nhập = giờ dạy thực tế × đơn giá giờ (giờ công chuẩn × hệ số). Phụ cấp vẫn trả nguyên mức tháng. BH NLD tính trên đúng khoản lương giờ.</p>`}<label class="field"><span>Số người phụ thuộc</span><input class="input" type="number" min="0" max="20" name="dependents" value="${Number(contract.dependents) > 0 ? String(contract.dependents) : ""}" placeholder="0" /><small>Giảm trừ ${vnd(policy.dependentDeduction)}/người/tháng.</small></label><label class="field"><span>Giờ dạy cam kết / tháng</span><input class="input" type="number" min="0" max="744" step="0.5" name="committedHours" value="${Number(contract.committedHours) > 0 ? String(contract.committedHours) : ""}" placeholder="Bỏ trống = nhận đủ phụ cấp" /><small>Chỉ áp cho phòng ban Giáo viên, lương giờ: đạt 100% giờ cam kết nhận đủ phụ cấp; thấp hơn giảm theo %, cao hơn tăng theo %.</small></label><label class="field"><span>Phụ cấp ăn ca / tháng (trợ giảng, vận hành · ghi đè)</span><input class="input" type="number" min="0" step="100000" name="mealAllowance" value="${overrideValue(contract.mealAllowance)}" placeholder="Theo chính sách: ${vnd(policy.mealAllowance)}" /></label><label class="field"><span>Phụ cấp ăn trưa / ngày (giáo viên · ghi đè)</span><input class="input" type="number" min="0" step="1000" name="mealAllowancePerDay" value="${overrideValue(contract.mealAllowancePerDay)}" placeholder="Theo chính sách: ${vnd(policy.mealAllowancePerDay)}" /></label><label class="field"><span>Phụ cấp điện thoại / tháng (ghi đè)</span><input class="input" type="number" min="0" step="100000" name="phoneAllowance" value="${overrideValue(contract.phoneAllowance)}" placeholder="Theo chính sách: ${vnd(policy.phoneAllowance)}" /></label><label class="field"><span>Phụ cấp xăng xe / tháng (ghi đè)</span><input class="input" type="number" min="0" step="100000" name="fuelAllowance" value="${overrideValue(contract.fuelAllowance)}" placeholder="Theo chính sách: ${vnd(policy.fuelAllowance)}" /></label><label class="field"><span>Phụ cấp đồng phục / tháng (ghi đè)</span><input class="input" type="number" min="0" step="100000" name="uniformAllowance" value="${overrideValue(contract.uniformAllowance)}" placeholder="Theo chính sách: ${vnd(policy.uniformAllowance)}" /></label><p class="teacher-form-section">Thông tin cá nhân &amp; thanh toán</p><label class="field"><span>CCCD / Hộ chiếu</span><input class="input" name="nationalId" value="${value(contract.nationalId)}" placeholder="Số CCCD" /></label><label class="field"><span>Ngày sinh</span><input class="input" type="date" name="dateOfBirth" value="${value(contract.dateOfBirth)}" /></label><label class="field"><span>Mã số thuế</span><input class="input" name="taxCode" value="${value(contract.taxCode)}" placeholder="MST cá nhân" /></label><label class="field"><span>Số BHXH</span><input class="input" name="socialInsuranceNo" value="${value(contract.socialInsuranceNo)}" placeholder="Số sổ BHXH" /></label><label class="field"><span>Số tài khoản</span><input class="input" name="bankAccount" value="${value(contract.bankAccount)}" placeholder="Tài khoản nhận lương" /></label><label class="field"><span>Ngân hàng</span><input class="input" name="bankName" value="${value(contract.bankName)}" placeholder="Tên ngân hàng" /></label><label class="field span-2"><span>Ghi chú hợp đồng</span><input class="input" name="note" value="${value(contract.note)}" placeholder="Điều khoản bổ sung, thoả thuận riêng..." /></label></div><div class="settings-modal-footer"><span class="teacher-contract-save-note">Thay đổi chỉ áp dụng cho ${isAccountant ? "kế toán" : "giáo viên"} này.</span>${isAuditor() ? "" : `<button class="primary-btn" type="submit">Lưu hợp đồng</button>`}</div></form></section>`;
}

function teacherPayrollTab(row) {
  const month = payrollMonthKey();
  const range = payrollMonthRange(month);
  const totals = timesheetTotals(timesheetSessions(row.id, range), row.id, timesheetCalendarEvents(row.id, range));
  const kpi = attendanceKpi(row.id, range);
  const pay = payrollRowFor(row, totals.actual, month, { kpi });
  const monthly = pay.payMode === "MONTHLY";
  const kpiText = kpi.eligible ? `${kpi.eligible - kpi.late}/${kpi.eligible} buổi · ${payrollPercent(kpi.onTimeRate)}` : "Chưa có buổi đã qua";
  const lateRows = kpi.lateSessions.map((session, index) => {
    const cls = findBy(state.data.classes, session.classId);
    const submitted = session.attendanceSubmittedAt ? new Intl.DateTimeFormat("vi-VN", { dateStyle: "short", timeStyle: "short" }).format(new Date(session.attendanceSubmittedAt)) : "Chưa điểm danh";
    return `<tr><td class="cell-index">${index + 1}</td><td>${formatDateVi(session.date)}</td><td>${escapeHtml(cls?.name || "—")}</td><td>${escapeHtml(session.startTime)}–${escapeHtml(session.endTime)}</td><td>${escapeHtml(submitted)}</td></tr>`;
  }).join("");
  const rateText = `${vnd(pay.hourlyRate)}/giờ`;
  const workText = monthly
    ? `${Number(pay.paidDays).toLocaleString("vi-VN", { maximumFractionDigits: 2 })} / ${pay.workingDays} ngày · ${pay.salaryHours} giờ`
    : `${formatHours(Math.round(pay.hours * 60))} giờ / ${pay.quotaHours} giờ`;
  return `<div class="class-summary-grid teacher-pay-summary"><section class="card summary-card"><small>Thực lĩnh ${escapeHtml(monthLabel(month))}</small><strong>${vnd(pay.net)}</strong></section><section class="card summary-card"><small>Tổng thu nhập</small><strong>${vnd(pay.gross)}</strong></section><section class="card summary-card"><small>KPI đúng hạn</small><strong>${kpi.eligible ? payrollPercent(kpi.onTimeRate) : "—"}</strong><small class="people-subline">${escapeHtml(kpiText)}</small></section><section class="card summary-card"><small>Ngày công / giờ</small><strong>${escapeHtml(workText)}</strong><small class="people-subline">${monthly ? (pay.overridePaidDays ? "Kế toán sửa tay" : pay.unpaidLeaveDays ? `Trừ ${pay.unpaidLeaveDays} ngày nghỉ không lương (cấu hình tháng)` : "Không có ngày nghỉ không lương") : "Từ báo cáo chấm công"}</small></section></div><section class="card detail-section profile-card"><div class="card-header"><div class="card-heading"><div><h2>Bảng tính lương ${escapeHtml(monthLabel(month))}</h2><p>${escapeHtml(payrollContractLabel(pay.contract, pay.payMode))} · ${escapeHtml(rateText)}</p></div><button class="secondary-btn" type="button" data-nav="/ke-toan/luong">Mở báo cáo lương</button></div></div><dl class="profile-info-grid"><div><dt>Lương cơ bản</dt><dd>${vnd(pay.salary)}<small class="people-subline">${monthly ? `${vnd(pay.hourlyRate)} × ${pay.salaryHours} giờ lương (${PAYROLL_DAILY_HOURS} giờ × ${Number(pay.paidDays).toLocaleString("vi-VN", { maximumFractionDigits: 2 })} ngày công)` : `${formatHours(Math.round(pay.hours * 60))} giờ × ${vnd(pay.hourlyRate)}`}</small></dd></div><div><dt>Phụ cấp tự tính</dt><dd>${pay.autoAllowance ? vnd(pay.autoAllowance) : "—"}<small class="people-subline">Ăn trưa ${vnd(pay.mealAllowance)} · Điện thoại ${vnd(pay.phoneAllowance)} · Xăng xe ${vnd(pay.fuelAllowance)} · Đồng phục ${vnd(pay.uniformAllowance)}</small></dd></div><div><dt>Phụ cấp nhập tay</dt><dd>${vnd(pay.allowance)}</dd></div><div><dt>Lương năng suất</dt><dd>${kpi.eligible || pay.quotaRate ? vnd(pay.productivityPay) : "—"}<small class="people-subline">${payrollPercent(pay.onTimeRate)} đúng hạn + ${payrollPercent(pay.quotaRate)} đạt ${pay.quotaHours} giờ định mức = ${payrollPercent(pay.productivityRate)} × lương cơ bản</small></dd></div><div><dt>Tổng thu nhập</dt><dd>${vnd(pay.gross)}</dd></div><div><dt>BH NLD trừ</dt><dd>${pay.isLabor ? vnd(pay.insurance) : "—"}${pay.isLabor ? `<small class="people-subline">${vnd(pay.insuranceBase)} × ${payrollPercent(pay.policy.employeeInsuranceRate)}${monthly ? "" : " · Tính trên lương giờ (giờ × đơn giá)"}</small>` : ""}</dd></div><div><dt>Giảm trừ gia cảnh</dt><dd>${pay.isLabor ? vnd(pay.deduction) : "—"}<small class="people-subline">${pay.isLabor ? `${vnd(pay.policy.personalDeduction)} bản thân${pay.dependents ? ` + ${pay.dependents} NPT` : ""}` : ""}</small></dd></div><div><dt>Thuế TNCN</dt><dd>${vnd(pay.tax)}<small class="people-subline">${pay.isLabor ? "Lũy tiến 5 bậc" : pay.gross >= pay.policy.serviceTaxThreshold ? `Khấu trừ ${payrollPercent(pay.policy.serviceTaxRate)}` : "Chưa đến ngưỡng khấu trừ"}</small></dd></div><div><dt>Tạm ứng</dt><dd>${vnd(pay.advance)}</dd></div><div><dt>Thực lĩnh</dt><dd><strong>${vnd(pay.net)}</strong></dd></div></dl></section>${kpi.late ? `<section class="card detail-section teacher-late-card"><div class="card-header"><div><h2>Buổi điểm danh trễ trong kỳ (${kpi.late})</h2><p>Buổi trễ làm giảm % đúng hạn — % này là một thành phần của lương năng suất.</p></div></div><div class="table-wrap"><table><thead><tr><th>STT</th><th>Ngày</th><th>Lớp</th><th>Giờ dạy</th><th>Nộp điểm danh</th></tr></thead><tbody>${lateRows}</tbody></table></div></section>` : ""}`;
}

function teacherDetailPage(row, tab = "tong-quan", staffKind = "teachers") {
  const isAccountant = staffKind === "accountants";
  const classes = state.data.classes.filter((item) => item.teacherId === row.id);
  const contract = payrollContract(row.id);
  const kind = payrollContractKind(contract);
  const mode = payrollStaffPayMode(row.id, contract);
  const status = payrollContractStatus(contract);
  const contractKindLabel = PAYROLL_CONTRACT_KIND_LABELS[kind] || "Chưa có hợp đồng";
  const rateLabel = `${vnd(payrollHourlyRate(contract))}/giờ`;
  const kpi = attendanceKpi(row.id, payrollMonthRange(payrollMonthKey()));
  return `<div class="people-detail teacher-detail"><button class="back-link" data-nav="${isAccountant ? "/ke-toan-vien" : "/giao-vien"}">← Danh sách ${isAccountant ? "kế toán" : "giáo viên"}</button><div class="page-header"><div><h1>${escapeHtml(row.fullName)}</h1><p>${escapeHtml(row.code)} · ${isAccountant ? "Kế toán" : `${classes.length} lớp phụ trách`}</p></div><div class="page-actions">${isAuditor() ? "" : `<button class="secondary-btn" data-print-contract="${escapeHtml(row.id)}">${icon("printer")}In hợp đồng</button>`}${(isAccountant ? !isAuditor() : canEditTeachers()) ? `<button class="secondary-btn" data-people-edit="${staffKind}|${escapeHtml(row.id)}">${icon("pencil")}Sửa thông tin</button>` : ""}</div></div><div class="profile-summary-grid"><section class="card summary-card"><small>Hợp đồng</small><strong>${escapeHtml(contractKindLabel)}</strong><small class="people-subline"><span class="badge badge-${status === "ACTIVE" ? "green" : status === "EXPIRED" ? "red" : "amber"}">${PAYROLL_CONTRACT_STATUS_LABELS[status]}</span> ${mode === "MONTHLY" ? "Lương tháng" : "Theo giờ"}</small></section><section class="card summary-card"><small>Đơn giá giờ</small><strong>${escapeHtml(rateLabel)}</strong><small class="people-subline">Giờ công chuẩn ${vnd(payrollPolicy().standardHourlyRate)} · hệ số lương ${Number(payrollSalaryCoefficient(contract).toFixed(2)).toLocaleString("vi-VN")}</small></section><section class="card summary-card"><small>KPI đúng hạn</small><strong>${kpi.eligible ? payrollPercent(kpi.onTimeRate) : "—"}</strong><small class="people-subline">${kpi.eligible ? `${kpi.late} buổi trễ` : "Chưa có buổi đã qua"}</small></section><section class="card summary-card"><small>${isAccountant ? "Role" : "Lớp phụ trách"}</small><strong>${isAccountant ? "Kế toán" : classes.length}</strong><small class="people-subline">${isAccountant ? "Nhân sự văn phòng" : `${classes.filter((item) => item.status === "ACTIVE").length} lớp đang hoạt động`}</small></section></div><nav class="nz-class-tabs"><button class="nz-tab ${tab === "tong-quan" ? "active" : ""}" data-nav="${staffHref(staffKind, row.id)}">Tổng quan</button><button class="nz-tab ${tab === "hop-dong" ? "active" : ""}" data-nav="${staffHref(staffKind, row.id, "hop-dong")}">Hợp đồng</button><button class="nz-tab ${tab === "luong" ? "active" : ""}" data-nav="${staffHref(staffKind, row.id, "luong")}">Lương &amp; KPI</button></nav>${tab === "hop-dong" ? teacherContractTab(row) : tab === "luong" ? teacherPayrollTab(row) : teacherOverviewTab(row, classes, staffKind)}${peopleModalHtml(staffKind)}</div>`;
}

const TEACHER_CONTRACT_TITLES = {
  TT: "HỢP ĐỒNG LAO ĐỘNG",
  BTG: "HỢP ĐỒNG LAO ĐỘNG BÁN THỜI GIAN",
  NN: "HỢP ĐỒNG LAO ĐỘNG NGƯỜI NƯỚC NGOÀI",
  CSH: "HỢP ĐỒNG CỘNG SỰ",
  DV: "HỢP ĐỒNG DỊCH VỤ",
};

function openTeacherContract(teacherId) {
  const teacher = findBy(state.data.teachers, teacherId) || findBy(state.data.accountants || [], teacherId);
  if (!teacher) return toast("Không tìm thấy nhân sự.");
  const contract = payrollContract(teacherId);
  const kind = payrollContractKind(contract);
  const mode = payrollStaffPayMode(teacherId, contract);
  const defaultJobTitle = payrollStaffRole(teacherId) === "ACCOUNTANT" ? "Kế toán" : "Giáo viên";
  const policy = payrollPolicy();
  const rates = payrollInsuranceRates(contract, policy);
  const isLabor = payrollIsLabor(contract);
  const center = state.data.settings?.center || {};
  const dateText = (value) => value ? formatDateVi(value) : "—";
  const moneyText = (value) => vnd(value);
  const statusLabel = PAYROLL_CONTRACT_STATUS_LABELS[payrollContractStatus(contract)];
  const title = TEACHER_CONTRACT_TITLES[kind] || "HỢP ĐỒNG LAO ĐỘNG";
  const meal = contract.mealAllowancePerDay === undefined || contract.mealAllowancePerDay === null || contract.mealAllowancePerDay === "" ? policy.mealAllowancePerDay : contract.mealAllowancePerDay;
  const phone = contract.phoneAllowance === undefined || contract.phoneAllowance === null ? policy.phoneAllowance : contract.phoneAllowance;
  const fuel = contract.fuelAllowance === undefined || contract.fuelAllowance === null ? policy.fuelAllowance : contract.fuelAllowance;
  const uniform = contract.uniformAllowance === undefined || contract.uniformAllowance === null ? policy.uniformAllowance : contract.uniformAllowance;
  const coefficientText = Number(payrollSalaryCoefficient(contract).toFixed(2)).toLocaleString("vi-VN");
  const hourlyRateText = moneyText(payrollHourlyRate(contract, policy));
  const fullMonthHoursText = PAYROLL_DAILY_HOURS * policy.standardDays;
  const salaryClause = mode === "MONTHLY"
    ? `Lương chính: đơn giá giờ ${hourlyRateText}/giờ (giờ công chuẩn của trung tâm ${moneyText(policy.standardHourlyRate)}/giờ × hệ số lương ${coefficientText}). Số giờ lương của tháng = ${PAYROLL_DAILY_HOURS} giờ × số ngày công tính lương; ngày công chuẩn bằng số ngày đi làm thực tế của tháng (thứ 2–thứ 7, nghỉ Chủ nhật), biến thiên theo lịch từng tháng, trừ nghỉ không lương theo SỐ NGÀY kế toán cấu hình cho từng tháng (trừ nguyên ngày, không quy theo giờ dạy).`
    : `Lương theo giờ: đơn giá giờ ${hourlyRateText}/giờ (giờ công chuẩn của trung tâm ${moneyText(policy.standardHourlyRate)}/giờ × hệ số lương ${coefficientText}), tính trên số giờ chấm công thực tế trong tháng.`;
  const allowanceClause = `Phụ cấp ăn trưa ${moneyText(meal)}/ngày làm việc; phụ cấp điện thoại ${moneyText(phone)}/tháng; phụ cấp xăng xe ${moneyText(fuel)}/tháng; phụ cấp đồng phục ${moneyText(uniform)}/tháng. Các khoản phụ cấp trả nguyên mức tháng, không chia theo ngày công và áp dụng cho cả hình thức lương giờ.`;
  const performanceClause = mode === "MONTHLY"
    ? `Lương năng suất = lương cơ bản × (% điểm danh đúng hạn + % đạt định mức giờ), hai tỷ lệ cộng thẳng, không giới hạn tối đa. Định mức giờ của tháng = ${PAYROLL_DAILY_HOURS} giờ × số ngày công tính lương.`
    : `Lương năng suất = lương cơ bản × (% điểm danh đúng hạn + % đạt định mức giờ), hai tỷ lệ cộng thẳng, không giới hạn tối đa. Định mức giờ của tháng = ${PAYROLL_DAILY_HOURS} giờ × ${policy.standardDays} ngày chuẩn.`;
  const kpiBonusClause = mode === "MONTHLY"
    ? `KPI: tỷ lệ điểm danh đúng hạn (nộp trong ${policy.attendanceDeadlineHours} giờ sau buổi học). Buổi nộp trễ làm giảm tỷ lệ đúng hạn, giảm lương năng suất nêu trên.`
    : `KPI: tỷ lệ điểm danh đúng hạn (nộp trong ${policy.attendanceDeadlineHours} giờ sau buổi học) là một thành phần của lương năng suất bên B nêu trên.`;
  const insuranceClause = isLabor
    ? mode === "MONTHLY"
      ? `Người lao động đóng ${payrollPercent(rates.employee)}, người sử dụng lao động đóng ${payrollPercent(rates.employer)} trên mức lương đóng BH ${moneyText(contract.insuranceSalary || payrollHourlyRate(contract, policy) * fullMonthHoursText)}. Thuế TNCN khấu trừ theo biểu lũy tiến 5 bậc, giảm trừ bản thân ${moneyText(policy.personalDeduction)} và ${moneyText(policy.dependentDeduction)}/người phụ thuộc.`
      : `Người lao động đóng ${payrollPercent(rates.employee)}, người sử dụng lao động đóng ${payrollPercent(rates.employer)} trên tổng lương giờ thực tế của tháng (giờ × đơn giá). Thuế TNCN khấu trừ theo biểu lũy tiến 5 bậc, giảm trừ bản thân ${moneyText(policy.personalDeduction)} và ${moneyText(policy.dependentDeduction)}/người phụ thuộc.`
    : `Không tham gia BH bắt buộc. Thu nhập từ ${moneyText(policy.serviceTaxThreshold)} trở lên bị khấu trừ ${payrollPercent(policy.serviceTaxRate)} theo chính sách dịch vụ.`;
  const bankClause = contract.bankAccount
    ? `Chuyển khoản vào tài khoản ${escapeHtml(contract.bankAccount)}${contract.bankName ? ` tại ${escapeHtml(contract.bankName)}` : ""}, hoặc hình thức thanh toán khác theo thoả thuận.`
    : "Thanh toán bằng tiền mặt hoặc chuyển khoản theo thoả thuận giữa hai bên.";
  const popup = window.open("", "_blank", "width=900,height=1000");
  if (!popup) return toast("Trình duyệt đang chặn cửa sổ in. Vui lòng cho phép popup.");
  popup.document.open();
  popup.document.write(`<!doctype html><html lang="vi"><head><meta charset="utf-8"><title>Hợp đồng - ${escapeHtml(teacher.fullName)}</title><style>
    @page{size:A4;margin:18mm}*{box-sizing:border-box}body{margin:0;padding-bottom:64px;color:#0f172a;background:#f1f5f9;font-family:"Times New Roman",serif;font-size:13.5px;line-height:1.55}main{max-width:780px;margin:20px auto 0;padding:30px 36px;border:1px solid #dbe3ef;border-radius:14px;background:white}.center{text-align:center}.center strong{display:block;font-size:15px;text-transform:uppercase}.center span{display:block;color:#475569;font-size:12px}.title{margin:22px 0 4px;text-align:center;font-size:22px;font-weight:700;letter-spacing:.02em}.subtitle{margin:0 0 18px;text-align:center;color:#475569;font-size:12.5px;font-style:italic}.meta{display:grid;grid-template-columns:1fr 1fr;gap:4px 24px;margin-bottom:18px;padding:12px 14px;border:1px solid #dbe3ef;border-radius:10px;background:#f8fafc;font-size:13px}.meta span{color:#64748b}.party{margin:14px 0}h3{margin:0 0 6px;font-size:14px;text-transform:uppercase}h3 small{text-transform:none;font-weight:400;color:#64748b}.party p{margin:3px 0}.article{margin:16px 0}.article h4{margin:0 0 4px;font-size:14px}.article p{margin:3px 0;text-align:justify}.note{margin-top:18px;padding-top:12px;border-top:1px dashed #cbd5e1;color:#64748b;font-size:11.5px}.sign{display:grid;grid-template-columns:1fr 1fr;gap:40px;margin-top:26px;text-align:center}.sign div{min-height:120px}.sign strong{display:block;text-transform:uppercase}.sign span{display:block;color:#64748b;font-size:11.5px;font-style:italic}.export{position:sticky;bottom:16px;display:flex;height:42px;margin:18px auto 0;align-items:center;justify-content:center;padding:0 22px;border:0;border-radius:9px;color:white;background:#2563eb;font:600 13px Arial,sans-serif;box-shadow:0 8px 20px #0f172a2b;cursor:pointer}.export:hover{background:#1d4ed8}@media print{body{padding:0;background:white}main{margin:0;border:0;padding:0}.export{display:none}}
  </style></head><body><main><header class="center"><strong>${escapeHtml(center.name || "TRUNG TÂM STEPS")}</strong><span>${escapeHtml(center.address || "")}</span><span>${escapeHtml([center.phone, center.email].filter(Boolean).join(" · "))}</span></header><h1 class="title">${escapeHtml(title)}</h1><p class="subtitle">Số: ${escapeHtml(contract.contractNo || "................")} · ${escapeHtml(statusLabel || "")}</p><section class="meta"><div><span>Ngày ký:</span> ${escapeHtml(dateText(contract.signedDate))}</div><div><span>Hiệu lực:</span> ${escapeHtml(dateText(contract.startDate))} – ${escapeHtml(contract.endDate ? dateText(contract.endDate) : "không thời hạn")}</div><div><span>Loại HĐ:</span> ${escapeHtml(PAYROLL_CONTRACT_KIND_LABELS[kind] || "—")}</div><div><span>Hình thức trả lương:</span> ${mode === "MONTHLY" ? "Lương tháng" : "Theo giờ"}</div></section><section class="party"><h3>Bên A <small>(Người sử dụng lao động)</small></h3><p><strong>${escapeHtml(center.name || "Trung tâm STEPS")}</strong></p><p>Địa chỉ: ${escapeHtml(center.address || "—")}</p><p>Điện thoại: ${escapeHtml(center.phone || "—")} · Email: ${escapeHtml(center.email || "—")}</p><p>Đại diện: .................................................... Chức vụ: ....................................................</p></section><section class="party"><h3>Bên B <small>(Người lao động / cộng sự)</small></h3><p><strong>${escapeHtml(teacher.fullName)}</strong> · Mã: ${escapeHtml(teacher.code)}</p><p>Số CCCD/Hộ chiếu: ${escapeHtml(contract.nationalId || "—")} · Ngày sinh: ${escapeHtml(dateText(contract.dateOfBirth))}</p><p>Địa chỉ: ${escapeHtml(teacher.address || "—")} · Điện thoại: ${escapeHtml(teacher.phone || "—")}</p><p>Mã số thuế: ${escapeHtml(contract.taxCode || "—")} · Số BHXH: ${escapeHtml(contract.socialInsuranceNo || "—")}</p></section><section class="article"><h4>Điều 1. Công việc và địa điểm làm việc</h4><p>Bên B đảm nhận vị trí <strong>${escapeHtml(contract.jobTitle || defaultJobTitle)}</strong>${contract.department ? `, phòng ban ${escapeHtml(contract.department)}` : ""}, làm việc tại ${escapeHtml(contract.workLocation || center.address || "trung tâm")}. Nhiệm vụ cụ thể do Bên A phân công theo nhu cầu vận hành và năng lực của Bên B.</p></section><section class="article"><h4>Điều 2. Thời hạn hợp đồng</h4><p>Hợp đồng có hiệu lực từ ngày ${escapeHtml(dateText(contract.startDate))}${contract.endDate ? ` đến ngày ${escapeHtml(dateText(contract.endDate))}` : " cho đến khi một bên chấm dứt theo thoả thuận hoặc quy định pháp luật"}. Hai bên có thể gia hạn bằng phụ lục hợp đồng.</p></section><section class="article"><h4>Điều 3. Lương, phụ cấp và lương năng suất</h4><p>${salaryClause}</p><p>${allowanceClause}</p><p>${performanceClause}</p><p>${kpiBonusClause}</p></section><section class="article"><h4>Điều 4. Thời giờ làm việc</h4><p>Chế độ làm việc theo lịch phân công của trung tâm. Thời gian chuẩn tham chiếu: ${policy.standardDays} ngày/tháng, ${fullMonthHoursText} giờ/tháng (${PAYROLL_DAILY_HOURS} giờ/ngày). Thời gian điểm danh được ghi nhận theo từng buổi dạy trên hệ thống.</p></section><section class="article"><h4>Điều 5. Bảo hiểm và thuế</h4><p>${insuranceClause}</p><p>${bankClause}</p></section><section class="article"><h4>Điều 6. Điều khoản chung</h4><p>Hai bên cam kết thực hiện đúng các thoả thuận trong hợp đồng. Mọi thay đổi được lập thành phụ lục có chữ ký của hai bên. Hợp đồng được lập thành 02 bản, mỗi bên giữ 01 bản có giá trị như nhau.</p>${contract.note ? `<p><em>Ghi chú: ${escapeHtml(contract.note)}</em></p>` : ""}</section><section class="sign"><div><strong>Đại diện Bên A</strong><span>(Ký, ghi rõ họ tên, đóng dấu)</span></div><div><strong>Bên B</strong><span>(Ký, ghi rõ họ tên)</span></div></section><p class="note">Mẫu hợp đồng demo tạo từ hồ sơ lương trên hệ thống${contract.contractNo ? "" : " — hợp đồng chưa có số, vui lòng bổ sung trước khi ký chính thức"}. Nội dung sẽ được thay bằng mẫu hợp đồng chính thức của trung tâm khi anh gửi PDF mẫu.</p></main><button class="export" onclick="window.print()">In hợp đồng</button></body></html>`);
  popup.document.close();
}

// --- Nhóm nhân sự trên Quản lý người dùng (anh Mori 12/11/2026) ---
// 4 nhóm: Học viên, Giáo viên, Kế toán, Hành chính. Kế toán / Hành chính chỉ là nhóm hiển thị:
// quyền đăng nhập vẫn theo loại tài khoản (kế toán / Audit). Nhóm lưu ở staffSettings.groups;
// chưa đặt thì theo danh sách mặc định dưới đây, còn lại vào Kế toán.
const STAFF_DEFAULT_HC_NAMES = ["Nguyễn Thị Bích Liễu", "Lê Hà", "Trương Đức Nhật", "Trần Thị Phú"];

function staffGroupOf(person) {
  if (!person) return "";
  const stored = state.data?.staffSettings?.groups?.[person.id];
  if (stored === "KT" || stored === "HC") return stored;
  const key = payrollImportKey(person.fullName).replace(/\s+/g, " ").trim();
  return STAFF_DEFAULT_HC_NAMES.some((name) => payrollImportKey(name).replace(/\s+/g, " ").trim() === key) ? "HC" : "KT";
}

