const classStatusLabels = { DRAFT: "Nháp", ACTIVE: "Đang học", PAUSED: "Tạm dừng", FINISHED: "Kết thúc" };
const sessionStatusLabels = { SCHEDULED: "Đã xếp lịch", COMPLETED: "Hoàn thành", CANCELLED: "Đã huỷ" };
const weekdayLabels = ["Chủ nhật", "Thứ 2", "Thứ 3", "Thứ 4", "Thứ 5", "Thứ 6", "Thứ 7"];
const weekdayShort = ["CN", "T2", "T3", "T4", "T5", "T6", "T7"];
const weekdayFull = ["Chủ nhật", "Thứ 2", "Thứ 3", "Thứ 4", "Thứ 5", "Thứ 6", "Thứ 7"];

function scheduleSlotAppliesOnDate(slot, date) {
  if (!slot || !date) return false;
  if (slot.weekday !== localDate(date).getDay()) return false;
  if (slot.effectiveFrom && date < slot.effectiveFrom) return false;
  if (slot.effectiveTo && date > slot.effectiveTo) return false;
  return true;
}

function scheduleSlotRangeText(slot) {
  if (!slot?.effectiveFrom && !slot?.effectiveTo) return "";
  const from = slot.effectiveFrom ? formatDateVi(slot.effectiveFrom) : "…";
  if (slot.effectiveTo) return `${from} → ${formatDateVi(slot.effectiveTo)}`;
  return `${from} →`;
}

// Đổi lịch có hiệu lực: suất đang chạy mà draft gỡ/đổi thì kết thúc từ hôm qua,
// suất draft mới có hiệu lực từ hôm nay — lịch đã học trước đó giữ nguyên,
// chỉ từ lúc đổi về sau mới theo lịch mới. Suất đã kết thúc (lịch sử) luôn
// được giữ lại để các khóa cũ render đúng; suất tương lai vẫn gỡ được.
function transitionClassSchedules(oldSlots, draftSlots, today = localDateKey(new Date())) {
  if (!(oldSlots || []).length) return structuredClone(draftSlots || []);
  const same = (a, b) => a.weekday === b.weekday && a.startTime === b.startTime && a.endTime === b.endTime
    && (a.effectiveFrom || "") === (b.effectiveFrom || "") && (a.effectiveTo || "") === (b.effectiveTo || "");
  const yest = localDateKey(addDays(localDate(today), -1));
  const pool = (draftSlots || []).slice();
  const out = [];
  for (const slot of oldSlots) {
    // Cửa sổ rỗng (bắt đầu sau ngày kết thúc — rác của các lần lưu trước) không
    // bao giờ áp dụng được, bỏ hẳn để dữ liệu tự lành sau mỗi lần lưu.
    if (slot.effectiveFrom && slot.effectiveTo && slot.effectiveFrom > slot.effectiveTo) continue;
    if (slot.effectiveTo && slot.effectiveTo < today) { out.push(slot); continue; }
    const kept = pool.findIndex((d) => same(d, slot));
    if (kept >= 0) { pool.splice(kept, 1); out.push(slot); continue; }
    // Suất chỉ mới có hiệu lực từ hôm nay/tương lai mà đã bị gỡ khỏi draft thì
    // chưa hề sinh lịch sử — bỏ luôn thay vì đóng lùi thành cửa sổ rỗng.
    if (slot.effectiveFrom && slot.effectiveFrom >= today) continue;
    out.push({ ...slot, effectiveTo: yest });
  }
  for (const slot of pool) {
    if (oldSlots.some((o) => same(o, slot))) continue;
    out.push({ weekday: slot.weekday, periodId: slot.periodId, startTime: slot.startTime, endTime: slot.endTime, effectiveFrom: today });
  }
  return out;
}

function findBy(items, id) { return (items || []).find((item) => item.id === id); }
function localDate(value) { return new Date(`${value}T12:00:00`); }
function localDateKey(value) { const date = value instanceof Date ? value : localDate(value); return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`; }
function addDays(value, amount) { const date = value instanceof Date ? new Date(value) : localDate(value); date.setDate(date.getDate() + amount); return date; }
function addMonths(value, amount) { const date = value instanceof Date ? new Date(value) : localDate(value); date.setMonth(date.getMonth() + amount); return date; }
function formatDateVi(value) { return new Intl.DateTimeFormat("vi-VN", { day: "2-digit", month: "2-digit", year: "numeric" }).format(value instanceof Date ? value : localDate(value)); }

