/** Lưu học liệu của một tháng, chỉ gọi API khi tiền hoặc mô tả thực sự đổi. */
function applyMaterialFee(target, key, formData) {
  const amount = Math.max(0, Math.round(Number(formData.get("materialsAmount")) || 0));
  const description = String(formData.get("materialsDescription") || "").trim().slice(0, 200);
  const fees = { ...(target.materialFees || {}) };
  if (amount) fees[key] = { amount, description };
  else if (/^course\|\d+$/.test(key)) fees[key] = { amount: 0, description };
  else delete fees[key];
  target.materialFees = fees;
  return { amount, description };
}

async function saveClassMaterialFee(classId, key, formData) {
  const cls = findBy(state.data.classes, classId);
  if (!cls) return;
  const amount = Math.max(0, Math.round(Number(formData.get("materialsAmount")) || 0));
  const description = String(formData.get("materialsDescription") || "").trim().slice(0, 200);
  const current = classMaterialFee(cls, key);
  if (current.amount === amount && current.description === (amount ? description : "")) return;
  const items = structuredClone(state.data.classes || []);
  const target = items.find((item) => item.id === classId);
  if (!target) return;
  applyMaterialFee(target, key, formData);
  const period = key === COURSE_MATERIAL_KEY ? "khóa này" : monthLabel(key).toLowerCase();
  await persistClasses(items, amount ? `Đã lưu học liệu ${period}: ${vnd(amount)}.` : `Đã bỏ học liệu ${period}.`);
}

