function classScheduleText(row) {
  const today = localDateKey(new Date());
  const sorted = (row.schedules || []).filter((slot) => (!slot.effectiveFrom || today >= slot.effectiveFrom) && (!slot.effectiveTo || today <= slot.effectiveTo)).sort((a, b) => a.weekday - b.weekday || a.startTime.localeCompare(b.startTime));
  return sorted.length ? sorted.map((slot) => `${weekdayShort[slot.weekday]} ${slot.startTime}`).join(" · ") : "—";
}

function classProgressCounts(row) {
  if (classBillingMode(row) === "MONTHLY") {
    const sessions = classMonthScheduleSessions(row);
    // Tử và mẫu cùng một "vũ trụ" buổi học: suất lịch đã ghép bản ghi thật +
    // buổi ngoài lịch — lớp đổi giờ hay học thêm không còn làm tử vượt mẫu.
    const total = sessions.filter((item) => !isPlannedTuitionOff(item) && item.status !== "CANCELLED").length;
    if (!total) return null;
    const done = sessions.filter((item) => sessionChargesTuition(item)).length;
    return { done, total };
  }
  // Tiến độ hiển thị của "hộp" khóa đang chạy: buổi đã qua trong cửa sổ khóa
  // hiện tại / tổng buổi khóa — lớp sang khóa 2 không còn đếm lại buổi khóa 1.
  const courseIndex = classCurrentCourseIndex(row);
  const todayKey = localDateKey(new Date());
  const window = classCourseWindowByIndex(row, courseIndex);
  const inWindow = new Set(window.sessions.filter((item) => !String(item.id).startsWith("recurring|")).map((item) => sessionIdentity(item)));
  // Buổi hôm nay cũng tính khi đã có bản ghi thật tính phí (điểm danh xong) —
  // đồng bộ với số buổi trừ của học viên trong lớp (classElapsedCourseSessions).
  let done = window.sessions.filter((item) => item.date <= todayKey && sessionChargesTuition(item)).length;
  // Count extra sessions only when the course schedule numbers them. Unnumbered
  // no-fee sessions must not advance progress; configured boundary exceptions remain numbered.
  for (const item of state.data?.lessonSessions || []) {
    if (item.classId !== row.id || item.date > todayKey || inWindow.has(sessionIdentity(item))) continue;
    if (classCourseIndexOfDate(row, item.date) === courseIndex
      && !item.isOff
      && item.status !== "CANCELLED"
      && (!isNoFeeSession(item) || !isCourseUnnumberedRow(row, item))) done += 1;
  }
  const total = classCourseSizeAt(row, courseIndex);
  return { done: Math.min(done, total), total };
}

function classProgressText(row) {
  const progress = classProgressCounts(row);
  return progress ? `${progress.done}/${progress.total}` : "—";
}

const ATTENDANCE_CHOICES = [
  ["PRESENT", "Có mặt"],
  ["EXCUSED", "Vắng phép"],
  ["ABSENT", "Vắng không phép"],
];

function withAttendanceHistory(previous, rows, isOff = false) {
  const prevById = new Map((previous || []).map((row) => [row.studentId, row]));
  return (rows || []).map((row) => {
    const prev = prevById.get(row.studentId) || {};
    if (isOff) return { ...row, firstStatus: prev.firstStatus ?? null, late: false };
    const firstStatus = prev.firstStatus || (prev.firstStatus === null ? row.status : (prev.status || row.status)) || null;
    return { ...row, firstStatus, late: Boolean(firstStatus === "ABSENT" && row.status === "PRESENT") };
  });
}

function attendanceScore(value) {
  if (value === "" || value === null || value === undefined) return null;
  const score = Number(value);
  return Number.isFinite(score) && score >= 0 && score <= 1000
    ? Math.round(score * 100) / 100
    : null;
}

function attendanceAssessmentText(value) {
  if (value === "" || value === null || value === undefined) return null;
  const answer = String(value).trim().slice(0, 200);
  return answer || null;
}

function attendanceAbsenceLocksGrading(status) {
  return status === "EXCUSED" || status === "ABSENT";
}

function attendanceClipValue(formData, studentId, isOff, previous = {}) {
  return isOff ? Boolean(previous.pronunciationVideoDone) : formData.has(`clip_${studentId}`);
}

function attendanceWorksheetValue(formData, studentId, isOff, previous = {}) {
  return isOff ? Boolean(previous.worksheetDone) : formData.has(`worksheet_${studentId}`);
}

function attendanceGradeClearIntent(formData, studentId, assessmentColumns, previous = {}, freezeGrades = false) {
  if (freezeGrades) return null;
  const vocabularyField = `vocabulary_${studentId}`;
  const vocabulary = formData.has(vocabularyField)
    && attendanceAssessmentText(previous.vocabularyScore) !== null
    && attendanceAssessmentText(formData.get(vocabularyField)) === null;
  const assessmentColumnIds = assessmentColumns
    .filter((column) => {
      const field = `assessment_${column.id}_${studentId}`;
      return formData.has(field)
        && attendanceAssessmentText(previous.assessmentScores?.[column.id]) !== null
        && attendanceAssessmentText(formData.get(field)) === null;
    })
    .map((column) => column.id);
  return vocabulary || assessmentColumnIds.length ? { studentId, vocabulary, assessmentColumnIds } : null;
}

function attendanceAssessmentColumns(session) {
  const stored = Array.isArray(session?.assessmentColumns) ? session.assessmentColumns : [];
  const drafts = state.attendanceColumnDrafts[session?.id] || [];
  const removed = new Set(state.attendanceRemovedColumns[session?.id] || []);
  const names = state.attendanceColumnNames[session?.id] || {};
  const storedIds = new Set(stored.map((column) => column.id));
  return [...stored, ...drafts.map((column) => (storedIds.has(column.id) ? column : { ...column, draft: true }))]
    .filter((column) => !removed.has(column.id))
    .map((column) => (names[column.id] !== undefined ? { ...column, name: names[column.id] } : column))
    .slice(0, 12);
}

function snapshotAttendanceColumnNames(form) {
  const sessionId = form?.dataset.sessionId;
  if (!sessionId) return;
  const names = { ...(state.attendanceColumnNames[sessionId] || {}) };
  form.querySelectorAll(".attendance-column-name").forEach((input) => {
    const columnId = String(input.name || "").replace(/^assessment_column_/, "");
    if (columnId) names[columnId] = input.value;
  });
  state.attendanceColumnNames[sessionId] = names;
}

function attendanceAssessmentColumnKey(columnId) {
  return `assessment:${columnId}`;
}

/**
 * Thứ tự cũ bị lỗi khi lưu: cột điểm mới bị nối vào SAU "Nhận xét" ([…, note, assessment:…]).
 * Nhận dạng đúng mẫu đó (sau note chỉ toàn cột điểm) và đưa Nhận xét về cuối.
 */
function repairAttendanceColumnOrder(order) {
  const list = Array.isArray(order) ? [...order] : [];
  const noteIndex = list.indexOf("note");
  if (noteIndex < 0 || noteIndex === list.length - 1) return list;
  const tail = list.slice(noteIndex + 1);
  if (!tail.every((key) => String(key).startsWith("assessment:"))) return list;
  return [...list.slice(0, noteIndex), ...tail, "note"];
}

function normalizeAttendanceColumnOrder(order, availableKeys) {
  const available = new Set(availableKeys);
  const result = [];
  for (const key of repairAttendanceColumnOrder(order)) {
    if (!available.has(key) || result.includes(key)) continue;
    result.push(key);
  }
  // Cột chưa có trong thứ tự đã lưu (cột mới) chèn đúng vị trí chuẩn —
  // ngay sau cột phía trước gần nhất đã có mặt — thay vì xuống cuối.
  for (let index = 0; index < availableKeys.length; index++) {
    const key = availableKeys[index];
    if (result.includes(key)) continue;
    let position = result.length;
    for (let before = index - 1; before >= 0; before--) {
      const at = result.indexOf(availableKeys[before]);
      if (at >= 0) { position = at + 1; break; }
    }
    result.splice(position, 0, key);
  }
  return result;
}

function attendanceColumnOrder(session, assessmentColumns = attendanceAssessmentColumns(session)) {
  const availableKeys = [
    "status",
    "clip",
    "worksheet",
    "vocabulary",
    ...assessmentColumns.map((column) => attendanceAssessmentColumnKey(column.id)),
    "note",
  ];
  const draft = state.attendanceColumnOrders[session?.id];
  return normalizeAttendanceColumnOrder(draft || session?.attendanceColumnOrder, availableKeys);
}

function reorderAttendanceColumnKeys(order, sourceKey, targetKey, placeAfter = false) {
  if (sourceKey === targetKey || !order.includes(sourceKey) || !order.includes(targetKey)) return [...order];
  const next = order.filter((key) => key !== sourceKey);
  const targetIndex = next.indexOf(targetKey);
  next.splice(targetIndex + (placeAfter ? 1 : 0), 0, sourceKey);
  return next;
}

function applyAttendanceColumnOrderToTable(table, order) {
  for (const row of table?.querySelectorAll("tr") || []) {
    const anchor = row.querySelector('[data-attendance-column-control="add"]');
    if (!anchor) continue;
    const cells = new Map([...row.children]
      .filter((cell) => cell.dataset.attendanceColumnKey)
      .map((cell) => [cell.dataset.attendanceColumnKey, cell]));
    for (const key of order) {
      const cell = cells.get(key);
      if (cell) row.insertBefore(cell, anchor);
    }
  }
}

function bindAttendanceCellNavigation() {
  const form = document.querySelector("#attendance-form");
  const table = form?.querySelector("table");
  if (!form || !table) return;
  form.addEventListener("keydown", (event) => {
    const key = event.key;
    if (!key.startsWith("Arrow")) return;
    const field = event.target;
    if (!(field instanceof HTMLElement) || !field.matches("input, select")) return;
    const cell = field.closest("td, th");
    const row = field.closest("tr");
    if (!cell || !row) return;
    // Ô text: ←/→ chỉ chuyển ô khi con trỏ đã ở mép, còn lại giữ nhập bình thường.
    const isText = field instanceof HTMLInputElement && !["checkbox", "radio", "button", "submit", "hidden"].includes(field.type);
    if (isText && key === "ArrowLeft" && (field.selectionStart || 0) > 0) return;
    if (isText && key === "ArrowRight" && (field.selectionEnd ?? field.value.length) < field.value.length) return;
    // <select> giữ ↑/↓ để đổi option như mặc định, chỉ ←/→ mới chuyển ô.
    if (field instanceof HTMLSelectElement && (key === "ArrowUp" || key === "ArrowDown")) return;
    const focusIn = (targetRow, columnKey) => {
      const targetCell = columnKey ? targetRow?.querySelector(`[data-attendance-column-key="${columnKey}"]`) : null;
      const next = targetCell?.querySelector("input:not([disabled]):not([type='hidden']), select:not([disabled])");
      if (next instanceof HTMLElement) {
        next.focus();
        if (next instanceof HTMLInputElement && !["checkbox", "radio"].includes(next.type)) next.select();
        return true;
      }
      return false;
    };
    const rows = [...table.querySelectorAll("tr")];
    const rowIndex = rows.indexOf(row);
    const columnKey = cell.dataset.attendanceColumnKey || "";
    if (key === "ArrowUp" || key === "ArrowDown") {
      const step = key === "ArrowDown" ? 1 : -1;
      for (let index = rowIndex + step; index >= 0 && index < rows.length; index += step) {
        if (focusIn(rows[index], columnKey)) { event.preventDefault(); return; }
      }
      return;
    }
    const headerKeys = [...table.querySelectorAll("thead [data-attendance-column-key]")].map((item) => item.dataset.attendanceColumnKey);
    const columnIndex = headerKeys.indexOf(columnKey);
    if (columnIndex < 0) return;
    const step = key === "ArrowRight" ? 1 : -1;
    for (let index = columnIndex + step; index >= 0 && index < headerKeys.length; index += step) {
      if (focusIn(row, headerKeys[index])) { event.preventDefault(); return; }
    }
  });
}

function bindAttendanceColumnDragging() {
  const form = document.querySelector("#attendance-form");
  const table = form?.querySelector(".nz-attendance-table table");
  const headers = [...(table?.querySelectorAll("thead [data-attendance-column-key]") || [])];
  if (!form || !table || headers.length < 2) return;
  let draggingKey = "";
  const clearDropState = () => headers.forEach((header) => header.classList.remove("is-dragging", "is-drop-before", "is-drop-after"));

  for (const header of headers) {
    header.addEventListener("dragstart", (event) => {
      const eventTarget = event.target instanceof Element ? event.target : null;
      if (eventTarget?.closest("input, button") && !eventTarget.closest("[data-attendance-column-drag-handle]")) {
        event.preventDefault();
        return;
      }
      draggingKey = header.dataset.attendanceColumnKey || "";
      if (!draggingKey) return event.preventDefault();
      header.classList.add("is-dragging");
      if (event.dataTransfer) {
        event.dataTransfer.effectAllowed = "move";
        event.dataTransfer.setData("text/plain", draggingKey);
      }
    });
    header.addEventListener("dragover", (event) => {
      if (!draggingKey || draggingKey === header.dataset.attendanceColumnKey) return;
      event.preventDefault();
      headers.forEach((item) => item.classList.remove("is-drop-before", "is-drop-after"));
      const bounds = header.getBoundingClientRect();
      header.classList.add(event.clientX >= bounds.left + bounds.width / 2 ? "is-drop-after" : "is-drop-before");
      if (event.dataTransfer) event.dataTransfer.dropEffect = "move";
    });
    header.addEventListener("drop", (event) => {
      event.preventDefault();
      const targetKey = header.dataset.attendanceColumnKey || "";
      const currentOrder = [...table.querySelectorAll("thead [data-attendance-column-key]")]
        .map((item) => item.dataset.attendanceColumnKey)
        .filter(Boolean);
      const bounds = header.getBoundingClientRect();
      const placeAfter = event.clientX >= bounds.left + bounds.width / 2;
      const nextOrder = reorderAttendanceColumnKeys(currentOrder, draggingKey, targetKey, placeAfter);
      applyAttendanceColumnOrderToTable(table, nextOrder);
      state.attendanceColumnOrders[form.dataset.sessionId] = nextOrder;
      clearDropState();
      toast("Đã đổi vị trí cột. Bấm Lưu để áp dụng cho báo cáo.");
    });
    header.addEventListener("dragend", () => {
      draggingKey = "";
      clearDropState();
    });
  }
}

function attendanceNoticeText(session, students) {
  if (!session || session.isOff) return "";
  const roster = students || [];
  if (!roster.length) return "";
  const byId = new Map((session.attendance || []).map((row) => [row.studentId, row]));
  if (![...byId.values()].some((row) => row.status)) return "";
  const present = roster.filter((student) => byId.get(student.id)?.status === "PRESENT");
  const late = roster.filter((student) => {
    const row = byId.get(student.id);
    return row?.late && row.status === "PRESENT";
  });
  const absent = roster.filter((student) => byId.get(student.id)?.status === "ABSENT");
  const excused = roster.filter((student) => byId.get(student.id)?.status === "EXCUSED");
  const lines = [`Đã điểm danh ${present.length}/${roster.length}`];
  if (late.length) lines.push(`Đi muộn: ${late.map((student) => student.fullName).join(", ")}`);
  if (absent.length) lines.push(`Vắng không phép: ${absent.map((student) => student.fullName).join(", ")}`);
  if (excused.length) lines.push(`Vắng có phép: ${excused.map((student) => student.fullName).join(", ")}`);
  return lines.join("\n");
}

function attendanceNoticeComplete(session, students) {
  const roster = students || [];
  if (!roster.length || session?.isOff) return false;
  const byId = new Map((session?.attendance || []).map((row) => [row.studentId, row]));
  return roster.every((student) => byId.get(student.id)?.status === "PRESENT");
}
const LESSON_SCHEDULE_START = "2026-09-01";
const SESSION_BALANCE_EPOCH_MONTH = LESSON_SCHEDULE_START.slice(0, 7);

function isAdminConfiguredOff(session) {
  return Boolean(session?.isOff && session.offSource !== "TEACHER");
}

function isPlannedTuitionOff(session) {
  return isAdminConfiguredOff(session);
}

/**
 * Buổi GV cho nghỉ còn nguyên trạng nghỉ. Lớp thu khóa: suất đó không chiếm
 * vị trí của khóa — khóa tự kéo dài để học bù, khóa sau vẫn thu đủ số buổi.
 * Bản sao tuition-billing.
 */
function isTeacherOffSession(session) {
  return Boolean(session?.isOff && session.offSource === "TEACHER" && session.status !== "CANCELLED");
}

/**
 * Buổi "học không tính phí": lớp vẫn học và điểm danh bình thường nhưng không
 * tính tiền. Với lớp thu khóa suất đó không chiếm vị trí của khóa — khóa tự
 * nối dài thêm một suất để bù, giống buổi GV cho nghỉ. Bản sao tuition-billing.
 */
function isNoFeeSession(session) {
  return Boolean(session?.noFee && !session.isOff && session.status !== "CANCELLED");
}

/**
 * Suất lịch không chiếm vị trí "Buổi N" của khóa: nghỉ học vụ, GV cho nghỉ,
 * buổi học không tính phí và buổi bị huỷ đều bị bỏ qua khi sinh/đếm suất —
 * khóa tự kéo dài để học bù. Bản sao tuition-billing.
 */
function isCourseSlotSkippingSession(session) {
  return Boolean(session?.isOff || session?.noFee || session?.status === "CANCELLED");
}

/** Buổi dạy bù đã được xếp cho một buổi nghỉ (nếu có). Buổi bù chiếm đúng vị
 * trí khóa của buổi nghỉ — khóa không kéo dài thêm suất bù ở cuối nữa. Buổi
 * bù bị hủy/nghỉ thì không còn hiệu lực — buổi nghỉ lại chờ được bù. */
function makeupSessionFor(session, sessions = state.data.lessonSessions || []) {
  if (!session?.id) return undefined;
  // Trong một lượt render: chỉ mục buổi bù theo buổi gốc (trang Học phí gọi hàng chục nghìn lần,
  // mỗi lần quét cả lịch). Giữ đúng "buổi đầu tiên khớp" như .find.
  if (perf.active && invoiceQueueRenderCache) {
    let index = invoiceQueueRenderCache.makeups.get(sessions);
    if (!index) {
      index = new Map();
      for (const item of sessions) {
        if (item.makeupOf && !item.isOff && item.status !== "CANCELLED" && !index.has(item.makeupOf)) index.set(item.makeupOf, item);
      }
      invoiceQueueRenderCache.makeups.set(sessions, index);
    }
    return index.get(session.id);
  }
  return sessions.find((item) => item.makeupOf === session.id && !item.isOff && item.status !== "CANCELLED");
}

/** Khoảng ngày thật của một list buổi khóa: buổi dạy bù được phát ra đúng vị
 * trí buổi nghỉ nhưng mang ngày riêng, nên list theo vị trí không đảm bảo
 * tăng dần theo ngày — start/end phải lấy min/max thay vì đầu/cuối list. */
function sessionRowsDateRange(rows) {
  let start = "", end = "";
  for (const row of rows || []) {
    const date = row?.date || "";
    if (!date) continue;
    if (!start || date < start) start = date;
    if (!end || date > end) end = date;
  }
  return { start, end };
}

/**
 * Hàng trong bảng khóa không chiếm số "Buổi N": GV nghỉ, học không tính phí,
 * buổi huỷ và nghỉ học vụ trên ngày lịch thường — tất cả đã làm khóa giãn để
 * học bù. Riêng nghỉ học vụ trong khe hở cắt cố ý của các lớp được đếm (vd
 * S13 nghỉ 01/09 = Buổi 16 trên sheet) vẫn giữ số buổi như trước.
 */
function isCourseUnnumberedRow(cls, session) {
  if (!isCourseSlotSkippingSession(session)) return false;
  // Buổi "không tính phí" ghim về khóa trước (vd S40 17/10 = buổi 25 khóa 1)
  // vẫn đánh số "Buổi N" — chỉ không tính phí, giãn khóa để bù như thường.
  if (BOUNDARY_NOFEE_COURSE_OVERRIDES.has(`${cls?.id || ""}|${String(session?.date || "")}`)) return false;
  if (!isAdminConfiguredOff(session)) return true;
  return !(COURSE_GAP_ADMIN_OFF_CLASS_IDS.has(cls?.id)
    && classScheduleGapAround(cls, sessionClaimDate(session), session.startTime));
}

function sessionChargesTuition(session) {
  if (!session || session.status === "CANCELLED" || isPlannedTuitionOff(session) || session.noFee) return false;
  if (session.isOff && session.offSource === "TEACHER") return true;
  return session.status === "COMPLETED" && !session.isOff;
}

function sessionIdentity(session) {
  return session.recurrenceKey || `${session.classId}|${session.date}|${session.startTime}`;
}

/** Ngày mà một bản ghi buổi học "chiếm" suất lịch — theo recurrenceKey nếu có. Bản sao tuition-billing. */
function sessionClaimDate(session) {
  return String(session?.recurrenceKey || "").split("|")[1] || session?.date;
}

/**
 * Ghép bản ghi thật vào các suất lịch của một ngày: bản ghi cùng ngày khác giờ
 * (lịch đã chỉnh sau khi có bản ghi) chiếm suất trống còn lại thay vì đếm thêm.
 * Bản sao tuition-billing.
 */
function claimDaySlots(daySlots, storedToday) {
  const claimed = new Array(daySlots.length);
  const pending = [];
  for (const item of storedToday) {
    const index = daySlots.findIndex((slot, i) => !claimed[i] && slot.startTime === item.startTime);
    if (index >= 0) claimed[index] = item; else pending.push(item);
  }
  const leftovers = [];
  for (const item of pending) {
    const index = daySlots.findIndex((slot, i) => !claimed[i]);
    if (index >= 0) claimed[index] = item; else leftovers.push(item);
  }
  return { claimed, leftovers };
}

function storedSessionsByClaimDate(sessions, classId) {
  const map = new Map();
  for (const item of sessions || []) {
    if (item.classId !== classId || item.isExtra) continue;
    const date = sessionClaimDate(item);
    if (!map.has(date)) map.set(date, []);
    map.get(date).push(item);
  }
  for (const list of map.values()) list.sort((a, b) => a.startTime.localeCompare(b.startTime));
  return map;
}

function sessionStudentIds(session, cls) {
  return perfMemo("sessids", `${session ? session.id || sessionIdentity(session) : ""}|${cls?.id}`, () => sessionStudentIdsInner(session, cls));
}

function sessionStudentIdsInner(session, cls) {
  const ids = new Set(cls?.studentIds || []);
  for (const row of session?.attendance || []) {
    if (row.studentId) ids.add(row.studentId);
  }
  return ids;
}

/** Bản sao courseOneReceivableOpen bên tuition-billing: phiếu thu khóa 1 đang mở = chưa đóng khóa đầu. */
function courseOneReceivableOpen(studentId, cls) {
  return perfMemo("c1open", `${studentId}|${cls?.id}`, () => courseOneReceivableOpenInner(studentId, cls));
}

function courseOneReceivableOpenInner(studentId, cls) {
  if (!studentId) return false;
  return perfStudentReceivables(studentId).some((receivable) => {
    if (receivable.studentId !== studentId) return false;
    if (receivable.status !== "OPEN" && receivable.status !== "PARTIALLY_PAID") return false;
    const billKey = String(receivable.billKey || "");
    return billKey.split("|")[0] === "course"
      && billKey.split("|")[1] === cls.id
      && courseIndexOfBillKey(billKey) === 1;
  });
}

/** Số suất lịch đã trôi qua trước endKey: nghỉ lễ vẫn chiếm vị trí trong khóa,
 * suất GV cho nghỉ thì không nên ranh giới khóa tự đẩy sang. Bản sao tuition-billing. */
function classScheduleSlotsBefore(cls, endKey, sessions = []) {
  const compute = () => classScheduleSlotsBeforeInner(cls, endKey, sessions);
  return perfDefaultSessions(sessions) ? perfMemo("slotsbefore", `${cls?.id}|${endKey}`, compute) : compute();
}

function classScheduleSlotsBeforeInner(cls, endKey, sessions = []) {
  const startKey = classCourseStartDate(cls);
  if (startKey >= endKey) return 0;
  const storedByDate = storedSessionsByClaimDate(sessions, cls.id);
  let count = 0;
  for (let cursor = localDate(startKey); localDateKey(cursor) < endKey; cursor = addDays(cursor, 1)) {
    const date = localDateKey(cursor);
    const daySlots = (cls.schedules || []).filter((slot) => scheduleSlotAppliesOnDate(slot, date));
    if (!daySlots.length) continue;
    const { claimed } = claimDaySlots(daySlots, storedByDate.get(date) || []);
    for (const stored of claimed) {
      // Suất nghỉ không đếm — trừ khi đã có buổi dạy bù lấp đúng vị trí đó.
      if (isCourseSlotSkippingSession(stored) && !makeupSessionFor(stored, sessions)) continue;
      count += 1;
    }
  }
  return count;
}

/** Khóa đang chạy hiện tại: suất lịch trôi qua dồn vào từng khóa theo số
 * buổi riêng của khóa đó (khóa 1 của lớp override có thể ngắn hơn). */
function classCurrentCourseIndex(cls, now = new Date(), sessions = state.data.lessonSessions || []) {
  const compute = () => boundaryHeldCourseIndex(cls, localDateKey(now), courseIndexAtSlotOrdinal(cls, classScheduleSlotsBefore(cls, localDateKey(now), sessions)));
  return perfDefaultSessions(sessions) ? perfMemo("ccidx", `${cls?.id}|${localDateKey(now)}`, compute) : compute();
}

/** Buổi ghim cuối khóa (BOUNDARY_NOFEE_COURSE_OVERRIDES) chưa qua thì lớp vẫn
 * đang ở khóa sở hữu buổi đó — khóa sau (công nợ) chỉ mở từ ngày sau buổi ghim.
 * Bản sao tuition-billing. */
function boundaryHeldCourseIndex(cls, todayKey, index) {
  let held = index;
  for (const [key, owner] of BOUNDARY_NOFEE_COURSE_OVERRIDES) {
    const [classId, date] = key.split("|");
    if (classId === cls?.id && todayKey <= date && owner < held) held = owner;
  }
  return held;
}

function classCourseIndexOfDate(cls, date, sessions = state.data.lessonSessions || []) {
  const compute = () => BOUNDARY_NOFEE_COURSE_OVERRIDES.get(`${cls?.id || ""}|${String(date || "")}`)
    ?? courseIndexAtSlotOrdinal(cls, classScheduleSlotsBefore(cls, date, sessions));
  return perfDefaultSessions(sessions) ? perfMemo("ccidate", `${cls?.id}|${date}`, compute) : compute();
}

/** Mốc thu học phí khóa qua hệ thống — mirror COURSE_BILLING_GOLIVE của tuition-billing. */
const COURSE_BILLING_GOLIVE = LESSON_SCHEDULE_START;

/** Khóa đầu tiên học viên phải đóng ở lớp: khóa chứa ngày nhập học, mặc định khóa 1. */
function studentFirstCourseIndex(student, cls) {
  const joinDate = studentClassJoinDate(student, cls?.id);
  return joinDate ? Math.max(1, classCourseIndexOfDate(cls, joinDate)) : 1;
}

/** Phiếu khóa (bỏ phiếu hủy, phiếu chuyển lớp) của học viên ở lớp, gom theo số khóa. */
function studentCourseReceivables(studentId, cls) {
  return perfMemo("scr", `${studentId}|${cls?.id}`, () => {
    const map = new Map();
    for (const row of perfStudentReceivables(studentId)) {
      if (row.studentId !== studentId || row.status === "CANCELLED") continue;
      const parts = String(row.billKey || "").split("|");
      if (parts[0] !== "course" || parts[1] !== cls.id) continue;
      const index = courseIndexOfBillKey(row.billKey);
      map.set(index, [...(map.get(index) || []), row]);
    }
    return map;
  });
}

/** Phiếu khóa còn mở: OPEN/PARTIALLY_PAID và chưa về số dư 0 (phiếu cũ không ghi số dư vẫn tính là mở). */
function courseRowIsOpen(row) {
  if (!["OPEN", "PARTIALLY_PAID"].includes(String(row?.status))) return false;
  const balance = row.balanceDue ?? row.amountDue;
  return balance === undefined || balance === null || Math.round(Number(balance) || 0) > 0;
}

function courseRowOpenBalance(row) {
  return courseRowIsOpen(row) ? Math.max(0, Math.round(Number(row.balanceDue ?? row.amountDue) || 0)) : 0;
}

/** Phiếu khóa chưa bắt đầu nhưng đã gửi yêu cầu / đã thu một phần — vẫn là nợ, thu tiếp được (mirror server). */
function courseRowRequestedEarly(row) {
  return courseRowIsOpen(row) && (Boolean(row.frozenAt) || Math.round(Number(row.amountPaid) || 0) > 0);
}

/** Khóa đã thu ngoài hệ thống: bắt đầu trước mốc golive, học viên không có phiếu nào của khóa. */
function isLegacyPaidCourse(student, cls, index) {
  if ((studentCourseReceivables(student.id, cls).get(index) || []).length) return false;
  // Khóa 1 so theo ngày khai giảng đã cấu hình, các khóa sau theo buổi đầu của khóa.
  const explicit = /^\d{4}-\d{2}-\d{2}$/.test(String(cls?.courseStartDate || "")) ? cls.courseStartDate : undefined;
  const start = index === 1 ? explicit : classCourseWindowByIndex(cls, index).start;
  return Boolean(start && start < COURSE_BILLING_GOLIVE);
}

/**
 * Trạng thái thu từng khóa (mirror studentCourseCollectStates của server):
 * DUE thu được · PAID đã đủ · LEGACY_PAID thu trước khi dùng hệ thống ·
 * FUTURE chưa bắt đầu (chỉ xem phiếu báo) · COVERED phiếu lớp nguồn bao phủ.
 */
function studentCourseCollectStates(student, cls) {
  return perfMemo("sccs", `${student?.id}|${cls?.id}|${localDateKey(new Date())}`, () => {
    const current = classCurrentCourseIndex(cls);
    const first = studentFirstCourseIndex(student, cls);
    const rows = studentCourseReceivables(student.id, cls);
    const states = [];
    const lastEarly = Math.max(0, ...[...rows.entries()].filter(([, list]) => list.some(courseRowRequestedEarly)).map(([index]) => index));
    for (let index = first; index <= Math.max(current + 1, first, lastEarly); index += 1) {
      const list = rows.get(index) || [];
      const balance = list.reduce((sum, row) => sum + courseRowOpenBalance(row), 0);
      const hasOpen = list.some(courseRowIsOpen);
      let status;
      if (index > current && list.some(courseRowRequestedEarly)) status = "DUE";
      else if (index > current) status = "FUTURE";
      else if (hasOpen) status = "DUE";
      else if (list.length) status = "PAID";
      else if (isLegacyPaidCourse(student, cls, index)) status = "LEGACY_PAID";
      else if (isTransferCoveredCourse(student, cls, index)) status = "COVERED";
      else status = "DUE";
      // Khóa đã bắt đầu mà phiếu chưa kịp lập (đồng bộ chạy ở lượt ghi kế tiếp) — nợ theo báo giá.
      const due = status === "DUE" ? (balance > 0 ? balance : Math.max(0, Math.round(Number(courseQuoteFor(student, cls, index).amount) || 0))) : 0;
      states.push({ index, status, due, receivable: list.find(courseRowIsOpen) || list[0] || null });
    }
    return states;
  });
}

/** Khóa mặc định để thu: khóa cũ nhất còn nợ đã bắt đầu, không còn thì khóa đang học. */
function defaultCollectCourseIndex(student, cls) {
  const states = studentCourseCollectStates(student, cls);
  return states.find((row) => row.status === "DUE" && row.due > 0)?.index
    || Math.max(studentFirstCourseIndex(student, cls), classCurrentCourseIndex(cls));
}

/** Công nợ lớp thu khóa = tổng phần còn nợ của các khóa đã bắt đầu. */
function courseDebtAmount(student, cls) {
  if (student?.tuitionExempt) return 0;
  return studentCourseCollectStates(student, cls).reduce((sum, row) => sum + (row.status === "DUE" ? row.due : 0), 0);
}

/** Khóa mà biên lai đã trả, suy từ billKey của khoản phải thu gốc. */
function receiptCourseIndex(receipt) {
  return perfMemo("rci", receipt?.id, () => {
    const maps = perfMaps();
    const payment = maps.paymentsById.get(receipt.paymentId);
    const receivable = maps.receivablesById.get(payment?.receivableId);
    return courseIndexOfBillKey(receivable?.billKey);
  });
}

function paidCourseSessions(student, cls, courseIndex, assumedCourseSize) {
  return perfMemo("paidcourse", `${student?.id}|${cls?.id}|${courseIndex ?? ""}|${assumedCourseSize ?? ""}`, () => paidCourseSessionsInner(student, cls, courseIndex, assumedCourseSize));
}

function paidCourseSessionsInner(student, cls, courseIndex, assumedCourseSize) {
  const price = classSessionPrice(cls);
  let extraPaid = 0;
  for (const receipt of perfStudentReceipts(student.id)) {
    if (receipt.studentId !== student.id) continue;
    if (!receipt.classId || receiptClassId(receipt) !== cls.id) continue;
    if ((receipt.billingMode || "COURSE") !== "COURSE") continue;
    if (courseIndex !== undefined && receiptCourseIndex(receipt) !== courseIndex) continue;
    extraPaid += price > 0 ? Math.round(receiptTuitionAmount(receipt, joinExcessIndex().byPayment.get(receipt.paymentId) || 0) / price) : classCourseSizeAt(cls, receiptCourseIndex(receipt) || 1);
  }
  extraPaid += appliedJoinExcessSessions(student.id, cls, courseIndex);
  // Mỗi khóa một hộp riêng: chỉ khóa 1 được mặc định "đã đóng" (lớp cũ trước
  // SePay, không phiếu khóa 1 đang mở); khóa 2+ không biên lai đúng khóa thì = 0.
  const legacyCourseOne = (courseIndex === undefined || courseIndex === 1)
    && (cls?.courseStartDate ? String(cls.courseStartDate) < COURSE_BILLING_GOLIVE : true);
  if (!legacyCourseOne) return extraPaid;
  // Khóa 1 lớp cũ: mặc định đã đóng đủ, trừ số buổi ứng với phần còn nợ của phiếu khóa 1 (mirror server).
  const size = assumedCourseSize ?? classCourseSizeAt(cls, 1);
  const open = perfStudentReceivables(student.id).reduce((sum, receivable) => {
    if (receivable.status !== "OPEN" && receivable.status !== "PARTIALLY_PAID") return sum;
    const billKey = String(receivable.billKey || "");
    if (billKey.split("|")[0] !== "course" || billKey.split("|")[1] !== cls.id || courseIndexOfBillKey(billKey) !== 1) return sum;
    return sum + Math.max(0, Math.round(Number(receivable.balanceDue) || 0));
  }, 0);
  // Nợ cũ gộp vào phiếu khóa 2+ (phần vượt học phí khóa đó) — mirror server; học viên có
  // nợ buổi nhập tay (tuitionCredits âm) thì phần đó đã trừ riêng.
  const legacyCredit = Math.round(Number(student?.tuitionCredits?.[cls.id]) || 0);
  const lumped = legacyCredit < 0 ? 0 : perfStudentReceivables(student.id).reduce((sum, receivable) => {
    if (receivable.status === "CANCELLED" || receivable.classId !== cls.id) return sum;
    const billKey = String(receivable.billKey || "");
    if (billKey.split("|")[0] !== "course") return sum;
    const index = courseIndexOfBillKey(billKey);
    if (index < 2) return sum;
    const nominal = classCourseSizeAt(cls, index) * price + Math.max(0, Math.round(Number(courseMaterialFee(cls, index).amount) || 0));
    return sum + Math.max(0, Math.round(Number(receivable.amountDue) || 0) - nominal);
  }, 0);
  const owed = open + lumped;
  const unpaid = owed <= 0 ? 0 : price > 0 ? Math.round(owed / price) : size;
  return Math.max(Math.max(0, size - unpaid), extraPaid);
}

function chargedCourseSessions(studentId, cls, courseIndex, joinDate) {
  return perfMemo("ccourse", `${studentId}|${cls?.id}|${courseIndex ?? ""}|${joinDate ?? ""}`, () => chargedCourseSessionsInner(studentId, cls, courseIndex, joinDate));
}

function chargedCourseSessionsInner(studentId, cls, courseIndex, joinDate) {
  const sessions = state.data.lessonSessions || [];
  const startKey = classCourseStartDate(cls);
  const todayKey = localDateKey(new Date());
  const explicit = perfClassSessions(cls.id);
  const storedByDate = perfStoredByClaimDate(cls.id);
  const seen = new Set();
  let count = 0;
  let slotIndex = 0;
  // Suất lịch đã qua tính phí như elapsed, chạy liên tục qua mọi khóa; suất
  // chưa lưu bản ghi vẫn coi như đã dạy. courseIndex lọc về đúng "hộp" khóa.
  if (startKey <= todayKey) {
    for (let cursor = localDate(startKey); localDateKey(cursor) < todayKey; cursor = addDays(cursor, 1)) {
      const date = localDateKey(cursor);
      const daySlots = (cls.schedules || []).filter((slot) => scheduleSlotAppliesOnDate(slot, date));
      if (!daySlots.length) continue;
      const { claimed } = claimDaySlots(daySlots, storedByDate.get(date) || []);
      for (const stored of claimed) {
        if (stored) seen.add(sessionIdentity(stored));
        // Suất nghỉ (học vụ hoặc GV) hoặc "học không tính phí" không chiếm vị
        // trí khóa và không tính phí — khóa đã tự kéo dài để học bù. Nếu đã có
        // buổi dạy bù thì buổi bù chiếm vị trí này và tính phí như buổi thường
        // (chỉ khi buổi bù đã diễn ra).
        const makeup = stored ? makeupSessionFor(stored, sessions) : undefined;
        if (isCourseSlotSkippingSession(stored) && !makeup) continue;
        const belongsTo = courseIndexAtSlotOrdinal(cls, slotIndex);
        slotIndex += 1;
        if (courseIndex !== undefined && belongsTo !== courseIndex) continue;
        if (makeup) seen.add(sessionIdentity(makeup));
        if (!sessionChargesTuition(makeup || stored || { status: "COMPLETED", isOff: false })) continue;
        // Buổi trước ngày nhập học không tính phí cho học viên này.
        if (joinDate && date < joinDate) continue;
        if (!sessionStudentIds(makeup || stored, cls).has(studentId)) continue;
        count += 1;
      }
    }
  }
  // Bản ghi ngoài thời khóa biểu (học thêm, GV nghỉ ghi trước...) gán về khóa theo ngày.
  // Buổi trước ngày bắt đầu khóa thuộc chu kỳ khóa cũ — không tính vào khóa
  // hiện tại (đồng bộ classElapsedCourseSessions vốn cũng bỏ qua các bản ghi đó).
  for (const session of explicit) {
    if (seen.has(sessionIdentity(session))) continue;
    if (session.date < startKey) continue;
    if (joinDate && session.date < joinDate) continue;
    if (session.isOff || !sessionChargesTuition(session) || !sessionStudentIds(session, cls).has(studentId)) continue;
    if (courseIndex !== undefined && classCourseIndexOfDate(cls, session.date, sessions) !== courseIndex) continue;
    count += 1;
  }
  return count;
}

function lessonScheduleWindow() {
  const start = localDate(LESSON_SCHEDULE_START);
  const today = localDate(localDateKey(new Date()));
  const futureAnchor = today > start ? today : start;
  return { start, end: addMonths(futureAnchor, 6) };
}

function parseClassRoute(teacherView = false) {
  const match = state.route.match(teacherView
    ? /^\/gv\/lop-hoc\/([^/]+)(?:\/(hoc-vien|diem-danh|syllabus)(?:\/([^/]+))?)?$/
    : /^\/lop-hoc\/([^/]+)(?:\/(hoc-vien|diem-danh|syllabus)(?:\/([^/]+))?)?$/);
  if (!match) return null;
  return { id: decodeURIComponent(match[1]), tab: match[2] || "info", sessionId: match[3] ? decodeURIComponent(match[3]) : "" };
}

function classHref(id, tab = "info", sessionId = "", teacherView = false) {
  const base = `${teacherView ? "/gv/lop-hoc" : "/lop-hoc"}/${encodeURIComponent(id)}`;
  if (!tab || tab === "info") return base;
  return sessionId ? `${base}/${tab}/${encodeURIComponent(sessionId)}` : `${base}/${tab}`;
}

function classSessions(cls) {
  return perfMemo("clsess", `${cls?.id}`, () => classSessionsInner(cls));
}

function classSessionsInner(cls) {
  const { start, end } = lessonScheduleWindow();
  const explicit = (state.data.lessonSessions || []).filter((item) => item.classId === cls.id && item.date >= LESSON_SCHEDULE_START);
  const storedByDate = perfStoredByClaimDate(cls.id);
  const generated = [];
  const generatedKeys = new Set();
  const startKey = classCourseStartDate(cls);
  for (let cursor = new Date(start.getFullYear(), start.getMonth(), start.getDate(), 12); cursor <= end; cursor = addDays(cursor, 1)) {
    const date = localDateKey(cursor);
    // Lớp chưa khai giảng (courseStartDate ở tương lai) thì chưa có suất lịch —
    // không hiện trên bảng điểm danh/lịch dạy cho tới ngày bắt đầu.
    if (date < startKey) continue;
    const daySlots = (cls.schedules || []).filter((slot) => scheduleSlotAppliesOnDate(slot, date));
    if (!daySlots.length) continue;
    const { claimed } = claimDaySlots(daySlots, storedByDate.get(date) || []);
    for (let index = 0; index < daySlots.length; index += 1) {
      const slot = daySlots[index];
      const stored = claimed[index];
      const key = `${cls.id}|${date}|${slot.startTime}`;
      if (stored) generatedKeys.add(sessionIdentity(stored));
      generatedKeys.add(key);
      generated.push(stored || {
        id: `recurring|${key}`,
        classId: cls.id,
        date,
        startTime: slot.startTime,
        endTime: slot.endTime,
        teacherId: cls.teacherId,
        roomId: cls.roomId,
        status: date < localDateKey(new Date()) ? "COMPLETED" : "SCHEDULED",
        isExtra: false,
        recurrenceKey: key,
        note: "",
        isOff: false,
        hasHomework: false,
        attendance: [],
      });
    }
  }
  const standalone = explicit.filter((item) => item.isExtra || !generatedKeys.has(item.recurrenceKey || `${item.classId}|${item.date}|${item.startTime}`));
  const items = [...generated, ...standalone].sort((a, b) => `${a.date}${a.startTime}`.localeCompare(`${b.date}${b.startTime}`));
  const courseSequence = classBillingMode(cls) === "COURSE"
    ? new Map(classCourseWindows(cls).flatMap((item) => mergeCourseOffSessions(cls, item.sessions, item.index).filter((row) => !isCourseUnnumberedRow(cls, row))).map((item, index) => [item.recurrenceKey || `${item.classId}|${item.date}|${item.startTime}`, index + 1]))
    : new Map();
  return items.map((item, index) => ({
    ...item,
    sequence: isCourseUnnumberedRow(cls, item) && courseSequence.size
      ? "—"
      : (courseSequence.get(item.recurrenceKey || `${item.classId}|${item.date}|${item.startTime}`) || index + 1),
  }));
}

function classMonthScheduleSessions(cls, key = monthKey()) {
  return perfMemo("cmss", `${cls?.id}|${key}`, () => classMonthScheduleSessionsInner(cls, key));
}

function classMonthScheduleSessionsInner(cls, key = monthKey()) {
  const selected = /^\d{4}-(0[1-9]|1[0-2])$/.test(String(key || "")) ? key : monthKey();
  const [year, month] = selected.split("-").map(Number);
  const start = new Date(year, month - 1, 1, 12);
  const end = new Date(year, month, 0, 12);
  const explicit = (state.data.lessonSessions || []).filter((item) => item.classId === cls.id && item.date.startsWith(selected));
  const storedByDate = storedSessionsByClaimDate(explicit, cls.id);
  const rows = [];
  const courseStartKey = classCourseStartDate(cls);
  for (let cursor = new Date(start); cursor <= end; cursor = addDays(cursor, 1)) {
    const date = localDateKey(cursor);
    if (date < courseStartKey) continue;
    const daySlots = (cls.schedules || []).filter((slot) => scheduleSlotAppliesOnDate(slot, date));
    if (!daySlots.length) continue;
    const { claimed } = claimDaySlots(daySlots, storedByDate.get(date) || []);
    for (let index = 0; index < daySlots.length; index += 1) {
      const slot = daySlots[index];
      const stored = claimed[index];
      const recurrenceKey = `${cls.id}|${date}|${slot.startTime}`;
      rows.push(stored || {
        id: `recurring|${recurrenceKey}`,
        classId: cls.id,
        date,
        startTime: slot.startTime,
        endTime: slot.endTime,
        teacherId: cls.teacherId,
        roomId: cls.roomId,
        status: date < localDateKey(new Date()) ? "COMPLETED" : "SCHEDULED",
        isExtra: false,
        recurrenceKey,
        note: "",
        isOff: false,
        hasHomework: false,
        attendance: [],
      });
    }
  }
  const generatedKeys = new Set(rows.map((item) => item.recurrenceKey || `${item.classId}|${item.date}|${item.startTime}`));
  rows.push(...explicit.filter((item) => item.isExtra || !generatedKeys.has(item.recurrenceKey || `${item.classId}|${item.date}|${item.startTime}`)));
  return rows.sort((a, b) => `${a.date}|${a.startTime}|${a.id}`.localeCompare(`${b.date}|${b.startTime}|${b.id}`));
}

function classCourseStartDate(row) {
  const value = String(row?.courseStartDate || "");
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return LESSON_SCHEDULE_START;
  const parsed = localDate(value);
  return Number.isNaN(parsed.getTime()) || localDateKey(parsed) !== value ? LESSON_SCHEDULE_START : value;
}

function classCourseScheduleSessions(cls, startDate = classCourseStartDate(cls), sessionCount = classCourseSizeAt(cls, 1), sourceSessions = state.data.lessonSessions || []) {
  const target = Math.max(1, Math.min(1000, Math.round(Number(sessionCount) || classCourseSizeAt(cls, 1))));
  const start = localDate(startDate);
  if (Number.isNaN(start.getTime())) return [];
  const slots = [...(cls.schedules || [])].sort((a, b) => `${a.weekday}|${a.startTime}`.localeCompare(`${b.weekday}|${b.startTime}`));
  if (!slots.length) return [];
  const storedByDate = perfDefaultSessions(sourceSessions) ? perfStoredByClaimDate(cls.id) : storedSessionsByClaimDate(sourceSessions || [], cls.id);
  const rows = [];
  const guardDays = Math.max(366, target * 14 + 14);
  for (let offset = 0; offset <= guardDays && rows.length < target; offset += 1) {
    const cursor = addDays(start, offset);
    const date = localDateKey(cursor);
    const daySlots = slots.filter((slot) => scheduleSlotAppliesOnDate(slot, date));
    if (!daySlots.length) continue;
    const { claimed } = claimDaySlots(daySlots, storedByDate.get(date) || []);
    for (let index = 0; index < daySlots.length; index += 1) {
      if (rows.length >= target) break;
      const slot = daySlots[index];
      const stored = claimed[index];
      // Suất nghỉ (học vụ hoặc GV) hoặc "học không tính phí" không phát sinh
      // buổi của khóa — khóa dài ra đúng một suất để học bù vào cuối, khóa sau
      // không mất buổi nào. Riêng buổi nghỉ đã được xếp lịch dạy bù thì buổi
      // bù chiếm đúng vị trí này — khóa kết thúc đúng hạn như chưa nghỉ.
      if (isCourseSlotSkippingSession(stored)) {
        const makeup = makeupSessionFor(stored, sourceSessions);
        if (makeup) rows.push(makeup);
        continue;
      }
      const recurrenceKey = `${cls.id}|${date}|${slot.startTime}`;
      rows.push(stored || {
        id: `recurring|${recurrenceKey}`,
        classId: cls.id,
        date,
        startTime: slot.startTime,
        endTime: slot.endTime,
        teacherId: cls.teacherId,
        roomId: cls.roomId,
        status: date < localDateKey(new Date()) ? "COMPLETED" : "SCHEDULED",
        isExtra: false,
        recurrenceKey,
        note: "",
        isOff: false,
        hasHomework: false,
        attendance: [],
      });
    }
  }
  return rows;
}

/**
 * Buổi GV cho nghỉ không chiếm suất khóa nên không nằm trong danh sách buổi
 * của khóa — nhưng vẫn phải hiển thị để ai cũng thấy lớp đã nghỉ ngày đó.
 * Trộn các bản ghi nghỉ nằm trong khung ngày của khóa vào list, giữ nguyên
 * thứ tự thời gian; các hàng này không đánh số "Buổi N" và không tính phí.
 * Ngoại lệ: buổi thêm trước ngày khai giảng khóa 1 (vd lớp mở sớm) trộn vào
 * khóa 1 — được đánh số theo thứ tự ngày nhưng vẫn không tính phí.
 */
/** Ngoại lệ theo lớp: chỉ các lớp này đếm buổi nghỉ học vụ (nằm trong khe hở
 * lịch cố ý) vào số thứ tự "Buổi N" của khóa — vd S13 nghỉ 01/09 = Buổi 16
 * theo sheet. Lớp khác (S15…) nghỉ học vụ không hiện trong bảng khóa. */
const COURSE_GAP_ADMIN_OFF_CLASS_IDS = new Set(["class-import-s13"]);

/** Buổi "học không tính phí" rơi đúng biên hai khóa mà thực chất là buổi cuối
 * của khóa trước — vd S40 buổi 17/10/2026: điểm danh thật, không tính phí,
 * thuộc khóa 1 (khóa 2 mở buổi 1 ngày 19/10). Buổi được ghim vẫn đánh số
 * "Buổi N" trong bảng khóa trước nhưng không chiếm suất tính phí.
 * Key = `${classId}|${date}`, value = index khóa sở hữu. */
const BOUNDARY_NOFEE_COURSE_OVERRIDES = new Map([["class-import-s40|2026-10-17", 1], ["class-import-s36|2026-10-24", 1], ["class-import-s42|2026-10-27", 1], ["class-import-s42|2026-10-31", 1]]);

function mergeCourseOffSessions(cls, courseSessions, courseIndex, sourceSessions = state.data.lessonSessions || []) {
  const { start: first, end: last } = sessionRowsDateRange(courseSessions);
  if (!first || !last) return courseSessions;
  const known = new Set(courseSessions.map((item) => sessionIdentity(item) || item.id));
  const offs = (sourceSessions || []).filter((item) => {
    if (item.classId !== cls.id || known.has(sessionIdentity(item) || item.id)) return false;
    // Buổi thêm trước ngày khai giảng khóa 1 = buổi dạy sớm của khóa đó —
    // trộn vào bảng khóa 1, đánh số "Buổi N" theo thứ tự, không tính phí.
    if (item.isExtra && !item.isOff) {
      return courseIndex === 1 && item.date < classCourseStartDate(cls);
    }
    const claim = sessionClaimDate(item);
    const inGap = classScheduleGapAround(cls, claim, item.startTime);
    // Nghỉ học vụ trên ngày lịch lớp được cắt đúng quanh (suất cùng thứ/giờ
    // kết thúc trước và mở lại sau ngày đó): chỉ các lớp được đếm mới giữ vị
    // trí "Buổi N · Nghỉ" trong khóa — trộn lại vào bảng thay vì để biến mất.
    if (isAdminConfiguredOff(item) && inGap) {
      return COURSE_GAP_ADMIN_OFF_CLASS_IDS.has(cls.id)
        && courseIndex !== undefined
        && classCourseIndexOfDate(cls, claim, sourceSessions) === courseIndex;
    }
    // Buổi nghỉ (học vụ hoặc GV) / học không tính phí / buổi huỷ không chiếm
    // suất nên toàn bộ suất khóa trôi sau — neo theo khoảng [first, last] sẽ
    // làm mất buổi nghỉ rơi đúng biên khóa (ví dụ suất đầu khóa). Thuộc khóa
    // nào xác định bằng số suất billable đã trôi trước ngày đó — bất biến với
    // việc suất bị đẩy. Buổi nghỉ rơi khe hở cắt cố ý không trộn vào khóa.
    if (!item.isOff && !isNoFeeSession(item) && item.status !== "CANCELLED") return false;
    if (inGap) return false;
    // Nghỉ học vụ / buổi huỷ chỉ trộn khi ngày đó thật sự có suất lịch — bản
    // ghi nghỉ trên ngày không học (suất chưa hiệu lực/đã hết) không thuộc
    // khóa nào cả, để ngoài bảng khóa như trước.
    if (isAdminConfiguredOff(item) || (item.status === "CANCELLED" && !item.isOff)) {
      const hasSlot = (cls.schedules || []).some((slot) => scheduleSlotAppliesOnDate(slot, claim) && slot.startTime === item.startTime);
      if (!hasSlot) return false;
    }
    return courseIndex === undefined
      ? claim >= first && claim <= last
      : claim >= classCourseStartDate(cls) && classCourseIndexOfDate(cls, claim, sourceSessions) === courseIndex;
  });
  return [...courseSessions, ...offs].sort((a, b) => `${a.date}|${a.startTime}`.localeCompare(`${b.date}|${b.startTime}`));
}

/** Ngày `date` có phải khe hở cố ý trong lịch lớp không: có suất cùng thứ/giờ
 * kết thúc trước date (effectiveTo) và suất cùng thứ/giờ mở lại sau date
 * (effectiveFrom) — tức lịch được tách để bỏ qua đúng ngày đó. */
function classScheduleGapAround(cls, date, startTime) {
  const weekday = localDate(date).getDay();
  let endsBefore = false;
  let startsAfter = false;
  for (const slot of cls?.schedules || []) {
    if (slot.weekday !== weekday || slot.startTime !== startTime) continue;
    if (slot.effectiveTo && slot.effectiveTo < date) endsBefore = true;
    if (slot.effectiveFrom && slot.effectiveFrom > date) startsAfter = true;
  }
  return endsBefore && startsAfter;
}

/** Danh sách buổi của một khóa để hiển thị: suất lịch + nghỉ GV + buổi thêm/nghỉ thuộc khóa. */
function classCourseViewSessions(cls, courseIndex) {
  const index = Math.max(1, Math.round(Number(courseIndex) || 1));
  const compute = () => mergeCourseOffSessions(cls, classCourseWindowByIndexInner(cls, index).sessions, index);
  return perfMemo("ccview", `${cls?.id}|${index}`, compute);
}

/**
 * Cửa sổ của khóa thứ `courseIndex` (đếm từ 1): khóa 1 neo courseStartDate,
 * khóa sau nối tiếp ngay suất lịch cuối khóa trước, cùng `courseSessions` suất.
 */
function classCourseWindowByIndex(cls, courseIndex = 1, sourceSessions = state.data.lessonSessions || []) {
  const index = Math.max(1, Math.round(Number(courseIndex) || 1));
  const compute = () => classCourseWindowByIndexInner(cls, index, sourceSessions);
  return perfDefaultSessions(sourceSessions) ? perfMemo("ccw", `${cls?.id}|${index}`, compute) : compute();
}

function classCourseWindowByIndexInner(cls, courseIndex = 1, sourceSessions = state.data.lessonSessions || []) {
  const index = Math.max(1, Math.round(Number(courseIndex) || 1));
  const offset = courseSlotOffsetBefore(cls, index);
  const all = classCourseScheduleSessions(cls, classCourseStartDate(cls), offset + classCourseWindowSlotsAt(cls, index), sourceSessions);
  const sessions = withPinnedBoundarySessions(cls, index, all.slice(offset, offset + classCourseWindowSlotsAt(cls, index)), sourceSessions);
  const { start, end } = sessionRowsDateRange(sessions);
  return { index, start, end, sessions };
}

/** Buổi ghim cuối khóa (BOUNDARY_NOFEE_COURSE_OVERRIDES, vd buổi học không tính phí)
 * hiện trong danh sách của đúng khóa sở hữu — khóa kết thúc ở ngày buổi ghim. */
function withPinnedBoundarySessions(cls, index, sessions, sourceSessions = state.data.lessonSessions || []) {
  const pinnedDates = [...BOUNDARY_NOFEE_COURSE_OVERRIDES].filter(([key, owner]) => owner === index && key.split("|")[0] === cls?.id).map(([key]) => key.split("|")[1]);
  if (!pinnedDates.length || !sessions.length) return sessions;
  const have = new Set(sessions.map((item) => item.id));
  const extra = (sourceSessions || []).filter((item) => item.classId === cls.id && pinnedDates.includes(item.date) && !have.has(item.id));
  if (!extra.length) return sessions;
  return [...sessions, ...extra].sort((a, b) => `${a.date}|${a.startTime || ""}`.localeCompare(`${b.date}|${b.startTime || ""}`));
}

/**
 * Các khóa của lớp thu khóa: toàn bộ khóa đã qua, khóa đang học (khóa chứa
 * hôm nay) và đúng một khóa sắp tới kế tiếp.
 */
function classCourseWindows(cls, sourceSessions = state.data.lessonSessions || [], now = new Date()) {
  const compute = () => classCourseWindowsInner(cls, sourceSessions, now);
  return perfDefaultSessions(sourceSessions) ? perfMemo("ccws", `${cls?.id}|${localDateKey(now)}`, compute) : compute();
}

function classCourseWindowsInner(cls, sourceSessions = state.data.lessonSessions || [], now = new Date()) {
  if (!classCourseSessions(cls) || !(cls.schedules || []).length) return [];
  const todayKey = localDateKey(now);
  const startKey = classCourseStartDate(cls);
  let covered = 1;
  let target = classCourseWindowSlotsAt(cls, 1);
  let rows = classCourseScheduleSessions(cls, startKey, target, sourceSessions);
  // Kéo dài lịch cho tới khi khóa cuối cùng chứa hôm nay (hoặc sinh hết được).
  for (let guard = 0; rows.length >= target && sessionRowsDateRange(rows).end < todayKey && guard < 60; guard += 1) {
    covered += 1;
    target += classCourseWindowSlotsAt(cls, covered);
    rows = classCourseScheduleSessions(cls, startKey, target, sourceSessions);
  }
  // Sinh thêm một khóa nữa để dropdown luôn có "khóa sắp tới".
  if (rows.length >= target) {
    covered += 1;
    target += classCourseWindowSlotsAt(cls, covered);
    rows = classCourseScheduleSessions(cls, startKey, target, sourceSessions);
  }
  const windows = [];
  for (let offset = 0, index = 1; offset < rows.length; index += 1) {
    const size = classCourseWindowSlotsAt(cls, index);
    const sessions = withPinnedBoundarySessions(cls, index, rows.slice(offset, offset + size), sourceSessions);
    offset += size;
    const { start, end } = sessionRowsDateRange(sessions);
    windows.push({ index: windows.length + 1, start, end, sessions });
  }
  // Khóa "đang học" = khóa đầu tiên còn suất lịch từ hôm nay trở đi — kể cả khi
  // hôm nay nằm giữa hai suất của hai khóa liên tiếp.
  const anchor = windows.findIndex((item) => item.end >= todayKey);
  const current = anchor < 0 ? Math.max(0, windows.length - 1) : anchor;
  return windows.slice(0, current + 2).map((item, index) => ({
    ...item,
    isPast: index < current,
    isCurrent: index === current,
    isFuture: index === current + 1,
  }));
}

function sessionStamp(session) {
  const day = weekdayShort[localDate(session.date).getDay()];
  return `${day}, ${formatDateVi(session.date)} · ${session.startTime}–${session.endTime}`;
}

function attendanceStatusBadge(status, isOff = false) {
  if (isOff) return '<span class="badge badge-amber">Nghỉ học</span>';
  if (status === "PRESENT") return '<span class="badge badge-green">Có mặt</span>';
  if (status === "ABSENT") return '<span class="badge badge-red">Vắng không phép</span>';
  if (status === "EXCUSED") return '<span class="badge badge-amber">Vắng phép</span>';
  return '<span class="muted">Chưa điểm danh</span>';
}

function classSyllabusStack(row) {
  const syllabus = classSyllabus(row);
  const document = syllabus ? state.teacherDocuments[syllabus.id] : null;
  const units = document?.units || syllabus?.units || [];
  const unitBlocks = units.map((unit, index) => {
    const unitId = unit.id;
    const days = (document?.days || []).filter((day) => day.unitId === unitId).sort((a, b) => a.sortOrder - b.sortOrder);
    const lessons = (document?.lessons || []).filter((lesson) => lesson.unitId === unitId).sort((a, b) => a.order - b.order);
    const dayRows = days.map((day) => {
      const dayLessons = lessons.filter((lesson) => lesson.courseDayId === day.id);
      const details = dayLessons.map((lesson) => {
        const skills = [[lesson.hasListening, "Listening"], [lesson.hasSpeaking, "Speaking"], [lesson.hasReading, "Reading"], [lesson.hasWriting, "Writing"]].filter(([enabled]) => enabled).map(([, label]) => label);
        return `<div class="teacher-lesson"><strong>${escapeHtml(lesson.name || `Bài ${lesson.lessonNumber}`)}</strong>${skills.length ? `<span>${skills.map((skill) => `<em>${skill}</em>`).join("")}</span>` : ""}${(lesson.languageTargets || []).length ? `<small>Ngôn ngữ: ${escapeHtml(lesson.languageTargets.join(" · "))}</small>` : ""}${(lesson.lessonPlan || []).length ? `<ol>${lesson.lessonPlan.map((step) => `<li>${escapeHtml(step)}</li>`).join("")}</ol>` : ""}</div>`;
      }).join("");
      return `<div class="teacher-day"><div><b>Day ${day.courseDayNumber || day.unitDayNumber}</b><span>${escapeHtml(day.title)}</span></div>${details || "<p>Chưa có nội dung bài học.</p>"}</div>`;
    }).join("");
    const title = unit.name || unit.title || `Unit ${unit.unitNumber || index + 1}`;
    const overview = unit.overview || unit.description || unit.topic || "";
    return `<details class="teacher-unit" ${index === 0 ? "open" : ""}><summary><span>UNIT ${unit.unitNumber || index + 1}</span><strong>${escapeHtml(title)}</strong><small>${days.length || lessons.length} Day</small></summary>${overview ? `<p class="teacher-unit-overview">${escapeHtml(overview)}</p>` : ""}<div class="teacher-day-list">${dayRows || '<p class="teacher-empty-copy">Unit này chưa có Day.</p>'}</div></details>`;
  }).join("");
  return { syllabus, units, unitBlocks };
}

function classModalHtml() {
  const modal = state.classModal;
  if (!modal) return "";
  const row = findBy(state.data.classes, modal.id);
  const editing = Boolean(row);
  const settings = state.data.settings;
  const scheduleRows = state.classDraftSchedules.map((slot, index) => {
    const range = scheduleSlotRangeText(slot);
    const periodName = findBy(settings.lessonPeriods, slot.periodId)?.name || "";
    return `<li><span>${weekdayLabels[slot.weekday]}</span><strong>${escapeHtml(slot.startTime)}–${escapeHtml(slot.endTime)}</strong><small>${escapeHtml(range || periodName)}</small><button type="button" class="icon-button danger" data-class-schedule-remove="${index}">×</button></li>`;
  }).join("");
  return `<div class="modal-backdrop" data-action="close-class-modal"><div class="modal-card class-modal" data-class-modal-card><div class="modal-head"><div><h2>${editing ? "Sửa lớp học" : "Thêm lớp học"}</h2><p>Thông tin lớp, người phụ trách, học viên và thời khoá biểu tuần.</p></div><button class="close-btn" type="button" data-action="close-class-modal">×</button></div><form id="class-form" data-id="${escapeHtml(row?.id || "")}"><div class="form-grid class-form-grid">
    <p class="form-section-title span-2">Thông tin lớp</p>
    <label class="field"><span>Tên lớp</span><input class="input" name="name" value="${escapeHtml(row?.name || "")}" placeholder="STEPS Starters A" required autofocus /></label>
    <label class="field"><span>Mã lớp</span><input class="input" name="code" value="${escapeHtml(row?.code || "")}" placeholder="Bỏ trống để tự sinh" /></label>
    <label class="field"><span>Loại lớp</span><select class="input" name="classTypeId" required><option value="">— Chọn loại lớp —</option>${settings.classTypes.map((item) => `<option value="${escapeHtml(item.id)}" ${row?.classTypeId === item.id ? "selected" : ""}>${escapeHtml(item.name)}</option>`).join("")}</select></label>
    <label class="field"><span>Trạng thái</span><select class="input" name="status">${Object.entries(classStatusLabels).map(([value, label]) => `<option value="${value}" ${(row?.status || "DRAFT") === value ? "selected" : ""}>${label}</option>`).join("")}</select></label>
    <label class="field"><span>Chi nhánh</span><select class="input" name="branchId" required><option value="">— Chọn chi nhánh —</option>${settings.branches.map((item) => `<option value="${escapeHtml(item.id)}" ${row?.branchId === item.id ? "selected" : ""}>${escapeHtml(item.name)}</option>`).join("")}</select></label>
    <label class="field"><span>Giáo viên</span><select class="input" name="teacherId"><option value="">— Chưa phân công —</option>${state.data.teachers.map((item) => `<option value="${escapeHtml(item.id)}" ${row?.teacherId === item.id ? "selected" : ""}>${escapeHtml(item.fullName)} (${escapeHtml(item.code)})</option>`).join("")}</select></label>
    <label class="field"><span>Hình thức thu</span><select class="input" name="billingMode">${billingChoiceOptions(row)}</select></label>
    <label class="field"><span>Giá / buổi</span><input class="input" type="number" name="sessionPrice" min="1000" step="1000" value="${classSessionPrice(row) || 200000}" required /></label>
    <p class="form-section-title span-2">Thời khoá biểu</p>
    <div class="schedule-builder span-2"><select class="input" id="class-weekday">${weekdayLabels.map((label, index) => `<option value="${index}" ${index === 1 ? "selected" : ""}>${label}</option>`).join("")}</select><select class="input" id="class-period"><option value="">— Chọn tiết học —</option>${settings.lessonPeriods.map((item) => `<option value="${escapeHtml(item.id)}">${escapeHtml(item.name)} (${item.startTime}–${item.endTime})</option>`).join("")}</select><button class="secondary-btn" type="button" data-action="add-class-schedule">${icon("plus")}Thêm</button></div>
    <ul class="schedule-list span-2">${scheduleRows || "<li class='empty-schedule'>Chưa có lịch tuần — lớp sẽ chưa hiển thị trên Lịch dạy.</li>"}</ul>
    <p class="form-section-title span-2">Học viên trong lớp</p>
    <div class="student-check-list span-2">${state.data.students.map((student) => `<label><input type="checkbox" name="studentIds" value="${escapeHtml(student.id)}" ${(row?.studentIds || []).includes(student.id) ? "checked" : ""}/><span><strong>${escapeHtml(student.fullName)}</strong><small>${escapeHtml(student.code)} · ${escapeHtml(student.school || "Chưa có trường")}</small></span></label>`).join("") || "<p>Chưa có học viên để xếp lớp.</p>"}</div>
    <label class="field span-2"><span>Ghi chú</span><textarea class="input textarea" name="note" placeholder="Ghi chú vận hành lớp">${escapeHtml(row?.note || "")}</textarea></label>
  </div><div class="settings-modal-footer"><button class="secondary-btn" type="button" data-action="close-class-modal">Huỷ</button><button class="primary-btn" type="submit">${editing ? "Lưu thay đổi" : "Tạo lớp"}</button></div></form></div></div>`;
}

function classStudentModalHtml() {
  const modal = state.classStudentModal;
  if (!modal) return "";
  const currentClass = findBy(state.data.classes, modal.classId);
  if (!currentClass) return "";
  if (modal.kind === "add") {
    const currentIds = new Set(currentClass.studentIds || []);
    // Bạn đang ở Lớp chờ lên đầu danh sách (gắn nhãn) — xếp lớp cho học viên mới nhanh hơn.
    const waitingIds = new Set((state.data.classes.find(isWaitingClass)?.studentIds) || []);
    const candidates = [...state.data.students]
      .filter((student) => !currentIds.has(student.id))
      .sort((a, b) => Number(waitingIds.has(b.id)) - Number(waitingIds.has(a.id)) || a.fullName.localeCompare(b.fullName, "vi"));
    const choices = candidates.map((student) => `<label data-student-picker-item><input type="checkbox" name="studentIds" value="${escapeHtml(student.id)}"/><span><strong>${escapeHtml(student.fullName)}${waitingIds.has(student.id) ? ' <em class="picker-waiting-tag">Lớp chờ</em>' : ""}</strong><small>${escapeHtml(student.code)} · ${escapeHtml(student.school || "Chưa có trường")}</small></span></label>`).join("");
    return `<div class="modal-backdrop" data-action="close-class-student-modal"><div class="modal-card class-student-modal" data-class-student-modal-card><div class="modal-head"><div><h2>Thêm học sinh</h2><p>Chọn học sinh cần thêm vào lớp ${escapeHtml(currentClass.name)}.</p></div><button class="close-btn" type="button" data-action="close-class-student-modal">×</button></div><form id="class-student-add-form" data-class-id="${escapeHtml(currentClass.id)}"><div class="class-student-modal-body"><label class="field"><span>Tìm học sinh</span><input class="input" type="search" data-student-picker-search placeholder="Nhập tên hoặc mã học sinh..." autofocus /></label><div class="student-check-list class-student-picker">${choices || '<p class="empty-cell">Tất cả học sinh đã có trong lớp này.</p>'}</div></div><div class="settings-modal-footer"><button class="secondary-btn" type="button" data-action="close-class-student-modal">Huỷ</button><button class="primary-btn" type="submit" ${candidates.length ? "" : "disabled"}>Thêm vào lớp</button></div></form></div></div>`;
  }
  const student = findBy(state.data.students, modal.studentId);
  if (!student) return "";
  if (modal.kind === "remove") {
    return `<div class="modal-backdrop" data-action="close-class-student-modal"><div class="modal-card class-transfer-modal" data-class-student-modal-card><div class="modal-head"><div><h2>Xoá khỏi lớp</h2><p>Đưa ${escapeHtml(student.fullName)} ra khỏi lớp ${escapeHtml(currentClass.name)}.</p></div><button class="close-btn" type="button" data-action="close-class-student-modal">×</button></div><form id="class-student-remove-form" data-class-id="${escapeHtml(currentClass.id)}" data-student-id="${escapeHtml(student.id)}"><div class="class-student-modal-body"><p class="class-transfer-note">Học viên sẽ chuyển về <strong>Lớp chờ</strong>, trạng thái đổi thành <strong>Chưa xếp lớp</strong>. Phiếu thu, công nợ và lịch sử điểm danh được giữ nguyên.</p></div><div class="settings-modal-footer"><button class="secondary-btn" type="button" data-action="close-class-student-modal">Huỷ</button><button class="danger-btn" type="submit">Xoá khỏi lớp</button></div></form></div></div>`;
  }
  // Chỉ chuyển giữa hai lớp cùng loại thu phí (tháng ↔ tháng, khóa ↔ khóa);
  // từ Lớp chờ hoặc về Lớp chờ thì không giới hạn vì lớp chờ không thu phí.
  const sourceWaiting = isWaitingClass(currentClass);
  const targetClasses = [...state.data.classes]
    .filter((row) => row.id !== currentClass.id && row.status !== "FINISHED" && !(row.studentIds || []).includes(student.id)
      && (sourceWaiting || isWaitingClass(row) || classBillingMode(row) === classBillingMode(currentClass)))
    .sort((a, b) => a.name.localeCompare(b.name, "vi"));
  const options = targetClasses.map((row) => {
    const branch = findBy(state.data.settings.branches, row.branchId);
    return `<option value="${escapeHtml(row.id)}">${escapeHtml(row.name)} (${escapeHtml(row.code)}) · ${escapeHtml(branch?.name || "Chưa có chi nhánh")}</option>`;
  }).join("");
  return `<div class="modal-backdrop" data-action="close-class-student-modal"><div class="modal-card class-transfer-modal" data-class-student-modal-card><div class="modal-head"><div><h2>Chuyển lớp</h2><p>Chuyển ${escapeHtml(student.fullName)} khỏi lớp ${escapeHtml(currentClass.name)}.</p></div><button class="close-btn" type="button" data-action="close-class-student-modal">×</button></div><form id="class-student-transfer-form" data-class-id="${escapeHtml(currentClass.id)}" data-student-id="${escapeHtml(student.id)}"><div class="class-student-modal-body"><label class="field"><span>Lớp cần chuyển đến</span><select class="input" name="targetClassId" required><option value="">— Chọn lớp —</option>${options}</select></label><p class="class-transfer-note">Chỉ chuyển giữa các lớp cùng loại thu phí (tháng ↔ tháng, khóa ↔ khóa). Nợ lớp cũ và chênh lệch đơn giá của các buổi còn lại sẽ gộp thành một phiếu riêng ở lớp mới vào kỳ thu sau; phiếu thường của lớp mới vẫn thu y như các bạn khác.</p></div><div class="settings-modal-footer"><button class="secondary-btn" type="button" data-action="close-class-student-modal">Huỷ</button><button class="primary-btn" type="submit" ${targetClasses.length ? "" : "disabled"}>Xác nhận chuyển lớp</button></div></form></div></div>`;
}

// Chương trình Portal của lớp (lưu ở class.syllabusId). Chỉ liệt kê chương trình soạn ở tab Portal;
// lớp đang gán syllabus cũ thì vẫn giữ lựa chọn đó để Lưu thông tin lớp không vô tình xóa.
function classPortalField(row, lockedView) {
  const assigned = findBy(state.data.syllabuses, row.syllabusId);
  const programs = (state.data.syllabuses || []).filter(isPortalProgram);
  const canPreview = state.role === "ADMIN" && assigned && isPortalProgram(assigned);
  const control = lockedView
    ? `<input class="input" value="${escapeHtml(assigned?.name || "Chưa gán")}" disabled />`
    : `<select class="input" name="syllabusId" id="class-portal-program"><option value="">— Chưa gán —</option>${programs.map((item) => `<option value="${escapeHtml(item.id)}" ${item.id === row.syllabusId ? "selected" : ""}>${escapeHtml(item.name)}${item.code ? ` (${escapeHtml(item.code)})` : ""}</option>`).join("")}${assigned && !isPortalProgram(assigned) ? `<option value="${escapeHtml(assigned.id)}" selected>${escapeHtml(assigned.name)} (syllabus cũ)</option>` : ""}</select>`;
  const button = state.role === "ADMIN" ? `<button class="secondary-btn" type="button" data-portal-preview-class="${escapeHtml(row.id)}" ${canPreview ? "" : "disabled title=\"Gán chương trình Portal rồi Lưu thông tin lớp\""}>${icon("eye")}Xem Portal</button>` : "";
  return `<div class="field class-portal-field"><span>Chương trình Portal</span><div class="class-portal-control">${control}${button}</div></div>`;
}

function classInfoField(label, control, extra = "") {
  return `<label class="field${extra ? ` ${extra}` : ""}"><span>${label}</span>${control}</label>`;
}

function classOffScheduleConfig(row, readOnly = false) {
  const lock = readOnly ? " disabled" : "";
  const mode = classBillingMode(row);
  const selectedMonth = /^\d{4}-(0[1-9]|1[0-2])$/.test(String(state.classOffMonth || "")) ? state.classOffMonth : monthKey();
  state.classOffMonth = selectedMonth;
  if (state.classCourseConfigFor !== row.id) {
    state.classCourseConfigFor = row.id;
    state.classCourseStartDate = classCourseStartDate(row);
    state.classCourseSessionCount = classCourseSessions(row);
    state.classCourseIndex = 0;
  }
  const windows = mode === "COURSE" ? classCourseWindows(row) : [];
  const defaultCourseIndex = windows.find((item) => item.isCurrent)?.index || windows.find((item) => item.isFuture)?.index || 1;
  const courseIndex = windows.some((item) => item.index === state.classCourseIndex) ? state.classCourseIndex : defaultCourseIndex;
  const selectedWindow = windows.find((item) => item.index === courseIndex) || null;
  const courseStart = courseIndex === 1
    ? (state.classCourseStartDate || classCourseStartDate(row))
    : (selectedWindow?.start || classCourseStartDate(row));
  const courseCount = Math.max(1, Math.min(1000, Math.round(Number(state.classCourseSessionCount) || classCourseSessions(row))));
  const sessions = mode === "MONTHLY"
    ? classMonthScheduleSessions(row, selectedMonth)
    : mergeCourseOffSessions(row, courseIndex === 1
      // Khóa 1 chốt cứng lịch (COURSE_WINDOW_SLOT_OVERRIDES): hiện đúng cửa sổ khóa đã chốt.
      ? (hasCourseWindowOverride(row, 1) && courseStart === classCourseStartDate(row) && courseCount === classCourseSessions(row)
        ? classCourseWindowByIndex(row, 1).sessions
        : classCourseScheduleSessions(row, courseStart, courseCount))
      : (selectedWindow?.sessions || []), courseIndex);
  const draftKey = `${row.id}|${mode}|${mode === "MONTHLY" ? selectedMonth : `course${courseIndex}|${courseStart}|${courseCount}`}`;
  if (state.classOffDraftFor !== draftKey) {
    const previousDraft = String(state.classOffDraftFor || "").startsWith(`${row.id}|${mode}|`)
      ? new Set(state.classOffDraftSelected || [])
      : new Set();
    const available = new Set(sessions.map((item) => item.recurrenceKey || item.id || `${item.classId}|${item.date}|${item.startTime}`));
    state.classOffDraftFor = draftKey;
    state.classOffDraftSelected = [...new Set([
      ...sessions
      .filter((item) => isAdminConfiguredOff(item) || item.status === "CANCELLED")
      .map((item) => item.recurrenceKey || item.id || `${item.classId}|${item.date}|${item.startTime}`),
      ...[...previousDraft].filter((identity) => available.has(identity)),
    ])];
  }
  const selectedDraft = new Set(state.classOffDraftSelected || []);
  // Thu khóa: buổi GV nghỉ và buổi "học không tính phí" không chiếm suất khóa.
  // Thu tháng: buổi GV nghỉ vẫn một suất lịch tháng và vẫn tính phí (trừ sang
  // tháng sau), buổi không tính phí chỉ bị loại khỏi số buổi tính tiền.
  const noFeeCount = sessions.filter(isNoFeeSession).length;
  // Hàng không chiếm số buổi của khóa (nghỉ học vụ, GV nghỉ, không tính phí,
  // huỷ) — khóa đã giãn để bù. Riêng nghỉ học vụ trong khe hở cắt cố ý vẫn
  // đếm số "Buổi N" nhưng không tính phí.
  const unnumberedCount = mode === "COURSE" ? sessions.filter((item) => isCourseUnnumberedRow(row, item)).length : 0;
  const slotCount = mode === "COURSE" ? sessions.length - unnumberedCount : sessions.length;
  const gapOffCount = mode === "COURSE" ? sessions.filter((item) => isCourseSlotSkippingSession(item) && !isCourseUnnumberedRow(row, item)).length : 0;
  const offCount = sessions.filter((item) => !isTeacherOffSession(item) && !isNoFeeSession(item) && selectedDraft.has(item.recurrenceKey || item.id || `${item.classId}|${item.date}|${item.startTime}`)).length;
  // Buổi thêm gắn khóa (inCourse) hiển thị trong lịch khóa nhưng không tính phí.
  // Buổi dạy bù KHÔNG phải buổi thêm — nó chiếm vị trí khóa của buổi nghỉ nên
  // đánh số "Buổi N" và tính phí như buổi thường.
  const extraCount = mode === "COURSE" ? sessions.filter((item) => item.isExtra && !isTeacherOffSession(item) && !item.makeupOf).length : 0;
  // Thu khóa: buổi nghỉ (kể cả học vụ cấu hình) làm khóa giãn chứ không trừ
  // buổi tính phí — chỉ nghỉ trong khe hở được đếm số mới giảm billable.
  const billable = mode === "COURSE"
    // Khóa chốt cứng lịch: học phí giữ đúng số buổi khóa đã chốt (mirror billedCourseSessions).
    ? (hasCourseWindowOverride(row, courseIndex) ? classCourseSizeAt(row, courseIndex) : slotCount - gapOffCount - extraCount)
    : slotCount - offCount - extraCount - noFeeCount;
  let slotIndex = 0;
  const sessionRows = sessions.map((session, index) => {
    const identity = session.recurrenceKey || session.id || `${session.classId}|${session.date}|${session.startTime}`;
    const isAdminOff = selectedDraft.has(identity);
    const isTeacherOff = isTeacherOffSession(session);
    const isNoFee = isNoFeeSession(session);
    const isCourseExtra = mode === "COURSE" && Boolean(session.isExtra) && !isTeacherOff && !session.makeupOf;
    const statusTone = session.status === "COMPLETED" ? "green" : "blue";
    const statusLabel = session.status === "COMPLETED" ? "Đã hoàn thành" : "Đã lên lịch";
    const makeupSource = session.makeupOf
      ? (state.data?.lessonSessions || []).find((item) => item.id === session.makeupOf)
      : null;
    const baseTone = isTeacherOff || isNoFee || session.makeupOf ? "blue" : isCourseExtra ? "green" : statusTone;
    const baseLabel = isTeacherOff ? "Giáo viên nghỉ" : isNoFee ? "Học không tính phí" : session.makeupOf ? `Dạy bù${makeupSource ? ` ${formatDateVi(makeupSource.date)}` : ""}` : isCourseExtra ? "Buổi thêm" : statusLabel;
    const badgeTitle = session.makeupOf && makeupSource
      ? ` title="Dạy bù cho buổi ${formatDateVi(makeupSource.date)} ${escapeHtml(makeupSource.startTime)}–${escapeHtml(makeupSource.endTime)}"`
      : "";
    const badgeTone = isAdminOff ? "amber" : baseTone;
    const badgeLabel = isAdminOff ? "Nghỉ đã khóa" : baseLabel;
    const isGapCountedOff = isAdminOff && !isCourseUnnumberedRow(row, session);
    const slotLabel = mode === "COURSE" && (isCourseUnnumberedRow(row, session) || (isAdminOff && !isGapCountedOff)) ? "—" : `Buổi ${(slotIndex += 1)}`;
    return `<tr class="${isAdminOff || isTeacherOff || isNoFee ? "is-off" : ""}"${isCourseExtra ? ` data-extra="1"` : ""}>
      <td class="cell-index">${index + 1}</td>
      <td>${isCourseExtra
        ? `<input type="checkbox" disabled aria-label="Buổi thêm không nằm trong phí khóa" />`
        : `<input type="checkbox" name="offSession" value="${escapeHtml(identity)}" ${isAdminOff ? "checked" : ""}${lock} data-teacher-off="${isTeacherOff ? "1" : "0"}" data-no-fee="${isNoFee ? "1" : "0"}" data-gap-off="${isGapCountedOff ? "1" : "0"}" data-unnumbered="${mode === "COURSE" && (isCourseUnnumberedRow(row, session) || (isAdminOff && !isGapCountedOff)) ? "1" : "0"}" aria-label="Cho nghỉ buổi ${formatDateVi(session.date)} ${escapeHtml(session.startTime)}" />`}</td>
      <td class="cell-index class-session-name">${slotLabel}</td>
      <td><strong>${formatDateVi(session.date)}</strong></td>
      <td>${weekdayFull[localDate(session.date).getDay()]}</td>
      <td class="tabular">${escapeHtml(session.startTime)}–${escapeHtml(session.endTime)}</td>
      <td><span class="badge badge-${badgeTone}"${badgeTitle} data-off-status data-base-tone="${baseTone}" data-base-label="${escapeHtml(baseLabel)}">${badgeLabel}</span></td>
    </tr>`;
  }).join("");
  const courseStatusLabel = (item) => item.isCurrent ? "Đang học" : item.isFuture ? "Sắp tới" : "Đã kết thúc";
  const courseOptions = windows.length
    ? windows.map((item) => {
      const view = classCourseViewSessions(row, item.index);
      const viewStart = view[0]?.date || item.start;
      const viewEnd = view.at(-1)?.date || item.end;
      return `<option value="${item.index}" ${item.index === courseIndex ? "selected" : ""}>Khóa ${item.index} · ${formatDateVi(viewStart)} – ${formatDateVi(viewEnd)} (${courseStatusLabel(item)})</option>`;
    }).join("")
    : `<option value="1" selected>Khóa 1</option>`;
  const periodControls = mode === "MONTHLY"
    ? `<label class="field"><span>Tháng / năm</span><input class="input" id="class-off-month" type="month" value="${selectedMonth}" /></label>`
    : `<div class="class-course-config-fields">
        <label class="field"><span>Khóa học</span><select class="input" id="class-course-index">${courseOptions}</select></label>
        ${courseIndex === 1 ? `<label class="field"><span>Ngày bắt đầu khóa</span><input class="input" id="class-course-start" type="date" value="${escapeHtml(courseStart)}" required${lock} /></label>
        <label class="field"><span>Số buổi trong khóa</span><input class="input" id="class-course-session-count" type="number" min="1" max="1000" value="${courseCount}" required${lock} /></label>` : `<p class="class-course-derived">Khóa ${courseIndex} · ${formatDateVi(courseStart)} → tự nối tiếp khóa trước, ${courseCount} buổi — chỉ chỉnh được ngày nghỉ.</p>`}
      </div>`;
  const description = mode === "MONTHLY"
    ? "Chọn tháng rồi tick trước các buổi nghỉ lễ / học vụ. Buổi được tick không tính học phí và khóa Điểm danh, kể cả khi giáo viên đã cho nghỉ."
    : courseIndex === 1
      ? "Chọn ngày bắt đầu và số buổi. Hệ thống sinh toàn bộ lịch khóa theo lịch tuần; buổi được tick nghỉ lễ không tính học phí, khóa tự kéo dài để học bù và buổi đó được khóa trong Điểm danh, kể cả khi giáo viên đã cho nghỉ."
      : `Khóa ${courseIndex} tự nối tiếp ngay sau khóa trước (cùng ${courseCount} buổi). Tick trước các buổi nghỉ lễ / học vụ của khóa này; buổi được tick không tính học phí và khóa tự kéo dài để học bù.`;
  const emptyLabel = mode === "MONTHLY"
    ? "Tháng này chưa có buổi học theo thời khóa biểu."
    : "Chưa thể sinh lịch khóa. Hãy cấu hình ít nhất một lịch học trong tuần.";
  const materials = mode === "MONTHLY" ? classMaterialFee(row, selectedMonth) : courseMaterialFee(row, courseIndex);
  const materialsFields = `<div class="class-materials-block">
        <div class="class-materials-head"><h3>${mode === "MONTHLY" ? "Học liệu tháng này" : `Học liệu của khóa ${courseIndex}`}</h3><p>${mode === "MONTHLY" ? "Bỏ trống nếu tháng này không thu học liệu." : courseIndex === 1 ? "Bỏ trống nếu khóa này không thu học liệu." : "Bỏ trống nếu khóa này không thu học liệu; chưa nhập riêng thì kế thừa học liệu khóa 1."} Có tiền thì phiếu báo và bill học phí cộng thêm khoản này.</p></div>
        <div class="class-materials-fields">
          <label class="field"><span>Tiền học liệu</span><input class="input" id="class-materials-amount" name="materialsAmount" type="number" min="0" step="1000" value="${materials.amount || ""}" placeholder="0"${lock} /></label>
          <label class="field"><span>Mô tả học liệu</span><input class="input" name="materialsDescription" maxlength="200" value="${escapeHtml(materials.description)}" placeholder="Ví dụ: sách tô màu"${lock} /></label>
        </div>
      </div>`;
  const offHeadTitle = mode === "MONTHLY" ? "Cấu hình lịch nghỉ theo tháng" : "Cấu hình lịch khóa";
  const offHeadInner = mode === "COURSE"
    ? `<div class="class-off-head"><div><p>${description}</p></div>${periodControls}</div>`
    : `<div class="class-off-head"><div><h2>${offHeadTitle}</h2><p>${description}</p></div>${periodControls}</div>`;
  // Thu khóa: cụm cấu hình (khóa, ngày bắt đầu, số buổi, học liệu) thu gọn
  // được — mặc định đóng để bảng buổi chiếm tối đa chiều cao; mở ra khi cần
  // chỉnh. Nút Lưu giữ ngoài để tick nghỉ xong lưu được luôn.
  const offCfgKey = `${row.id}|${courseIndex}`;
  const offHead = mode === "COURSE"
    ? `<details class="class-off-settings"${state.classOffCfgOpen?.[offCfgKey] ? " open" : ""}><summary><span class="class-off-settings-title">${offHeadTitle}</span><span class="class-off-settings-meta">Khóa ${courseIndex} · ${formatDateVi(courseStart)} · Học liệu ${materials.amount ? vnd(materials.amount) : "0 ₫"}</span><span class="class-off-settings-stats"><strong data-off-total>${slotCount} buổi</strong> · Nghỉ <strong data-off-count>${offCount} buổi</strong>${noFeeCount ? ` · Miễn phí <strong>${noFeeCount} buổi</strong>` : ""} · Tính <strong data-billable-count>${billable} buổi</strong> · <strong data-billable-amount>${vnd(billable * classSessionPrice(row) + materials.amount)}</strong></span>${icon("chevron")}</summary>${offHeadInner}${materialsFields}</details>`
    : offHeadInner;
  return `<section class="card nz-class-card class-off-card">
    <form id="class-off-days-form" data-class-id="${escapeHtml(row.id)}" data-mode="${mode}" data-month="${selectedMonth}" data-course-index="${courseIndex}" data-course-start="${escapeHtml(courseStart)}" data-course-sessions="${courseCount}" data-session-price="${classSessionPrice(row)}">
      ${offHead}
      <div class="class-off-summary">
        <span>${mode === "MONTHLY" ? "Lịch tháng" : "Lịch khóa"} <strong data-off-total>${slotCount} buổi</strong></span>
        <span>Nghỉ <strong data-off-count>${offCount} buổi</strong></span>
        ${noFeeCount ? `<span>Học không tính phí <strong>${noFeeCount} buổi</strong></span>` : ""}
        <span>Tính học phí <strong data-billable-count>${billable} buổi</strong></span>
        <span>Thành tiền <strong data-billable-amount>${vnd(billable * classSessionPrice(row) + materials.amount)}</strong></span>
      </div>
      <div class="table-wrap class-off-table"><table><thead><tr><th>STT</th><th>Nghỉ</th><th>Tên buổi</th><th>Ngày học</th><th>Thứ</th><th>Giờ học</th><th>Trạng thái</th></tr></thead><tbody>${sessionRows || `<tr><td class="empty-cell" colspan="7">${emptyLabel}</td></tr>`}</tbody></table></div>
      ${mode === "COURSE" ? "" : materialsFields}
      ${readOnly ? "" : `<div class="class-off-footer"><p>${mode === "MONTHLY" ? "Thay đổi chỉ có hiệu lực sau khi bấm Lưu lịch nghỉ." : courseIndex === 1 ? "Lưu để chốt ngày bắt đầu, số buổi và các ngày nghỉ của khóa." : `Lưu để chốt các ngày nghỉ của khóa ${courseIndex} — ngày bắt đầu và số buổi đi theo khóa 1.`}</p><button class="primary-btn" type="submit" ${sessions.length ? "" : "disabled"}>${mode === "MONTHLY" ? "Lưu lịch nghỉ" : "Lưu cấu hình khóa"}</button></div>`}
    </form>
  </section>`;
}

function classTuitionNoticePanel(row) {
  const mode = classBillingMode(row);
  if (state.classTuitionNoticeFor !== row.id) {
    state.classTuitionNoticeFor = row.id;
    state.classTuitionNoticePeriod = mode === "MONTHLY" ? (state.classOffMonth || monthKey()) : "course";
  }
  const windows = mode === "COURSE" ? classCourseWindows(row) : [];
  const defaultCourseIndex = windows.find((item) => item.isCurrent)?.index || windows.find((item) => item.isFuture)?.index || 1;
  const selectedPeriod = mode === "MONTHLY"
    ? (/^\d{4}-(0[1-9]|1[0-2])$/.test(String(state.classTuitionNoticePeriod || "")) ? state.classTuitionNoticePeriod : monthKey())
    : (/^course\|\d+$/.test(String(state.classTuitionNoticePeriod || "")) ? state.classTuitionNoticePeriod : `course|${defaultCourseIndex}`);
  state.classTuitionNoticePeriod = selectedPeriod;
  const notice = tuitionNoticeDetails(null, row, selectedPeriod);
  const options = mode === "MONTHLY"
    ? tuitionNoticeMonthKeys(selectedPeriod).map((key) => `<option value="${key}" ${key === selectedPeriod ? "selected" : ""}>${monthLabel(key)}</option>`).join("")
    : (windows.length ? windows.map((item) => `<option value="course|${item.index}" ${`course|${item.index}` === selectedPeriod ? "selected" : ""}>Khóa ${item.index} · ${item.sessions.filter((row) => !isPlannedTuitionOff(row) && row.status !== "CANCELLED").length} buổi tính phí · ${formatDateVi(item.start)} – ${formatDateVi(item.end)}</option>`).join("") : `<option value="course|1" selected>${notice.sessions} buổi tính phí · ${escapeHtml(notice.periodLabel)}</option>`);
  return `<section class="card class-tuition-notice-card">
    <div class="class-tuition-notice-head"><h2>Thông báo học phí</h2><p>Tải phiếu báo của toàn bộ học viên trong lớp — mỗi em một phiếu, học phí riêng.</p></div>
    <div class="class-tuition-notice-controls" data-class-id="${escapeHtml(row.id)}">
      <label class="field"><span>${mode === "MONTHLY" ? "Tháng học phí" : "Số buổi tính phí"}</span><select class="input" id="class-tuition-notice-period">${options}</select></label>
      <button class="primary-btn" id="class-tuition-notice-download-button" type="button" ${notice.sessions ? "" : "disabled"}>${icon("download")}Tải phiếu</button>
    </div>
    <div class="class-tuition-notice-preview"><span data-class-tuition-summary>${escapeHtml(row.name)} · ${escapeHtml(notice.label)} · ${tuitionNoticeSummaryText(notice)}</span><strong data-class-tuition-amount>${vnd(notice.amount)}</strong></div>
  </section>`;
}

function classInfoTab(row, teacherView, readOnly = false) {
  const lockedView = teacherView || readOnly;
  const settings = state.data.settings;
  if (!state.classModal && state.classDraftFor !== row.id) {
    state.classDraftFor = row.id;
    // Form chỉ hiện lịch đang/sắp áp dụng — suất đã kết thúc (effectiveTo quá
    // khứ) là lịch sử, transitionClassSchedules vẫn giữ lại trong dữ liệu.
    const today = localDateKey(new Date());
    state.classDraftSchedules = structuredClone((row.schedules || [])
      .filter((slot) => !slot.effectiveTo || slot.effectiveTo >= today));
  }
  const schedules = state.classDraftFor === row.id ? state.classDraftSchedules : (row.schedules || []);
  const price = classSessionPrice(row) || 200000;
  const scheduleRows = schedules.map((slot, index) => {
    const range = scheduleSlotRangeText(slot);
    return `<li><span>${weekdayLabels[slot.weekday]}</span><strong>${escapeHtml(slot.startTime)}–${escapeHtml(slot.endTime)}</strong>${range ? `<small>${escapeHtml(range)}</small>` : ""}${lockedView ? "" : `<button type="button" class="icon-button danger" data-class-schedule-remove="${index}">×</button>`}</li>`;
  }).join("");
  const lock = lockedView ? " disabled" : "";
  const typeControl = lockedView
    ? `<input class="input" value="${escapeHtml(findBy(settings.classTypes, row.classTypeId)?.name || "—")}" disabled />`
    : `<select class="input" name="classTypeId">${settings.classTypes.map((item) => `<option value="${escapeHtml(item.id)}" ${row.classTypeId === item.id ? "selected" : ""}>${escapeHtml(item.name)}</option>`).join("")}</select>`;
  const statusControl = lockedView
    ? `<input class="input" value="${escapeHtml(classStatusLabels[row.status] || row.status)}" disabled />`
    : `<select class="input" name="status">${Object.entries(classStatusLabels).map(([value, label]) => `<option value="${value}" ${row.status === value ? "selected" : ""}>${label}</option>`).join("")}</select>`;
  const branchControl = lockedView
    ? `<input class="input" value="${escapeHtml(findBy(settings.branches, row.branchId)?.name || "—")}" disabled />`
    : `<select class="input" name="branchId">${settings.branches.map((item) => `<option value="${escapeHtml(item.id)}" ${row.branchId === item.id ? "selected" : ""}>${escapeHtml(item.name)}</option>`).join("")}</select>`;
  const teacherControl = lockedView
    ? `<input class="input" value="${escapeHtml(findBy(state.data.teachers, row.teacherId)?.fullName || "Chưa phân công")}" disabled />`
    : `<select class="input" name="teacherId"><option value="">— Chưa phân công —</option>${state.data.teachers.map((item) => `<option value="${escapeHtml(item.id)}" ${row.teacherId === item.id ? "selected" : ""}>${escapeHtml(item.fullName)}</option>`).join("")}</select>`;
  const billingControl = lockedView
    ? `<input class="input" value="${billingChoiceLabel(row)}" disabled />`
    : `<select class="input" name="billingMode">${billingChoiceOptions(row)}</select>`;
  const priceControl = lockedView
    ? `<input class="input" value="${vnd(price)}" disabled />`
    : `<input class="input" type="number" name="sessionPrice" min="1000" step="1000" value="${price}" required />`;
  const fields = [
    classInfoField("Tên lớp", `<input class="input" name="name" value="${escapeHtml(row.name)}" required${lock} />`),
    classInfoField("Mã lớp", `<input class="input" name="code" value="${escapeHtml(row.code)}" required${lock} />`),
    classInfoField("Loại lớp", typeControl),
    classInfoField("Trạng thái", statusControl),
    classInfoField("Chi nhánh", branchControl),
    classInfoField("Giáo viên chủ nhiệm", teacherControl),
    classInfoField("Hình thức thu", billingControl),
    classInfoField("Giá / buổi", priceControl),
    classPortalField(row, lockedView),
  ].join("");
  const scheduleHead = lockedView
    ? `<div class="nz-schedule-head"><span>Lịch học</span></div>`
    : `<div class="nz-schedule-head"><span>Lịch học</span><div class="schedule-builder"><select class="input" id="class-weekday">${weekdayLabels.map((label, index) => `<option value="${index}" ${index === 1 ? "selected" : ""}>${label}</option>`).join("")}</select><select class="input" id="class-period"><option value="">— Chọn tiết —</option>${settings.lessonPeriods.map((item) => `<option value="${escapeHtml(item.id)}">${escapeHtml(item.name)} (${item.startTime}–${item.endTime})</option>`).join("")}</select><button class="secondary-btn" type="button" data-action="add-class-schedule">${icon("plus")}Thêm</button></div></div>`;
  const infoHead = `<div class="class-info-head"><p class="nz-section-label">Thông tin lớp</p>${lockedView
    ? '<p class="nz-class-hint">Chỉ quản trị viên mới sửa được thông tin lớp.</p>'
    : '<div class="nz-class-save"><button class="primary-btn" type="submit">Lưu thông tin lớp</button></div>'}</div>`;
  const body = `<div class="nz-class-split">${infoHead}<div class="nz-class-fields">${fields}</div><div class="nz-class-side"><div class="nz-schedule-block">${scheduleHead}<ul class="schedule-list compact${lockedView ? " readonly" : ""}">${scheduleRows || "<li class='empty-schedule'>Chưa có lịch tuần.</li>"}</ul></div></div></div>`;
  if (teacherView) return `<section class="card nz-class-card">${body}</section>`;
  return `<div class="class-info-content"><div class="class-info-column"><section class="card nz-class-card class-info-card"><form id="class-info-form" data-id="${escapeHtml(row.id)}">${body}</form></section>${classTuitionNoticePanel(row)}</div><div class="class-config-column">${classOffScheduleConfig(row, readOnly)}</div></div>`;
}

function classStudentCount(row) {
  const roster = new Set(state.data.students.map((student) => student.id));
  return (row.studentIds || []).filter((id) => roster.has(id)).length;
}

function classStudentsTab(row, teacherView, readOnly = false) {
  const locked = teacherView || readOnly;
  const waitingClass = isWaitingClass(row);
  const students = state.data.students.filter((student) => (row.studentIds || []).includes(student.id));
  const rows = students.map((student, index) => {
    const remaining = studentSessionRemaining(student, row);
    // Ngày nhập học: mốc đã lưu, mặc định = ngày bắt đầu khóa của lớp.
    const joinDate = String(student.classJoinedAt?.[row.id] || "") || classCourseStartDate(row);
    const joinKey = `${escapeHtml(row.id)}|${escapeHtml(student.id)}`;
    let joinCell;
    if (locked) {
      joinCell = escapeHtml(formatDateVi(joinDate));
    } else if (classBillingMode(row) === "COURSE") {
      // Dropdown các buổi của khóa đang chạy: buổi được chọn là buổi đầu tiên
      // học viên bị tính phí — vào trễ thì các buổi trước không tính.
      const sessions = classCourseWindowByIndex(row, classCurrentCourseIndex(row)).sessions;
      if (!sessions.length) {
        joinCell = `<input class="input join-date-input" type="date" data-join-date="${joinKey}" value="${escapeHtml(joinDate)}" />`;
      } else {
        const found = sessions.findIndex((item) => item.date >= joinDate);
        const pick = found >= 0 ? found : sessions.length - 1;
        const options = sessions.map((item, index) => `<option value="${escapeHtml(item.date)}" ${index === pick ? "selected" : ""}>Buổi ${index + 1} · ${escapeHtml(formatDateVi(item.date))}</option>`).join("");
        joinCell = `<select class="input join-date-input" data-join-date="${joinKey}">${options}</select>`;
      }
    } else {
      joinCell = `<input class="input join-date-input" type="date" data-join-date="${joinKey}" value="${escapeHtml(joinDate)}" />`;
    }
    const pick = waitingClass && !locked ? `<td class="cell-check"><input type="checkbox" data-waiting-pick value="${escapeHtml(student.id)}" ${state.waitingPicked.includes(student.id) ? "checked" : ""} aria-label="Chọn ${escapeHtml(student.fullName)}"></td>` : "";
    return `<tr>${pick}<td class="cell-index">${index + 1}</td><td title="${escapeHtml(student.fullName)}">${teacherView ? escapeHtml(student.fullName) : `<button class="table-link" data-nav="/hoc-vien/${encodeURIComponent(student.id)}" title="${escapeHtml(student.fullName)}">${escapeHtml(student.fullName)}</button>`}</td>${waitingClass ? "" : `<td><span class="badge badge-${remaining >= 0 ? "green" : "red"} tabular">${remaining} buổi</span>${student.tuitionExempt ? '<small class="people-subline tuition-exempt-label">Miễn học phí</small>' : ""}</td><td class="join-date-cell">${joinCell}</td>`}<td class="cell-ellipsis" title="${escapeHtml(student.parentName || "")}">${escapeHtml(student.parentName || "—")}</td><td>${escapeHtml(student.parentZalo || "—")}</td><td>${escapeHtml(student.phone || "—")}</td><td><span class="badge badge-${student.status === "STUDYING" ? "green" : student.status === "STOPPED" ? "amber" : "blue"}">${escapeHtml(studentStatuses[student.status] || student.status)}</span></td>${locked ? "" : `<td class="class-transfer-cell"><button class="secondary-btn class-transfer-btn" type="button" data-class-transfer="${escapeHtml(row.id)}|${escapeHtml(student.id)}">Chuyển lớp</button>${waitingClass ? "" : `<button class="trash-btn class-remove-btn" type="button" data-class-remove="${escapeHtml(row.id)}|${escapeHtml(student.id)}" title="Xoá khỏi lớp — học viên về Lớp chờ">${icon("trash")}</button>`}</td>`}</tr>`;
  }).join("");
  return `<section class="card nz-class-card class-students-card"><div class="card-header people-card-header"><div class="card-heading"><div><h2>Danh sách học viên (${students.length})</h2><p>${locked ? "Danh sách học viên và số buổi học phí còn lại của lớp." : "Thêm học sinh mới hoặc chuyển học sinh sang lớp khác."}</p></div><div class="class-roster-actions"><button class="secondary-btn" type="button" data-class-roster-export="${escapeHtml(row.id)}">${icon("download")}Xuất Excel</button>${locked ? "" : `<button class="primary-btn" data-class-student-add="${escapeHtml(row.id)}">${icon("plus")}Thêm học sinh</button>`}</div></div></div>${waitingClass && !locked ? waitingBulkBar(students) : ""}<div class="table-wrap people-table"><table><thead><tr>${waitingClass && !locked ? `<th class="cell-check"><input type="checkbox" data-waiting-pick-all ${students.length && students.every((student) => state.waitingPicked.includes(student.id)) ? "checked" : ""} aria-label="Chọn tất cả"></th>` : ""}<th>STT</th><th>Tên HV</th>${waitingClass ? "" : "<th>Học phí</th><th>Ngày nhập học</th>"}<th>Bố mẹ</th><th>SĐT 1</th><th>SĐT 2</th><th>Trạng thái</th>${locked ? "" : "<th>Chuyển lớp</th>"}</tr></thead><tbody>${rows || `<tr><td class="empty-cell" colspan="${(waitingClass ? 6 : 8) + (locked ? 0 : waitingClass ? 2 : 1)}">Lớp chưa có học viên nào.</td></tr>`}</tbody></table></div></section>`;
}

/** Lớp chờ: tick nhiều bạn → chọn lớp đã tạo → Xếp vào lớp (một lần lưu roster;
 * server tự rút khỏi Lớp chờ, đổi Đang học, ghi ngày vào lớp, seed số buổi lớp khóa). */
function waitingBulkBar(students) {
  const ids = new Set(students.map((student) => student.id));
  const picked = state.waitingPicked.filter((id) => ids.has(id));
  const targets = [...state.data.classes]
    .filter((row) => !isWaitingClass(row) && row.status !== "FINISHED")
    .sort((a, b) => String(a.name).localeCompare(String(b.name), "vi"));
  const options = targets.map((row) => `<option value="${escapeHtml(row.id)}" ${state.waitingTarget === row.id ? "selected" : ""}>${escapeHtml(row.name)} (${escapeHtml(row.code)}) · ${classBillingMode(row) === "COURSE" ? "thu khóa" : "thu tháng"}</option>`).join("");
  return `<div class="waiting-bulk-bar"><span class="waiting-bulk-count">Đã chọn <strong>${picked.length}</strong> / ${students.length} bạn</span><select class="input" data-waiting-target aria-label="Lớp cần xếp vào"><option value="">— Chọn lớp cần xếp vào —</option>${options}</select><button class="primary-btn" type="button" data-waiting-assign ${picked.length && state.waitingTarget ? "" : "disabled"}>Xếp vào lớp${picked.length ? ` (${picked.length})` : ""}</button></div>`;
}

/** Xuất danh sách học viên của một lớp ra Excel — đủ các cột như bảng trên màn hình. */
function exportClassRosterExcel(classId) {
  const cls = findBy(state.data.classes, classId);
  if (!cls) return;
  const students = state.data.students.filter((student) => (cls.studentIds || []).includes(student.id));
  const phoneCell = (value) => `<td style='mso-number-format:"\\@"'>${escapeHtml(value || "")}</td>`;
  const rows = students.map((student, index) => {
    const remaining = studentSessionRemaining(student, cls);
    const fee = `${remaining} buổi${student.tuitionExempt ? " · Miễn học phí" : ""}`;
    const joinDate = String(student.classJoinedAt?.[cls.id] || "") || classCourseStartDate(cls);
    const status = studentStatuses[student.status] || student.status;
    return `<tr><td>${index + 1}</td><td>${escapeHtml(student.fullName)}</td><td>${escapeHtml(fee)}</td><td>${escapeHtml(formatDateVi(joinDate))}</td><td>${escapeHtml(student.parentName || "")}</td>${phoneCell(student.parentZalo)}${phoneCell(student.phone)}<td>${escapeHtml(status)}</td></tr>`;
  }).join("");
  const sheetName = `DSHV ${cls.name}`.replace(/[[\]:*?/\\]/g, " ").replace(/\s+/g, " ").trim().slice(0, 31);
  const html = `<html xmlns:x="urn:schemas-microsoft-com:office:excel"><head><meta charset="UTF-8"><!--[if gte mso 9]><xml><x:ExcelWorkbook><x:ExcelWorksheets><x:ExcelWorksheet><x:Name>${escapeHtml(sheetName)}</x:Name><x:WorksheetOptions><x:DisplayGridlines/></x:WorksheetOptions></x:ExcelWorksheet></x:ExcelWorksheets></x:ExcelWorkbook></xml><![endif]--></head><body><table border="1"><thead><tr><th>STT</th><th>Tên HV</th><th>Học phí</th><th>Ngày nhập học</th><th>Bố mẹ</th><th>SĐT 1</th><th>SĐT 2</th><th>Trạng thái</th></tr></thead><tbody>${rows}</tbody></table></body></html>`;
  const blob = new Blob([html], { type: "application/vnd.ms-excel" });
  const link = document.createElement("a");
  link.href = URL.createObjectURL(blob);
  link.download = `${sheetName.replace(/[<>:"/\\|?*]/g, "-")}.xls`;
  link.click();
  setTimeout(() => URL.revokeObjectURL(link.href), 1000);
}

/** Nhãn "Buổi N" của một buổi học theo đúng bảng danh sách buổi của kỳ thu —
 * tháng với lớp thu tháng, khóa với lớp thu khóa — để trang Điểm danh hiển
 * thị trùng số thứ tự với bảng buổi ở Thông tin lớp (GV dễ đối chiếu). Hàng
 * không chiếm suất khóa (nghỉ GV, học không tính phí, nghỉ học vụ ngoài khe
 * hở, huỷ) hiện "—" giống cột Buổi của bảng khóa. */
function attendanceSlotTag(cls, session) {
  if (!cls || !session) return null;
  const same = (item) => item.id === session.id || sessionIdentity(item) === sessionIdentity(session);
  if (classBillingMode(cls) !== "COURSE") {
    const month = String(session.date || "").slice(0, 7);
    const index = classMonthScheduleSessions(cls, month).findIndex(same);
    return index < 0 ? null : { label: `Buổi ${index + 1}`, period: `Tháng ${Number(month.slice(5))}/${month.slice(0, 4)}` };
  }
  for (const window of classCourseWindows(cls)) {
    const list = classCourseViewSessions(cls, window.index);
    let count = 0;
    for (const item of list) {
      const unnumbered = isCourseUnnumberedRow(cls, item);
      if (!unnumbered) count += 1;
      if (!same(item)) continue;
      return { label: unnumbered ? "—" : `Buổi ${count}`, period: `Khóa ${window.index}` };
    }
  }
  // Buổi thuộc khóa xa hơn khóa đang chạy/kế tiếp (cửa sổ chưa sinh) — suy ra
  // số khóa từ ngày buổi rồi đánh số trong cửa sổ đó.
  const futureIndex = classCourseIndexOfDate(cls, sessionClaimDate(session));
  const futureList = classCourseViewSessions(cls, futureIndex);
  let count = 0;
  for (const item of futureList) {
    const unnumbered = isCourseUnnumberedRow(cls, item);
    if (!unnumbered) count += 1;
    if (!same(item)) continue;
    return { label: unnumbered ? "—" : `Buổi ${count}`, period: `Khóa ${futureIndex}` };
  }
  return null;
}

function classAttendanceTab(row, teacherView, sessionId) {
  const students = state.data.students.filter((student) => (row.studentIds || []).includes(student.id));
  const today = localDateKey(new Date());
  const sessions = classSessions(row);
  const requested = sessionId ? sessions.find((item) => item.id === sessionId) : null;
  const pastOrToday = sessions.filter((item) => item.date <= today);
  const current = requested || sessions.find((item) => item.date === today) || pastOrToday.at(-1) || sessions[0];
  if (!current) {
    return `<section class="card nz-class-card"><div class="card-header"><div><h2>Chưa có buổi để điểm danh</h2><p>Lớp chưa có thời khóa biểu từ ngày 01/09/2026.</p></div></div></section>`;
  }
  const isFuture = current.date > today;
  const adminLocked = isAdminConfiguredOff(current);
  const locked = isFuture || adminLocked ? " disabled" : "";
  // Trợ giảng chỉ nhập điểm và nhận xét: điểm danh, clip quay ở nhà và trạng
  // thái nghỉ luôn khoá, giá trị cũ gửi kèm dạng hidden để không bị ghi mất.
  const assistantView = assistantOnlyFor(row, current);
  const attendanceLocked = assistantView ? " disabled" : locked;
  const stored = (current.attendance || []);
  const assessmentColumns = attendanceAssessmentColumns(current);
  const isOff = adminLocked ? true : state.attendanceOff === null ? Boolean(current.isOff) : state.attendanceOff;
  // "Học không tính phí" là quyết định thu phí — chỉ quản trị viên đổi; giáo
  // viên/trợ giảng/kế toán lưu điểm danh giữ nguyên trạng thái đã có.
  const noFeeLocked = state.role === "ADMIN" && !teacherView && !assistantView ? locked : " disabled";
  const isNoFee = !isOff && (state.attendanceNoFee === null || state.attendanceNoFee === undefined ? Boolean(current.noFee) : state.attendanceNoFee);
  // Buổi nghỉ chỉ còn 2 cột thao tác được: clip quay ở nhà và phiếu bài tập
  // (học viên vẫn làm bài ở nhà). Mọi cột khác — điểm danh, từ vựng, các cột
  // điểm tự đặt, ghi chú, tên/xóa/thêm cột — đóng băng hết khi isOff.
  const gradingLocked = locked;
  const offFrozen = isOff ? " disabled" : "";
  const columnCtlLocked = gradingLocked || offFrozen;
  const slotTag = (item) => attendanceSlotTag(row, item);
  const options = sessions.map((item) => {
    const tag = slotTag(item);
    const periodPrefix = tag && /^Khóa /.test(tag.period) ? `${tag.period} · ` : "";
    const prefix = !tag ? "" : tag.label === "—" ? `${periodPrefix}— · ` : `${periodPrefix}${tag.label} · `;
    const label = sessionStamp(item);
    const offLabel = isAdminConfiguredOff(item) ? " · Nghỉ (đã khóa)" : item.isOff ? " · GV cho nghỉ" : isNoFeeSession(item) ? " · Không tính phí" : "";
    return `<option value="${escapeHtml(item.id)}" ${item.id === current.id ? "selected" : ""}>${escapeHtml(prefix + label)}${offLabel}</option>`;
  }).join("");
  const orderedColumnKeys = attendanceColumnOrder(current, assessmentColumns);
  const assessmentByKey = new Map(assessmentColumns.map((column) => [attendanceAssessmentColumnKey(column.id), column]));
  const draggableHeader = (key, className, content, label) => `<th class="${className} attendance-draggable-column" draggable="true" data-attendance-column-key="${escapeHtml(key)}" title="Kéo để đổi vị trí cột ${escapeHtml(label)}"><div class="attendance-column-drag-wrap"><span class="attendance-column-drag-handle" data-attendance-column-drag-handle aria-hidden="true">⠿</span>${content}</div></th>`;
  const columnHeader = (key) => {
    if (key === "status") return draggableHeader(key, "attendance-status-col", "<span>Điểm danh</span>", "Điểm danh");
    if (key === "clip") return draggableHeader(key, "attendance-clip-col", "<span class=\"attendance-head-label\">Clip quay ở nhà</span>", "Clip quay ở nhà");
    if (key === "worksheet") return draggableHeader(key, "attendance-clip-col", "<span class=\"attendance-head-label\">Phiếu bài tập</span>", "Phiếu bài tập");
    if (key === "vocabulary") return draggableHeader(key, "attendance-vocabulary-col", "<span>Từ vựng</span>", "Từ vựng");
    if (key === "note") return draggableHeader(key, "attendance-note-col", "<span>Ghi chú</span>", "Ghi chú");
    const column = assessmentByKey.get(key);
    if (!column) return "";
    const content = `<div class="attendance-column-head"><input class="attendance-column-name" type="text" name="assessment_column_${escapeHtml(column.id)}" maxlength="50" value="${escapeHtml(String(column.name || "").replace(/\s+/g, " "))}" placeholder="BTVN" aria-label="Tên cột điểm"${columnCtlLocked || (assistantView && !column.draft ? " disabled" : "")} />${assistantView && !column.draft ? "" : `<button class="attendance-column-remove" type="button" data-attendance-column-remove="${escapeHtml(column.id)}" title="Xóa cột" aria-label="Xóa cột ${escapeHtml(column.name || "BTVN")}"${columnCtlLocked}>×</button>`}</div>`;
    // Trợ giảng không xoá / đổi tên cột điểm giáo viên đã lưu (S29 10/11/2026 mất cột điểm của cô Ái Đức).
    return draggableHeader(key, "attendance-vocabulary-col attendance-assessment-col", content, column.name || "BTVN").replace("<th ", `<th data-assessment-column="${escapeHtml(column.id)}" `);
  };
  const columnHeaders = orderedColumnKeys.map(columnHeader).join("");
  const rows = students.map((student, index) => {
    const record = stored.find((item) => item.studentId === student.id) || {};
    const status = record.status || "PRESENT";
    const absentLocked = !isOff && attendanceAbsenceLocksGrading(status);
    const gradeLocked = gradingLocked || (absentLocked || isOff ? " disabled" : "");
    const statusOptions = ATTENDANCE_CHOICES.map(([value, label]) => `<option value="${value}" ${status === value ? "selected" : ""}>${label}</option>`).join("");
    const attendanceCell = isOff
      ? `<input type="hidden" name="status_${student.id}" value="EXCUSED" />${attendanceStatusBadge("EXCUSED", true)}`
      : assistantView
        ? `<input type="hidden" name="status_${student.id}" value="${escapeHtml(status)}" /><select class="input" data-attendance-status disabled>${statusOptions}</select>`
        : `<select class="input" name="status_${student.id}" data-attendance-status${locked}>${statusOptions}</select>`;
    const noteCell = `<input class="input" data-attendance-grade name="note_${student.id}" maxlength="300" value="${escapeHtml(record.note || "")}" placeholder="Ghi chú"${locked || gradeLocked} />`;
    const clipCell = assistantView
      ? `${record.pronunciationVideoDone ? `<input type="hidden" name="clip_${escapeHtml(student.id)}" value="1" />` : ""}<label class="attendance-clip-check" title="Clip quay ở nhà do giáo viên tick"><input type="checkbox" ${record.pronunciationVideoDone ? "checked " : ""}disabled /><span aria-hidden="true">✓</span></label>`
      : `<label class="attendance-clip-check" title="Clip quay ở nhà của ${escapeHtml(student.fullName)}"><input type="checkbox" name="clip_${escapeHtml(student.id)}" ${record.pronunciationVideoDone ? "checked " : ""}${gradingLocked} /><span aria-hidden="true">✓</span></label>`;
    const worksheetCell = assistantView
      ? `${record.worksheetDone ? `<input type="hidden" name="worksheet_${escapeHtml(student.id)}" value="1" />` : ""}<label class="attendance-clip-check" title="Phiếu bài tập do giáo viên tick"><input type="checkbox" ${record.worksheetDone ? "checked " : ""}disabled /><span aria-hidden="true">✓</span></label>`
      : `<label class="attendance-clip-check" title="Phiếu bài tập của ${escapeHtml(student.fullName)}"><input type="checkbox" name="worksheet_${escapeHtml(student.id)}" ${record.worksheetDone ? "checked " : ""}${gradingLocked} /><span aria-hidden="true">✓</span></label>`;
    const vocabularyCell = `<input class="input attendance-assessment-input" data-attendance-grade type="text" maxlength="200" name="vocabulary_${escapeHtml(student.id)}" value="${escapeHtml(record.vocabularyScore ?? "")}" aria-label="Từ vựng của ${escapeHtml(student.fullName)}"${gradeLocked} />`;
    const cellByKey = new Map([
      ["status", `<td class="attendance-status-col" data-attendance-column-key="status">${attendanceCell}</td>`],
      ["clip", `<td class="attendance-clip-col" data-attendance-column-key="clip">${clipCell}</td>`],
      ["worksheet", `<td class="attendance-clip-col" data-attendance-column-key="worksheet">${worksheetCell}</td>`],
      ["vocabulary", `<td class="attendance-vocabulary-col" data-attendance-column-key="vocabulary">${vocabularyCell}</td>`],
      ["note", `<td class="attendance-note-col" data-attendance-column-key="note">${noteCell}</td>`],
      ...assessmentColumns.map((column) => [
        attendanceAssessmentColumnKey(column.id),
        `<td class="attendance-vocabulary-col attendance-assessment-col" data-attendance-column-key="${escapeHtml(attendanceAssessmentColumnKey(column.id))}" data-assessment-column="${escapeHtml(column.id)}"><input class="input attendance-assessment-input" data-attendance-grade type="text" maxlength="200" name="assessment_${escapeHtml(column.id)}_${escapeHtml(student.id)}" value="${escapeHtml(record.assessmentScores?.[column.id] ?? "")}" aria-label="${escapeHtml(column.name || "BTVN")} của ${escapeHtml(student.fullName)}"${gradeLocked} /></td>`,
      ]),
    ]);
    const orderedCells = orderedColumnKeys.map((key) => cellByKey.get(key) || "").join("");
    return `<tr${absentLocked ? " class=\"is-absent-row\"" : ""}><td class="cell-index attendance-index-col">${index + 1}</td><td class="code attendance-code-col">${escapeHtml(student.code)}</td><td class="attendance-student-col" title="${escapeHtml(student.fullName)}">${escapeHtml(student.fullName)}</td>${orderedCells}<td class="attendance-add-col" data-attendance-column-control="add"></td></tr>`;
  }).join("");
  const markedCount = stored.filter((item) => item.status).length;
  const sessionNote = adminLocked ? "Nghỉ do học vụ cấu hình · Đã khóa" : isOff ? "Giáo viên cho nghỉ · Có thể sửa" : isNoFee ? "Học không tính phí · Khóa kéo dài 1 buổi" : isFuture ? `Mở điểm danh vào ${formatDateVi(current.date)}` : `đã điểm danh ${markedCount}/${students.length}`;
  const statusNotice = !isOff && !isFuture ? attendanceNoticeText(current, students) : "";
  const hint = (assistantView
    ? "Trợ giảng chỉ nhập điểm và nhận xét. Điểm danh, clip quay ở nhà và trạng thái nghỉ do giáo viên phụ trách nên đã khóa."
    : adminLocked
    ? "Buổi nghỉ do học vụ cấu hình đã đóng băng. Muốn thay đổi, quản trị viên mở Cấu hình lịch nghỉ của lớp."
    : isOff
      ? "Buổi nghỉ do giáo viên chọn vẫn tính phí (trừ 1 buổi tồn). Chỉ nhập được Clip quay ở nhà và Phiếu bài tập — các cột còn lại đóng băng. Học bù thì bỏ tick và điểm danh lại, không trừ thêm; không học bù thì khấu trừ kỳ sau. Nếu học vụ khóa ngày này thành nghỉ lễ thì không tính phí."
    : isNoFee
      ? "Buổi học vẫn điểm danh và nhập điểm bình thường nhưng không tính vào học phí — khóa tự kéo dài thêm 1 buổi bù ở cuối. Bỏ tick rồi Lưu để tính phí lại."
    : isFuture
      ? "Buổi học tương lai chỉ để xem. Điểm danh sẽ tự mở khóa vào đúng ngày học."
      : "Lưu điểm danh trừ 1 buổi của mỗi học viên, kể cả vắng phép hoặc vắng không phép. GV cho nghỉ vẫn trừ; nghỉ lễ do học vụ khóa thì không trừ.")
    + " Kéo tiêu đề cột để đổi vị trí; bấm Lưu để áp dụng cho báo cáo.";
  const currentTag = slotTag(current);
  const currentSlotText = currentTag
    ? (currentTag.label === "—" ? "—" : `${currentTag.label} · ${currentTag.period}`)
    : `Buổi ${current.sequence}`;
  const badgeTone = isOff ? "amber" : isNoFee ? "blue" : current.status === "COMPLETED" ? "green" : "blue";
  const badgeLabel = isOff ? "Nghỉ học" : isNoFee ? "Học không tính phí" : current.status === "COMPLETED" ? "Hoàn thành" : isFuture ? "Sắp diễn ra" : "Đã lên lịch";
  const columnCount = 9 + assessmentColumns.length;
  const tableWidth = 1152 + (assessmentColumns.length * 130);
  return `<form id="attendance-form" class="card nz-class-card" data-session-id="${escapeHtml(current.id)}" data-class-id="${escapeHtml(row.id)}"${locked || isOff ? " data-session-locked=\"1\"" : ""}><div class="nz-attendance-head"><div><div class="nz-attendance-title"><h2>Điểm danh</h2><span class="badge badge-${badgeTone}">${badgeLabel}</span></div><p>${currentSlotText} · ${sessionNote}</p></div><div class="nz-attendance-actions"><select class="input nz-attendance-session" id="attendance-session-select" aria-label="Chọn buổi điểm danh" data-class-id="${escapeHtml(row.id)}" data-teacher="${teacherView ? "1" : ""}">${options}</select><label class="nz-check"><input type="checkbox" id="attendance-off" ${isOff ? "checked" : ""}${attendanceLocked} />Nghỉ học</label><label class="nz-check" title="Lớp vẫn học và điểm danh bình thường nhưng buổi này không tính học phí — khóa tự kéo dài thêm 1 buổi bù ở cuối"><input type="checkbox" id="attendance-no-fee" ${isNoFee ? "checked" : ""}${noFeeLocked} />Học không tính phí</label><button class="primary-btn" type="submit"${locked}>Lưu</button></div></div><div class="table-wrap people-table nz-attendance-table"><table style="min-width:${tableWidth}px"><thead><tr><th class="attendance-index-col">STT</th><th class="attendance-code-col">Mã</th><th class="attendance-student-col">Học viên</th>${columnHeaders}<th class="attendance-add-col" data-attendance-column-control="add"><button class="attendance-add-column" type="button" data-attendance-column-add title="Thêm cột điểm" aria-label="Thêm cột điểm"${assessmentColumns.length >= 12 ? " disabled" : columnCtlLocked}>+</button></th></tr></thead><tbody>${rows || `<tr><td class="empty-cell" colspan="${columnCount}">Lớp chưa có học viên đang học.</td></tr>`}</tbody></table></div>${statusNotice ? `<p class="nz-attendance-status dashboard-attendance-note${attendanceNoticeComplete(current, students) ? " is-complete" : ""}">${escapeHtml(statusNotice)}</p>` : ""}<p class="nz-attendance-hint">${hint}</p></form>`;
}

function classSyllabusTab(row) {
  const syllabus = classSyllabus(row);
  if (!syllabus?.id) {
    return `<section class="card nz-class-card"><div class="card-header"><div><h2>Chưa gán syllabus</h2><p>Vào tab Thông tin lớp, chọn syllabus rồi Lưu thông tin lớp.</p></div></div></section>`;
  }
  return `<div id="class-syllabus-react-root" class="nz-class-syllabus" data-syllabus-id="${escapeHtml(syllabus.id)}" data-readonly="${state.role !== "ADMIN" ? "1" : "0"}"></div>`;
}

function classDetailPage(row, teacherView = false) {
  const parsed = parseClassRoute(teacherView) || { tab: "info", sessionId: "" };
  const settings = state.data.settings;
  const students = state.data.students.filter((student) => (row.studentIds || []).includes(student.id));
  const typeName = findBy(settings.classTypes, row.classTypeId)?.name || "Lớp";
  const tab = ["info", "hoc-vien", "diem-danh"].includes(parsed.tab) ? parsed.tab : "info";
  const readOnly = !canManageRoster();
  const waiting = isWaitingClass(row);
  // "Lớp chờ" chỉ là bể chờ học viên — không lịch/điểm danh/học phí, chỉ hiện danh sách.
  const body = waiting || tab === "hoc-vien"
    ? classStudentsTab(row, teacherView, readOnly)
    : tab === "diem-danh"
      ? classAttendanceTab(row, teacherView, parsed.sessionId)
      : classInfoTab(row, teacherView, readOnly);
  const tabs = waiting
    ? `<button class="nz-tab active">Danh sách học viên (${students.length})</button>`
    : [
      ["info", "Thông tin lớp"],
      ["hoc-vien", `Danh sách học viên (${students.length})`],
      ["diem-danh", "Điểm danh"],
    ].map(([key, label]) => `<button class="nz-tab ${tab === key ? "active" : ""}" data-nav="${classHref(row.id, key, "", teacherView)}">${label}</button>`).join("");
  return `<div class="class-detail nz-class-page${teacherView ? " teacher-class-detail" : ""}"><div class="nz-class-topbar"><div class="nz-class-heading-row"><h1>${escapeHtml(row.name)}</h1><div class="page-actions">${waiting ? '<span class="badge badge-blue">Lớp hệ thống</span>' : `<span class="badge badge-amber">${escapeHtml(typeName)}</span><span class="badge badge-${row.status === "ACTIVE" ? "green" : "blue"}">${classStatusLabels[row.status]}</span>`}</div></div><nav class="nz-class-tabs">${tabs}</nav>${teacherView || !canDeleteRoster() || waiting ? "" : `<div class="page-actions nz-class-top-actions"><button class="danger-btn" data-class-delete="${escapeHtml(row.id)}">${icon("trash")}Xoá lớp</button></div>`}</div>${body}${classModalHtml()}${classStudentModalHtml()}</div>`;
}

function classesPage() {
  const parsed = parseClassRoute(false);
  if (parsed) { const row = findBy(state.data.classes, parsed.id); return row ? classDetailPage(row, false) : `<div class="empty-state"><h1>Không tìm thấy lớp học</h1><button class="primary-btn" data-nav="/lop-hoc">Quay lại</button></div>`; }
  const query = state.classQuery.trim().toLowerCase();
  const settings = state.data.settings;
  const items = state.data.classes.filter((row) => (!query || `${row.code} ${row.name}`.toLowerCase().includes(query)) && (!state.classTypeFilter || row.classTypeId === state.classTypeFilter) && (!state.classBranchFilter || row.branchId === state.classBranchFilter) && (!state.classBillingFilter || classBillingMode(row) === state.classBillingFilter));
  const rows = items.map((row, index) => `<tr><td class="cell-index">${index + 1}</td><td class="code">${escapeHtml(row.code)}</td><td class="class-name-cell"><button class="table-link" data-nav="/lop-hoc/${encodeURIComponent(row.id)}">${escapeHtml(row.name)}</button></td><td>${escapeHtml(findBy(settings.classTypes, row.classTypeId)?.name || "—")}</td><td>${escapeHtml(findBy(settings.branches, row.branchId)?.name || "—")}</td><td class="schedule-cell">${escapeHtml(classScheduleText(row))}</td><td class="class-progress-cell">${escapeHtml(classProgressText(row))}</td><td>${classStudentCount(row)}</td><td><span class="badge badge-${row.status === "ACTIVE" ? "green" : row.status === "PAUSED" ? "amber" : "blue"}">${classStatusLabels[row.status]}</span></td><td class="settings-actions-cell">${canManageRoster() ? `<div class="row-actions settings-row-actions"><button class="mini-btn" data-class-edit="${escapeHtml(row.id)}" title="Sửa">${icon("pencil")}</button>${isWaitingClass(row) || !canDeleteRoster() ? "" : `<button class="trash-btn" data-class-delete="${escapeHtml(row.id)}" title="Xoá">${icon("trash")}</button>`}</div>` : "—"}</td></tr>`).join("");
  return `<div class="classes-page"><div class="page-header"><div><h1>Lớp học</h1><p>Quản lý lớp, giáo viên, học viên và lịch học lặp theo tuần.</p></div></div><section class="card settings-card"><div class="card-header people-card-header"><div class="card-heading"><div><h2>Danh sách lớp (${items.length})</h2><p>Số học viên tính theo danh sách hiện đang được xếp trong lớp.</p></div>${canManageRoster() ? `<button class="primary-btn" data-class-add>${icon("plus")}Thêm</button>` : ""}</div><form id="class-filter-form" class="filter-grid class-filters"><label class="field"><span>Tìm kiếm</span><input class="input" name="q" value="${escapeHtml(state.classQuery)}" placeholder="Tên hoặc mã lớp, gõ xong bấm Enter..." /></label><label class="field"><span>Loại lớp</span><select class="input" name="type"><option value="">Tất cả</option>${settings.classTypes.map((item) => `<option value="${escapeHtml(item.id)}" ${state.classTypeFilter === item.id ? "selected" : ""}>${escapeHtml(item.name)}</option>`).join("")}</select></label><label class="field"><span>Chi nhánh</span><select class="input" name="branch"><option value="">Tất cả</option>${settings.branches.map((item) => `<option value="${escapeHtml(item.id)}" ${state.classBranchFilter === item.id ? "selected" : ""}>${escapeHtml(item.name)}</option>`).join("")}</select></label><label class="field"><span>Hình thức thu</span><select class="input" name="billing"><option value="">Tất cả</option><option value="MONTHLY" ${state.classBillingFilter === "MONTHLY" ? "selected" : ""}>Thu tháng</option><option value="COURSE" ${state.classBillingFilter === "COURSE" ? "selected" : ""}>Thu khóa</option></select></label></form></div><div class="table-wrap people-table"><table><thead><tr><th>STT</th><th>Mã</th><th>Tên lớp</th><th>Loại</th><th>Chi nhánh</th><th>Lịch tuần</th><th>Tiến độ</th><th>Học viên</th><th>Trạng thái</th><th class="settings-actions-cell">Thao tác</th></tr></thead><tbody>${rows || '<tr><td class="empty-cell" colspan="10">Không có lớp nào khớp bộ lọc.</td></tr>'}</tbody></table></div></section>${classModalHtml()}</div>`;
}

function calendarRange() {
  const focus = localDate(state.calendarDate);
  if (state.calendarView === "day") return { from: focus, to: focus, days: [focus] };
  if (state.calendarView === "month") {
    const first = new Date(focus.getFullYear(), focus.getMonth(), 1, 12);
    const offset = (first.getDay() + 6) % 7;
    const from = addDays(first, -offset); const to = addDays(from, 41);
    return { from, to, days: Array.from({ length: 42 }, (_, index) => addDays(from, index)) };
  }
  const offset = (focus.getDay() + 6) % 7; const from = addDays(focus, -offset); const to = addDays(from, 6);
  return { from, to, days: Array.from({ length: 7 }, (_, index) => addDays(from, index)) };
}

function calendarSessions() {
  return calendarSessionsForDays(calendarRange().days, true);
}

/** Buổi học hiện trên lịch dạy cho các ngày `days`. applyFilters=false bỏ qua bộ
 * lọc GV/lớp/chi nhánh — dùng để kiểm tra trùng lịch của một giáo viên. */
function calendarSessionsForDays(days, applyFilters = true) {
  const { start, end } = lessonScheduleWindow();
  const fromKey = localDateKey(start);
  const toKey = localDateKey(end);
  const visibleDays = days.filter((date) => { const key = localDateKey(date); return key >= fromKey && key <= toKey; });
  const visibleDayKeys = new Set(visibleDays.map((date) => localDateKey(date)));
  const explicit = (state.data.lessonSessions || []).filter((item) => !item.isExtra);
  const byClassDate = new Map();
  for (const item of explicit) {
    const key = `${item.classId}|${sessionClaimDate(item)}`;
    if (!byClassDate.has(key)) byClassDate.set(key, []);
    byClassDate.get(key).push(item);
  }
  for (const list of byClassDate.values()) list.sort((a, b) => a.startTime.localeCompare(b.startTime));
  const generated = [];
  for (const date of visibleDays) for (const cls of state.data.classes) {
    if (cls.status === "FINISHED" || cls.status === "DRAFT") continue;
    if (localDateKey(date) < classCourseStartDate(cls)) continue;
    const daySlots = (cls.schedules || []).filter((slot) => scheduleSlotAppliesOnDate(slot, localDateKey(date)));
    if (!daySlots.length) continue;
    const { claimed } = claimDaySlots(daySlots, byClassDate.get(`${cls.id}|${localDateKey(date)}`) || []);
    for (let index = 0; index < daySlots.length; index += 1) {
      const slot = daySlots[index];
      const key = `${cls.id}|${localDateKey(date)}|${slot.startTime}`;
      generated.push(claimed[index] || { id: `recurring|${key}`, classId: cls.id, date: localDateKey(date), startTime: slot.startTime, endTime: slot.endTime, teacherId: cls.teacherId, roomId: cls.roomId, status: "SCHEDULED", isExtra: false, recurrenceKey: "", note: "" });
    }
  }
  // Buổi ngoài lịch (học thêm, dạy bù) không ghép suất nào nhưng vẫn phải hiện
  // trên lịch dạy — nếu không buổi bù vừa xếp sẽ "biến mất" khỏi lưới tuần.
  const extras = (state.data.lessonSessions || []).filter((item) => item.isExtra && visibleDayKeys.has(item.date));
  return [...generated, ...extras].filter((item) => { const cls = findBy(state.data.classes, item.classId); if (!cls || isAdminConfiguredOff(item)) return false; if (!applyFilters) return true; return (!state.calendarTeacher || item.teacherId === state.calendarTeacher) && (!state.calendarClass || item.classId === state.calendarClass) && (!state.calendarBranch || cls.branchId === state.calendarBranch); }).sort((a, b) => `${a.date}${a.startTime}`.localeCompare(`${b.date}${b.startTime}`));
}

function calendarTone(id) {
  let hash = 0;
  for (const character of String(id || "")) hash = ((hash << 5) - hash + character.charCodeAt(0)) | 0;
  return `tone-${Math.abs(hash) % 5}`;
}

function sessionCard(item, compact = false) {
  const cls = findBy(state.data.classes, item.classId); const teacher = findBy(state.data.teachers, item.teacherId);
  const secondary = compact
    ? `<span>${escapeHtml(item.startTime)}–${escapeHtml(item.endTime)}</span>`
    : `<span class="calendar-session-teacher">${icon("user")}${escapeHtml(teacher?.fullName || "Chưa phân công")}</span>`;
  // Tag lịch dạy cùng phân loại với Báo cáo chấm công: dạy bù (học lại buổi nghỉ),
  // dạy thay (buổi theo lịch đổi giáo viên), nghỉ học (giáo viên tick nghỉ).
  const extraTag = item.makeupOf ? '<em class="calendar-tag tag-makeup">Dạy bù</em>' : item.isExtra ? '<em class="calendar-tag">Buổi thêm</em>' : "";
  const substituteTag = !item.isOff && timesheetSubstitution(item) ? '<em class="calendar-tag tag-substitute">Dạy thay</em>' : "";
  const offTag = item.isOff ? '<em class="calendar-tag tag-off">Nghỉ học</em>' : "";
  return `<button class="calendar-session ${calendarTone(item.classId)} status-${item.status.toLowerCase()}${item.isOff ? " is-off" : ""} ${compact ? "compact" : ""}" data-session-view="${escapeHtml(item.id)}" data-session-class="${escapeHtml(item.classId)}"><strong>${escapeHtml(cls?.name || "Lớp học")}</strong>${secondary}${extraTag}${substituteTag}${offTag}</button>`;
}

// Lịch thêm ngoài lịch lớp — giữ khớp cloudflare/calendar-events.ts.
const CALENDAR_EVENT_KINDS = ["TEST_SPEAKING", "KEM_SPEAKING", "KEM_CA_NHAN", "KEM_LOP", "DAY_THAY"];
const CALENDAR_EVENT_LABELS = { TEST_SPEAKING: "Test speaking", KEM_SPEAKING: "Kèm speaking", KEM_CA_NHAN: "Kèm hỗ trợ cá nhân", KEM_LOP: "Kèm hỗ trợ lớp", DAY_THAY: "Dạy thay" };
const CALENDAR_ADD_KINDS = [["MAKEUP", "Dạy bù"], ...CALENDAR_EVENT_KINDS.map((kind) => [kind, CALENDAR_EVENT_LABELS[kind]])];

async function loadCalendarEvents() {
  if (!state.data || state.role === "STUDENT") return;
  try { state.data.calendarEvents = (await api("/api/calendar-events")).items || []; } catch { state.data.calendarEvents = state.data.calendarEvents || []; }
}

function timeRangesOverlap(aStart, aEnd, bStart, bEnd) { return aStart < bEnd && bStart < aEnd; }

/** Lịch thêm hiện trên lịch dạy: lọc GV áp dụng; lọc theo lớp thì ẩn (lịch thêm không thuộc lớp). */
function calendarEventsForDays(days, { teacherId = state.calendarTeacher, hideWhenClassFilter = true } = {}) {
  if (hideWhenClassFilter && state.calendarClass) return [];
  const keys = new Set(days.map((day) => localDateKey(day)));
  return (state.data.calendarEvents || []).filter((item) => keys.has(item.date) && (!teacherId || item.teacherId === teacherId)).sort((a, b) => `${a.date}${a.startTime}`.localeCompare(`${b.date}${b.startTime}`));
}

/** Mọi lịch của giáo viên chồng giờ với [startTime, endTime) ngày `date`:
 * buổi dạy (kể cả dạy bù / dạy thay, trừ buổi nghỉ) và lịch thêm. */
function teacherScheduleConflicts(teacherId, date, startTime, endTime, { excludeEventId = "", excludeSessionId = "" } = {}) {
  if (!teacherId || !date || !startTime || !endTime || endTime <= startTime) return [];
  const sessions = calendarSessionsForDays([localDate(date)], false)
    .filter((item) => item.date === date && item.teacherId === teacherId && !item.isOff && item.status !== "CANCELLED" && item.id !== excludeSessionId && timeRangesOverlap(startTime, endTime, item.startTime, item.endTime))
    .map((item) => ({ startTime: item.startTime, endTime: item.endTime, label: findBy(state.data.classes, item.classId)?.name || "Lớp học" }));
  const events = (state.data.calendarEvents || [])
    .filter((item) => item.id !== excludeEventId && item.teacherId === teacherId && item.date === date && timeRangesOverlap(startTime, endTime, item.startTime, item.endTime))
    .map((item) => ({ startTime: item.startTime, endTime: item.endTime, label: CALENDAR_EVENT_LABELS[item.kind] || "Lịch thêm" }));
  return [...sessions, ...events].sort((a, b) => a.startTime.localeCompare(b.startTime));
}

function calendarConflictHtml(conflicts, teacherId) {
  if (!conflicts.length) return "";
  const teacher = findBy(state.data.teachers, teacherId);
  return `<div class="calendar-conflict-warning" role="alert"><strong>⚠ Trùng lịch — ${escapeHtml(teacher?.fullName || "giáo viên")} đã có ${conflicts.length} lịch chồng giờ, không lưu được. Đổi giờ hoặc giáo viên khác:</strong><ul>${conflicts.map((item) => `<li>${escapeHtml(item.startTime)}–${escapeHtml(item.endTime)} · ${escapeHtml(item.label)}</li>`).join("")}</ul></div>`;
}

function calendarEventCard(item, compact = false) {
  const teacher = findBy(state.data.teachers, item.teacherId);
  const conflict = teacherScheduleConflicts(item.teacherId, item.date, item.startTime, item.endTime, { excludeEventId: item.id }).length > 0;
  const label = CALENDAR_EVENT_LABELS[item.kind] || "Lịch thêm";
  const title = `${label} · ${item.startTime}–${item.endTime} · ${teacher?.fullName || "Chưa phân công"}${item.note ? ` · ${item.note}` : ""}${conflict ? " · TRÙNG LỊCH" : ""}`;
  return `<button class="calendar-event kind-${escapeHtml(String(item.kind).toLowerCase())}${compact ? " compact" : ""}${conflict ? " has-conflict" : ""}" type="button" data-calendar-event="${escapeHtml(item.id)}" title="${escapeHtml(title)}"><strong>${escapeHtml(label)}</strong><span class="calendar-event-time">${escapeHtml(item.startTime)}–${escapeHtml(item.endTime)}</span>${compact ? "" : `<span class="calendar-session-teacher">${icon("user")}${escapeHtml(teacher?.fullName || "Chưa phân công")}</span>${item.note ? `<small class="calendar-event-note">${escapeHtml(item.note)}</small>` : ""}`}${conflict ? '<em class="calendar-tag tag-conflict">Trùng lịch</em>' : ""}</button>`;
}

function calendarBoard(items, days, events = []) {
  const today = localDateKey(new Date());
  if (state.calendarView === "month") {
    return `<div class="month-weekdays">${["Thứ 2", "Thứ 3", "Thứ 4", "Thứ 5", "Thứ 6", "Thứ 7", "CN"].map((label) => `<span>${label}</span>`).join("")}</div><div class="month-grid">${days.map((day) => { const key = localDateKey(day); const rows = [...items.filter((item) => item.date === key).map((item) => ({ at: item.startTime, html: () => sessionCard(item, true) })), ...events.filter((item) => item.date === key).map((item) => ({ at: item.startTime, html: () => calendarEventCard(item, true) }))].sort((a, b) => a.at.localeCompare(b.at)); return `<div class="month-day ${day.getMonth() !== localDate(state.calendarDate).getMonth() ? "outside " : ""}${key === today ? "is-today" : ""}"${key === today ? ' aria-current="date"' : ""}><strong>${day.getDate()}</strong>${rows.slice(0, 4).map((row) => row.html()).join("")}${rows.length > 4 ? `<button class="month-more" type="button" data-calendar-open-day="${key}">+${rows.length - 4} lịch khác</button>` : ""}</div>`; }).join("")}</div>`;
  }
  // Hàng = khung giờ. Lịch thêm (test / kèm) nằm đúng hàng khung giờ của nó, cùng ô với buổi học
  // (anh Mori 12/11/2026: trước đây thẻ kéo dài qua mọi hàng chồng giờ nên rất dài, khó nhìn).
  const slotKeys = new Set([...items, ...events].map((item) => `${item.startTime}|${item.endTime}`));
  const slots = [...slotKeys].sort();
  const dayKeys = days.map((day) => localDateKey(day));
  const template = `96px repeat(${days.length}, minmax(0,1fr))`;
  const dayLabel = (day) => day.getDay() === 0 ? "CN" : `Thứ ${day.getDay() + 1}`;
  const rows = slots.map((slot, rowIndex) => {
    const [start, end] = slot.split("|");
    const row = rowIndex + 2;
    const cardsByDay = dayKeys.map((key) => [
      ...items.filter((item) => item.date === key && item.startTime === start && item.endTime === end).map((item) => () => sessionCard(item)),
      ...events.filter((item) => item.date === key && item.startTime === start && item.endTime === end).map((item) => () => calendarEventCard(item)),
    ]);
    const laneCount = Math.max(1, ...cardsByDay.map((cards) => cards.length));
    return `<div class="calendar-time" style="grid-column:1;grid-row:${row}">${escapeHtml(start)}<span>–</span>${escapeHtml(end)}</div>${cardsByDay.map((cards, dayIndex) => { const key = dayKeys[dayIndex]; return `<div class="calendar-cell${key === today ? " is-today" : ""}" style="grid-column:${dayIndex + 2};grid-row:${row};--calendar-lanes:${laneCount}"${key === today ? ' aria-current="date"' : ""}>${Array.from({ length: laneCount }, (_, index) => `<div class="calendar-lane">${cards[index] ? cards[index]() : ""}</div>`).join("")}</div>`; }).join("")}`;
  }).join("");
  return `<div class="calendar-grid" style="--calendar-days:${days.length};grid-template-columns:${template}"><div class="calendar-corner" style="grid-column:1;grid-row:1">Giờ</div>${days.map((day, dayIndex) => { const key = dayKeys[dayIndex]; return `<div class="calendar-day-head${key === today ? " is-today" : ""}"${key === today ? ' aria-current="date"' : ""} style="grid-column:${dayIndex + 2};grid-row:1"><strong>${dayLabel(day)}</strong><span>${formatDateVi(day).slice(0, 5)}</span></div>`; }).join("")}${rows || `<div class="calendar-empty" style="grid-column:1 / -1;grid-row:2">${state.calendarKind === "SUPPORT" ? "Chưa có lịch bổ trợ trong khoảng thời gian này." : "Chưa có buổi học trong khoảng thời gian này."}</div>`}</div>`;
}

function teacherMobileWeekAgenda(items, days, events = []) {
  const today = localDateKey(new Date());
  const dayLabel = (day) => day.getDay() === 0 ? "Chủ nhật" : `Thứ ${day.getDay() + 1}`;
  return `<div class="teacher-week-agenda">${days.map((day) => {
    const key = localDateKey(day);
    const sessions = [...items.filter((item) => item.date === key), ...events.filter((item) => item.date === key).map((item) => ({ ...item, isCalendarEvent: true }))].sort((a, b) => a.startTime.localeCompare(b.startTime));
    const rows = sessions.map((item) => {
      if (item.isCalendarEvent) return `<button class="teacher-agenda-session calendar-event-agenda kind-${escapeHtml(String(item.kind).toLowerCase())}" data-calendar-event="${escapeHtml(item.id)}"><time>${escapeHtml(item.startTime)}<span>–${escapeHtml(item.endTime)}</span></time><span class="teacher-agenda-class"><strong>${escapeHtml(CALENDAR_EVENT_LABELS[item.kind] || "Lịch thêm")}</strong><small>${escapeHtml(item.note || "Lịch thêm")}</small></span><span class="teacher-agenda-arrow" aria-hidden="true">›</span></button>`;
      const cls = findBy(state.data.classes, item.classId);
      const branch = findBy(state.data.settings.branches, cls?.branchId);
      return `<button class="teacher-agenda-session ${calendarTone(item.classId)} status-${item.status.toLowerCase()}${item.isOff ? " is-off" : ""}" data-session-view="${escapeHtml(item.id)}" data-session-class="${escapeHtml(item.classId)}"><time>${escapeHtml(item.startTime)}<span>–${escapeHtml(item.endTime)}</span></time><span class="teacher-agenda-class"><strong>${escapeHtml(cls?.name || "Lớp học")}${item.isOff ? ' <em>Nghỉ</em>' : ""}</strong><small>${escapeHtml(branch?.name || "Chưa có chi nhánh")}</small></span><span class="teacher-agenda-arrow" aria-hidden="true">›</span></button>`;
    }).join("");
    return `<section class="teacher-agenda-day${key === today ? " is-today" : ""}"><header><span><strong>${dayLabel(day)}</strong><small>${formatDateVi(day).slice(0, 5)}</small></span><em>${key === today ? "Hôm nay" : `${sessions.length} lịch`}</em></header><div>${rows || '<p class="teacher-agenda-empty">Không có lịch dạy</p>'}</div></section>`;
  }).join("")}</div>`;
}

function calendarViewButtons() {
  return `<div class="calendar-view-buttons">${["day", "week", "month"].map((view) => `<button class="${state.calendarView === view ? "active" : ""}" data-calendar-view="${view}">${view === "day" ? "Ngày" : view === "week" ? "Tuần" : "Tháng"}</button>`).join("")}</div>`;
}

function calendarModalHtml(teacherView = false) {
  const modal = state.calendarModal; if (!modal) return "";
  const availableSessions = teacherView ? teacherClasses().flatMap((cls) => classSessions(cls)) : calendarSessions();
  const source = modal.id ? availableSessions.find((item) => item.id === modal.id) : null;
  if (!source) return "";
  const cls = findBy(state.data.classes, source.classId); const teacher = findBy(state.data.teachers, source.teacherId); const room = findBy(state.data.settings.rooms, source.roomId);
  const classRoute = teacherView ? `/gv/lop-hoc/${encodeURIComponent(cls?.id || "")}/diem-danh` : `/lop-hoc/${encodeURIComponent(cls?.id || "")}/diem-danh`;
  const isMakeup = source.isExtra || source.makeupOf;
  const canEdit = state.role === "ADMIN" && !teacherView;
  return `<div class="modal-backdrop" data-action="close-calendar-modal"><div class="modal-card" data-calendar-modal-card><div class="modal-head"><div><h2>Chi tiết buổi học</h2><p>${canEdit ? "Đổi giáo viên đứng buổi (khác giáo viên chính của lớp = dạy thay, tự lên tag và chấm công) hoặc xóa buổi bù." : "Thông tin chỉ để xem, không chỉnh sửa tại lịch dạy."}</p></div><button class="close-btn" type="button" data-action="close-calendar-modal">×</button></div><form id="calendar-session-form"><div class="form-grid"><label class="field span-2"><dt>Lớp học</dt><dd>${cls ? `<button class="detail-link" data-nav="${classRoute}">${escapeHtml(cls.name)} (${escapeHtml(cls.code)})</button>` : "—"}</dd></label><label class="field"><dt>Ngày học</dt><dd>${formatDateVi(source.date)}</dd></label><label class="field"><dt>Trạng thái</dt><dd><span class="badge badge-${source.isOff ? "amber" : source.status === "COMPLETED" ? "green" : source.status === "CANCELLED" ? "red" : "blue"}">${source.isOff ? (source.offSource === "TEACHER" ? "GV nghỉ" : "Nghỉ học vụ") : escapeHtml(sessionStatusLabels[source.status])}</span></dd></label><label class="field"><dt>Giờ bắt đầu</dt><dd>${escapeHtml(source.startTime)}</dd></label><label class="field"><dt>Giờ kết thúc</dt><dd>${escapeHtml(source.endTime)}</dd></label><label class="field"><dt>Giáo viên</dt><dd>${canEdit ? `<select class="input" name="teacher"><option value="">Chưa phân công</option>${state.data.teachers.map((item) => `<option value="${escapeHtml(item.id)}" ${source.teacherId === item.id ? "selected" : ""}>${escapeHtml(item.fullName)}</option>`).join("")}</select>` : escapeHtml(teacher?.fullName || "Chưa phân công")}</dd></label><label class="field"><dt>Phòng học</dt><dd>${escapeHtml(room?.name || "Chưa xếp phòng")}</dd></label><label class="field span-2"><dt>Ghi chú</dt><dd>${canEdit ? `<input class="input" name="note" value="${escapeHtml(source.note || "")}" placeholder="Ghi chú buổi học...">` : escapeHtml(source.note || "Không có ghi chú")}</dd></label></div><div class="settings-modal-footer">${isMakeup && canEdit ? `<button class="danger-btn" type="button" data-calendar-session-delete>Xóa buổi bù</button>` : ""}<button class="secondary-btn" type="button" data-action="close-calendar-modal">Đóng</button>${canEdit ? `<button class="primary-btn" type="submit">Lưu thay đổi</button>` : ""}</div></form></div></div>`;
}

/** Các ngày của kỳ in (ngày / tuần / tháng) quanh ngày đang xem trên lịch — tháng in đúng các ngày của tháng. */
function calendarPrintDays(mode) {
  const focus = localDate(state.calendarDate);
  if (mode === "day") return [focus];
  if (mode === "month") {
    const first = new Date(focus.getFullYear(), focus.getMonth(), 1, 12);
    const count = new Date(focus.getFullYear(), focus.getMonth() + 1, 0, 12).getDate();
    return Array.from({ length: count }, (_, index) => addDays(first, index));
  }
  const from = addDays(focus, -((focus.getDay() + 6) % 7));
  return Array.from({ length: 7 }, (_, index) => addDays(from, index));
}

/** Các dòng lịch để in, theo đúng bộ lọc giáo viên / lớp / loại lịch đang chọn. */
function calendarPrintRows(days) {
  const sessions = state.calendarKind === "SUPPORT" ? [] : calendarSessionsForDays(days, true);
  const events = calendarEventsForDays(days);
  const rooms = state.data.settings?.rooms || [];
  const rows = sessions.map((item) => {
    const cls = findBy(state.data.classes, item.classId);
    const teacher = findBy(state.data.teachers, item.teacherId || cls?.teacherId);
    const note = item.status === "CANCELLED" ? "Đã hủy" : item.isOff ? "Nghỉ" : item.makeupOf ? "Dạy bù" : item.isExtra ? "Học thêm" : "";
    return { date: item.date, startTime: item.startTime, endTime: item.endTime, title: cls?.name || "Lớp học", teacher: teacher?.fullName || "Chưa phân công", room: findBy(rooms, item.roomId || cls?.roomId)?.name || "", note, muted: Boolean(item.isOff || item.status === "CANCELLED") };
  });
  for (const item of events) {
    rows.push({ date: item.date, startTime: item.startTime, endTime: item.endTime, title: CALENDAR_EVENT_LABELS[item.kind] || "Lịch thêm", teacher: findBy(state.data.teachers, item.teacherId)?.fullName || "Chưa phân công", room: "", note: item.note || "Lịch thêm", muted: false });
  }
  return rows.sort((a, b) => `${a.date}${a.startTime}${a.title}`.localeCompare(`${b.date}${b.startTime}${b.title}`, "vi"));
}

/** Dữ liệu in lịch (ngày / tuần / tháng) theo bộ lọc đang chọn — máy chủ vẽ PDF. */
function calendarPrintData(mode = "week", now = new Date()) {
  const days = calendarPrintDays(mode);
  const rows = calendarPrintRows(days);
  const weekday = (day) => (day.getDay() === 0 ? "Chủ nhật" : `Thứ ${day.getDay() + 1}`);
  const focus = localDate(state.calendarDate);
  const title = mode === "day" ? `LỊCH DẠY ${weekday(days[0]).toUpperCase()} ${formatDateVi(days[0])}`
    : mode === "month" ? `LỊCH DẠY THÁNG ${focus.getMonth() + 1}/${focus.getFullYear()}`
      : `LỊCH DẠY TUẦN ${formatDateVi(days[0])} – ${formatDateVi(days[6])}`;
  const teacher = state.calendarTeacher ? findBy(state.data.teachers, state.calendarTeacher) : null;
  const cls = state.calendarClass ? findBy(state.data.classes, state.calendarClass) : null;
  const filter = [teacher ? `Giáo viên: ${teacher.fullName}` : "Tất cả giáo viên", cls ? `Lớp: ${cls.name}` : "Tất cả lớp", state.calendarKind === "SUPPORT" ? "Chỉ lịch bổ trợ" : ""].filter(Boolean).join(" · ");
  const pad = (n) => String(n).padStart(2, "0");
  return {
    mode, title, filter,
    exportedAt: `${pad(now.getHours())}:${pad(now.getMinutes())} ${formatDateVi(now)}`,
    days: days.map((day) => ({ key: localDateKey(day), weekday: weekday(day), date: mode === "week" ? formatDateVi(day).slice(0, 5) : formatDateVi(day) })),
    rows,
  };
}

/** Bấm In lịch: máy chủ vẽ PDF (A4 ngang) rồi trình duyệt tải file về máy. */
async function printCalendar(mode = "week", button = null) {
  if (button) button.disabled = true;
  try {
    const data = calendarPrintData(mode);
    const response = await fetch("/api/calendar/print-pdf", {
      method: "POST",
      credentials: "same-origin",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data),
    });
    if (!response.ok) {
      const body = await response.json().catch(() => ({}));
      throw new Error(body.error || "Không tạo được PDF lịch dạy.");
    }
    const blob = await response.blob();
    const match = /filename="([^"]+)"/.exec(response.headers.get("Content-Disposition") || "");
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = match?.[1] || "lich-day.pdf";
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(link.href), 1000);
    toast("Đã xuất PDF lịch dạy.");
  } catch (error) {
    toast(error.message || "Không xuất được PDF lịch dạy. Thử lại.");
  } finally {
    if (button) button.disabled = false;
  }
}

/** Nút In lịch (bên phải Thêm lịch): chọn in theo ngày / tuần / tháng đang xem. */
function calendarPrintMenu() {
  const options = [["day", "In lịch ngày"], ["week", "In lịch tuần"], ["month", "In lịch tháng"]];
  return `<details class="calendar-print"><summary class="secondary-btn">${icon("download")}In lịch</summary><div class="calendar-print-menu">${options.map(([mode, label]) => `<button type="button" data-calendar-print="${mode}" class="${state.calendarView === mode ? "active" : ""}">${label}</button>`).join("")}</div></details>`;
}

function calendarPage() {
  // Lọc "Bổ trợ": chỉ hiện lịch Test / Kèm speaking, Kèm hỗ trợ — ẩn buổi học lớp.
  const { from, to, days } = calendarRange(); const items = state.calendarKind === "SUPPORT" ? [] : calendarSessions(); const events = calendarEventsForDays(days); const settings = state.data.settings;
  const title = state.calendarView === "day" ? formatDateVi(from) : state.calendarView === "month" ? `Tháng ${localDate(state.calendarDate).getMonth() + 1}/${localDate(state.calendarDate).getFullYear()}` : `${formatDateVi(from)} – ${formatDateVi(to)}`;
  const filters = `<form id="calendar-filter-form" class="calendar-filters"><select class="input" name="teacher" aria-label="Giáo viên"><option value="">Tất cả giáo viên</option>${state.data.teachers.map((item) => `<option value="${escapeHtml(item.id)}" ${state.calendarTeacher === item.id ? "selected" : ""}>${escapeHtml(item.fullName)} (${escapeHtml(item.code)})</option>`).join("")}</select><select class="input" name="class" aria-label="Lớp"><option value="">Tất cả lớp</option>${state.data.classes.map((item) => `<option value="${escapeHtml(item.id)}" ${state.calendarClass === item.id ? "selected" : ""}>${escapeHtml(item.name)} (${escapeHtml(item.code)})</option>`).join("")}</select><select class="input" name="kind" aria-label="Loại lịch"><option value="">Tất cả</option><option value="SUPPORT" ${state.calendarKind === "SUPPORT" ? "selected" : ""}>Bổ trợ</option></select></form>`;
  return `<div class="calendar-page nz-calendar-page"><section class="card calendar-card"><div class="calendar-toolbar"><div class="calendar-nav-buttons"><button class="secondary-btn square" data-calendar-move="prev" aria-label="Kỳ trước">‹</button><button class="secondary-btn" data-calendar-move="today">Hôm nay</button><button class="secondary-btn square" data-calendar-move="next" aria-label="Kỳ sau">›</button><strong>${title}</strong></div>${filters}${calendarViewButtons()}${state.role === "ADMIN" ? `<button class="primary-btn calendar-add-btn" type="button" data-calendar-add>＋ Thêm lịch</button>` : ""}${calendarPrintMenu()}</div><div class="calendar-board">${calendarBoard(items, days, events)}</div></section>${calendarModalHtml()}${calendarMakeupModalHtml()}${calendarEventModalHtml()}</div>`;
}

/**
 * Buổi GV đã tick nghỉ còn chờ dạy bù: isOff + offSource TEACHER, chưa có buổi
 * bù nào trỏ tới, thuộc lớp còn hoạt động. Lớp thu tháng: từ đầu tháng hiện
 * tại (tháng trước đã khấu trừ học phí); lớp thu khóa: mọi buổi nghỉ chưa bù. Buổi "học không tính phí"
 * (noFee) không nằm trong danh sách. Không chọn GV → liệt kê của cả trung
 * tâm; chọn GV → chỉ các buổi nghỉ GV đó đã tick. Cũ nhất lên trước.
 */
function teacherOffSessionsNeedingMakeup(teacherId = "") {
  const sessions = state.data.lessonSessions || [];
  const monthStart = `${localDateKey(new Date()).slice(0, 7)}-01`;
  return sessions.filter((item) => {
    if (!item.isOff || item.offSource !== "TEACHER" || item.noFee || makeupSessionFor(item, sessions)) return false;
    const cls = findBy(state.data.classes, item.classId);
    if (!cls || cls.status === "FINISHED" || cls.status === "DRAFT") return false;
    // Lớp thu tháng: buổi nghỉ không bù trong tháng thì sang tháng sau đã khấu
    // trừ học phí — không còn chờ bù. Lớp thu khóa: buổi nghỉ làm khóa kéo dài,
    // bù lúc nào khóa cũng rút về — vẫn chờ bù dù đã qua tháng.
    const since = classBillingMode(cls) === "COURSE" ? LESSON_SCHEDULE_START : monthStart;
    if (!item.date || item.date < since) return false;
    return !teacherId || item.teacherId === teacherId;
  }).sort((a, b) => `${a.date}|${a.startTime}`.localeCompare(`${b.date}|${b.startTime}`));
}

/** Modal "Xếp lịch dạy bù": bấm + ở ô lịch → chọn buổi nghỉ của GV cần bù,
 * ngày/giờ lấy sẵn từ ô đã bấm và chỉnh được. Buổi bù tạo ra thuộc cùng lớp
 * của buổi nghỉ nên điểm danh/chấm điểm như buổi thường. */
function calendarMakeupModalHtml() {
  const modal = state.calendarMakeup;
  if (!modal) return "";
  // Hai việc tách riêng: "GV nghỉ" chỉ để lọc danh sách buổi nghỉ; "Giáo viên dạy bù" là người dạy buổi bù
  // (GV nghỉ có thể đang dạy lớp khác đúng giờ bù → nhờ GV khác dạy bù, cùng giờ vẫn xếp được).
  const offs = teacherOffSessionsNeedingMakeup(modal.offTeacherId || "");
  const weekday = (date) => { const day = localDate(date).getDay(); return day === 0 ? "CN" : `T${day + 1}`; };
  // Nhóm theo giáo viên đã nghỉ, trong nhóm cũ nhất lên trước.
  const groups = new Map();
  for (const item of offs) { const key = item.teacherId || ""; if (!groups.has(key)) groups.set(key, []); groups.get(key).push(item); }
  const offOptions = [...groups.entries()].sort(([a], [b]) => (findBy(state.data.teachers, a)?.fullName || "").localeCompare(findBy(state.data.teachers, b)?.fullName || "", "vi")).map(([teacherId, rows]) => {
    const teacher = findBy(state.data.teachers, teacherId);
    return `<div class="makeup-group"><p class="makeup-group-title">${escapeHtml(teacher?.fullName || "Chưa phân công")} <span>${rows.length} buổi</span></p>${rows.map((item) => {
      const cls = findBy(state.data.classes, item.classId);
      return `<label class="makeup-option"><input type="radio" name="makeup-off" value="${escapeHtml(item.id)}" ${modal.offSessionId === item.id ? "checked" : ""}><span class="makeup-option-body"><strong>${escapeHtml(cls?.name || "Lớp học")}</strong><small>${weekday(item.date)} ${formatDateVi(item.date)} · ${escapeHtml(item.startTime)}–${escapeHtml(item.endTime)}</small></span></label>`;
    }).join("")}</div>`;
  }).join("");
  const off = (state.data.lessonSessions || []).find((item) => item.id === modal.offSessionId);
  const conflictTeacher = modal.teacherId || off?.teacherId || "";
  const conflicts = teacherScheduleConflicts(conflictTeacher, modal.date, modal.startTime, modal.endTime);
  const offTeacherIds = [...new Set(teacherOffSessionsNeedingMakeup("").map((item) => item.teacherId).filter(Boolean))];
  const offFilter = `<select class="input makeup-off-filter" id="makeup-off-filter" aria-label="Lọc theo giáo viên nghỉ"><option value="">GV nghỉ: tất cả</option>${offTeacherIds.map((id) => findBy(state.data.teachers, id)).filter(Boolean).sort((a, b) => a.fullName.localeCompare(b.fullName, "vi")).map((item) => `<option value="${escapeHtml(item.id)}" ${modal.offTeacherId === item.id ? "selected" : ""}>GV nghỉ: ${escapeHtml(item.fullName)}</option>`).join("")}</select>`;
  const extra = `<div class="makeup-options"><div class="makeup-options-head"><p class="makeup-options-title">Buổi nghỉ cần dạy bù${modal.offTeacherId ? "" : " · toàn trung tâm"} (${offs.length})</p>${offFilter}</div>${offOptions || '<p class="makeup-options-empty">Không còn buổi nghỉ nào chờ dạy bù.</p>'}</div>`;
  return calendarAddShell({ kind: "MAKEUP", close: "close-makeup-modal", card: "data-makeup-modal-card", formId: "calendar-makeup-form", modal,
    teacherLabel: "Giáo viên dạy bù", teacherEmpty: "GV của buổi nghỉ", teacherSelectId: "makeup-teacher",
    extra, conflicts: calendarConflictHtml(conflicts, conflictTeacher), submit: "Xếp lịch dạy bù" });
}

function calendarAddTabs(active, editing = false) {
  return `<div class="calendar-add-kinds" role="tablist" aria-label="Loại lịch">${CALENDAR_ADD_KINDS.map(([kind, label], index) => `<button type="button" role="tab" class="calendar-add-kind kind-${kind.toLowerCase()}${kind === active ? " active" : ""}" data-calendar-add-kind="${kind}" aria-selected="${kind === active}"${editing && kind === "MAKEUP" ? " disabled" : ""}><span>${index + 1}</span>${escapeHtml(label)}</button>`).join("")}</div>`;
}

const CALENDAR_ADD_HINTS = {
  MAKEUP: "Chọn buổi giáo viên đã báo nghỉ — buổi bù chiếm đúng vị trí khóa của buổi nghỉ nên khóa không giãn thêm. Chấm công cột Dạy bù.",
  TEST_SPEAKING: "Lịch test speaking ngoài lịch lớp. Chấm công cột Bổ trợ.",
  KEM_SPEAKING: "Lịch kèm speaking ngoài lịch lớp. Chấm công cột Bổ trợ.",
  KEM_CA_NHAN: "Lịch kèm hỗ trợ cá nhân ngoài lịch lớp. Chấm công cột Bổ trợ.",
  KEM_LOP: "Lịch kèm hỗ trợ lớp ngoài lịch lớp. Chấm công cột Bổ trợ.",
  DAY_THAY: "Buổi dạy thay không có trên lịch lớp (ghi chú: lớp + giáo viên được dạy thay, vd \"T12 (cô Lê Huyền)\"). Chấm công cột Dạy thay, không tạo buổi học.",
};

/** Khung chung của popup Thêm lịch: kích thước cố định, cùng bố cục cho cả 5 tab
 * (giáo viên → ngày, giờ → phần riêng của tab → cảnh báo trùng) nên chuyển tab không nhảy. */
function calendarAddShell({ kind, editing = false, close, card, formId, modal, teacherLabel, teacherEmpty, teacherSelectId = "", teacherRequired = false, extra, conflicts, submit, danger = "" }) {
  const teachers = [...(state.data.teachers || [])].sort((a, b) => String(a.fullName || "").localeCompare(String(b.fullName || ""), "vi"));
  return `<div class="modal-backdrop" data-action="${close}"><div class="modal-card calendar-add-modal" ${card}><div class="modal-head"><div><h2>${editing ? "Sửa lịch" : "Thêm lịch"}</h2><p>Chọn loại lịch, giáo viên, ngày giờ. Hệ thống cảnh báo khi giáo viên bị trùng lịch.</p></div><button class="close-btn" type="button" data-action="${close}">×</button></div>${calendarAddTabs(kind, editing)}<p class="calendar-add-hint">${escapeHtml(CALENDAR_ADD_HINTS[kind] || "")}</p><form id="${formId}" class="calendar-add-form" data-calendar-add-form><div class="calendar-add-body"><div class="calendar-add-fields"><label class="field calendar-add-teacher"><span>${teacherLabel}</span><select class="input" name="teacher"${teacherSelectId ? ` id="${teacherSelectId}"` : ""}${teacherRequired ? " required" : ""}><option value="">${teacherEmpty}</option>${teachers.map((item) => `<option value="${escapeHtml(item.id)}" ${modal.teacherId === item.id ? "selected" : ""}>${escapeHtml(item.fullName)}${item.code ? ` (${escapeHtml(item.code)})` : ""}</option>`).join("")}</select></label><label class="field"><span>Ngày</span><input class="input" type="date" name="date" value="${escapeHtml(modal.date || "")}" required></label><label class="field"><span>Giờ bắt đầu</span><input class="input" type="time" name="startTime" value="${escapeHtml(modal.startTime || "")}" required></label><label class="field"><span>Giờ kết thúc</span><input class="input" type="time" name="endTime" value="${escapeHtml(modal.endTime || "")}" required></label></div><div data-calendar-conflict-box>${conflicts}</div>${extra}</div><div class="settings-modal-footer">${danger}<button class="secondary-btn" type="button" data-action="${close}">Hủy</button><button class="primary-btn" type="submit">${submit}</button></div></form></div></div>`;
}

/** Modal lịch thêm (Test speaking, Kèm speaking, Kèm hỗ trợ cá nhân / lớp):
 * chọn GV, ngày, giờ, ghi chú. Không phụ thuộc lịch lớp; cảnh báo trùng lịch GV. */
function calendarEventModalHtml() {
  const modal = state.calendarEvent;
  if (!modal) return "";
  const canEdit = state.role === "ADMIN";
  const label = CALENDAR_EVENT_LABELS[modal.kind] || "Lịch thêm";
  const conflicts = teacherScheduleConflicts(modal.teacherId, modal.date, modal.startTime, modal.endTime, { excludeEventId: modal.id || "" });
  if (!canEdit) {
    const teacher = findBy(state.data.teachers, modal.teacherId);
    return `<div class="modal-backdrop" data-action="close-event-modal"><div class="modal-card" data-event-modal-card><div class="modal-head"><div><h2>${escapeHtml(label)}</h2><p>Lịch thêm ngoài lịch lớp.</p></div><button class="close-btn" type="button" data-action="close-event-modal">×</button></div><div class="form-grid"><label class="field"><dt>Giáo viên</dt><dd>${escapeHtml(teacher?.fullName || "—")}</dd></label><label class="field"><dt>Ngày</dt><dd>${formatDateVi(modal.date)}</dd></label><label class="field"><dt>Giờ</dt><dd>${escapeHtml(modal.startTime)}–${escapeHtml(modal.endTime)}</dd></label><label class="field span-2"><dt>Ghi chú công việc</dt><dd>${escapeHtml(modal.note || "Không có ghi chú")}</dd></label></div>${calendarConflictHtml(conflicts, modal.teacherId)}<div class="settings-modal-footer"><button class="secondary-btn" type="button" data-action="close-event-modal">Đóng</button></div></div></div>`;
  }
  const extra = `<label class="field calendar-add-note"><span>Ghi chú công việc</span><textarea class="input" name="note" rows="4" placeholder="VD: Test speaking đầu vào bé An, kèm 3 bạn lớp S26 phần đọc...">${escapeHtml(modal.note || "")}</textarea></label>`;
  return calendarAddShell({ kind: modal.kind, editing: Boolean(modal.id), close: "close-event-modal", card: "data-event-modal-card", formId: "calendar-event-form", modal,
    teacherLabel: "Giáo viên", teacherEmpty: "— Chọn giáo viên —", teacherRequired: true,
    extra, conflicts: calendarConflictHtml(conflicts, modal.teacherId), submit: modal.id ? "Lưu thay đổi" : "Lưu",
    danger: modal.id ? `<button class="danger-btn" type="button" data-calendar-event-delete>Xóa lịch</button>` : "" });
}

const auditActionLabels = { CREATE: "Tạo mới", UPDATE: "Sửa", DELETE: "Xoá", LOGIN: "Đăng nhập" };
const auditEntityLabels = { User: "Tài khoản", Student: "Học viên", Teacher: "Giáo viên", Class: "Lớp học", LessonSession: "Buổi học", PeriodicReport: "Báo cáo định kỳ", FinanceForecast: "Dự thu - Dự chi", Settings: "Cấu hình", Finance: "Tài chính", CashEntry: "Thu chi", Invoice: "Hoá đơn", Reconciliation: "Đối soát", CalendarEvent: "Lịch thêm", PayrollConfig: "Hồ sơ lương" };
const AUDIT_CATEGORIES = [
  ["TUITION", "Học phí"],
  ["PROFILE", "Thông tin"],
  ["ATTENDANCE", "Điểm danh"],
  ["STATEMENT", "Sao kê"],
  ["RECON", "Đối soát"],
  ["OTHER", "Nghiệp vụ khác"],
];
const auditRoleLabels = { ADMIN: "Quản trị", TEACHER: "Giáo viên", ACCOUNTANT: "Kế toán", ASSISTANT: "Trợ giảng", STUDENT: "Học viên" };

/** Xếp dòng nhật ký vào nghiệp vụ — cùng luật với auditCategoryOf (cloudflare/audit-diff.ts). Dòng cũ chưa có category thì suy ra. */
function auditCategoryOf(row) {
  const known = AUDIT_CATEGORIES.map(([key]) => key);
  if (row.category && known.includes(row.category)) return row.category;
  const entity = String(row.entity || "");
  const summary = String(row.summary || "");
  if (row.action === "LOGIN") return "OTHER";
  if (entity === "Reconciliation" || /^(Đối soát|Gỡ đối soát|Duyệt khớp|Hoàn tác duyệt)/i.test(summary)) return "RECON";
  if (/sao kê|giao dịch lệch|thu vô danh/i.test(summary)) return "STATEMENT";
  if (entity === "LessonSession") return "ATTENDANCE";
  if (entity === "Invoice" || /học phí|thanh toán|biên lai|phiếu báo|hoá đơn|hóa đơn|webhook sepay|truy thu|thu trước/i.test(summary)) return "TUITION";
  if (entity === "Finance") return "TUITION";
  if (["Student", "Teacher", "Class", "User"].includes(entity)) return "PROFILE";
  return "OTHER";
}

function auditDetailsHtml(row) {
  const details = Array.isArray(row.details) ? row.details : [];
  if (!details.length) return "";
  const line = (item) => {
    const from = String(item.from || "");
    const to = String(item.to || "");
    const body = from && to
      ? `<span class="audit-from">${escapeHtml(from)}</span><span class="audit-arrow">→</span><span class="audit-to">${escapeHtml(to)}</span>`
      : to ? `<span class="audit-to">${escapeHtml(to)}</span>` : `<span class="audit-from">${escapeHtml(from)}</span>`;
    return `<li><span class="audit-field">${escapeHtml(item.label || "")}:</span> ${body}</li>`;
  };
  const shown = details.slice(0, 8).map(line).join("");
  const more = details.length > 8 ? `<details class="audit-more"><summary>Xem thêm ${details.length - 8} thay đổi</summary><ul>${details.slice(8).map(line).join("")}</ul></details>` : "";
  return `<ul class="audit-details">${shown}</ul>${more}`;
}

function auditPage() {
  const all = state.data.auditLogs || [];
  const query = String(state.auditSearch || "").trim().toLowerCase();
  const base = all.filter((row) => (!state.auditAction || row.action === state.auditAction)
    && (!state.auditUser || row.userName === state.auditUser)
    && (!state.auditFrom || row.createdAt.slice(0, 10) >= state.auditFrom)
    && (!state.auditTo || row.createdAt.slice(0, 10) <= state.auditTo)
    && (!query || [row.summary, row.userName, row.entityId, ...(row.details || []).flatMap((item) => [item.label, item.from, item.to])].some((text) => String(text || "").toLowerCase().includes(query))));
  const counts = {};
  for (const row of base) { const key = auditCategoryOf(row); counts[key] = (counts[key] || 0) + 1; }
  const tab = state.auditCategory || "";
  const items = tab ? base.filter((row) => auditCategoryOf(row) === tab) : base;
  const users = [...new Set(all.map((row) => row.userName).filter(Boolean))].sort((a, b) => a.localeCompare(b, "vi"));
  const catLabel = Object.fromEntries(AUDIT_CATEGORIES);
  const tabs = [["", "Tất cả", base.length], ...AUDIT_CATEGORIES.map(([key, label]) => [key, label, counts[key] || 0])]
    .map(([key, label, count]) => `<button type="button" class="audit-tab ${tab === key ? "active" : ""}" data-audit-tab="${key}">${label}<span>${count}</span></button>`).join("");
  const fmt = new Intl.DateTimeFormat("vi-VN", { dateStyle: "short", timeStyle: "short" });
  const rows = items.slice(0, 500).map((row, index) => {
    const category = auditCategoryOf(row);
    return `<tr><td class="cell-index">${index + 1}</td><td class="audit-time">${fmt.format(new Date(row.createdAt))}</td><td><strong>${escapeHtml(row.userName)}</strong><small class="people-subline">${escapeHtml(auditRoleLabels[row.role] || row.role || "")}${row.userEmail ? ` · ${escapeHtml(row.userEmail)}` : ""}</small></td><td><span class="badge audit-${String(row.action).toLowerCase()}">${auditActionLabels[row.action] || row.action}</span>${tab ? "" : `<small class="people-subline audit-cat audit-cat-${category.toLowerCase()}">${escapeHtml(catLabel[category] || "")}</small>`}</td><td class="audit-content"><div class="audit-summary">${escapeHtml(row.summary || "—")}</div><small class="people-subline">${escapeHtml(auditEntityLabels[row.entity] || row.entity || "")}</small>${auditDetailsHtml(row)}</td></tr>`;
  }).join("");
  const more = items.length > 500 ? `<p class="muted audit-limit">Đang hiện 500 dòng mới nhất trong ${items.length} dòng — lọc theo ngày / người / từ khoá để xem dòng cũ hơn.</p>` : "";
  return `<div class="audit-page"><div class="page-header"><div><h1>Nhật ký hệ thống</h1><p>Ai làm gì, lúc nào; sửa thì ghi rõ từ … thành …</p></div></div><section class="card settings-card"><div class="card-header people-card-header"><div class="card-heading"><div><h2>Nhật ký (${items.length})</h2><p>Ai làm gì, lúc nào. Sửa thông tin ghi rõ <strong>từ … → thành …</strong>. Mật khẩu không bao giờ được ghi.</p></div></div><div class="audit-tabs">${tabs}</div><form id="audit-filter-form" class="audit-filters"><label class="field"><span>Tìm</span><input class="input" type="search" name="q" value="${escapeHtml(state.auditSearch || "")}" placeholder="Tên học viên, lớp, nội dung…" /></label><label class="field"><span>Người thực hiện</span><select class="input" name="user"><option value="">Tất cả</option>${users.map((name) => `<option value="${escapeHtml(name)}" ${state.auditUser === name ? "selected" : ""}>${escapeHtml(name)}</option>`).join("")}</select></label><label class="field"><span>Hành động</span><select class="input" name="action"><option value="">Tất cả</option>${Object.entries(auditActionLabels).map(([value, label]) => `<option value="${value}" ${state.auditAction === value ? "selected" : ""}>${label}</option>`).join("")}</select></label><label class="field"><span>Từ ngày</span><input class="input" type="date" name="from" value="${state.auditFrom}" /></label><label class="field"><span>Đến ngày</span><input class="input" type="date" name="to" value="${state.auditTo}" /></label></form></div><div class="table-wrap people-table"><table class="audit-table"><thead><tr><th>STT</th><th>Thời điểm</th><th>Người thực hiện</th><th>Hành động</th><th>Nội dung thay đổi</th></tr></thead><tbody>${rows || '<tr><td class="empty-cell" colspan="5">Không có bản ghi nào khớp bộ lọc.</td></tr>'}</tbody></table></div>${more}</section></div>`;
}

function financeBook() {
  return state.data.finance || { debts: [], cashbook: [], recon: [], reconEntries: [], payroll: [], forecasts: [] };
}

function vnd(value) {
  return new Intl.NumberFormat("vi-VN", { style: "currency", currency: "VND", maximumFractionDigits: 0 }).format(Number(value) || 0);
}

/** Diễn giải kết quả `enqueueZaloMessage` thành một câu ngắn về tình trạng gửi tin Zalo. */
function zaloMessageNote(zaloMessage) {
  if (!zaloMessage) return "";
  const reason = zaloMessage.errorMessage || zaloMessage.errorCode || "lỗi không rõ";
  if (zaloMessage.queued) return zaloMessage.status === "FAILED" ? `Zalo lỗi: ${reason}` : "Tin Zalo đang được gửi.";
  if (zaloMessage.reason === "DUPLICATE") {
    if (zaloMessage.existingStatus === "FAILED") return `Tin Zalo trước đó bị lỗi (${reason}) — vào trang Tin Zalo bấm "Gửi lại".`;
    if (zaloMessage.existingStatus === "SENT" || zaloMessage.existingStatus === "DELIVERED") return "Tin Zalo đã gửi trước đó.";
    return "Tin Zalo đang chờ gửi.";
  }
  if (zaloMessage.reason === "NO_TEMPLATE") return "Chưa cấu hình mẫu tin Zalo nên chưa gửi.";
  if (zaloMessage.reason === "CONFLICT") return "Hệ thống bận, chưa xếp được tin Zalo — bấm lại.";
  return "";
}

const COURSE_SESSIONS = 24;

function classBillingMode(row) {
  return row?.billingMode === "MONTHLY" ? "MONTHLY" : "COURSE";
}

function courseSessionOptions(row) {
  const packages = state.data?.settings?.tuitionPackages || [];
  const sessions = new Set([COURSE_SESSIONS]);
  for (const item of packages) {
    const value = Math.round(Number(item.sessions) || 0);
    if (value > 0) sessions.add(value);
  }
  const current = classCourseSessions(row);
  if (current > 0) sessions.add(current);
  return [...sessions].sort((a, b) => a - b);
}

function billingChoiceValue(row) {
  return classBillingMode(row) === "MONTHLY" ? "MONTHLY" : `COURSE:${classCourseSessions(row)}`;
}

function billingChoiceLabel(row) {
  return classBillingMode(row) === "MONTHLY" ? "Thu tháng" : `Thu khóa ${classCourseSessions(row)} buổi`;
}

function billingChoiceOptions(row) {
  const selected = billingChoiceValue(row);
  return [
    ["MONTHLY", "Thu tháng"],
    ...courseSessionOptions(row).map((sessions) => [`COURSE:${sessions}`, `Thu khóa ${sessions} buổi`]),
  ].map(([value, label]) => `<option value="${escapeHtml(value)}" ${value === selected ? "selected" : ""}>${label}</option>`).join("");
}

function parseBillingChoice(raw, fallbackSessions = COURSE_SESSIONS) {
  const value = String(raw || "");
  if (value === "MONTHLY") return { billingMode: "MONTHLY", courseSessions: Math.max(1, Math.round(Number(fallbackSessions) || COURSE_SESSIONS)) };
  const match = /^COURSE:(\d+)$/.exec(value);
  if (match) return { billingMode: "COURSE", courseSessions: Math.max(1, Number(match[1])) };
  if (value === "COURSE") return { billingMode: "COURSE", courseSessions: Math.max(1, Math.round(Number(fallbackSessions) || COURSE_SESSIONS)) };
  return { billingMode: "COURSE", courseSessions: Math.max(1, Math.round(Number(fallbackSessions) || COURSE_SESSIONS)) };
}

function classSessionPrice(row) {
  return Math.max(0, Math.round(Number(row?.sessionPrice) || 0));
}

function classCourseSessions(row) {
  const value = Math.round(Number(row?.courseSessions) || 0);
  return value > 0 ? value : COURSE_SESSIONS;
}

/** Mirror FIRST_COURSE_SESSIONS_OVERRIDES của tuition-billing.ts: lớp đã chốt
 * khóa 1 theo số buổi cũ, các khóa sau chạy theo courseSessions mới. */
const FIRST_COURSE_SESSIONS_OVERRIDES = {
  "class-import-s19": 20,
};

function classCourseSizeAt(cls, index) {
  const override = Math.round(Number(FIRST_COURSE_SESSIONS_OVERRIDES[String(cls?.id || "")]) || 0);
  return Math.max(1, Math.round(Number(index) || 1)) === 1 && override > 0
    ? override
    : classCourseSessions(cls);
}

/** Mirror COURSE_WINDOW_SLOT_OVERRIDES của tuition-billing.ts: khóa chốt cứng lịch
 * chiếm số suất tính phí khác số buổi khóa; học phí vẫn theo classCourseSizeAt. */
const COURSE_WINDOW_SLOT_OVERRIDES = {
  "class-import-s42": { 1: 22 },
};

function classCourseWindowSlotsAt(cls, index) {
  const override = Math.round(Number(COURSE_WINDOW_SLOT_OVERRIDES[String(cls?.id || "")]?.[Math.max(1, Math.round(Number(index) || 1))]) || 0);
  return override > 0 ? override : classCourseSizeAt(cls, index);
}

function hasCourseWindowOverride(cls, index) {
  return Boolean(COURSE_WINDOW_SLOT_OVERRIDES[String(cls?.id || "")]?.[Math.max(1, Math.round(Number(index) || 1))]);
}

function courseSlotOffsetBefore(cls, index) {
  let total = 0;
  for (let i = 1; i < index; i += 1) total += classCourseWindowSlotsAt(cls, i);
  return total;
}

function courseIndexAtSlotOrdinal(cls, ordinal) {
  let index = 1;
  let rest = Math.max(0, Math.floor(Number(ordinal) || 0));
  for (let guard = 0; guard < 500; guard += 1) {
    const size = classCourseWindowSlotsAt(cls, index);
    if (rest < size) return index;
    rest -= size;
    index += 1;
  }
  return index;
}

function monthKey(date = new Date()) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`;
}

function monthLabel(key = monthKey()) {
  const [year, month] = key.split("-");
  return `Tháng ${month}/${year}`;
}

function billedMonthSessions(cls, sessions, key = monthKey(), minDate) {
  const compute = () => billedMonthSessionsInner(cls, sessions, key, minDate);
  return perfDefaultSessions(sessions) ? perfMemo("bms", `${cls?.id}|${key}|${minDate ?? ""}`, compute) : compute();
}

function billedMonthSessionsInner(cls, sessions, key = monthKey(), minDate) {
  const [year, month] = key.split("-").map(Number);
  const start = new Date(year, month - 1, 1, 12);
  const end = new Date(year, month, 0, 12);
  const explicit = perfDefaultSessions(sessions) ? perfClassSessions(cls.id) : (sessions || []).filter((item) => item.classId === cls.id);
  const storedByDate = perfDefaultSessions(sessions) ? perfStoredByClaimDate(cls.id) : storedSessionsByClaimDate(explicit, cls.id);
  const claimedIds = new Set();
  let count = 0;
  for (let cursor = new Date(start); cursor <= end; cursor.setDate(cursor.getDate() + 1)) {
    const date = localDateKey(cursor);
    if (minDate && date < minDate) continue;
    const daySlots = (cls.schedules || []).filter((slot) => scheduleSlotAppliesOnDate(slot, date));
    if (!daySlots.length) continue;
    const { claimed } = claimDaySlots(daySlots, storedByDate.get(date) || []);
    for (const stored of claimed) {
      if (stored) claimedIds.add(sessionIdentity(stored));
      if (isPlannedTuitionOff(stored) || isNoFeeSession(stored) || stored?.status === "CANCELLED") continue;
      count += 1;
    }
  }
  // Bản ghi thật trong tháng không chiếm được suất lịch nào (học thêm, ngày ngoài
  // lịch hiện tại, lịch đã đổi sau khi có bản ghi) vẫn phải tính vào phiếu thu.
  for (const item of explicit) {
    if (!item.date.startsWith(key) || claimedIds.has(sessionIdentity(item))) continue;
    if (minDate && item.date < minDate) continue;
    // Buổi dạy bù thay cho buổi nghỉ đã tính phí (suất nghỉ vẫn nằm trong phiếu)
    // — không thu thêm lần nữa.
    if (item.makeupOf) continue;
    if (!isPlannedTuitionOff(item) && !isNoFeeSession(item) && item.status !== "CANCELLED") count += 1;
  }
  return count;
}

/**
 * Buổi GV nghỉ chỉ sinh khấu trừ khi thuộc tháng 10/2026 trở đi — các buổi
 * nghỉ trước đó kế toán đã tự trừ và thu tay, phiếu tháng 10 không khấu trừ.
 */
const TUITION_OFF_CREDIT_START_MONTH = "2026-10";
// Từ kỳ này không trừ thêm tín dụng buổi nghỉ lưu trên hồ sơ (tránh trừ lần 2) — khớp tuition-billing.ts.
const TUITION_STORED_CREDIT_END_MONTH = "2026-12";
// Phiếu T11/2026 chốt theo bảng 08/11: buổi GV nghỉ tháng 11 trừ ở phiếu T12 — trừ 2 buổi đã trừ ngay trên T11 (khớp tuition-billing.ts).
const NOV_2026_DEDUCTED_OFF_KEYS = new Set(["class-import-t8|2026-11-04"]);
function november2026DeferredOffSessions(cls, sessions) {
  return (sessions || []).filter((item) => (
    item.classId === cls.id
    && item.isOff
    && item.offSource === "TEACHER"
    && item.status !== "CANCELLED"
    && String(sessionClaimDate(item) || "").startsWith("2026-11")
    && !NOV_2026_DEDUCTED_OFF_KEYS.has(`${cls.id}|${sessionClaimDate(item)}`)
    && !makeupSessionFor(item, sessions || [])
  )).length;
}
const T2_CLASS_ID = "class-import-t2";
const T2_OCTOBER_BILLING_MONTH = "2026-10";
const T2_PREVIOUS_MONTH_DEBT = 400000;
const T2_PREVIOUS_MONTH_DEBT_NAMES = ["kieu oanh", "phuong linh", "quynh trang", "gia huy", "thao nguyen", "van nhi"];
const T2_PREVIOUS_MONTH_DEBT_CODES = new Set(["HV0567", "HV0569"]);
const T2_THUY_STUDENT_CODE = "HV0942";

function normalizedTuitionName(value) {
  return String(value || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[Đđ]/g, "d").replace(/[^a-zA-Z0-9]+/g, " ").trim().toLowerCase();
}

function t2PreviousMonthDebtAmount(student, cls, billingMonths) {
  if (cls?.id !== T2_CLASS_ID || !billingMonths.includes(T2_OCTOBER_BILLING_MONTH)) return 0;
  const code = String(student?.code || "").trim().toUpperCase();
  const name = normalizedTuitionName(student?.fullName);
  return (T2_PREVIOUS_MONTH_DEBT_CODES.has(code)
    || T2_PREVIOUS_MONTH_DEBT_NAMES.some((suffix) => name === suffix || name.endsWith(` ${suffix}`))) ? T2_PREVIOUS_MONTH_DEBT : 0;
}

function t2OctoberMinimumCreditSessions(_student, cls, billingMonth) {
  return cls?.id === T2_CLASS_ID && billingMonth === T2_OCTOBER_BILLING_MONTH ? 2 : 0;
}

function t2EffectivePaidThrough(student, cls, paidThrough) {
  if (cls?.id !== T2_CLASS_ID) return paidThrough;
  const code = String(student?.code || "").trim().toUpperCase();
  const isThuy = code === T2_THUY_STUDENT_CODE || normalizedTuitionName(student?.fullName) === "thuy";
  return isThuy && String(paidThrough || "") < "2026-09" ? "2026-09" : paidThrough;
}

