const T8_PREVIOUS_MONTH_DEBTS = [
  { codes: new Set(["HV0657"]), names: ["huyen trang"], amount: 350_000 },
  { codes: new Set(["HV0667"]), names: [], amount: 350_000 },
];

function previousMonthDebtAmountFor(debts, student) {
  const code = String(student?.code || "").trim().toUpperCase();
  const name = normalizedTuitionName(student?.fullName);
  perfValid();
  let store = perf.weak.get(debts);
  if (!store) perf.weak.set(debts, store = new Map());
  const key = `${code}|${name}`;
  if (store.has(key)) return store.get(key);
  let amount = 0;
  for (const debt of debts) {
    if (debt.codes.has(code) || debt.names.some((suffix) => name === suffix || name.endsWith(` ${suffix}`))) { amount = debt.amount; break; }
  }
  store.set(key, amount);
  return amount;
}

function t7PreviousMonthDebtAmount(student, cls, billingMonths) {
  if (cls?.id !== T7_CLASS_ID || !billingMonths.includes("2026-10")) return 0;
  return previousMonthDebtAmountFor(T7_PREVIOUS_MONTH_DEBTS, student);
}

