function reconLockWhen(lock) {
  const at = lock?.lockedAt ? new Date(lock.lockedAt) : null;
  return at && !Number.isNaN(at.getTime()) ? `${String(at.getHours()).padStart(2, "0")}:${String(at.getMinutes()).padStart(2, "0")} ${at.toLocaleDateString("vi-VN")}` : "";
}

function reconLockCell(date) {
  const report = reconReportButton(date);
  const lock = reconLockFor(date);
  if (!lock) {
    return state.role === "ADMIN"
      ? `<div class="recon-action-group"><button class="primary-btn recon-lock-btn" type="button" data-recon-lock="${escapeHtml(date)}">${icon("check")}Đối soát xong</button>${report}</div>`
      : '<span class="muted">Chưa đối soát</span>';
  }
  const unlock = isSuperAdmin() ? `<button class="secondary-btn recon-lock-btn" type="button" data-recon-unlock="${escapeHtml(date)}">${icon("lock")}Gỡ đối soát</button>` : "";
  return unlock || report ? `<div class="recon-action-group">${unlock}${report}</div>` : '<span class="badge badge-green">Đã đối soát</span>';
}

function reconPage() {
  const days = reconDailyRows();
  const totals = days.reduce((sum, day) => ({ inCount: sum.inCount + day.inCount, inCash: sum.inCash + day.inCash, inTransfer: sum.inTransfer + day.inTransfer, outCount: sum.outCount + day.outCount, outCash: sum.outCash + day.outCash, outTransfer: sum.outTransfer + day.outTransfer }), { inCount: 0, inCash: 0, inTransfer: 0, outCount: 0, outCash: 0, outTransfer: 0 });
  const outCell = (value) => `<td class="cash-amount-cell ${value ? "text-red" : ""}">${value ? `−${vnd(value)}` : vnd(0)}</td>`;
  const rows = days.map((day, index) => {
    const lock = reconLockFor(day.date);
    const who = lock ? `<span class="recon-lock-who">${icon("lock")}${escapeHtml(lock.lockedByName || lock.lockedBy || "—")}</span>` : '<span class="muted">—</span>';
    const when = lock ? escapeHtml(reconLockWhen(lock) || "—") : '<span class="muted">—</span>';
    return `<tr class="${lock ? "recon-locked-row" : ""}"><td class="cell-index">${index + 1}</td><td class="recon-date-cell">${financeDate(day.date)} <span class="muted">· ${day.inCount} thu · ${day.outCount} chi</span></td><td class="cash-amount-cell">${vnd(day.inCash)}</td><td class="cash-amount-cell">${vnd(day.inTransfer)}</td>${outCell(day.outCash)}${outCell(day.outTransfer)}<td class="recon-who-cell">${who}</td><td class="recon-when-cell">${when}</td><td class="recon-action-cell">${reconLockCell(day.date)}</td></tr>`;
  }).join("");
  const totalsRow = days.length
    ? `<tfoot><tr class="tuition-total-row"><td></td><td><strong>Tổng cộng</strong></td><td class="cash-amount-cell"><strong class="tuition-total-amount">${vnd(totals.inCash)}</strong></td><td class="cash-amount-cell"><strong class="tuition-total-amount">${vnd(totals.inTransfer)}</strong></td><td class="cash-amount-cell"><strong class="tuition-total-amount ${totals.outCash ? "text-red" : ""}">${totals.outCash ? "−" : ""}${vnd(totals.outCash)}</strong></td><td class="cash-amount-cell"><strong class="tuition-total-amount ${totals.outTransfer ? "text-red" : ""}">${totals.outTransfer ? "−" : ""}${vnd(totals.outTransfer)}</strong></td><td></td><td></td><td></td></tr></tfoot>`
    : "";
  return `<div class="people-page cashbook-page"><div class="page-header"><div><h1>Đối soát thu chi</h1><p>Tổng thu, tổng chi theo tiền mặt / chuyển khoản từng ngày. Bấm "Đối soát xong" để khoá ngày đó — không thêm, sửa, xoá thu chi, học phí của ngày đã đối soát.</p></div></div>${financeTodayLockBanner()}<section class="card settings-card cashbook-ledger-card"><div class="cashbook-filter-bar"><form id="recon-filter-form" class="filter-grid cashbook-filters"><label class="field cashbook-filter-date"><span>Từ ngày</span><input class="input" type="date" name="from" value="${state.reconFrom}" /></label><label class="field cashbook-filter-date"><span>Đến ngày</span><input class="input" type="date" name="to" value="${state.reconTo}" /></label></form></div><div class="table-wrap people-table"><table class="cashbook-table recon-table"><colgroup><col class="cash-col-index" /><col class="recon-col-date" /><col class="cash-col-amount" /><col class="cash-col-amount" /><col class="cash-col-amount" /><col class="cash-col-amount" /><col class="recon-col-who" /><col class="recon-col-when" /><col class="recon-col-action" /></colgroup><thead><tr><th rowspan="2">STT</th><th rowspan="2">Ngày</th><th colspan="2" class="recon-group-head">Tổng thu</th><th colspan="2" class="recon-group-head">Tổng chi</th><th rowspan="2">Người đối soát</th><th rowspan="2">Thời gian</th><th rowspan="2">Thao tác</th></tr><tr><th class="recon-sub-head">Tiền mặt</th><th class="recon-sub-head">Chuyển khoản</th><th class="recon-sub-head">Tiền mặt</th><th class="recon-sub-head">Chuyển khoản</th></tr></thead><tbody>${rows || '<tr><td class="empty-cell" colspan="9">Chưa có nghiệp vụ thu chi nào trong khoảng đã chọn.</td></tr>'}</tbody>${totalsRow}</table></div></section></div>`;
}

// --- Bảng lương theo hợp đồng (mẫu Excel của trung tâm) ---
// Chính sách lưu trong payroll-config.policy; đây là bộ mặc định khi chưa cấu hình.
const PAYROLL_POLICY_DEFAULTS = {
  effectiveFrom: "2026-10-01",
  standardDays: 26,
  personalDeduction: 15_500_000,
  dependentDeduction: 6_200_000,
  employeeInsuranceRate: 0.105,
  employerInsuranceRate: 0.215,
  foreignEmployeeInsuranceRate: 0.095,
  foreignEmployerInsuranceRate: 0.205,
  serviceTaxThreshold: 5_000_000,
  serviceTaxRate: 0.1,
  mealAllowance: 1_200_000,
  mealAllowancePerDay: 40_000,
  phoneAllowance: 300_000,
  fuelAllowance: 500_000,
  uniformAllowance: 400_000,
  standardHourlyRate: 0,
  attendanceDeadlineHours: 24,
  taxBrackets: [
    { upTo: 10_000_000, rate: 0.05 },
    { upTo: 30_000_000, rate: 0.1 },
    { upTo: 60_000_000, rate: 0.2 },
    { upTo: 100_000_000, rate: 0.3 },
    { upTo: null, rate: 0.35 },
  ],
};

/** Nhân sự không khấu trừ thuế TNCN trên bảng lương — KT0003 Trương Đức Nhật là chủ doanh nghiệp (fix cứng theo yêu cầu anh Vũ 02/11/2026). */
const PAYROLL_TAX_EXEMPT_CODES = new Set(["KT0003"]);

/** Một ngày công chuẩn = 8 giờ dạy — dùng quy ngày công của giáo viên lương tháng ra giờ. */
const PAYROLL_DAILY_HOURS = 8;

const PAYROLL_CONTRACT_KIND_LABELS = {
  TT: "HĐ toàn thời gian",
  BTG: "HĐ bán thời gian",
  NN: "HĐ người nước ngoài",
  CSH: "HĐ cộng sự",
  DV: "HĐ dịch vụ",
};

/** Phòng ban mặc định khi hợp đồng chưa ghi — chỉ dùng để hiện trên bảng lương/phiếu lương. */
const PAYROLL_STAFF_DEFAULT_DEPARTMENTS = { TEACHER: "Giáo viên", ACCOUNTANT: "Kế toán", ASSISTANT: "Trợ giảng" };

function payrollPolicy() {
  const stored = payrollConfig().policy || {};
  const policy = { ...PAYROLL_POLICY_DEFAULTS, taxBrackets: PAYROLL_POLICY_DEFAULTS.taxBrackets.map((row) => ({ ...row })) };
  for (const key of Object.keys(PAYROLL_POLICY_DEFAULTS)) {
    if (key === "taxBrackets") {
      const rows = (Array.isArray(stored.taxBrackets) ? stored.taxBrackets : [])
        .filter((row) => row && Number.isFinite(Number(row.rate)))
        .map((row) => ({
          upTo: row.upTo === null || row.upTo === undefined ? null : Math.max(0, Math.round(Number(row.upTo) || 0)),
          rate: Math.max(0, Math.min(1, Number(row.rate) || 0)),
        }))
        .sort((a, b) => (a.upTo === null ? Infinity : a.upTo) - (b.upTo === null ? Infinity : b.upTo));
      if (rows.length) policy.taxBrackets = rows;
    } else if (key === "effectiveFrom") {
      if (typeof stored.effectiveFrom === "string" && stored.effectiveFrom) policy.effectiveFrom = stored.effectiveFrom;
    } else if (Number.isFinite(Number(stored[key]))) {
      policy[key] = Math.max(0, Number(stored[key]));
    }
  }
  return policy;
}

function payrollContractKind(contract) {
  if (PAYROLL_CONTRACT_KIND_LABELS[contract?.contractKind]) return contract.contractKind;
  // Dữ liệu cũ chỉ có LABOR/SERVICE: HĐLĐ giữ BH + thuế lũy tiến, dịch vụ khấu trừ.
  return contract?.contractType === "LABOR" ? "TT" : "DV";
}

function payrollPayMode(contract, fallback = "HOURLY") {
  return contract?.payMode === "MONTHLY" ? "MONTHLY" : contract?.payMode === "HOURLY" ? "HOURLY" : fallback;
}

/** Đơn giá giờ của một giáo viên = giờ công chuẩn của trung tâm × hệ số lương người đó. */
function payrollHourlyRate(contract, policy = payrollPolicy()) {
  return Math.round(Math.max(0, Number(policy.standardHourlyRate) || 0) * payrollSalaryCoefficient(contract));
}

/** BH NLD/NSDLĐ theo loại HĐ: TT/BTG đủ mức, NN mức người nước ngoài, CSH/DV không đóng. */
function payrollInsuranceRates(contract, policy = payrollPolicy()) {
  const kind = payrollContractKind(contract);
  if (kind === "NN") return { employee: policy.foreignEmployeeInsuranceRate, employer: policy.foreignEmployerInsuranceRate };
  if (kind === "CSH" || kind === "DV") return { employee: 0, employer: 0 };
  return { employee: policy.employeeInsuranceRate, employer: policy.employerInsuranceRate };
}

function payrollIsLabor(contract) {
  const kind = payrollContractKind(contract);
  return kind === "TT" || kind === "BTG" || kind === "NN";
}

/** Buổi không diễn ra: tick nghỉ học (GV hoặc học vụ) hoặc đã hủy — trừ khỏi chấm công thực tế. */
function isSessionMissed(session) {
  return Boolean(session?.isOff || session?.status === "CANCELLED");
}

/** Buổi đã diễn ra: giờ kết thúc đã qua so với thời điểm xem — chấm công thực
 * tế chỉ cộng giờ đã chạy, chạy realtime từ đầu tháng tới cuối tháng. */
function isSessionElapsed(session) {
  const end = new Date(`${session?.date || ""}T${session?.endTime || "23:59"}:00`);
  const time = end.getTime();
  return Number.isNaN(time) ? (session?.date || "") <= localDateKey(new Date()) : time <= Date.now();
}

function formatHours(minutes) {
  return (minutes / 60).toLocaleString("vi-VN", { maximumFractionDigits: 2 });
}

function sessionTeacherId(session) {
  const cls = findBy(state.data.classes, session.classId);
  return session.teacherId || cls?.teacherId || "";
}

function sessionMinutesOf(session) {
  const start = String(session.startTime || "00:00").split(":").map(Number);
  const end = String(session.endTime || "00:00").split(":").map(Number);
  return Math.max(0, (end[0] || 0) * 60 + (end[1] || 0) - ((start[0] || 0) * 60 + (start[1] || 0)));
}

function allTeachingSessions() {
  const seen = new Set();
  const rows = [];
  for (const cls of state.data.classes || []) {
    for (const session of classSessions(cls)) {
      if (seen.has(session.id)) continue;
      seen.add(session.id);
      rows.push(session);
    }
  }
  return rows;
}

/** Mặc định trọn tháng hiện tại — giờ dạy lý thuyết là cả tháng theo lịch, gồm hủy. */
function timesheetMonthKey() {
  const key = /^\d{4}-(0[1-9]|1[0-2])$/.test(String(state.timesheetMonth || "")) ? state.timesheetMonth : monthKey();
  return key < TIMESHEET_MONTH_START ? TIMESHEET_MONTH_START : key;
}

/** Danh sách tháng chấm công: từ 10/2026 (tháng bắt đầu chấm công trên hệ thống) tới hết 12/2027. */
const TIMESHEET_MONTH_START = "2026-10";
const TIMESHEET_MONTH_END = "2027-12";
function timesheetMonthKeys() {
  const keys = [];
  let cursor = TIMESHEET_MONTH_START;
  while (cursor <= TIMESHEET_MONTH_END && keys.length < 240) {
    keys.push(cursor);
    cursor = shiftMonthKey(cursor, 1);
  }
  const selected = timesheetMonthKey();
  if (!keys.includes(selected) && selected >= TIMESHEET_MONTH_START) keys.push(selected);
  return keys.sort();
}

function timesheetRange(key = timesheetMonthKey()) {
  const [year, month] = key.split("-").map(Number);
  return { from: `${key}-01`, to: localDateKey(new Date(year, month, 0, 12)) };
}

/**
 * Khoảng ngày đang xem trên Báo cáo chấm công: mặc định trọn tháng đang chọn; kế toán
 * chọn Từ ngày / Đến ngày thì lấy đúng khoảng đó (đảo lại nếu nhập ngược).
 */
function timesheetViewRange() {
  const month = timesheetRange();
  const valid = (value) => /^\d{4}-\d{2}-\d{2}$/.test(String(value || ""));
  const from = valid(state.timesheetFrom) ? state.timesheetFrom : month.from;
  const to = valid(state.timesheetTo) ? state.timesheetTo : month.to;
  return from <= to ? { from, to } : { from: to, to: from };
}

/** Khoảng đang xem có đúng trọn một tháng không (để ghi nhãn tháng thay vì từ ngày – đến ngày). */
function timesheetRangeIsMonth(range) {
  const month = timesheetRange(range.from.slice(0, 7));
  return month.from === range.from && month.to === range.to;
}

function timesheetSessions(teacherId = state.timesheetTeacher, range = timesheetRange()) {
  return allTeachingSessions()
    .filter((session) => session.date >= range.from && session.date <= range.to)
    // Buổi dạy thay hiện ở cả giáo viên chính (nghỉ không lương) và giáo viên dạy thay.
    .filter((session) => !teacherId || timesheetEntries(session).some((entry) => entry.teacherId === teacherId))
    .sort((a, b) => `${b.date}${b.startTime}`.localeCompare(`${a.date}${a.startTime}`));
}

/**
 * Phân loại một buổi cho chấm công:
 * - HOLIDAY: nghỉ lễ / nghỉ học vụ do admin tick, hoặc buổi đã hủy — không lương.
 * - TEACHER_OFF: giáo viên tick nghỉ — nằm trong lý thuyết, trừ ra (nghỉ không lương).
 * - MAKEUP: buổi dạy bù cho một buổi nghỉ — cộng cho giáo viên dạy bù.
 * - NO_FEE: buổi học không tính phí — học viên không trả tiền, giáo viên vẫn chấm công.
 * - REGULAR: buổi theo lịch (kể cả buổi học thêm) — lý thuyết.
 */
function timesheetSessionKind(session) {
  if (session.status === "CANCELLED" || (session.isOff && session.offSource !== "TEACHER")) return "HOLIDAY";
  if (session.isOff) return "TEACHER_OFF";
  if (session.makeupOf) return "MAKEUP";
  if (session.noFee) return "NO_FEE";
  return "REGULAR";
}

/**
 * Dạy thay: buổi theo lịch (không phải buổi bù) được đổi sang giáo viên khác
 * giáo viên chính của lớp. Khác dạy bù: dạy bù là buổi học lại cho một buổi nghỉ.
 */
/**
 * Giáo viên chính của lớp trong một tháng = người đứng phần lớn buổi theo lịch của
 * tháng đó (không tính buổi bù). Lớp đổi hẳn giáo viên (vd S14, S22 tháng 9 do
 * giáo viên trước dạy cả tháng) không bị coi là dạy thay; hòa thì lấy GV hiện tại.
 */
function classMonthMainTeacher(cls, month) {
  return perfMemo("ts-main", `${cls?.id}|${month}`, () => {
    const counts = new Map();
    for (const item of classSessions(cls)) {
      if (!String(item.date || "").startsWith(month) || item.makeupOf || item.isOff || item.status === "CANCELLED") continue;
      const id = String(item.teacherId || cls.teacherId || "");
      if (id) counts.set(id, (counts.get(id) || 0) + 1);
    }
    const current = String(cls?.teacherId || "");
    let best = current;
    for (const [id, count] of counts) if (count > (counts.get(best) || 0)) best = id;
    return best;
  });
}

const TIMESHEET_ASSIGNED_NOTE = /\[phụ trách\]/i;

function timesheetSubstitution(session) {
  const cls = findBy(state.data.classes, session.classId);
  const main = cls ? classMonthMainTeacher(cls, String(session.date || "").slice(0, 7)) : "";
  const sub = String(session.teacherId || "");
  if (!main || !sub || main === sub || session.makeupOf) return null;
  // Lớp đổi giáo viên phụ trách giữa tháng: buổi ghi chú "[Phụ trách]" là giáo viên đứng lớp theo phân công, không phải dạy thay.
  if (TIMESHEET_ASSIGNED_NOTE.test(String(session.note || ""))) return null;
  const kind = timesheetSessionKind(session);
  if (kind !== "REGULAR" && kind !== "NO_FEE") return null;
  return { main, sub };
}

const TIMESHEET_PAID_COLUMNS = new Set(["regular", "makeup", "substitute", "noFee", "support"]);

/** Lịch thêm (Test speaking, Kèm speaking, Kèm hỗ trợ cá nhân / lớp) xếp ở Lịch dạy
 * trong tháng — chấm công vào cột Bổ trợ cho giáo viên được xếp. */
function timesheetCalendarEvents(teacherId = state.timesheetTeacher, range = timesheetRange()) {
  return (state.data.calendarEvents || [])
    .filter((item) => item.date >= range.from && item.date <= range.to && (!teacherId || item.teacherId === teacherId))
    .sort((a, b) => `${b.date}${b.startTime}`.localeCompare(`${a.date}${a.startTime}`));
}

function timesheetEventEntry(item) {
  const label = CALENDAR_EVENT_LABELS[item.kind] || "Bổ trợ";
  return { teacherId: item.teacherId, column: item.kind === "DAY_THAY" ? "substitute" : "support", minutes: sessionMinutesOf(item), note: `${label} ${formatDateVi(item.date).slice(0, 5)} ${item.startTime}–${item.endTime}${item.note ? `: ${item.note}` : ""}` };
}

/**
 * Chấm công của một buổi, tách theo từng giáo viên liên quan. Mỗi phần:
 * { teacherId, column, minutes, note } — column: regular (lý thuyết, đã dạy),
 * off (lý thuyết, nghỉ không lương), holiday, makeup, substitute, noFee.
 */
function timesheetEntries(session) {
  if (session.academicStaffId) return [];
  const cls = findBy(state.data.classes, session.classId);
  const code = cls?.code || cls?.name || "";
  const day = formatDateVi(session.date).slice(0, 5);
  const minutes = sessionMinutesOf(session);
  const nameOf = (id) => findBy(state.data.teachers, id)?.fullName || "giáo viên khác";
  const kind = timesheetSessionKind(session);
  const swap = timesheetSubstitution(session);
  if (swap && kind === "REGULAR") {
    return [
      { teacherId: swap.main, column: "off", minutes, note: `Nghỉ ${code} ${day}: ${nameOf(swap.sub)} dạy thay` },
      { teacherId: swap.sub, column: "substitute", minutes, note: `Dạy thay ${code} ${day} cho ${nameOf(swap.main)}` },
    ];
  }
  if (swap && kind === "NO_FEE") {
    return [{ teacherId: swap.sub, column: "noFee", minutes, note: `Dạy thay ${code} ${day} cho ${nameOf(swap.main)} (buổi không tính phí)` }];
  }
  const teacherId = sessionTeacherId(session);
  if (kind === "HOLIDAY") return [{ teacherId, column: "holiday", minutes, note: "" }];
  if (kind === "TEACHER_OFF") {
    const makeup = makeupSessionFor(session);
    return [{ teacherId, column: "off", minutes, note: makeup
      ? `Nghỉ ${code} ${day}: đã dạy bù ${formatDateVi(makeup.date).slice(0, 5)} (${nameOf(sessionTeacherId(makeup))})`
      : `Nghỉ ${code} ${day}: chưa dạy bù` }];
  }
  if (kind === "MAKEUP") {
    const off = (state.data.lessonSessions || []).find((item) => item.id === session.makeupOf);
    return [{ teacherId, column: "makeup", minutes, note: `Dạy bù ${code} ${day}${off ? ` cho ${nameOf(sessionTeacherId(off))} buổi ${formatDateVi(off.date).slice(0, 5)}` : ""}` }];
  }
  if (kind === "NO_FEE") return [{ teacherId, column: "noFee", minutes, note: "" }];
  return [{ teacherId, column: "regular", minutes, note: session.isExtra && /bù/i.test(String(session.note || ""))
    ? `Buổi thêm ${code} ${day} ghi "học bù" nhưng chưa nối với buổi nghỉ` : "" }];
}

/** Phần chấm công của một giáo viên trong buổi (nếu có). */
function timesheetEntryFor(session, teacherId) {
  return timesheetEntries(session).find((entry) => entry.teacherId === teacherId) || null;
}

/** Buổi được trả công cho giáo viên này (đã dạy theo lịch, dạy bù, dạy thay, không tính phí). */
function timesheetPaidFor(session, teacherId) {
  const entry = timesheetEntryFor(session, teacherId);
  return Boolean(entry && TIMESHEET_PAID_COLUMNS.has(entry.column));
}

function timesheetEmptyRow(extra = {}) {
  return { total: 0, totalElapsed: 0, holiday: 0, off: 0, makeup: 0, substitute: 0, noFee: 0, support: 0, actual: 0, elapsed: 0, sessions: 0, notes: [], ...extra };
}

/**
 * Lý thuyết = cả tháng theo lịch (kế hoạch). Các cột còn lại và chấm công thực tế
 * chỉ tính buổi ĐÃ QUA (giờ kết thúc đã trôi qua) — realtime, buổi tới đâu cập
 * nhật tới đó; hết tháng thì thực tế = lý thuyết − nghỉ không lương + dạy bù +
 * dạy thay + không tính phí.
 */
function timesheetAddEntry(row, entry, session) {
  row.sessions += 1;
  if (entry.column === "regular" || entry.column === "off") row.total += entry.minutes;
  if (!isSessionElapsed(session)) return;
  if (entry.column === "regular" || entry.column === "off") row.totalElapsed += entry.minutes;
  if (entry.column === "off") row.off += entry.minutes;
  if (entry.column === "holiday") row.holiday += entry.minutes;
  if (entry.column === "makeup") row.makeup += entry.minutes;
  if (entry.column === "substitute") row.substitute += entry.minutes;
  if (entry.column === "noFee") row.noFee += entry.minutes;
  if (entry.column === "support") row.support += entry.minutes;
  if (TIMESHEET_PAID_COLUMNS.has(entry.column)) row.elapsed += entry.minutes;
  if (entry.note) row.notes.push({ date: session.date, text: entry.note });
}

/**
 * Tổng hợp chấm công theo giáo viên: lý thuyết cả tháng; thực tế (realtime) =
 * lý thuyết đã qua − nghỉ không lương + dạy bù + dạy thay + dạy không tính phí.
 */
function timesheetTeacherRows(sessions, events = []) {
  const byTeacher = new Map();
  for (const teacher of state.data.teachers || []) byTeacher.set(teacher.id, timesheetEmptyRow({ teacher }));
  for (const session of sessions) {
    for (const entry of timesheetEntries(session)) {
      const row = byTeacher.get(entry.teacherId);
      if (row) timesheetAddEntry(row, entry, session);
    }
  }
  for (const item of events) {
    const row = byTeacher.get(item.teacherId);
    if (row) timesheetAddEntry(row, timesheetEventEntry(item), item);
  }
  return [...byTeacher.values()].filter((row) => row.sessions > 0).map((row) => ({
    ...row,
    actual: row.totalElapsed - row.off + row.makeup + row.substitute + row.noFee + row.support,
    notes: row.notes.sort((x, y) => x.date.localeCompare(y.date)).map((item) => item.text),
  }));
}

/** Tổng các cột chấm công cho một list buổi (một giáo viên nếu truyền teacherId). */
function timesheetTotals(sessions, teacherId = "", events = []) {
  const totals = timesheetEmptyRow();
  for (const session of sessions) {
    for (const entry of timesheetEntries(session)) {
      if (teacherId && entry.teacherId !== teacherId) continue;
      timesheetAddEntry(totals, entry, session);
    }
  }
  for (const item of events) if (!teacherId || item.teacherId === teacherId) timesheetAddEntry(totals, timesheetEventEntry(item), item);
  totals.actual = totals.totalElapsed - totals.off + totals.makeup + totals.substitute + totals.noFee + totals.support;
  return totals;
}

// --- Hồ sơ lương (payroll-config) ---
function payrollConfig() {
  return state.data?.payrollConfig || { teachers: {}, months: {} };
}

function payrollContract(teacherId) {
  return payrollConfig().teachers?.[teacherId] || {};
}

function payrollMonthInputs(month, teacherId) {
  return payrollConfig().months?.[month]?.[teacherId] || {};
}

function payrollMonthKey() {
  const key = /^\d{4}-(0[1-9]|1[0-2])$/.test(String(state.payrollMonth || "")) ? state.payrollMonth : monthKey();
  return key < TIMESHEET_MONTH_START ? TIMESHEET_MONTH_START : key;
}

function payrollMonthRange(key = payrollMonthKey()) {
  const [year, month] = key.split("-").map(Number);
  return { from: `${key}-01`, to: localDateKey(new Date(year, month, 0, 12)) };
}

function progressiveTax(taxable, brackets = payrollPolicy().taxBrackets) {
  let tax = 0;
  let prev = 0;
  for (const row of brackets) {
    const cap = row.upTo === null ? Infinity : row.upTo;
    if (taxable <= prev) break;
    tax += (Math.min(taxable, cap) - prev) * row.rate;
    prev = cap;
  }
  return Math.round(tax);
}

/** Một buổi đã qua có bị tính điểm danh trễ không. Buổi cũ chưa có mốc giờ nộp
 * thì coi như đã hoàn tất đúng hạn; buổi đã qua mà chưa điểm danh là trễ. */
function payrollSessionLate(session, policy = payrollPolicy()) {
  if (!sessionAttendanceMarked(session)) return true;
  if (!session.attendanceSubmittedAt) return false;
  const end = new Date(`${session.date}T${session.endTime || "23:59"}:00`).getTime();
  const submitted = new Date(session.attendanceSubmittedAt).getTime();
  if (!Number.isFinite(end) || !Number.isFinite(submitted)) return false;
  return submitted > end + policy.attendanceDeadlineHours * 3600000;
}

/** KPI: tỷ lệ điểm danh đúng hạn — số buổi đã dạy qua hạn nộp điểm danh / số buổi đã dạy. */
function attendanceKpi(teacherId, range = payrollMonthRange(), policy = payrollPolicy()) {
  let eligible = 0;
  let late = 0;
  const lateSessions = [];
  for (const session of timesheetSessions(teacherId, range)) {
    if (!timesheetPaidFor(session, teacherId) || !isSessionElapsed(session)) continue;
    eligible += 1;
    if (payrollSessionLate(session, policy)) {
      late += 1;
      lateSessions.push(session);
    }
  }
  const onTimeRate = eligible ? (eligible - late) / eligible : 1;
  return { eligible, late, onTimeRate, lateSessions };
}

/** Số ngày công chuẩn của tháng: toàn bộ ngày trong tháng trừ Chủ nhật (đi làm T2–T7), biến thiên theo lịch từng tháng. */
function payrollWorkingDays(month) {
  const [year, mon] = String(month || "").split("-").map(Number);
  if (!year || !mon) return 26;
  const total = new Date(year, mon, 0).getDate();
  let count = 0;
  for (let day = 1; day <= total; day += 1) if (new Date(year, mon - 1, day).getDay() !== 0) count += 1;
  return count;
}

/** Hệ số lương riêng của giáo viên — nhân với giờ công chuẩn ra đơn giá giờ. Bỏ trống = 1. */
function payrollSalaryCoefficient(contract) {
  const value = Number(contract?.salaryCoefficient);
  return Number.isFinite(value) && value > 0 ? Math.min(10, value) : 1;
}

/** Khoá so khớp họ tên khi nhập lương hàng loạt: bỏ dấu, thường hoá, gộp khoảng trắng. */
function payrollImportKey(value) {
  return String(value ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/đ/g, "d")
    .replace(/Đ/g, "D")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
}

/**
 * Đọc danh sách nhân sự dán vào (JSON) và trả về hợp đồng cần ghi cho từng
 * người. Khớp theo mã trước rồi tới họ tên không dấu. Chỉ trả về người có
 * trong danh sách — người khác giữ nguyên hợp đồng đang có.
 * Mỗi dòng: { code?, name, coefficient, payMode?, contractKind?, jobTitle?, department? }
 * Khối `policy` tuỳ chọn ghi thêm giờ công chuẩn và 4 mức phụ cấp.
 */
function payrollImportContracts(raw) {
  let parsed;
  try {
    parsed = typeof raw === "string" ? JSON.parse(raw) : raw;
  } catch {
    throw new Error("Dữ liệu không phải JSON hợp lệ — kiểm tra lại dấu ngoặc và dấu phẩy.");
  }
  const rows = Array.isArray(parsed) ? parsed : Array.isArray(parsed?.staff) ? parsed.staff : [];
  if (!rows.length) throw new Error("Không thấy dòng nhân sự nào trong dữ liệu dán vào.");
  const policy = {};
  const rawPolicy = parsed?.policy && typeof parsed.policy === "object" ? parsed.policy : {};
  for (const key of ["standardHourlyRate", "mealAllowancePerDay", "phoneAllowance", "fuelAllowance", "uniformAllowance"]) {
    const value = Number(rawPolicy[key]);
    if (Number.isFinite(value) && value >= 0) policy[key] = Math.round(value);
  }
  const people = [
    ...(state.data.teachers || []),
    ...(state.data.accountants || []),
    ...(state.data.assistants || []),
  ];
  const byCode = new Map(people.filter((item) => item.code).map((item) => [String(item.code).trim().toUpperCase(), item]));
  const byName = new Map(people.filter((item) => item.fullName).map((item) => [payrollImportKey(item.fullName), item]));
  const contracts = {};
  const applied = [];
  const missing = [];
  const invalid = [];
  for (const row of rows) {
    const code = String(row?.code || "").trim().toUpperCase();
    // Mã là khoá chính, nhưng nếu mã trỏ sang người khác với họ tên đã ghi thì
    // tin họ tên — tránh ghi nhầm lương khi mã nhân sự bị dùng lại.
    const byCodePerson = code ? byCode.get(code) : null;
    const byNamePerson = byName.get(payrollImportKey(row?.name || row?.fullName)) || null;
    const person = byCodePerson && (!byNamePerson || byCodePerson === byNamePerson) ? byCodePerson : byNamePerson;
    if (!person) {
      missing.push(String(row?.name || row?.fullName || row?.code || "").trim() || "(dòng không có tên)");
      continue;
    }
    const coefficient = Number(row?.coefficient ?? row?.salaryCoefficient);
    if (!Number.isFinite(coefficient) || coefficient <= 0 || coefficient > 10) {
      invalid.push(`${person.fullName} (hệ số ${row?.coefficient ?? row?.salaryCoefficient ?? "trống"})`);
      continue;
    }
    const contract = { ...payrollContract(person.id), ...(contracts[person.id] || {}) };
    contract.salaryCoefficient = Math.round(coefficient * 10000) / 10000;
    if (row.payMode === "HOURLY" || row.payMode === "MONTHLY") contract.payMode = row.payMode;
    if (PAYROLL_CONTRACT_KIND_LABELS[row.contractKind]) {
      contract.contractKind = row.contractKind;
      contract.contractType = row.contractKind === "DV" || row.contractKind === "CSH" ? "SERVICE" : "LABOR";
    }
    for (const key of ["jobTitle", "department"]) {
      if (typeof row[key] === "string" && row[key].trim()) contract[key] = row[key].trim();
    }
    if (!contract.contractKind) contract.contractKind = contract.contractType === "SERVICE" ? "DV" : "TT";
    contract.contractType = contract.contractKind === "DV" || contract.contractKind === "CSH" ? "SERVICE" : "LABOR";
    if (!contract.status) contract.status = "ACTIVE";
    if (!contract.startDate) contract.startDate = payrollPolicy().effectiveFrom || "2026-10-01";
    if (!contract.contractNo) contract.contractNo = `HĐ-2026/${person.code || person.id}`;
    contracts[person.id] = contract;
    applied.push(person.fullName);
  }
  return { contracts, policy, applied, missing, invalid };
}

/**
 * Một dòng lương của giáo viên cho tháng `month`.
 * - Đơn giá giờ = giờ công chuẩn của trung tâm (chính sách) × hệ số lương riêng
 *   của giáo viên. Không còn đơn giá nhập tay theo từng người.
 * - HOURLY: lương = số giờ chấm công thực tế × đơn giá giờ. Kế toán chốt tay
 *   được số giờ của tháng (`hours`) — dùng cho trợ giảng không có lịch dạy.
 * - MONTHLY: lương = đơn giá giờ × giờ công chuẩn/tháng × ngày công tính lương /
 *   ngày công chuẩn của tháng. Ngày công = ngày công chuẩn − số NGÀY nghỉ không
 *   lương kế toán cấu hình cho tháng (`unpaidLeaveDays`, trừ nguyên ngày); ghi đè
 *   tuyệt đối bằng ô `paidDays`.
 * - Phụ cấp ăn ca/điện thoại/đồng phục: trả NGUYÊN mức chính sách (hoặc mức ghi
 *   đè trên hợp đồng), không chia theo ngày công, áp dụng cho cả lương giờ.
 * - Không còn thưởng doanh số. Lương năng suất = lương × mốc % điểm danh đúng hạn
 *   (chỉ giáo viên lương tháng).
 * - BH + thuế TNCN 5 bậc theo chính sách trong Cấu hình hệ thống.
 */
function payrollRowFor(teacher, actualMinutes, month, context = {}) {
  const policy = payrollPolicy();
  const contract = payrollContract(teacher.id);
  const inputs = payrollMonthInputs(month, teacher.id);
  const kind = payrollContractKind(contract);
  const payMode = payrollStaffPayMode(teacher.id, contract);
  const hourlyRate = payrollHourlyRate(contract, policy);
  // Giờ công chốt tay của lương giờ (trợ giảng không có lịch dạy); bỏ trống thì lấy giờ chấm công.
  const overrideHours = inputs.hours === "" || inputs.hours === null || inputs.hours === undefined ? null : Number(inputs.hours);
  const hours = Number.isFinite(overrideHours) ? Math.max(0, Math.min(744, overrideHours)) : actualMinutes / 60;
  const standardDays = Math.max(1, payrollWorkingDays(month));
  const paidLeaveDays = Math.max(0, Math.min(standardDays, Math.round(Number(inputs.paidLeaveDays) || 0)));
  const unpaidLeaveDays = Math.max(0, Math.min(standardDays, Math.round(Number(inputs.unpaidLeaveDays) || 0)));
  const autoPaidDays = Math.max(0, standardDays - unpaidLeaveDays);
  const overridePaid = inputs.paidDays === "" || inputs.paidDays === null || inputs.paidDays === undefined ? null : Number(inputs.paidDays);
  const paidDays = Number.isFinite(overridePaid) ? Math.max(0, Math.min(31, overridePaid)) : Math.round(autoPaidDays * 100) / 100;
  const monthly = payMode === "MONTHLY";
  const hourly = !monthly;
  // Định mức giờ của tháng: lương tháng thì quy ngày công ra giờ (8h/ngày), lương giờ
  // thì định mức vẫn là cả tháng làm việc chuẩn để đo % đạt định mức.
  const quotaDays = monthly ? paidDays : standardDays;
  const quotaHours = PAYROLL_DAILY_HOURS * quotaDays;
  const salaryHours = monthly ? quotaHours : hours;
  const salary = Math.round(salaryHours * hourlyRate);
  const coefficient = payrollSalaryCoefficient(contract);
  const allowance = Math.max(0, Math.round(Number(inputs.allowance) || 0));
  const advance = Math.max(0, Math.round(Number(inputs.advance) || 0));
  const kpi = context.kpi || attendanceKpi(teacher.id, payrollMonthRange(month), policy);
  const onTimeRate = kpi.eligible ? kpi.onTimeRate : 0;
  const quotaRate = quotaHours > 0 ? hours / quotaHours : 0;
  const productivityRate = onTimeRate + quotaRate;
  const productivityPay = Math.round(salary * productivityRate);
  const overrideMoney = (value, fallback) => value === "" || value === null || value === undefined || !Number.isFinite(Number(value))
    ? fallback
    : Math.max(0, Math.round(Number(value)));
  // Giáo viên chưa có hồ sơ lương thì chưa phải là người của trung tâm — không
  // phát sinh phụ cấp, nếu không báo cáo tháng nào cũng cộng thêm tiền ảo.
  const configured = Object.keys(contract).length > 0;
  // Phụ cấp kiểu mới chỉ áp cho phòng ban Giáo viên (trợ giảng, vận hành tính sau — giữ phụ cấp nguyên mức tháng):
  // - Ăn trưa = mức/ngày × số ngày làm việc của tháng (trừ Chủ nhật) — đổi theo từng tháng.
  // - Mọi phụ cấp nhân % giờ cam kết: đạt 100% nhận đủ, thấp hơn giảm theo %, cao hơn (dạy thay…) tăng theo.
  //   Lương tháng, hoặc chưa ghi giờ cam kết, nhận đủ phụ cấp.
  const teacherDepartment = payrollImportKey(contract.department || PAYROLL_STAFF_DEFAULT_DEPARTMENTS[payrollStaffRole(teacher.id)] || "") === "giao vien";
  const mealPerDay = teacherDepartment ? overrideMoney(contract.mealAllowancePerDay, Math.max(0, Math.round(Number(policy.mealAllowancePerDay) || 0))) : 0;
  const committedHours = teacherDepartment ? Math.max(0, Number(contract.committedHours) || 0) : 0;
  const allowanceRate = hourly && committedHours > 0 ? hours / committedHours : 1;
  const scaled = (value) => Math.round(value * allowanceRate);
  const mealAllowance = !configured ? 0 : teacherDepartment
    ? scaled(mealPerDay * standardDays)
    : overrideMoney(contract.mealAllowance, Math.max(0, Math.round(Number(policy.mealAllowance) || 0)));
  const phoneAllowance = configured ? scaled(overrideMoney(contract.phoneAllowance, Math.max(0, Math.round(Number(policy.phoneAllowance) || 0)))) : 0;
  const fuelAllowance = configured ? scaled(overrideMoney(contract.fuelAllowance, Math.max(0, Math.round(Number(policy.fuelAllowance) || 0)))) : 0;
  const uniformAllowance = configured ? scaled(overrideMoney(contract.uniformAllowance, Math.max(0, Math.round(Number(policy.uniformAllowance) || 0)))) : 0;
  const autoAllowance = mealAllowance + phoneAllowance + fuelAllowance + uniformAllowance;
  const gross = salary + productivityPay + autoAllowance + allowance;
  const isLabor = payrollIsLabor(contract);
  const rates = payrollInsuranceRates(contract, policy);
  const fullMonthHours = PAYROLL_DAILY_HOURS * standardDays;
  // Lương cơ bản trên báo cáo: lương tháng hiện lương cứng cả tháng (đủ ngày công
  // chuẩn), lương giờ hiện tiền một giờ dạy.
  const baseSalary = hourly ? hourlyRate : Math.round(hourlyRate * fullMonthHours);
  const insuranceBase = hourly ? salary : Math.max(0, Math.round(Number(contract.insuranceSalary) || baseSalary));
  const insurance = Math.round(insuranceBase * rates.employee);
  const employerInsurance = Math.round(insuranceBase * rates.employer);
  const dependents = isLabor ? Math.max(0, Math.round(Number(contract.dependents) || 0)) : 0;
  const deduction = isLabor ? policy.personalDeduction + dependents * policy.dependentDeduction : 0;
  const taxableIncome = isLabor ? Math.max(0, gross - insurance - deduction) : gross;
  const taxExempt = PAYROLL_TAX_EXEMPT_CODES.has(String(teacher.code || "").trim().toUpperCase());
  const tax = taxExempt ? 0 : isLabor
    ? progressiveTax(taxableIncome, policy.taxBrackets)
    : (gross >= policy.serviceTaxThreshold ? Math.round(gross * policy.serviceTaxRate) : 0);
  const net = gross - insurance - tax - advance;
  return {
    teacher, contract, inputs, month, hours, policy,
    hourlyRate, baseSalary, payMode, kind, quotaHours, quotaDays, salaryHours, dailyHours: PAYROLL_DAILY_HOURS,
    paidDays, autoPaidDays, paidLeaveDays, unpaidLeaveDays, workingDays: standardDays, overridePaidDays: Number.isFinite(overridePaid), hoursOverride: Number.isFinite(overrideHours), actualHours: actualMinutes / 60,
    salary, allowance, autoAllowance, mealAllowance, phoneAllowance, fuelAllowance, uniformAllowance, mealPerDay, committedHours, allowanceRate,
    coefficient,
    productivityRate, productivityPay, onTimeRate, quotaRate, kpi,
    insuranceBase, insurance, employerInsurance,
    deduction, dependents, isLabor, taxMode: isLabor ? "LABOR" : "SERVICE",
    gross, taxableIncome, tax, taxExempt, advance, net,
  };
}

/** Nhân sự có bảng lương: giáo viên + kế toán + trợ giảng. Kế toán mặc định lương tháng, giáo viên và trợ giảng mặc định lương giờ. */
function payrollStaff() {
  return [
    ...(state.data.teachers || []),
    ...(state.data.accountants || []).map((item) => ({ ...item, role: "ACCOUNTANT" })),
    ...(state.data.assistants || []).map((item) => ({ ...item, role: "ASSISTANT" })),
  ];
}

function payrollStaffById(id) {
  return findBy(state.data.teachers, id)
    || findBy(state.data.accountants || [], id)
    || findBy(state.data.assistants || [], id)
    || null;
}

/** Vai trò trên bảng lương — dùng để chọn mặc định lương tháng/giờ và nhãn phòng ban. */
function payrollStaffRole(id) {
  if ((state.data.accountants || []).some((item) => item.id === id)) return "ACCOUNTANT";
  if ((state.data.assistants || []).some((item) => item.id === id)) return "ASSISTANT";
  return "TEACHER";
}

function payrollStaffPayMode(id, contract) {
  return payrollPayMode(contract, payrollStaffRole(id) === "ACCOUNTANT" ? "MONTHLY" : "HOURLY");
}

const PAYROLL_DEPARTMENT_FILTERS = [
  { value: "ALL", label: "Tất cả phòng ban" },
  { value: "ASSISTANT", label: "Trợ giảng" },
  { value: "TEACHER", label: "Giáo viên" },
  { value: "OPS", label: "Vận hành" },
];

/** Phòng ban hiện trên bảng lương: hợp đồng ghi đè, chưa có thì lấy theo vai trò. */
function payrollDepartmentLabel(row) {
  return row.contract.department || PAYROLL_STAFF_DEFAULT_DEPARTMENTS[payrollStaffRole(row.teacher.id)] || "";
}

/** Bộ lọc phòng ban theo nhãn phòng ban trên bảng lương: Trợ giảng, Giáo viên, còn lại là Vận hành. */
function payrollDepartmentGroup(row) {
  const key = payrollImportKey(payrollDepartmentLabel(row));
  if (key === "tro giang") return "ASSISTANT";
  if (key === "giao vien") return "TEACHER";
  return "OPS";
}

function payrollDepartmentMatches(row, filter) {
  if (filter !== "ASSISTANT" && filter !== "TEACHER" && filter !== "OPS") return true;
  return payrollDepartmentGroup(row) === filter;
}

const PAYROLL_COLUMNS_STORAGE_KEY = "steps:payroll:hidden-columns:v1";

/** Thứ tự cột trên bảng lương; hộp chọn cột đọc đúng danh sách này để không lệch với phần đầu bảng. */
const PAYROLL_COLUMNS = [
  { key: "index", label: "STT" },
  { key: "code", label: "Mã" },
  { key: "name", label: "Họ và tên" },
  { key: "department", label: "Phòng ban" },
  { key: "contract", label: "Hợp đồng" },
  { key: "baseSalary", label: "Lương cơ bản" },
  { key: "coefficient", label: "Hệ số lương" },
  { key: "work", label: "Ngày công/Giờ công" },
  { key: "paidLeave", label: "Nghỉ phép" },
  { key: "unpaidLeave", label: "Nghỉ không lương" },
  { key: "salary", label: "Lương theo công" },
  { key: "phone", label: "Phụ cấp điện thoại" },
  { key: "meal", label: "Phụ cấp ăn trưa" },
  { key: "fuel", label: "Phụ cấp xăng xe" },
  { key: "uniform", label: "Phụ cấp đồng phục" },
  { key: "onTime", label: "% đúng hạn" },
  { key: "quota", label: "Định mức giờ" },
  { key: "productivity", label: "Lương năng suất" },
  { key: "insurance", label: "BH NLD" },
  { key: "tax", label: "Thuế TNCN" },
  { key: "advance", label: "Tạm ứng" },
  { key: "net", label: "Thực lĩnh" },
];

/** Các cột cộng dồn được ở dòng tổng: số tiền của tháng, không phải đơn giá hay tỷ lệ. */
const PAYROLL_TOTAL_FIELDS = {
  salary: "salary",
  phone: "phoneAllowance",
  meal: "mealAllowance",
  fuel: "fuelAllowance",
  uniform: "uniformAllowance",
  productivity: "productivityPay",
  insurance: "insurance",
  tax: "tax",
  advance: "advance",
  net: "net",
};

function isPayrollColumnHidden(key) {
  return state.payrollHiddenColumns.includes(key);
}

function readPayrollHiddenColumns() {
  try {
    const saved = JSON.parse(localStorage.getItem(PAYROLL_COLUMNS_STORAGE_KEY) || "[]");
    return Array.isArray(saved) ? saved.filter((key) => PAYROLL_COLUMNS.some((column) => column.key === key)) : [];
  } catch {
    return [];
  }
}

function writePayrollHiddenColumns() {
  try {
    localStorage.setItem(PAYROLL_COLUMNS_STORAGE_KEY, JSON.stringify(state.payrollHiddenColumns));
  } catch { /* trình duyệt chặn localStorage thì chỉ nhớ trong phiên */ }
}

/** Nội dung từng ô của một dòng, khóa theo cột để ẩn cột chỉ là bỏ ô khỏi vòng lặp. */
function payrollRowCells(row, index, money) {
  const monthly = row.payMode === "MONTHLY";
  // Lương tháng: số ngày công chuẩn của tháng (trừ Chủ nhật); lương giờ: số giờ dạy thực tế.
  const workValue = monthly ? String(row.workingDays) : formatHours(Math.round(row.hours * 60));
  return {
    index: `<td class="cell-index">${index + 1}</td>`,
    code: `<td class="code">${escapeHtml(row.teacher.code)}</td>`,
    name: `<td><button class="table-link" data-payroll-detail="${escapeHtml(row.teacher.id)}">${escapeHtml(row.teacher.fullName)}</button></td>`,
    department: `<td>${escapeHtml(payrollDepartmentLabel(row) || "—")}</td>`,
    contract: `<td>${monthly ? "Lương tháng" : "Lương giờ"}</td>`,
    baseSalary: `<td>${vnd(row.baseSalary)}</td>`,
    coefficient: `<td>${Number(row.coefficient.toFixed(2)).toLocaleString("vi-VN")}</td>`,
    work: `<td>${workValue}</td>`,
    paidLeave: `<td>${row.paidLeaveDays || "—"}</td>`,
    unpaidLeave: `<td>${row.unpaidLeaveDays || "—"}</td>`,
    salary: `<td>${money(row.salary)}</td>`,
    phone: `<td>${money(row.phoneAllowance)}</td>`,
    meal: `<td>${money(row.mealAllowance)}</td>`,
    fuel: `<td>${money(row.fuelAllowance)}</td>`,
    uniform: `<td>${money(row.uniformAllowance)}</td>`,
    onTime: `<td>${row.kpi.eligible ? payrollPercent(row.kpi.onTimeRate) : "—"}</td>`,
    quota: `<td>${payrollPercent(row.quotaRate)}</td>`,
    productivity: `<td>${money(row.productivityPay)}</td>`,
    insurance: `<td>${money(row.insurance)}</td>`,
    tax: `<td>${money(row.tax)}</td>`,
    advance: `<td>${money(row.advance)}</td>`,
    net: `<td><strong>${vnd(row.net)}</strong></td>`,
  };
}

/** Nút cấu hình cột: tick = ẩn cột đó trên màn hình, dữ liệu và file Excel vẫn giữ nguyên. */
function payrollColumnMenu() {
  const options = PAYROLL_COLUMNS.map((column) => `<label class="payroll-column-option"><input type="checkbox" data-payroll-column="${column.key}" ${isPayrollColumnHidden(column.key) ? "checked" : ""} /><span>${escapeHtml(column.label)}</span></label>`).join("");
  return `<div class="payroll-columns"><button class="secondary-btn" type="button" data-payroll-columns aria-expanded="${state.payrollColumnMenu ? "true" : "false"}" title="Ẩn/hiện cột trên màn hình">${icon("panels")}Cột</button>${state.payrollColumnMenu ? `<div class="payroll-column-panel"><p>Tick để ẩn cột — dữ liệu vẫn giữ nguyên.</p><div class="payroll-column-list">${options}</div></div>` : ""}</div>`;
}

/** Bảng lương một tháng: toàn bộ nhân sự — ai chưa có hồ sơ lương thì hiện trống để kế toán nhập. */
function payrollMonthRows(month = payrollMonthKey(), range = payrollMonthRange(month)) {
  const byTeacher = new Map(timesheetTeacherRows(timesheetSessions("", range), timesheetCalendarEvents("", range)).map((row) => [row.teacher.id, row]));
  // attendanceKpi một lần cho cả bảng: gọi theo từng giáo viên sẽ quét lại toàn bộ
  // buổi của tháng (kèm suy dạy thay) cả chục lần, ngoài lúc render thì không có
  // cache nên treo cả chục giây.
  const staff = payrollStaff();
  const kpiByTeacher = new Map(staff.map((member) => [member.id, { eligible: 0, late: 0, onTimeRate: 1, lateSessions: [] }]));
  for (const session of timesheetSessions("", range)) {
    if (!isSessionElapsed(session)) continue;
    const late = payrollSessionLate(session, payrollPolicy());
    for (const entry of timesheetEntries(session)) {
      const kpi = kpiByTeacher.get(entry.teacherId);
      if (!kpi || !timesheetPaidFor(session, entry.teacherId)) continue;
      kpi.eligible += 1;
      if (late) { kpi.late += 1; kpi.lateSessions.push(session); }
    }
  }
  for (const kpi of kpiByTeacher.values()) kpi.onTimeRate = kpi.eligible ? (kpi.eligible - kpi.late) / kpi.eligible : 1;
  return staff.map((member) => {
    const ts = byTeacher.get(member.id);
    return payrollRowFor(member, ts ? ts.actual : 0, month, {
      kpi: kpiByTeacher.get(member.id),
    });
  });
}

/** Bảng lương của lần render gần nhất, tính theo tháng đang xem. */
let payrollRenderedRows = { month: "", rows: [] };

/** Dòng của một giáo viên trên bảng đang hiển thị — không có trong cache mới tính lại. */
function payrollRenderedRow(teacherId, month = payrollMonthKey()) {
  if (payrollRenderedRows.month !== month) {
    // Tính ngoài vòng render thì bật cache hiệu năng của render, nếu không mỗi
    // buổi lại bị suy ra dạy thay từ đầu và bảng lương treo nhiều giây.
    perf.active = true;
    try { payrollRenderedRows = { month, rows: payrollMonthRows(month) }; } finally { perf.active = false; }
  }
  return payrollRenderedRows.rows.find((row) => row.teacher.id === teacherId) || null;
}


/** Dòng dạy thay trong báo cáo: "Dạy thay S9 (cô Đức)" — lớp + giáo viên chính được dạy thay. */
function timesheetSubstituteLabel(session, cls) {
  const code = cls?.code || cls?.name || "";
  const main = timesheetSubstitution(session)?.main || "";
  const name = String(findBy(state.data.teachers, main)?.fullName || "").trim().split(/\s+/).pop() || "";
  return `Dạy thay ${code}${name ? ` (cô ${name})` : ""}`.trim();
}

const TIMESHEET_REPORT_TYPE_LABELS = {
  regular: "Theo lịch", makeup: "Dạy bù", substitute: "Dạy thay", noFee: "Không tính phí",
  TEST_SPEAKING: "Test speaking", KEM_SPEAKING: "Kèm speaking", KEM_CA_NHAN: "Kèm cá nhân", KEM_LOP: "Kèm lớp",
};

/**
 * Báo cáo buổi dạy (PDF) theo đúng bộ lọc đang xem — khoảng ngày + giáo viên. Mỗi giáo
 * viên: số buổi theo loại, tổng giờ, rồi từng buổi kèm loại. Chỉ tính buổi ĐÃ DẠY (đã qua
 * giờ kết thúc, được chấm công) — cùng cách tính với cột Chấm công thực tế.
 */
function timesheetReportData(now = new Date()) {
  const range = timesheetViewRange();
  const teacherId = state.timesheetTeacher;
  const selected = teacherId ? findBy(state.data.teachers, teacherId) : null;
  const items = [];
  // Dòng không tính giờ nhưng web vẫn hiện (Nghỉ không lương / Nghỉ lễ / Đã hủy): đưa vào chi tiết PDF để đối chiếu, không cộng vào tổng.
  const offItems = [];
  for (const session of timesheetSessions(teacherId, range)) {
    const elapsed = isSessionElapsed(session);
    const cls = findBy(state.data.classes, session.classId);
    for (const entry of timesheetEntries(session)) {
      if (teacherId && entry.teacherId !== teacherId) continue;
      if (entry.column === "off" || entry.column === "holiday") {
        const classLabel = cls ? `${cls.name}${cls.code && cls.code !== cls.name ? ` (${cls.code})` : ""}` : "—";
        offItems.push({
          session, teacherId: entry.teacherId, minutes: entry.minutes,
          type: entry.column === "off" ? "Nghỉ không lương" : session.status === "CANCELLED" ? "Đã hủy" : "Nghỉ lễ",
          className: entry.column === "off" && entry.note ? entry.note : classLabel,
        });
        continue;
      }
      if (!elapsed || !TIMESHEET_PAID_COLUMNS.has(entry.column)) continue;
      items.push({ session, teacherId: entry.teacherId, type: entry.column, minutes: entry.minutes, className: entry.column === "substitute" ? timesheetSubstituteLabel(session, cls) : cls ? `${cls.name}${cls.code && cls.code !== cls.name ? ` (${cls.code})` : ""}` : "—" });
    }
  }
  for (const item of timesheetCalendarEvents(teacherId, range)) {
    if (!isSessionElapsed(item)) continue;
    if (item.kind === "DAY_THAY") {
      const note = String(item.note || "").trim().replace(/^dạy thay\s*/i, "");
      items.push({ session: item, teacherId: item.teacherId, type: "substitute", minutes: sessionMinutesOf(item), className: note ? `Dạy thay ${note}` : "Dạy thay" });
      continue;
    }
    const type = TIMESHEET_REPORT_TYPE_LABELS[item.kind] ? item.kind : "KEM_CA_NHAN";
    items.push({ session: item, teacherId: item.teacherId, type, minutes: sessionMinutesOf(item), className: item.note ? `Lịch thêm: ${item.note}` : "Lịch thêm" });
  }
  const hours = (minutes) => (minutes / 60).toLocaleString("vi-VN", { minimumFractionDigits: 1, maximumFractionDigits: 2 });
  const weekday = (date) => { const day = localDate(date).getDay(); return day === 0 ? "CN" : `Thứ ${day + 1}`; };
  const nameOf = (id) => findBy(state.data.teachers, id) || { fullName: "Giáo viên khác", code: "" };
  const teachers = [...new Set(items.map((item) => item.teacherId))].map((id) => {
    const mine = items.filter((item) => item.teacherId === id)
      .sort((a, b) => `${a.session.date}${a.session.startTime}`.localeCompare(`${b.session.date}${b.session.startTime}`));
    const count = (fn) => mine.filter(fn).length;
    const minutes = mine.reduce((total, item) => total + item.minutes, 0);
    const teacher = nameOf(id);
    return {
      id, name: teacher.fullName, code: teacher.code || "", minutes,
      // Đếm riêng từng loại (theo lịch, không tính phí, dạy bù, dạy thay, test / kèm...) cho bảng trên trang.
      byType: Object.fromEntries(Object.keys(TIMESHEET_REPORT_TYPE_LABELS).map((key) => [key, count((item) => item.type === key)])),
      minutesByType: Object.fromEntries(Object.keys(TIMESHEET_REPORT_TYPE_LABELS).map((key) => [key, mine.filter((item) => item.type === key).reduce((total, item) => total + item.minutes, 0)])),
      regular: count((item) => item.type === "regular" || item.type === "noFee"),
      makeup: count((item) => item.type === "makeup"),
      substitute: count((item) => item.type === "substitute"),
      support: count((item) => TIMESHEET_REPORT_SUPPORT_KEYS.has(item.type)),
      count: mine.length,
      hours: hours(minutes),
      sessions: [
        ...mine.map((item) => ({ item, counted: true, type: TIMESHEET_REPORT_TYPE_LABELS[item.type] || "Theo lịch" })),
        ...offItems.filter((item) => item.teacherId === id).map((item) => ({ item, counted: false, type: item.type })),
      ].sort((a, b) => `${a.item.session.date}${a.item.session.startTime}`.localeCompare(`${b.item.session.date}${b.item.session.startTime}`))
        .map(({ item, counted, type }) => ({
          date: formatDateVi(item.session.date), weekday: weekday(item.session.date),
          time: `${item.session.startTime}–${item.session.endTime}`, className: item.className,
          type, hours: hours(item.minutes), counted,
        })),
    };
  }).sort((a, b) => b.minutes - a.minutes || a.name.localeCompare(b.name, "vi"));
  const totalMinutes = items.reduce((total, item) => total + item.minutes, 0);
  const pad = (n) => String(n).padStart(2, "0");
  const period = timesheetRangeIsMonth(range) ? `Tháng ${range.from.slice(5, 7)}/${range.from.slice(0, 4)}`
    : range.from === range.to ? `Ngày ${formatDateVi(range.from)}` : `Từ ngày ${formatDateVi(range.from)} đến ngày ${formatDateVi(range.to)}`;
  return {
    period,
    filter: selected ? `Giáo viên: ${selected.fullName}${selected.code ? ` (${selected.code})` : ""}` : "Tất cả giáo viên",
    exportedAt: `${pad(now.getHours())}:${pad(now.getMinutes())} ${formatDateVi(now)}`,
    totalCount: items.length,
    totalHours: hours(totalMinutes),
    teachers,
  };
}
const TIMESHEET_REPORT_SUPPORT_KEYS = new Set(["TEST_SPEAKING", "KEM_SPEAKING", "KEM_CA_NHAN", "KEM_LOP"]);

/** Xuất PDF báo cáo buổi dạy (máy chủ vẽ), theo đúng bộ lọc đang xem. */
async function exportTimesheetPdf(button) {
  if (button) button.disabled = true;
  try {
    const data = timesheetReportData();
    const response = await fetch("/api/timesheet/report-pdf", {
      method: "POST",
      credentials: "same-origin",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data),
    });
    if (!response.ok) {
      const body = await response.json().catch(() => ({}));
      throw new Error(body.error || "Không tạo được PDF báo cáo buổi dạy.");
    }
    const blob = await response.blob();
    const match = /filename="([^"]+)"/.exec(response.headers.get("Content-Disposition") || "");
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = match?.[1] || "bao-cao-buoi-day.pdf";
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(link.href), 1000);
    toast(`Đã xuất PDF báo cáo buổi dạy (${data.totalCount} buổi).`);
  } catch (error) {
    toast(error.message || "Không xuất được báo cáo. Thử lại.");
  } finally {
    if (button) button.disabled = false;
  }
}

/** Bảng lương đang xem (đúng tháng + bộ lọc tìm kiếm) xuất ra .xls bảng HTML như các file xuất khác. */
function payrollExportHtml() {
  const month = payrollMonthKey();
  const range = payrollMonthRange(month);
  const query = state.payrollQuery.trim().toLowerCase();
  const departmentFilter = state.payrollDepartment;
  const rows = payrollMonthRows(month, range)
    .filter((row) => (!query || `${row.teacher.fullName} ${row.teacher.code}`.toLowerCase().includes(query)) && payrollDepartmentMatches(row, departmentFilter));
  const text = (value) => `<td style="mso-number-format:'\\@'">${escapeHtml(String(value ?? ""))}</td>`;
  const cell = (value, label) => `<td x:num="${Number(value) || 0}">${escapeHtml(String(label))}</td>`;
  const money = (value) => cell(Math.round(Number(value) || 0), vnd(Math.round(Number(value) || 0)));
  const totals = { baseSalary: 0, salary: 0, phoneAllowance: 0, mealAllowance: 0, fuelAllowance: 0, uniformAllowance: 0, productivityPay: 0, insurance: 0, tax: 0, advance: 0, net: 0 };
  const body = rows.map((row, index) => {
    for (const key of Object.keys(totals)) totals[key] += Number(row[key]) || 0;
    const monthly = row.payMode === "MONTHLY";
    const department = payrollDepartmentLabel(row);
    const coefficient = Number(row.coefficient.toFixed(2));
    const work = monthly ? row.workingDays : Math.round(row.hours * 100) / 100;
    const workText = monthly ? String(row.workingDays) : formatHours(Math.round(row.hours * 60));
    return `<tr>${cell(index + 1, index + 1)}${text(row.teacher.code)}${text(row.teacher.fullName)}${text(department)}${text(monthly ? "Lương tháng" : "Lương giờ")}${money(row.baseSalary)}${cell(coefficient, coefficient.toLocaleString("vi-VN"))}${cell(work, workText)}${cell(row.paidLeaveDays || 0, row.paidLeaveDays || 0)}${cell(row.unpaidLeaveDays || 0, row.unpaidLeaveDays || 0)}${money(row.salary)}${money(row.phoneAllowance)}${money(row.mealAllowance)}${money(row.fuelAllowance)}${money(row.uniformAllowance)}${text(row.kpi.eligible ? payrollPercent(row.kpi.onTimeRate) : "—")}${text(payrollPercent(row.quotaRate))}${money(row.productivityPay)}${money(row.insurance)}${money(row.tax)}${money(row.advance)}${money(row.net)}</tr>`;
  }).join("");
  const totalRow = `<tr>${text("")}${text("")}${text("Tổng cộng")}${text("")}${text("")}${money(totals.baseSalary)}${text("")}${text("")}${text("")}${text("")}${money(totals.salary)}${money(totals.phoneAllowance)}${money(totals.mealAllowance)}${money(totals.fuelAllowance)}${money(totals.uniformAllowance)}${text("")}${text("")}${money(totals.productivityPay)}${money(totals.insurance)}${money(totals.tax)}${money(totals.advance)}${money(totals.net)}</tr>`;
  const head = "<tr><th>STT</th><th>Mã</th><th>Họ và tên</th><th>Phòng ban</th><th>Hợp đồng</th><th>Lương cơ bản</th><th>Hệ số lương</th><th>Ngày công/Giờ công</th><th>Nghỉ phép</th><th>Nghỉ không lương</th><th>Lương theo công</th><th>Phụ cấp điện thoại</th><th>Phụ cấp ăn trưa</th><th>Phụ cấp xăng xe</th><th>Phụ cấp đồng phục</th><th>% đúng hạn</th><th>Định mức giờ</th><th>Lương năng suất</th><th>BH NLD</th><th>Thuế TNCN</th><th>Tạm ứng</th><th>Thực lĩnh</th></tr>";
  const sheetName = `Luong ${month}`;
  const html = `<html xmlns:x="urn:schemas-microsoft-com:office:excel"><head><meta charset="UTF-8"><!--[if gte mso 9]><xml><x:ExcelWorkbook><x:ExcelWorksheets><x:ExcelWorksheet><x:Name>${escapeHtml(sheetName)}</x:Name><x:WorksheetOptions><x:DisplayGridlines/></x:WorksheetOptions></x:ExcelWorksheet></x:ExcelWorksheets></x:ExcelWorkbook></xml><![endif]--></head><body><table border="1"><tr><td colspan="22"><b>Bảng lương nhân sự · ${escapeHtml(monthLabel(month))}</b></td></tr>${head}${body || '<tr><td colspan="22">Không có nhân sự phù hợp.</td></tr>'}${rows.length ? totalRow : ""}</table></body></html>`;
  return { html, fileName: `Bảng lương ${monthLabel(month)}.xls` };
}

function exportPayrollExcel() {
  const { html, fileName } = payrollExportHtml();
  const blob = new Blob([html], { type: "application/vnd.ms-excel" });
  const link = document.createElement("a");
  link.href = URL.createObjectURL(blob);
  link.download = fileName.replace(/[\\/:*?"<>|]/g, "-");
  link.click();
  setTimeout(() => URL.revokeObjectURL(link.href), 1000);
  toast("Đã xuất Excel bảng lương.");
}

/**
 * Bảng chấm công "Tất cả giáo viên": luôn đủ nhân sự — mọi tài khoản giáo viên (kể cả phòng ban
 * Trợ giảng) và kế toán, chưa có buổi nào trong khoảng ngày vẫn có dòng 0 giờ; cộng Audit Lê Hà
 * từ tháng bắt đầu đi làm. Thứ tự: theo danh sách giáo viên, rồi kế toán, rồi Audit.
 */
function timesheetStaffRows(workedRows, range = timesheetViewRange()) {
  const byId = new Map(workedRows.map((row) => [row.teacher.id, row]));
  const rows = [];
  for (const teacher of state.data.teachers || []) {
    rows.push(byId.get(teacher.id) || { ...timesheetEmptyRow({ teacher }), notes: [] });
  }
  for (const accountant of state.data.accountants || []) {
    if (!byId.has(accountant.id)) rows.push({ ...timesheetEmptyRow({ teacher: accountant }), notes: [], staffOnly: "Kế toán" });
  }
  // Tài khoản Audit: chỉ Lê Hà là nhân sự (anh Vũ 04/11/2026), đi làm từ 11/2026 — khoảng ngày
  // kết thúc trước tháng đó thì chưa có dòng. 2 tài khoản Audit còn lại không lên bảng.
  for (const audit of state.data.audits || []) {
    const startMonth = TIMESHEET_AUDIT_STAFF.get(payrollImportKey(audit.fullName || ""));
    if (startMonth && range.to.slice(0, 7) >= startMonth && !byId.has(audit.id)) {
      rows.push({ ...timesheetEmptyRow({ teacher: audit }), notes: [], staffOnly: "Audit" });
    }
  }
  const filter = state.timesheetDepartment;
  return ["TEACHER", "ASSISTANT", "OPS"].includes(filter) ? rows.filter((row) => timesheetDepartmentGroup(row) === filter) : rows;
}

/** Nhóm phòng ban như bộ lọc Báo cáo lương: Giáo viên / Trợ giảng / còn lại (kế toán, audit…) là Vận hành.
 * Phòng ban lấy theo hồ sơ lương; chưa ghi thì giáo viên là "Giáo viên", kế toán là "Kế toán". */
function timesheetDepartmentGroup(row) {
  const id = row.teacher?.id;
  const fallback = row.staffOnly === "Kế toán" ? PAYROLL_STAFF_DEFAULT_DEPARTMENTS.ACCOUNTANT : row.staffOnly ? "" : PAYROLL_STAFF_DEFAULT_DEPARTMENTS.TEACHER;
  const key = payrollImportKey(payrollContract(id)?.department || fallback);
  if (key === "tro giang") return "ASSISTANT";
  if (key === "giao vien") return "TEACHER";
  return "OPS";
}

/** Tài khoản Audit được tính là nhân sự trên Báo cáo chấm công (so tên không dấu) → tháng bắt đầu đi làm. */
const TIMESHEET_AUDIT_STAFF = new Map([["le ha", "2026-11"]]);

function timesheetPage() {
  const month = timesheetMonthKey();
  // Giáo viên xem "Chấm công của tôi": khoá đúng giáo viên đang đăng nhập.
  const selfView = state.role === "TEACHER";
  if (selfView) state.timesheetTeacher = currentTeacher()?.id || "__none__";
  const teacherId = state.timesheetTeacher;
  const selected = teacherId ? findBy(state.data.teachers, teacherId) : null;
  const range = timesheetViewRange();
  const sessions = timesheetSessions(teacherId, range);
  const events = timesheetCalendarEvents(teacherId, range);
  const workedRows = timesheetTeacherRows(teacherId ? sessions : timesheetSessions("", range), teacherId ? events : timesheetCalendarEvents("", range));
  const summaries = teacherId ? workedRows : timesheetStaffRows(workedRows, range);
  const totals = timesheetTotals(sessions, teacherId || "", events);
  const teacherOptions = `<option value="">Tất cả giáo viên</option>${(state.data.teachers || []).map((item) => `<option value="${escapeHtml(item.id)}" ${teacherId === item.id ? "selected" : ""}>${escapeHtml(item.fullName)} (${escapeHtml(item.code)})</option>`).join("")}`;
  const monthOptions = timesheetMonthKeys().map((key) => `<option value="${key}" ${key === month ? "selected" : ""}>${escapeHtml(monthLabel(key))}</option>`).join("");
  const teacherField = selfView
    ? `<label class="field"><span>Giáo viên</span><input class="input" value="${escapeHtml(selected ? `${selected.fullName} (${selected.code})` : "Chưa gắn hồ sơ giáo viên")}" readonly /></label>`
    : `<label class="field"><span>Phòng ban</span><select class="input" name="department">${PAYROLL_DEPARTMENT_FILTERS.map((item) => `<option value="${item.value}" ${(state.timesheetDepartment || "ALL") === item.value ? "selected" : ""}>${escapeHtml(item.label)}</option>`).join("")}</select></label><label class="field"><span>Giáo viên</span><select class="input" name="teacher">${teacherOptions}</select></label>`;
  const filter = `<form id="timesheet-filter-form" class="filter-grid class-filters">${teacherField}<label class="field"><span>Tháng</span><select class="input" name="month">${monthOptions}</select></label><label class="field"><span>Từ ngày</span><input class="input" type="date" name="from" value="${range.from}" /></label><label class="field"><span>Đến ngày</span><input class="input" type="date" name="to" value="${range.to}" /></label><div class="timesheet-export"><button class="secondary-btn" type="button" data-timesheet-export>${icon("download")}Xuất PDF</button></div></form>`;
  // Cột giống file PDF: Dạy bù / Dạy thay / Không tính phí / Test speaking / Kèm speaking / Kèm cá nhân / Kèm lớp —
  // mỗi ô ghi số giờ, dưới là số buổi; Tổng buổi = số buổi đã dạy (theo lịch + các loại trên).
  const report = timesheetReportData();
  const reportById = new Map(report.teachers.map((row) => [row.id, row]));
  const typeCell = (stat, key) => {
    const minutes = stat?.minutesByType?.[key] || 0;
    const sessionsCount = stat?.byType?.[key] || 0;
    return `<td>${formatHours(minutes)}${sessionsCount ? `<small class="people-subline">${sessionsCount} buổi</small>` : ""}</td>`;
  };
  const summaryRows = summaries.map((row, index) => {
    const stat = reportById.get(row.teacher.id);
    return `<tr><td class="cell-index">${index + 1}</td><td class="code">${escapeHtml(row.teacher.code)}</td><td>${row.staffOnly ? `<span class="table-link timesheet-staff-name">${escapeHtml(row.teacher.fullName)}</span>` : `<button class="table-link" data-timesheet-teacher="${escapeHtml(row.teacher.id)}">${escapeHtml(row.teacher.fullName)}</button>`}</td><td>${formatHours(row.total)}${stat?.regular ? `<small class="people-subline">${stat.regular} buổi đã dạy</small>` : ""}</td><td>${formatHours(row.holiday)}</td><td>${formatHours(row.off)}</td>${["makeup", "substitute", "noFee", "TEST_SPEAKING", "KEM_SPEAKING", "KEM_CA_NHAN", "KEM_LOP"].map((key) => typeCell(stat, key)).join("")}<td><strong>${stat?.count || 0}</strong></td><td><strong>${formatHours(row.actual)}</strong></td><td class="timesheet-notes">${row.notes.map((note) => `<div>${escapeHtml(note)}</div>`).join("") || '<span class="muted">—</span>'}</td></tr>`;
  }).join("");
  const detailRows = [...sessions, ...events.map((item) => ({ ...item, isCalendarEvent: true }))].sort((a, b) => `${b.date}${b.startTime}`.localeCompare(`${a.date}${a.startTime}`));
  const sessionRows = detailRows.map((session, index) => {
    if (session.isCalendarEvent) {
      const entry = timesheetEventEntry(session);
      return `<tr><td class="cell-index">${index + 1}</td><td>${formatDateVi(session.date)}</td><td>${escapeHtml(CALENDAR_EVENT_LABELS[session.kind] || "Bổ trợ")}<small class="people-subline">Lịch thêm</small></td><td>${escapeHtml(session.startTime)}–${escapeHtml(session.endTime)}</td><td>${formatHours(entry.minutes)}</td><td>—</td><td><span class="muted">—</span></td><td><span class="badge badge-blue">${escapeHtml(TIMESHEET_REPORT_TYPE_LABELS[session.kind] || "Bổ trợ")}</span>${session.note ? `<small class="people-subline">${escapeHtml(session.note)}</small>` : ""}</td><td><span class="badge badge-${isSessionElapsed(session) ? "green" : "blue"}">${isSessionElapsed(session) ? "Đã qua" : "Sắp tới"}</span></td></tr>`;
    }
    const cls = findBy(state.data.classes, session.classId);
    const room = findBy(state.data.settings.rooms, session.roomId);
    const markedEntries = academicReportAttendance(session, cls).filter((item) => item.status);
    const present = markedEntries.filter((item) => item.status === "PRESENT").length;
    const marked = markedEntries.length;
    const attendance = session.isOff ? '<span class="badge badge-amber">Nghỉ học</span>' : marked ? `${present}/${marked} có mặt` : '<span class="muted">Chưa điểm danh</span>';
    // Giáo viên chỉ có link tới lớp mình mở được (route /gv); lớp khác hiện chữ thường.
    const linkable = !selfView || teacherAccessibleClasses().some((item) => item.id === session.classId);
    const dateCell = linkable
      ? `<button class="table-link" data-nav="${classHref(session.classId, "diem-danh", session.id, selfView)}">${formatDateVi(session.date)}</button>`
      : formatDateVi(session.date);
    const classCell = `${linkable ? `<button class="table-link" data-nav="${classHref(session.classId, "", "", selfView)}">${escapeHtml(cls?.name || "—")}</button>` : escapeHtml(cls?.name || "—")}<small class="people-subline">${escapeHtml(cls?.code || "")}</small>`;
    const entry = timesheetEntryFor(session, teacherId) || timesheetEntries(session)[0] || { column: "regular", note: "" };
    const badges = {
      holiday: `<span class="badge badge-${session.status === "CANCELLED" ? "red" : "amber"}">${session.status === "CANCELLED" ? "Đã hủy" : "Nghỉ lễ"}</span>`,
      off: '<span class="badge badge-amber">Nghỉ không lương</span>',
      makeup: '<span class="badge badge-blue">Dạy bù</span>',
      substitute: '<span class="badge badge-blue">Dạy thay</span>',
      noFee: '<span class="badge badge-blue">Không tính phí</span>',
      regular: '<span class="badge badge-green">Theo lịch</span>',
    };
    const missedLabel = (badges[entry.column] || badges.regular) + (entry.note ? `<small class="people-subline">${escapeHtml(entry.note)}</small>` : "");
    return `<tr><td class="cell-index">${index + 1}</td><td>${dateCell}</td><td>${classCell}</td><td>${escapeHtml(session.startTime)}–${escapeHtml(session.endTime)}</td><td>${formatHours(sessionMinutesOf(session))}</td><td>${escapeHtml(room?.name || "—")}</td><td>${attendance}</td><td>${missedLabel}</td><td><span class="badge badge-${session.status === "COMPLETED" ? "green" : session.status === "CANCELLED" ? "red" : "blue"}">${escapeHtml(sessionStatusLabels[session.status])}</span></td></tr>`;
  }).join("");
  const table = selected
    ? `<div class="table-wrap people-table"><table class="timesheet-table"><thead><tr><th>STT</th><th>Ngày</th><th>Lớp</th><th>Giờ dạy</th><th>Số giờ</th><th>Phòng</th><th>Điểm danh</th><th>Loại buổi</th><th>Trạng thái</th></tr></thead><tbody>${sessionRows || '<tr><td class="empty-cell" colspan="9">Không có buổi dạy nào khớp bộ lọc.</td></tr>'}</tbody></table></div>`
    : `<div class="table-wrap people-table"><table class="timesheet-table"><thead><tr><th>STT</th><th>Mã GV</th><th>Họ và tên</th><th>Giờ dạy lý thuyết</th><th>Nghỉ lễ</th><th>Nghỉ không lương</th><th>Dạy bù</th><th>Dạy thay</th><th>Dạy không tính phí</th><th>Test speaking</th><th>Kèm speaking</th><th>Kèm cá nhân</th><th>Kèm lớp</th><th>Tổng buổi</th><th>Chấm công thực tế</th><th>Ghi chú</th></tr></thead><tbody>${summaryRows || '<tr><td class="empty-cell" colspan="16">Chưa có buổi trên lịch dạy trong khoảng ngày này.</td></tr>'}</tbody></table></div>`;
  return `<div class="people-page"><div class="page-header"><div><h1>${selfView ? "Chấm công của tôi" : "Báo cáo chấm công"}</h1><p>Chọn Tháng để xem trọn tháng, hoặc chọn Từ ngày – Đến ngày để xem một khoảng ngày bất kỳ. Giờ dạy lý thuyết: cả khoảng ngày theo lịch của lớp (kể cả buổi giáo viên tick nghỉ). Các cột còn lại và chấm công thực tế cập nhật realtime — buổi học qua giờ kết thúc mới được tính. Nghỉ lễ: buổi admin tick nghỉ hoặc đã hủy — không lương. Nghỉ không lương: buổi giáo viên tick nghỉ hoặc được người khác dạy thay. Dạy bù: buổi bù xếp cho một buổi nghỉ, tính cho giáo viên dạy bù. Dạy thay: buổi theo lịch đổi sang giáo viên khác giáo viên chính của lớp. Dạy không tính phí: học viên không trả tiền nhưng giáo viên vẫn chấm công. Test speaking, Kèm speaking, Kèm cá nhân, Kèm lớp: lịch thêm xếp ở Lịch dạy. Mỗi ô ghi số giờ, dòng nhỏ bên dưới là số buổi đã dạy; Tổng buổi = mọi buổi đã dạy, giống file Xuất PDF. Chấm công thực tế = lý thuyết đã qua − nghỉ không lương + dạy bù + dạy thay + dạy không tính phí + test / kèm.</p></div></div><section class="card settings-card"><div class="card-header people-card-header timesheet-card-header">${filter}</div>${table}</section></div>`;
}

function payrollContractLabel(contract, payMode = payrollPayMode(contract)) {
  const kind = PAYROLL_CONTRACT_KIND_LABELS[payrollContractKind(contract)] || "Chưa có HĐ";
  return `${kind} · ${payMode === "MONTHLY" ? "lương tháng" : "theo giờ"}`;
}

function payrollPercent(value) {
  return `${(Number(value || 0) * 100).toLocaleString("vi-VN", { maximumFractionDigits: 1 })}%`;
}

function payrollDetailModal(row) {
  if (!row) return "";
  const month = row.month || payrollMonthKey();
  const range = payrollMonthRange(month);
  const sessions = [
    ...timesheetSessions(row.teacher.id, range).filter((session) => timesheetPaidFor(session, row.teacher.id) && isSessionElapsed(session)),
    ...timesheetCalendarEvents(row.teacher.id, range).filter((item) => isSessionElapsed(item)).map((item) => ({ ...item, isCalendarEvent: true })),
  ].sort((a, b) => `${b.date}${b.startTime}`.localeCompare(`${a.date}${a.startTime}`));
  const sessionRows = sessions.map((session, index) => {
    const cls = findBy(state.data.classes, session.classId);
    return `<tr><td class="cell-index">${index + 1}</td><td>${formatDateVi(session.date)}</td><td>${escapeHtml(session.isCalendarEvent ? `${CALENDAR_EVENT_LABELS[session.kind] || "Bổ trợ"} (bổ trợ)` : cls?.name || "—")}</td><td>${escapeHtml(session.startTime)}–${escapeHtml(session.endTime)}</td><td>${formatHours(sessionMinutesOf(session))}</td></tr>`;
  }).join("");
  const kpi = row.kpi || attendanceKpi(row.teacher.id, range, row.policy);
  const kpiText = kpi.eligible
    ? `${kpi.eligible - kpi.late}/${kpi.eligible} buổi · ${payrollPercent(kpi.onTimeRate)}`
    : "Chưa có buổi đã qua";
  const monthly = row.payMode === "MONTHLY";
  const salaryFormula = monthly
    ? `${vnd(row.hourlyRate)} × ${row.salaryHours} giờ lương (${PAYROLL_DAILY_HOURS} giờ × ${Number(row.paidDays).toLocaleString("vi-VN", { maximumFractionDigits: 2 })} ngày công)`
    : `${formatHours(Math.round(row.hours * 60))} giờ × ${vnd(row.hourlyRate)}`;
  const allowanceText = `${row.committedHours > 0 && row.payMode !== "MONTHLY" ? `${payrollPercent(row.allowanceRate)} giờ cam kết (${formatHours(Math.round(row.hours * 60))}/${row.committedHours} giờ)` : "Đủ mức"} · ${row.mealPerDay ? `Ăn trưa ${vnd(row.mealPerDay)} × ${row.workingDays} ngày = ${vnd(row.mealAllowance)}` : `Ăn ca ${vnd(row.mealAllowance)}`} · Điện thoại ${vnd(row.phoneAllowance)} · Xăng xe ${vnd(row.fuelAllowance)} · Đồng phục ${vnd(row.uniformAllowance)}${row.allowance ? ` · Khoản khác ${vnd(row.allowance)}` : ""}`;
  const taxText = row.taxExempt ? "Chủ doanh nghiệp — không khấu trừ thuế TNCN" : row.isLabor
    ? `Lũy tiến 5 bậc · BH ${payrollPercent(row.policy.employeeInsuranceRate)}`
    : row.gross >= row.policy.serviceTaxThreshold
      ? `Khấu trừ ${payrollPercent(row.policy.serviceTaxRate)}`
      : `Chưa đến ngưỡng ${vnd(row.policy.serviceTaxThreshold)}`;
  return `<div class="modal-backdrop" data-action="close-payroll-detail"><div class="modal-card payroll-detail" data-payroll-detail-card><div class="modal-head"><div><h2>Chi tiết lương</h2><p>${escapeHtml(row.teacher.fullName)} · ${escapeHtml(row.teacher.code)} · ${escapeHtml(monthLabel(month))} (${formatDateVi(range.from)} – ${formatDateVi(range.to)})</p></div><button class="close-btn" type="button" data-action="close-payroll-detail">×</button></div><div class="payroll-detail-body payroll-detail-split"><div class="payroll-detail-info"><dl class="session-view-grid"><div><dt>Loại hợp đồng</dt><dd>${escapeHtml(payrollContractLabel(row.contract, row.payMode))}</dd></div><div><dt>Đơn giá giờ</dt><dd>${vnd(row.hourlyRate)}<small class="people-subline">${row.policy.standardHourlyRate ? `Giờ công chuẩn ${vnd(row.policy.standardHourlyRate)} × hệ số ${Number(row.coefficient.toFixed(2)).toLocaleString("vi-VN")}` : "Chưa cấu hình giờ công chuẩn trong Cấu hình lương."}</small></dd></div><div><dt>Hệ số lương</dt><dd>${Number(row.coefficient.toFixed(2)).toLocaleString("vi-VN")}<small class="people-subline">Nhân với giờ công chuẩn của trung tâm ra đơn giá giờ.</small></dd></div><div><dt>Ngày công tính lương</dt><dd>${monthly ? `${Number(row.paidDays).toLocaleString("vi-VN", { maximumFractionDigits: 2 })} / ${row.workingDays} ngày` : "—"}<small class="people-subline">${monthly ? (row.overridePaidDays ? "Kế toán sửa tay" : row.unpaidLeaveDays ? `Ngày công chuẩn ${row.workingDays} − ${row.unpaidLeaveDays} ngày nghỉ không lương (cấu hình tháng)` : `Đủ ${row.workingDays} ngày công chuẩn — chưa cấu hình nghỉ không lương`) : ""}</small></dd></div><div><dt>Giờ dạy thực tế</dt><dd>${formatHours(Math.round(row.hours * 60))} giờ<small class="people-subline">${payrollPercent(row.quotaRate)} định mức ${row.quotaHours} giờ (${PAYROLL_DAILY_HOURS} giờ × ${row.quotaDays} ngày)</small></dd></div><div><dt>Lương cơ bản</dt><dd>${vnd(row.salary)}<small class="people-subline">${salaryFormula}</small></dd></div><div><dt>Phụ cấp tự tính</dt><dd>${row.autoAllowance ? vnd(row.autoAllowance) : "—"}<small class="people-subline">${allowanceText}</small></dd></div><div><dt>Lương năng suất</dt><dd>${vnd(row.productivityPay)}<small class="people-subline">${payrollPercent(row.onTimeRate)} đúng hạn + ${payrollPercent(row.quotaRate)} đạt định mức = ${payrollPercent(row.productivityRate)} × lương cơ bản</small></dd></div><div><dt>Điểm danh đúng hạn</dt><dd>${escapeHtml(kpiText)}<small class="people-subline">${kpi.late ? `${kpi.late} buổi điểm danh trễ — làm giảm % đúng hạn trong lương năng suất` : "Không có buổi trễ"}</small></dd></div><div><dt>Tổng thu nhập</dt><dd>${vnd(row.gross)}</dd></div><div><dt>BH NLD trừ</dt><dd>${row.isLabor ? vnd(row.insurance) : "—"}${row.isLabor ? `<small class="people-subline">${payrollPercent(row.policy.employeeInsuranceRate)} × ${vnd(row.insuranceBase)}${monthly ? "" : " · Tính trên lương giờ (giờ × đơn giá)"} · NSDLĐ ${payrollPercent(row.policy.employerInsuranceRate)}</small>` : ""}</dd></div><div><dt>Giảm trừ gia cảnh</dt><dd>${row.isLabor ? vnd(row.deduction) : "—"}${row.isLabor ? `<small class="people-subline">${vnd(row.policy.personalDeduction)} bản thân${row.dependents ? ` + ${row.dependents} NPT × ${vnd(row.policy.dependentDeduction)}` : ""}</small>` : ""}</dd></div><div><dt>Thu nhập tính thuế</dt><dd>${vnd(row.taxableIncome)}</dd></div><div><dt>Thuế TNCN</dt><dd>${vnd(row.tax)}<small class="people-subline">${taxText}</small></dd></div><div><dt>Tạm ứng</dt><dd>${vnd(row.advance)}</dd></div><div class="span-2"><dt>Thực lĩnh</dt><dd><strong>${vnd(row.net)}</strong><small class="people-subline">Thu nhập − BH − thuế − tạm ứng</small></dd></div></dl></div><aside class="payroll-attendance-panel"><div class="payroll-attendance-head"><h3>Chấm công thực tế ${escapeHtml(monthLabel(month))}</h3><span>${sessions.length} buổi · ${formatHours(Math.round(row.hours * 60))} giờ</span></div><div class="payroll-attendance-list">${sessions.length ? `<table><thead><tr><th>STT</th><th>Ngày</th><th>Lớp</th><th>Giờ dạy</th><th>Giờ</th></tr></thead><tbody>${sessionRows}</tbody></table>` : '<p class="payroll-attendance-empty">Chưa có buổi dạy nào đã qua trong kỳ.</p>'}</div></aside></div><div class="settings-modal-footer"><button class="primary-btn" type="button" data-payroll-slip="${escapeHtml(row.teacher.id)}">${icon("download")}Tải phiếu lương PDF</button>${row.teacher.role === "ACCOUNTANT" ? "" : `<button class="secondary-btn" type="button" data-timesheet-teacher="${escapeHtml(row.teacher.id)}">Xem chấm công</button>`}<button class="secondary-btn" type="button" data-action="close-payroll-detail">Đóng</button></div></div></div>`;
}

/**
 * Dữ liệu phiếu lương của một dòng báo cáo — gửi lên máy chủ để vẽ PDF A4.
 * Khoản bằng 0 bị lọc ra cho phiếu gọn; nhãn tiền dùng "đ" thường vì font PDF
 * không có glyph "₫".
 */
function payrollSlipPayload(row) {
  const month = row.month || payrollMonthKey();
  const range = payrollMonthRange(month);
  const center = state.data.settings?.center || {};
  const contract = row.contract || {};
  const policy = row.policy || payrollPolicy();
  const monthly = row.payMode === "MONTHLY";
  const money = (value) => Math.round(Number(value) || 0);
  const amountText = (value) => `${money(value).toLocaleString("vi-VN").replace(/,/g, ".")} đ`;
  const days = (value) => Number(value).toLocaleString("vi-VN", { maximumFractionDigits: 2 });
  const hoursText = `${formatHours(Math.round(row.hours * 60))} giờ`;
  const kpi = row.kpi || attendanceKpi(row.teacher.id, range, policy);
  return {
    teacherCode: row.teacher.code || "",
    monthKey: month,
    title: `PHIẾU LƯƠNG · ${monthLabel(month)}`,
    period: `Kỳ tính lương ${formatDateVi(range.from)} – ${formatDateVi(range.to)}`,
    issuedAt: formatDateVi(localDateKey(new Date())),
    center: {
      name: center.name || "Trung tâm Ngoại ngữ STEPS",
      address: center.address || "",
      contact: [center.phone, center.email].filter(Boolean).join(" · "),
    },
    info: [
      { label: row.teacher.role === "ACCOUNTANT" ? "Kế toán" : "Giáo viên", value: `${row.teacher.fullName} (${row.teacher.code})` },
      { label: "Hợp đồng", value: payrollContractLabel(contract, row.payMode) },
      { label: "Bộ phận / chức danh", value: contract.department || contract.jobTitle || "—" },
      { label: "Ngày công tính lương", value: monthly ? `${days(row.paidDays)} / ${row.workingDays} ngày` : "—" },
      { label: "Nghỉ phép / nghỉ không lương", value: `${days(row.paidLeaveDays || 0)} / ${days(row.unpaidLeaveDays || 0)} ngày` },
      { label: "Giờ dạy thực tế", value: hoursText },
      { label: "Định mức giờ", value: `${row.quotaHours} giờ · đạt ${payrollPercent(row.quotaRate)}` },
      { label: "Điểm danh đúng hạn", value: kpi.eligible ? `${kpi.eligible - kpi.late}/${kpi.eligible} buổi · ${payrollPercent(kpi.onTimeRate)}` : "Chưa có buổi nào" },
      { label: "Hệ số lương", value: days(row.coefficient) },
      { label: "Đơn giá giờ", value: `${amountText(row.hourlyRate)}/giờ · hệ số ${days(row.coefficient)}` },
      contract.bankAccount ? { label: "Nhận lương qua TK", value: `${contract.bankAccount}${contract.bankName ? ` · ${contract.bankName}` : ""}` } : null,
      contract.taxCode ? { label: "Mã số thuế", value: contract.taxCode } : null,
    ].filter(Boolean),
    income: [
      { label: monthly ? `Lương cơ bản · ${amountText(row.hourlyRate)} × ${row.salaryHours} giờ (${PAYROLL_DAILY_HOURS} giờ × ${days(row.paidDays)} ngày công)` : `Lương giờ · ${hoursText} × ${amountText(row.hourlyRate)}`, amount: money(row.salary) },
      { label: "Phụ cấp ăn trưa", amount: money(row.mealAllowance) },
      { label: "Phụ cấp điện thoại", amount: money(row.phoneAllowance) },
      { label: "Phụ cấp xăng xe", amount: money(row.fuelAllowance) },
      { label: "Phụ cấp đồng phục", amount: money(row.uniformAllowance) },
      { label: `Lương năng suất · ${payrollPercent(row.onTimeRate)} đúng hạn + ${payrollPercent(row.quotaRate)} đạt định mức`, amount: money(row.productivityPay) },
      { label: "Phụ cấp khác", amount: money(row.allowance) },
    ].filter((item) => item.amount > 0),
    deductions: [
      { label: row.isLabor ? `Bảo hiểm người lao động · ${payrollPercent(policy.employeeInsuranceRate)} × ${amountText(row.insuranceBase)}` : "Bảo hiểm người lao động", amount: money(row.insurance) },
      { label: row.isLabor ? `Thuế TNCN lũy tiến 5 bậc · giảm trừ ${amountText(row.deduction)}${row.dependents ? ` (${days(row.dependents)} người phụ thuộc)` : ""}` : `Thuế dịch vụ ${payrollPercent(policy.serviceTaxRate)}`, amount: money(row.tax) },
      { label: "Tạm ứng trừ vào lương", amount: money(row.advance) },
    ].filter((item) => item.amount > 0),
    gross: money(row.gross),
    totalDeduct: money(row.insurance) + money(row.tax) + money(row.advance),
    net: money(row.net),
    note: row.inputs?.note ? `Ghi chú của kế toán: ${row.inputs.note}` : "",
  };
}

/** Bấm "Tải phiếu lương": máy chủ vẽ PDF rồi trình duyệt lưu thẳng file về máy. */
async function downloadPayrollSlip(row, button) {
  if (!row) return;
  if (button) button.disabled = true;
  try {
    const response = await fetch("/api/payroll/slip-pdf", {
      method: "POST",
      credentials: "same-origin",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payrollSlipPayload(row)),
    });
    if (!response.ok) {
      const body = await response.json().catch(() => ({}));
      throw new Error(body.error || "Không tạo được phiếu lương PDF.");
    }
    const blob = await response.blob();
    const match = /filename="([^"]+)"/.exec(response.headers.get("Content-Disposition") || "");
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = match?.[1] || "phieu-luong.pdf";
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(link.href), 1000);
    toast(`Đã tải phiếu lương của ${row.teacher.fullName}.`);
  } catch (error) {
    toast(error.message);
  } finally {
    if (button) button.disabled = false;
  }
}


/**
 * Popup sửa nhanh một tháng lương của giáo viên — đúng ba khoản biến động:
 * ngày nghỉ phép, ngày nghỉ không lương và tạm ứng. Hợp đồng, hệ số lương và phụ
 * cấp cấu hình ở tab Hợp đồng của trang giáo viên.
 */
function payrollAdjustModal(row) {
  if (!row) return "";
  const month = row.month || payrollMonthKey();
  const inputs = row.inputs || {};
  const monthly = row.payMode === "MONTHLY";
  const numeric = (value) => value === "" || value === null || value === undefined ? "" : String(value);
  const days = (value) => Number(value).toLocaleString("vi-VN", { maximumFractionDigits: 2 });
  return `<div class="modal-backdrop" data-action="close-payroll-edit"><div class="modal-card payroll-adjust" data-payroll-edit-card><div class="modal-head"><div><h2>Chỉnh sửa lương ${escapeHtml(monthLabel(month))}</h2><p>${escapeHtml(row.teacher.fullName)} · ${escapeHtml(row.teacher.code)}</p></div><button class="close-btn" type="button" data-action="close-payroll-edit">×</button></div><form id="payroll-edit-form" data-teacher-id="${escapeHtml(row.teacher.id)}" data-month="${escapeHtml(month)}"><div class="form-grid"><label class="field"><span>Ngày nghỉ phép trong tháng</span><input class="input" type="number" min="0" max="31" step="1" name="paidLeaveDays" value="${numeric(inputs.paidLeaveDays)}" placeholder="0" /><small>Nghỉ phép vẫn hưởng lương — chỉ ghi nhận để theo dõi phép năm.</small></label><label class="field"><span>Ngày nghỉ không lương</span><input class="input" type="number" min="0" max="31" step="1" name="unpaidLeaveDays" value="${numeric(inputs.unpaidLeaveDays)}" placeholder="0" /><small>${monthly ? `Trừ nguyên ngày: ${days(row.workingDays)} − ${days(inputs.unpaidLeaveDays || 0)} = ${days(row.autoPaidDays)} ngày công.` : "Không áp dụng cho lương giờ — lương tính theo giờ dạy."}</small></label>${monthly ? "" : `<label class="field"><span>Giờ công tháng này</span><input class="input" type="number" min="0" max="744" step="0.5" name="hours" value="${numeric(inputs.hours)}" placeholder="${numeric(row.actualHours ? Math.round(row.actualHours * 100) / 100 : "") || "0"}" /><small>Bỏ trống = lấy giờ chấm công (${formatHours(Math.round(row.actualHours * 60))}). Trợ giảng không có lịch dạy thì nhập giờ công tại đây.</small></label>`}<label class="field"><span>Tạm ứng</span><input class="input" type="number" min="0" step="100000" name="advance" value="${numeric(inputs.advance)}" placeholder="0" /><small>Trừ trực tiếp vào thực lĩnh tháng này.</small></label></div><div class="settings-modal-footer"><button class="secondary-btn" type="button" data-action="close-payroll-edit">Hủy</button><button class="primary-btn" type="submit">Lưu</button></div></form></div></div>`;
}

function payrollPage() {
  const query = state.payrollQuery.trim().toLowerCase();
  const department = state.payrollDepartment;
  const month = payrollMonthKey();
  const range = payrollMonthRange(month);
  const allRows = payrollMonthRows(month, range);
  // Giữ lại đúng dòng đang hiển thị để nút tải phiếu lương không phải tính lại
  // cả bảng lương khi bấm (lúc đó không còn cache của vòng render).
  payrollRenderedRows = { month, rows: allRows };
  const items = allRows.filter((row) => (!query || `${row.teacher.fullName} ${row.teacher.code}`.toLowerCase().includes(query)) && payrollDepartmentMatches(row, department));
  const configuredRate = Math.max(0, Math.round(Number(payrollPolicy().standardHourlyRate) || 0));
  const monthOptions = timesheetMonthKeys().map((key) => `<option value="${key}" ${key === month ? "selected" : ""}>${escapeHtml(monthLabel(key))}</option>`).join("");
  const departmentOptions = PAYROLL_DEPARTMENT_FILTERS.map((item) => `<option value="${item.value}" ${item.value === department ? "selected" : ""}>${escapeHtml(item.label)}</option>`).join("");
  const money = (value) => value ? vnd(value) : "—";
  const visibleColumns = PAYROLL_COLUMNS.filter((column) => !isPayrollColumnHidden(column.key));
  const headerCells = `${visibleColumns.map((column) => `<th>${escapeHtml(column.label)}</th>`).join("")}<th class="settings-actions-cell">Thao tác</th>`;
  const rows = items.map((row, index) => {
    const cells = payrollRowCells(row, index, money);
    return `<tr>${visibleColumns.map((column) => cells[column.key]).join("")}<td class="settings-actions-cell"><div class="row-actions settings-row-actions"><button class="mini-btn" data-payroll-detail="${escapeHtml(row.teacher.id)}" title="Chi tiết lương">${icon("eye")}</button><button class="mini-btn" data-payroll-edit="${escapeHtml(row.teacher.id)}" title="Nhập ngày nghỉ &amp; tạm ứng">${icon("pencil")}</button></div></td></tr>`;
  }).join("");
  // Dòng tổng bám đáy khung bảng: cộng theo đúng các dòng đang hiển thị (đã qua bộ lọc).
  const totalLabelKey = visibleColumns.find((column) => column.key === "name")?.key || visibleColumns.find((column) => column.key !== "index")?.key || "";
  const totalCells = visibleColumns.map((column) => {
    if (column.key === totalLabelKey) return `<td><strong>Tổng cộng</strong></td>`;
    const field = PAYROLL_TOTAL_FIELDS[column.key];
    if (!field) return "<td></td>";
    const total = items.reduce((sum, row) => sum + (Number(row[field]) || 0), 0);
    return `<td><strong>${vnd(total)}</strong></td>`;
  }).join("");
  const totalRow = `<tr>${totalCells}<td class="settings-actions-cell"></td></tr>`;
  const detail = items.find((row) => row.teacher.id === state.payrollDetail);
  const editing = items.find((row) => row.teacher.id === state.payrollEdit)
    || (state.payrollEdit ? payrollRowFor(payrollStaffById(state.payrollEdit) || { id: state.payrollEdit, code: "", fullName: "—" }, 0, month) : null);
  return `<div class="people-page payroll-page"><div class="page-header"><div><h1>Báo cáo lương</h1><p>Trung tâm cấu hình một <strong>giờ công chuẩn</strong> (số tiền cho 1 giờ dạy chuẩn, trong Cấu hình lương); đơn giá giờ của giáo viên = giờ công chuẩn × <strong>hệ số lương riêng</strong> của người đó. Cột <strong>Lương cơ bản</strong> ghi lương cứng cả tháng (lương tháng = ${PAYROLL_DAILY_HOURS} giờ × ngày công chuẩn của tháng × đơn giá giờ) hoặc tiền 1 giờ dạy (lương giờ). Cột <strong>Ngày công/Giờ công</strong> ghi số ngày công chuẩn của tháng (các ngày trừ Chủ nhật) hoặc số giờ dạy thực tế. <strong>Lương theo công</strong> = Lương cơ bản ÷ ngày công chuẩn × ngày công tính lương (ngày công chuẩn − ngày nghỉ không lương) hoặc × số giờ dạy. Phụ cấp ăn ca, điện thoại, xăng xe, đồng phục trả NGUYÊN mức tháng cho cả lương giờ lẫn lương tháng, không chia theo ngày công. Không còn thưởng doanh số. <strong>Lương năng suất</strong> = Lương theo công × (% đúng hạn + % định mức giờ), trong đó % định mức giờ = giờ dạy thực tế ÷ ${PAYROLL_DAILY_HOURS} giờ × ngày công; hai tỷ lệ cộng thẳng, không trần, áp dụng cho cả lương giờ. Thuế TNCN 5 bậc.</p>${configuredRate ? "" : '<p class="payroll-alert">Chưa cấu hình <strong>giờ công chuẩn</strong> — toàn bộ đơn giá giờ đang bằng 0 nên lương chỉ còn phụ cấp. Vào Cấu hình › Cấu hình lương để nhập số tiền cho 1 giờ dạy chuẩn.</p>'}</div></div><section class="card settings-card"><div class="card-header payroll-report-head"><div class="card-heading"><div><h2>Bảng lương nhân sự · ${escapeHtml(monthLabel(month))} (${items.length})</h2></div></div><form id="payroll-filter-form" class="payroll-filters"><select class="input" name="month" title="Tháng lương">${monthOptions}</select><select class="input" name="department" title="Phòng ban">${departmentOptions}</select><input class="input" name="q" value="${escapeHtml(state.payrollQuery)}" placeholder="Tìm kiếm..." title="Tìm kiếm theo tên hoặc mã nhân sự" /><div class="payroll-filter-actions">${payrollColumnMenu()}<div class="timesheet-export"><button class="secondary-btn" type="button" data-payroll-export>${icon("download")}Xuất Excel</button></div></div></form></div><div class="table-wrap people-table"><table class="payroll-table"><thead><tr>${headerCells}</tr></thead><tbody>${rows || `<tr><td class="empty-cell" colspan="${visibleColumns.length + 1}">Không có nhân sự phù hợp với bộ lọc.</td></tr>`}</tbody><tfoot>${totalRow}</tfoot></table></div></section>${detail ? payrollDetailModal(detail) : ""}${editing ? payrollAdjustModal(editing) : ""}</div>`;
}

function forecastDueStatus(row, today = localDateKey(new Date())) {
  if (row.status === "SETTLED") return { key: "SETTLED", label: "Đã hoàn tất", tone: "green", days: null };
  const days = Math.round((localDate(row.dueDate).getTime() - localDate(today).getTime()) / 86400000);
  if (days < 0) return { key: "OVERDUE", label: "Quá hạn", tone: "red", days };
  if (days <= 7) return { key: "DUE_SOON", label: "Sắp đến hạn", tone: "amber", days };
  return { key: "ON_TRACK", label: "Trong hạn", tone: "blue", days };
}

function forecastTimingLabel(status) {
  if (status.days === null) return "Đã xử lý";
  if (status.days < 0) return `Quá ${Math.abs(status.days)} ngày`;
  if (status.days === 0) return "Đến hạn hôm nay";
  return `Còn ${status.days} ngày`;
}

function financeForecastRows(today = localDateKey(new Date())) {
  return perfMemo("ffr", today, () => financeForecastRowsInner(today));
}

function financeForecastRowsInner(today = localDateKey(new Date())) {
  const key = today.slice(0, 7);
  const tuitionRows = [];
  const studentsById = perfMaps().studentsById;
  for (const cls of state.data.classes || []) {
    if (cls.status !== "ACTIVE" || cls.billingEnabled === false) continue;
    for (const studentId of cls.studentIds || []) {
      const student = studentsById.get(studentId);
      if (!student || student.status !== "STUDYING" || student.tuitionExempt) continue;
      // Phiếu cùng lớp đang thu thật (đã chốt/thu một phần/lớp đang thu) của
      // học viên "đã đóng" theo buổi vẫn là khoản dự thu — không bỏ qua.
      if (classBillingMode(cls) === "COURSE" && studentTuitionPaid(student, cls) && !sameClassDueAmount(student, cls)) continue;
      const quote = tuitionCollectionQuote(student, cls, key);
      const quoteRemaining = tuitionQuoteRemaining(student, cls, quote);
      if (quoteRemaining <= 0) continue;
      const oldestMonth = quote.months?.[0] || key;
      tuitionRows.push({
        id: `auto-tuition|${student.id}|${cls.id}|${quote.billKey}`,
        kind: "IN",
        source: "TUITION",
        category: "Học phí",
        description: `${student.fullName} · ${cls.name} · ${quote.period.split(" · ")[0]}`,
        amount: quoteRemaining,
        dueDate: classBillingMode(cls) === "MONTHLY" ? `${oldestMonth}-10` : (classCourseWindowByIndex(cls, quote.courseIndex || 1).start || classCourseStartDate(cls)),
        status: "PLANNED",
        branchId: cls.branchId || "",
        studentId: student.id,
        classId: cls.id,
      });
    }
  }

  const [year, month] = key.split("-").map(Number);
  const monthEnd = localDateKey(new Date(year, month, 0, 12));
  const monthStart = `${key}-01`;
  // Chỉ giáo viên đã có hồ sơ lương mới tính được dự chi — chưa cấu hình hợp
  // đồng thì không biết đơn giá giờ nên không đẩy khoản 0đ vào dự chi.
  const payrollRows = payrollMonthRows(key, { from: monthStart, to: today }).filter((row) => row.net > 0).map((row) => ({
    id: `auto-payroll|${row.teacher.id}|${key}`,
    kind: "OUT",
    source: "PAYROLL",
    category: "Lương",
    description: `Lương đã phát sinh ${monthLabel(key).toLowerCase()} · ${row.teacher.fullName}`,
    amount: row.net,
    dueDate: monthEnd,
    status: "PLANNED",
    branchId: "",
    teacherId: row.teacher.id,
  }));
  const manualRows = (financeBook().forecasts || []).map((row) => ({ ...row, source: "MANUAL" }));
  return [...tuitionRows, ...payrollRows, ...manualRows].map((row) => ({ ...row, due: forecastDueStatus(row, today) }));
}

function financeForecastModal(rows = []) {
  if (state.financeModal?.kind !== "forecast-view") return "";
  const current = rows.find((row) => row.id === state.financeModal.id);
  if (!current) return "";
  const branch = findBy(state.data.settings?.branches || [], current.branchId);
  const source = current.source === "TUITION" ? "Tổng hợp từ học phí" : current.source === "PAYROLL" ? "Tổng hợp từ báo cáo lương" : "Khoản dự kiến đã ghi nhận";
  return `<div class="modal-backdrop" data-action="close-finance-modal"><div class="modal-card forecast-view-modal" data-finance-modal-card>
    <div class="modal-head"><div><h2>Chi tiết khoản ${current.kind === "IN" ? "dự thu" : "dự chi"}</h2><p>Thông tin chỉ đọc từ kế hoạch dòng tiền.</p></div><button class="close-btn" type="button" data-action="close-finance-modal">×</button></div>
    <div class="forecast-view-body">
      <div class="forecast-view-amount ${current.kind === "IN" ? "positive" : "negative"}"><span>${current.kind === "IN" ? "Dự thu" : "Dự chi"}</span><strong>${vnd(current.amount)}</strong></div>
      <dl class="forecast-view-grid">
        <div><dt>Khoản mục</dt><dd>${escapeHtml(current.category)}</dd></div>
        <div><dt>Tình trạng</dt><dd><span class="badge badge-${current.due.tone}">${escapeHtml(current.due.label)}</span></dd></div>
        <div><dt>Hạn thanh toán</dt><dd>${formatDateVi(current.dueDate)}<small>${escapeHtml(forecastTimingLabel(current.due))}</small></dd></div>
        <div><dt>Phạm vi</dt><dd>${escapeHtml(branch?.name || "Toàn công ty")}</dd></div>
        <div class="span-2"><dt>Nội dung</dt><dd>${escapeHtml(current.description)}</dd></div>
        <div class="span-2"><dt>Nguồn dữ liệu</dt><dd>${escapeHtml(source)}</dd></div>
      </dl>
    </div>
    <div class="settings-modal-footer"><button class="primary-btn" type="button" data-action="close-finance-modal">Đóng</button></div>
  </div></div>`;
}

function financeForecastPage() {
  const allRows = financeForecastRows();
  const query = state.forecastQuery.trim().toLowerCase();
  const filtered = allRows.filter((row) => {
    const branch = findBy(state.data.settings?.branches || [], row.branchId);
    return (!query || `${row.category} ${row.description} ${branch?.name || ""}`.toLowerCase().includes(query))
      && (!state.forecastKind || row.kind === state.forecastKind)
      && (!state.forecastStatus || row.due.key === state.forecastStatus)
      && (!state.forecastFrom || row.dueDate >= state.forecastFrom)
      && (!state.forecastTo || row.dueDate <= state.forecastTo);
  }).sort((a, b) => {
    const order = { OVERDUE: 0, DUE_SOON: 1, ON_TRACK: 2, SETTLED: 3 };
    return order[a.due.key] - order[b.due.key] || a.dueDate.localeCompare(b.dueDate) || a.description.localeCompare(b.description, "vi");
  });
  const open = allRows.filter((row) => row.status !== "SETTLED");
  const overdueIncome = open.filter((row) => row.kind === "IN" && row.due.key === "OVERDUE");
  const currentMonth = localDateKey(new Date()).slice(0, 7);
  const monthlyIncomeRows = open.filter((row) => row.kind === "IN" && row.dueDate.startsWith(currentMonth));
  const monthlyIncome = monthlyIncomeRows.reduce((sum, row) => sum + row.amount, 0);
  const monthlyExpenseRows = open.filter((row) => row.kind === "OUT" && row.dueDate.startsWith(currentMonth));
  const monthlyExpense = monthlyExpenseRows.reduce((sum, row) => sum + row.amount, 0);
  const overdueIncomeAmount = overdueIncome.reduce((sum, row) => sum + row.amount, 0);
  const tableRows = filtered.map((row, index) => {
    const branch = findBy(state.data.settings?.branches || [], row.branchId);
    const automatic = row.source !== "MANUAL";
    return `<tr><td class="cell-index">${index + 1}</td><td><span class="badge badge-${row.kind === "IN" ? "green" : "red"}">${row.kind === "IN" ? "Dự thu" : "Dự chi"}</span></td><td><strong>${escapeHtml(row.category)}</strong><small class="people-subline forecast-source">${automatic ? "Tự động" : "Đã ghi nhận"}${branch ? ` · ${escapeHtml(branch.name)}` : ""}</small></td><td class="forecast-description" title="${escapeHtml(row.description)}">${escapeHtml(row.description)}</td><td><strong>${formatDateVi(row.dueDate)}</strong></td><td class="money-cell ${row.kind === "IN" ? "positive" : "negative"}">${vnd(row.amount)}</td><td><span class="badge badge-${row.due.tone}">${row.due.label}</span></td><td class="forecast-note ${row.due.key === "OVERDUE" ? "danger-text" : ""}">${forecastTimingLabel(row.due)}</td><td class="settings-actions-cell"><button class="secondary-btn forecast-view-btn" type="button" data-forecast-view="${escapeHtml(row.id)}">Xem</button></td></tr>`;
  }).join("");
  return `<div class="people-page forecast-page">
    <div class="forecast-summary-grid">
      <section class="card forecast-summary"><small>Phải thu tháng này</small><strong>${vnd(monthlyIncome)}</strong><span>${monthlyIncomeRows.length} khoản</span></section>
      <section class="card forecast-summary"><small>Phải trả tháng này</small><strong>${vnd(monthlyExpense)}</strong><span>${monthlyExpenseRows.length} khoản</span></section>
      <section class="card forecast-summary"><small>Khoản thu quá hạn</small><strong>${vnd(overdueIncomeAmount)}</strong><span>${overdueIncome.length} khoản</span></section>
    </div>
    <section class="card settings-card forecast-list-card"><div class="card-header forecast-list-head"><div><h2>Kế hoạch dòng tiền (${filtered.length})</h2><p>Trang tổng hợp chỉ đọc; bấm Xem để mở chi tiết từng khoản.</p></div><form id="forecast-filter-form" class="forecast-filters"><label class="field"><span>Tìm kiếm</span><input class="input" name="q" value="${escapeHtml(state.forecastQuery)}" placeholder="Khoản mục, nội dung, chi nhánh..." /></label><label class="field"><span>Loại</span><select class="input" name="kind"><option value="">Tất cả</option><option value="IN" ${state.forecastKind === "IN" ? "selected" : ""}>Dự thu</option><option value="OUT" ${state.forecastKind === "OUT" ? "selected" : ""}>Dự chi</option></select></label><label class="field"><span>Tình trạng</span><select class="input" name="status"><option value="">Tất cả</option><option value="OVERDUE" ${state.forecastStatus === "OVERDUE" ? "selected" : ""}>Quá hạn</option><option value="DUE_SOON" ${state.forecastStatus === "DUE_SOON" ? "selected" : ""}>Sắp đến hạn</option><option value="ON_TRACK" ${state.forecastStatus === "ON_TRACK" ? "selected" : ""}>Trong hạn</option><option value="SETTLED" ${state.forecastStatus === "SETTLED" ? "selected" : ""}>Đã hoàn tất</option></select></label><label class="field"><span>Từ hạn</span><input class="input" type="date" name="from" value="${state.forecastFrom}" /></label><label class="field"><span>Đến hạn</span><input class="input" type="date" name="to" value="${state.forecastTo}" /></label></form></div><div class="table-wrap people-table forecast-table"><table><thead><tr><th>STT</th><th>Loại</th><th>Khoản mục</th><th>Nội dung</th><th>Hạn thanh toán</th><th>Số tiền</th><th>Tình trạng</th><th>Ghi chú</th><th class="settings-actions-cell">Chi tiết</th></tr></thead><tbody>${tableRows || '<tr><td class="empty-cell" colspan="9">Không có khoản dự thu - dự chi phù hợp.</td></tr>'}</tbody></table></div></section>
    ${financeForecastModal(allRows)}
  </div>`;
}

function financePage() {
  const receivableMatch = state.route.match(/^\/ke-toan\/(?:hoc-phi|khoan-thu)\/([^/]+)$/);
  if (receivableMatch) return receivablePayPage(decodeURIComponent(receivableMatch[1]));
  if (state.route.startsWith("/ke-toan/thu-chi")) return cashbookPage();
  if (state.route.startsWith("/ke-toan/du-thu-du-chi")) return financeForecastPage();
  if (state.route.startsWith("/ke-toan/doi-soat")) return visibleFinanceNavPaths.has("/ke-toan/doi-soat") ? reconPage() : tuitionPage();
  if (state.route.startsWith("/ke-toan/cham-cong")) return timesheetPage();
  if (state.route.startsWith("/ke-toan/luong")) return payrollPage();
  if (state.route.startsWith("/ke-toan/khoan-thu")) return tuitionPage();
  if (state.route.startsWith("/ke-toan/sepay")) return sepayTransactionsPage();
  if (state.route.startsWith("/ke-toan/can-duyet")) return needsReviewPage();
  if (state.route.startsWith("/ke-toan/hoa-don")) return invoicesPage();
  if (state.route.startsWith("/ke-toan/tin-zalo")) return zaloMessagesPage();
  return tuitionPage();
}

function sepayBook() {
  return financeBook().sepay || { settings: {}, receivables: [], paymentOrders: [], bankTransactions: [], payments: [], receipts: [], invoices: [], credits: [], webhookLogs: [] };
}

// Mốc golive: nhật ký thu chi / đối soát / biên lai / hóa đơn / giao dịch SePay
// từ trước ngày này bị ẩn khỏi giao diện — chỉ ẩn hiển thị, dữ liệu vẫn giữ
// nguyên trong DB và nghiệp vụ tính toán phía server không đổi.
const FINANCE_HISTORY_SINCE = "2026-10-01";
function financeHistoryVisible(dateValue) {
  const raw = String(dateValue || "");
  if (!raw) return false;
  // ISO có múi giờ (Z) lưu UTC → quy về ngày giờ VN; chuỗi naive "YYYY-MM-DD[ HH:mm]" đã là giờ VN.
  const vnDay = /(Z|[+-]\d{2}:?\d{2})\s*$/i.test(raw) && !Number.isNaN(new Date(raw).getTime())
    ? new Date(new Date(raw).getTime() + 7 * 3600000).toISOString().slice(0, 10)
    : raw.slice(0, 10);
  return vnDay >= FINANCE_HISTORY_SINCE;
}

function sepayStatusSnapshot() {
  return JSON.stringify(sepayBook().receivables.map((row) => [row.id, row.status, row.amountPaid, row.balanceDue]));
}

function applySepayFinance(finance, message) {
  const prev = sepayStatusSnapshot();
  state.data.finance = finance;
  if (prev !== sepayStatusSnapshot()) state.sepayFlash = true;
  render();
  if (message) toast(message);
}

function receivableStatusBadge(status) {
  const jump = state.sepayFlash ? " sy-status-jump" : "";
  if (status === "PAID") return `<span class="badge badge-green${jump}">Đã thanh toán</span>`;
  if (status === "PARTIALLY_PAID") return `<span class="badge badge-amber${jump}">Thanh toán một phần</span>`;
  if (status === "OVERPAID") return `<span class="badge badge-blue${jump}">Trả thừa</span>`;
  if (status === "OPEN") return `<span class="badge badge-amber${jump}">Chưa thanh toán</span>`;
  return `<span class="badge${jump}">${escapeHtml(status)}</span>`;
}

