    return `<tr><td class="cell-index">${index + 1}</td><td>${formatDateVi(row.date)}</td><td><button class="table-link" data-nav="/lop-hoc/${encodeURIComponent(cls?.id || "")}">${escapeHtml(cls?.name || "Lớp học")}</button></td><td>${escapeHtml(row.startTime)}–${escapeHtml(row.endTime)}</td><td>${escapeHtml(teacher?.fullName || "Chưa phân công")}</td><td>${escapeHtml(room?.name || "Chưa xếp phòng")}</td><td>${escapeHtml(row.topic)}</td><td>${badge}</td></tr>`;
