    const checkboxes = [...classOffForm.querySelectorAll("input[name='offSession']")];
    state.classOffDraftSelected = checkboxes.filter((item) => item.checked).map((item) => item.value);
    // Thu khóa: mọi buổi nghỉ (học vụ, GV) và "học không tính phí" đều không
    // chiếm suất — khóa tự giãn để bù, số buổi tính phí của khóa không đổi.
    // Thu tháng: GV nghỉ vẫn tính phí trong tháng, buổi nghỉ học vụ/không tính
