    const numbered = classOffForm.dataset.mode === "COURSE"
      ? checkboxes.filter((item) => item.dataset.teacherOff !== "1" && item.dataset.noFee !== "1" && item.dataset.unnumbered !== "1")
      : checkboxes;
    const offCount = numbered.filter((item) => item.checked).length;
    const gapOffCount = classOffForm.dataset.mode === "COURSE" ? numbered.filter((item) => item.dataset.gapOff === "1").length : 0;
    const extraCount = classOffForm.dataset.mode === "COURSE" ? classOffForm.querySelectorAll("[data-extra]").length : 0;
    const noFeeCount = classOffForm.dataset.mode === "MONTHLY" ? checkboxes.filter((item) => item.dataset.noFee === "1").length : 0;
    const billable = classOffForm.dataset.mode === "COURSE"
      ? numbered.length - gapOffCount
      : numbered.length - offCount - noFeeCount;
    const setOffText = (attr, text) => classOffForm.querySelectorAll(`[${attr}]`).forEach((el) => { el.textContent = text; });
    setOffText("data-off-total", `${numbered.length + extraCount} buổi`);
