    setOffText("data-billable-count", `${billable} buổi`);
    const materialsAmount = Math.max(0, Math.round(Number(classOffForm.querySelector("#class-materials-amount")?.value) || 0));
    setOffText("data-billable-amount", vnd(billable * Number(classOffForm.dataset.sessionPrice || 0) + materialsAmount));
