      state.classCourseConfigFor = "";
      await refreshAudit();
      render();
      toast(courseIndex === 1 ? "Đã lưu cấu hình lịch khóa và các buổi nghỉ." : `Đã lưu các ngày nghỉ của khóa ${courseIndex}.`);
