    const hint = document.querySelector("[data-collect-amount-hint]");
    if (hint) hint.innerHTML = collectAmountHint(Number(input.dataset.due) || 0, amount, input.dataset.mode === "COURSE");
    const submit = document.querySelector("[data-collect-submit]");
