  document.querySelector("#collect-tuition-form")?.addEventListener("submit", async (event) => {
    event.preventDefault();
    const form = event.currentTarget;
    const fd = new FormData(form);
    const amountInput = form.querySelector("[data-collect-amount]");
    const amount = parseAmountInput(fd.get("amount"));
    const due = Number(amountInput?.dataset.due) || 0;
    const carry = Number(amountInput?.dataset.carry) || 0;
    if (amountInput && amount <= 0) return toast("Nhập số tiền thực thu.");
    // Thu đủ đúng phiếu (không có truy thu) giữ nguyên đường thu cũ; thu thiếu / dư /
    // có truy thu gửi số tiền để server phân bổ: truy thu → kỳ này → thu trước kỳ sau.
    const sendAmount = amountInput && (amount !== due || carry > 0);
    if (sendAmount && amount > due && !confirm(due > 0
      ? `Thu ${vnd(amount)}, dư ${vnd(amount - due)} so với công nợ.\nPhần dư ghi là thu trước cho kỳ sau (phiếu kỳ sau tự trừ). Tiếp tục?`
      : `Học viên đã hết nợ. Ghi ${vnd(amount)} là thu trước cho kỳ sau?`)) return;
    try {
      const result = await api("/api/finance/sepay", {
        method: "POST",
        body: JSON.stringify({
          action: "collect",
          studentId: form.dataset.studentId,
          classId: form.dataset.classId,
          method: String(fd.get("method") || "TRANSFER"),
          note: String(fd.get("note") || ""),
          ...(form.dataset.courseIndex ? { courseIndex: Number(form.dataset.courseIndex) } : {}),
          // Thu thủ công từ hàng đợi Giao dịch lệch: luôn gửi số tiền + mã giao dịch để server
          // ghi ngày chứng từ = ngày GD và gỡ giao dịch khỏi hàng đợi trong cùng lượt ghi.
          ...(sendAmount || state.financeModal?.reviewTxId || form.dataset.collectMonth ? { amount } : {}),
          ...(form.dataset.collectMonth ? { month: form.dataset.collectMonth } : {}),
          ...(state.financeModal?.reviewTxId ? { reviewTransactionId: state.financeModal.reviewTxId } : {}),
        }),
      });
      state.data.finance = result.finance;
      if (result.students) state.data.students = result.students;
      state.financeModal = null;
      try { if (state.role === "ADMIN") state.data.auditLogs = (await api("/api/audit-logs")).items; } catch { /* kế toán không tải nhật ký */ }
      render();
      const collectedNote = !sendAmount ? "Đã thu học phí." : amount < due
        ? `Đã thu ${vnd(amount)} — còn thiếu ${vnd(due - amount)}, tự truy thu ở phiếu kỳ sau.`
        : amount > due ? `Đã thu ${vnd(amount)} — ${vnd(amount - due)} ghi thu trước, phiếu kỳ sau tự trừ.` : `Đã thu ${vnd(amount)}.`;
      toast([collectedNote, zaloMessageNote(result.zaloMessage)].filter(Boolean).join(" "));
    } catch (error) { toast(error.message); }
  });
