  document.querySelector("#payroll-edit-form")?.addEventListener("submit", async (event) => {
    event.preventDefault();
    const form = event.currentTarget;
    const teacherId = String(form.dataset.teacherId || "");
    const month = String(form.dataset.month || "");
    if (!teacherId || !/^\d{4}-(0[1-9]|1[0-2])$/.test(month)) return toast("Thiếu giáo viên hoặc tháng lương.");
    const fd = new FormData(form);
    const days = (name) => Math.max(0, Math.min(31, Math.round(Number(fd.get(name)) || 0)));
    // Giờ công chốt tay chỉ có ở lương giờ; để trống thì xoá ghi đè, quay lại lấy giờ chấm công.
    const hoursValue = String(fd.get("hours") ?? "").trim();
    const hoursOverride = fd.has("hours") ? (hoursValue === "" ? undefined : Math.max(0, Math.min(744, Math.round(Number(hoursValue) * 100) / 100))) : undefined;
    const config = structuredClone(payrollConfig());
    config.months = { ...(config.months || {}) };
    // Popup chỉ sửa các khoản biến động — hợp đồng, phụ cấp và thưởng để ở tab Hợp đồng.
    config.months[month] = {
      ...(config.months[month] || {}),
      [teacherId]: {
        ...(config.months[month]?.[teacherId] || {}),
        paidLeaveDays: days("paidLeaveDays"),
        unpaidLeaveDays: days("unpaidLeaveDays"),
        ...(fd.has("hours") ? { hours: hoursOverride } : {}),
        advance: Math.max(0, Math.round(Number(fd.get("advance")) || 0)),
      },
    };
    try {
      const result = await api("/api/payroll-config", { method: "PUT", body: JSON.stringify({ config }) });
      state.data.payrollConfig = result.config;
      state.payrollEdit = "";
      render();
      toast("Đã lưu điều chỉnh lương.");
    } catch (error) {
      toast(error.message);
    }
  });
