  document.querySelector("#sepay-qr-file")?.addEventListener("change", (event) => {
    const input = event.currentTarget;
    const file = input.files?.[0];
    if (!file) return;
    const supportedType = file.type === "image/png" || file.type === "image/jpeg" || /\.(png|jpe?g)$/i.test(file.name);
    if (!supportedType) {
      input.value = "";
      return toast("Chỉ nhận ảnh QR định dạng PNG, JPG hoặc JPEG.");
    }
    if (file.size > 1_000_000) {
      input.value = "";
      return toast("Ảnh QR tối đa 1 MB.");
    }
    const reader = new FileReader();
    reader.onload = () => {
      const form = input.closest("#sepay-bank-form");
      const value = String(reader.result || "");
      if (!form || !/^data:image\/(png|jpeg);base64,(iVBORw0KGgo|\/9j\/)/i.test(value)) {
        input.value = "";
        return toast("File đã chọn không phải ảnh PNG/JPG hợp lệ.");
      }
      form.querySelector("[name=qrImageDataUrl]").value = value;
      const preview = form.querySelector("[data-sepay-qr-preview]");
      const empty = form.querySelector("[data-sepay-qr-empty]");
      preview.src = value;
      preview.hidden = false;
      empty.hidden = true;
      form.querySelector("[data-sepay-qr-remove]").disabled = false;
    };
    reader.onerror = () => {
      input.value = "";
      toast("Không đọc được ảnh QR đã chọn.");
    };
    reader.readAsDataURL(file);
  });
