  /** Hiện kết quả của các nút AI ngay trên trang (không biến mất như toast) và kèm toast. */
  function setAiStatus(tone, text, withToast = true) {
    state.integrationAiStatus = { tone, text };
    const el = document.querySelector("#integration-ai-status");
    if (el) { el.className = `integration-ai-status ${tone}`; el.textContent = text; el.hidden = false; }
    if (withToast) toast(text);
  }
  /** Chạy một thao tác AI: khoá nút, đổi chữ "Đang…", báo kết quả; giữ nguyên key/model người dùng đang gõ. */
  async function runAiAction(button, busyText, action) {
    const idleText = button.textContent;
    const form = document.querySelector("#integration-ai-form");
    const typedKey = form?.querySelector("[name=apiKey]")?.value || "";
    button.disabled = true;
    button.textContent = busyText;
    setAiStatus("busy", busyText, false);
    try {
      await action(typedKey);
    } catch (error) {
      setAiStatus("error", error.message || "Không thực hiện được, thử lại sau.");
    } finally {
      button.disabled = false;
      button.textContent = idleText;
    }
  }
  async function loadAiModels(silent) {
    const form = document.querySelector("#integration-ai-form");
    const apiKey = form?.querySelector("[name=apiKey]")?.value || "";
    const model = form?.querySelector("[name=model]")?.value || "";
    const result = await api("/api/integrations/ai-models", { method: "POST", body: JSON.stringify({ apiKey }) });
    state.integrationAiModels = result.models;
    state.integrationAiStatus = silent ? null : {
      tone: result.models.length ? "ok" : "error",
      text: result.models.length ? `Đã tải ${result.models.length} model mới (phát hành trong 6 tháng gần nhất). Chọn một model rồi bấm Lưu cấu hình AI.` : "Kết nối được nhưng OpenAI không có model chat nào phát hành trong 6 tháng gần nhất.",
    };
    render();
    // render dựng lại form: trả lại key đang gõ và model đang chọn
    const next = document.querySelector("#integration-ai-form");
    if (next && apiKey) next.querySelector("[name=apiKey]").value = apiKey;
    if (next && model && [...next.querySelector("[name=model]").options].some((option) => option.value === model)) next.querySelector("[name=model]").value = model;
    if (!silent && state.integrationAiStatus) toast(state.integrationAiStatus.text);
  }
  document.querySelector("#integration-ai-models")?.addEventListener("click", (event) => runAiAction(event.currentTarget, "Đang tải danh sách model…", () => loadAiModels(false)));
  document.querySelector("#integration-ai-ping")?.addEventListener("click", (event) => runAiAction(event.currentTarget, "Đang kiểm tra kết nối OpenAI…", async (apiKey) => {
    const result = await api("/api/integrations/ai-ping", { method: "POST", body: JSON.stringify({ apiKey }) });
    setAiStatus(result.ok ? "ok" : "error", result.message || (result.ok ? "Kết nối OpenAI thành công." : "Kết nối OpenAI thất bại."));
  }));
